local config = {
  str_homestory_800601001_0_dialog_content = "卡蓮......",
  str_homestory_800601001_1_dialog_content = "你好，PlayerName。",
  str_homestory_800601001_2_dialog_content = "卡蓮，妳在做什麼？",
  str_homestory_800601001_3_dialog_content = "只是自言自語罷了。",
  str_homestory_800601001_4_dialog_content = "其實是在「許願」吧？",
  str_homestory_800601001_5_dialog_content = "......",
  str_homestory_800601001_6_dialog_content = "沒錯，讓你見笑了。",
  str_homestory_800601001_7_dialog_content = "怎麼會呢，許願豈不是很正常嗎？",
  str_homestory_800601001_8_dialog_content = "握不住刀劍的小孩，可以許願尋求大人的庇護。",
  str_homestory_800601001_9_dialog_content = "陷入絕症的患者，可以向神明祈求一個健康的身體。",
  str_homestory_800601001_10_dialog_content = "但是，假如一個人有足夠的本事，又何必依賴於「願望」這種東西呢？",
  str_homestory_800601001_11_dialog_content = "（贊同）",
  str_homestory_800601001_12_dialog_content = "雖然聽起來有些殘酷，但妳說得很有道理......",
  str_homestory_800601001_13_dialog_content = "假使能將命運掌握在自己手裡，自然不用仰仗他人。",
  str_homestory_800601001_14_dialog_content = "偏偏世界上有太多我們無法控制的東西。PlayerName，你的措辭很精準。",
  str_homestory_800601001_15_dialog_content = "命運。",
  str_homestory_800601001_16_dialog_content = "我們統稱那些無法逆轉的事情為命運，心想這樣會好受一點。",
  str_homestory_800601001_17_dialog_content = "但對我而言，命運可以被改變。",
  str_homestory_800601001_18_dialog_content = "（反對）",
  str_homestory_800601001_19_dialog_content = "白夜城不是有向光之神祈禱的習慣嗎？",
  str_homestory_800601001_20_dialog_content = "我以為大家都會這麼做呢。卡蓮也不例外。",
  str_homestory_800601001_21_dialog_content = "的確，我們會時不時向光之神訴說想法，或者傳達願望。",
  str_homestory_800601001_22_dialog_content = "但對我來說，這樣做不過是尋求內心慰藉而已。",
  str_homestory_800601001_23_dialog_content = "當祈禱結束，依然需要克服跟前的困難，這一點從未改變過。",
  str_homestory_800601001_24_dialog_content = "……",
  str_homestory_800601001_25_dialog_content = "嗯，想到這裡，我覺得自己應該算幸運。",
  str_homestory_800601001_26_dialog_content = "幸運？為什麼？",
  str_homestory_800601001_27_dialog_content = "因為我不用獨自面對敵人。",
  str_homestory_800601001_28_dialog_content = "我突然有感，能和大家成為夥伴真是太好了。",
  str_homestory_800601001_29_dialog_content = "我也這麼覺得。身旁有可以一起冒险的夥伴，真是太好了。",
  str_homestory_800601001_30_dialog_content = "是的。",
  str_homestory_800601001_31_dialog_content = "卡蓮今天特別感性呢？",
  str_homestory_800601001_32_dialog_content = "可能是這個地方的緣故。我覺得這裡......特別適合思考。",
  str_homestory_800601001_33_dialog_content = "沒有無盡的戰鬥，也沒有聒噪的王公貴族。一切都很平靜。",
  str_homestory_800601001_34_dialog_content = "那我就不打擾妳了。多給妳一些獨處的時間會更好吧？",
  str_homestory_800601001_35_dialog_content = "PlayerName，謝謝你。",
  str_homestory_800601001_36_dialog_content = "卡蓮，不用謝。",
  str_homestory_800201001_0_dialog_content = "是緋長官啊。",
  str_homestory_800201001_1_dialog_content = "有何貴事？",
  str_homestory_800201001_2_dialog_content = "莫非也來許願嗎？",
  str_homestory_800201001_3_dialog_content = "啊，是的",
  str_homestory_800201001_4_dialog_content = "見緋長官也在這裡，所以想來打聲招呼。",
  str_homestory_800201001_5_dialog_content = "嗯。",
  str_homestory_800201001_6_dialog_content = "緋長官在這裡......冥想嗎？",
  str_homestory_800201001_7_dialog_content = "我在許願。<sprite=emo_mojing size=60 />",
  str_homestory_800201001_8_dialog_content = "......！",
  str_homestory_800201001_9_dialog_content = "你看起來很驚訝。",
  str_homestory_800201001_10_option_content = "（承認）",
  str_homestory_800201001_11_dialog_content = "我......我確實沒料想到，連緋長官也會許願。",
  str_homestory_800201001_12_option_content = "（否認）",
  str_homestory_800201001_13_dialog_content = "比起驚訝，不如說是震驚更能表達......",
  str_homestory_800201001_14_dialog_content = "因為妳看起來很強大，就......感覺不會輕易為某事而煩惱。",
  str_homestory_800201001_15_dialog_content = "謝謝你的誇獎。",
  str_homestory_800201001_16_dialog_content = "不過我不是在向任何神明許願，而是對自己。",
  str_homestory_800201001_17_dialog_content = "慢著，對自己許願？",
  str_homestory_800201001_18_dialog_content = "我好像聽不太懂......",
  str_homestory_800201001_19_dialog_content = "我聽說最近很多人都在此處許願。",
  str_homestory_800201001_20_dialog_content = "我想，或許人們心中真正的期許，會在許下願望的瞬間變得更明確。",
  str_homestory_800201001_21_dialog_content = "也就是說，我覺得在這裡許願能讓我們看清自己想要的究竟是什麼。",
  str_homestory_800201001_22_dialog_content = "啊......我明白了。",
  str_homestory_800201001_23_dialog_content = "類似「找到自己真正想要完成的事」的感覺嗎？",
  str_homestory_800201001_24_dialog_content = "是的。",
  str_homestory_800201001_25_dialog_content = "那......緋長官現在找到了嗎？",
  str_homestory_800201001_26_dialog_content = "嗯。",
  str_homestory_800201001_27_dialog_content = "雖然這個「願望」沒我想像得那麼明確......但好歹有了大方向吧。",
  str_homestory_800201001_28_dialog_content = "這樣聽來，緋長官之前沒有特定的方向嗎？",
  str_homestory_800201001_29_dialog_content = "客觀面的方向很清晰。",
  str_homestory_800201001_30_dialog_content = "但論主觀方向和願望，確實比較模糊。",
  str_homestory_800201001_31_dialog_content = "不過現在我總算能理解......人們為何熱衷於許願。",
  str_homestory_800201001_32_dialog_content = "是啊......",
  str_homestory_800201001_33_dialog_content = "對緋長官這樣強大的人而言，許願可以明確心之所向......",
  str_homestory_800201001_34_dialog_content = "而對那些辛苦生活的人而言，許願則可能純屬一種虔誠的寄託。",
  str_homestory_800201001_35_dialog_content = "這也佐證了祈望池存在的必要性。",
  str_homestory_800201001_36_dialog_content = "為了建造這裡，你和薇絲也辛苦了。",
  str_homestory_800201001_37_dialog_content = "（突......突然有種在和上級對話的氛圍啊......）",
  str_homestory_800201001_38_dialog_content = "那我就不打擾你了，PlayerName，去許願吧。",
  str_homestory_800201001_39_dialog_content = "再見。",
  str_homestory_800201001_40_dialog_content = "啊......是，是！......再見，緋長官！",
  str_homestory_802501001_0_dialog_content = "他......在吟詩嗎？",
  str_homestory_802501001_1_dialog_content = "不錯......",
  str_homestory_802501001_2_dialog_content = "不錯？",
  str_homestory_802501001_3_dialog_content = "嗯，我不得不承認......",
  str_homestory_802501001_4_dialog_content = "不錯！這個舞台真的很不錯！<sprite=emo_yinfu size=60 />",
  str_homestory_802501001_5_dialog_content = "舞台？",
  str_homestory_802501001_6_dialog_content = "喔！PlayerName，你來得正好！",
  str_homestory_802501001_7_dialog_content = "你看，這風信塔外的小廣場......",
  str_homestory_802501001_8_dialog_content = "多麼適合上演一齣感人肺腑的戲劇！",
  str_homestory_802501001_9_dialog_content = "PlayerName，可別浪費這麼棒的光線與空間。",
  str_homestory_802501001_10_dialog_content = "請務必讓我在這裡上演一段曠世千古的傳奇之作！",
  str_homestory_802501001_11_option_content = "（同意）",
  str_homestory_802501001_12_dialog_content = "嗯......那是當然，只要別鬧得太過火......",
  str_homestory_802501001_13_dialog_content = "那怎麼行？",
  str_homestory_802501001_14_dialog_content = "列車！火焰！血染茶杯！金屬樂！黑膠唱片，還有擴音器！",
  str_homestory_802501001_15_dialog_content = "我要讓這齣戲迴響遍至空島的每一個角落！",
  str_homestory_802501001_16_dialog_content = "......那樣不會很擾民嗎？",
  str_homestory_802501001_17_dialog_content = "擾民？莫非此處的居民絲毫不懂得欣賞藝術？",
  str_homestory_802501001_18_dialog_content = "啊哈哈！怎......怎麼會呢！",
  str_homestory_802501001_19_dialog_content = "只是想，小眾藝術只有內行人才懂得欣賞嘛！",
  str_homestory_802501001_20_dialog_content = "不過，我認為在夜靜人深時欣賞你的戲劇，氣氛更足。",
  str_homestory_802501001_21_dialog_content = "所以呢，卡戎，你看......",
  str_homestory_802501001_22_option_content = "（拒絕）",
  str_homestory_802501001_23_dialog_content = "現在該如何是好？",
  str_homestory_802501001_24_dialog_content = "你冷若冰霜的拒絕，反而讓在下腦中燃起了新的靈感！",
  str_homestory_802501001_25_dialog_content = "靈感反覆交織，吼叫著、撕扯著，它們在我靈魂深處洶湧翻騰！",
  str_homestory_802501001_26_dialog_content = "究竟是什麼在低聲怒吼......是藝術，是一種脫離了掌控的表演——",
  str_homestory_802501001_27_dialog_content = "就是現在，讓這齣戲迴盪在整座空谷之中吧！",
  str_homestory_802501001_28_dialog_content = "（看起來拒絕也是毫無影響力啊......）",
  str_homestory_802501001_29_dialog_content = "要不還是......改天吧？",
  str_homestory_802501001_30_dialog_content = "......改天？",
  str_homestory_802501001_31_dialog_content = "唉......在下的內心突如其來盪起了憂傷。",
  str_homestory_802501001_32_dialog_content = "誰料PlayerName也學會玩無視別人的把戲了。",
  str_homestory_802501001_33_dialog_content = "既然如此，我會考慮請你在我的戲裡客串「冷漠之人」一角。",
  str_homestory_802501001_34_dialog_content = "......",
  str_homestory_810501001_0_dialog_content = "伊芙好忙啊！",
  str_homestory_810501001_1_dialog_content = "導航員，你來啦......！<sprite=emo_aixin size=60 />",
  str_homestory_810501001_2_dialog_content = "伊芙等等再來和你玩喔，伊芙在思索還需要什麼呢......",
  str_homestory_810501001_3_dialog_content = "啊，好的，沒關係。",
  str_homestory_810501001_4_dialog_content = "話說，妳還缺什麼？我可以幫妳找找。",
  str_homestory_810501001_5_dialog_content = "哎呀，沒關係啦，你已經幫我們準備了好多東西囉！",
  str_homestory_810501001_6_dialog_content = "伊芙只是想製作一些禮物～",
  str_homestory_810501001_7_dialog_content = "剛剛正在想，如果要繡花、或者縫一個杯套，應該用哪種顏色的布料比較好。",
  str_homestory_810501001_8_dialog_content = "繡花？還有杯套？",
  str_homestory_810501001_9_dialog_content = "對呀～",
  str_homestory_810501001_10_dialog_content = "我幫多恩做了一件衣服<sprite=emo_qunzi size=60 />，打算在上面縫幾朵黎花......",
  str_homestory_810501001_11_dialog_content = "嗯......杯套則是因為哥哥總是隨身帶著我喝水用的水杯嘛......",
  str_homestory_810501001_12_dialog_content = "所以就想到，做個可愛的杯套讓哥哥用也不錯。",
  str_homestory_810501001_13_dialog_content = "嘿嘿......導航員覺得怎麼樣呢？",
  str_homestory_810501001_14_dialog_content = "超棒的！",
  str_homestory_810501001_15_dialog_content = "我覺得是很用心的禮物，相信他們收到也會很開心。",
  str_homestory_810501001_16_dialog_content = "嗯嗯，那就好......",
  str_homestory_810501001_17_dialog_content = "所以，我該用哪種顏色的布料呢？",
  str_homestory_810501001_18_dialog_content = "雖然黎花是白色，但伊芙也在想，用其他顏色的花花會不會更有意思......",
  str_homestory_810501001_19_dialog_content = "杯套也是，紅色好還是黑色好呢？哥哥可能比較喜歡哪種呢？",
  str_homestory_810501001_20_dialog_content = "哎呀，真是令人苦惱呢。",
  str_homestory_810501001_21_dialog_content = "嗯......",
  str_homestory_810501001_22_dialog_content = "妳要送多恩的衣服是哪個顏色？",
  str_homestory_810501001_23_dialog_content = "是黑色的喔！",
  str_homestory_810501001_24_dialog_content = "那還是繡上白色的黎花比較適合吧？",
  str_homestory_810501001_25_dialog_content = "如果把花繡得立體一點，多恩摸到還能感覺到黎花的形狀，這樣如何？",
  str_homestory_810501001_26_dialog_content = "白色的、立體的黎花......",
  str_homestory_810501001_27_dialog_content = "啊......真是個超棒提議呢！",
  str_homestory_810501001_28_dialog_content = "能幫到妳就好。",
  str_homestory_810501001_29_dialog_content = "那......關於哥哥的杯套顏色，導航員有建議嗎？",
  str_homestory_810501001_30_option_content = "有",
  str_homestory_810501001_31_dialog_content = "假如還在黑色和紅色之間糾結的話，不如縫一個黑紅相間就罷。",
  str_homestory_810501001_32_dialog_content = "不過，伊芙......",
  str_homestory_810501001_33_option_content = "沒有",
  str_homestory_810501001_34_dialog_content = "老實說，伊芙......",
  str_homestory_810501001_35_dialog_content = "我覺得無論妳送醒山什麼東西，他都會欣喜若狂。",
  str_homestory_810501001_36_dialog_content = "就算妳隨便撿片葉子，或者捧一把沙送給他，他都會視其為珍寶，並且大肆宣揚。",
  str_homestory_810501001_37_dialog_content = "欸......",
  str_homestory_810501001_38_dialog_content = "好吧，導航員說的也有道理......",
  str_homestory_810501001_39_dialog_content = "我知道啦！索性挑我自己喜歡的顏色好啦，嘿嘿。",
  str_homestory_810501001_40_dialog_content = "嗯，我覺得可以。",
  str_homestory_810501001_41_dialog_content = "話說，伊芙......妳幫多恩和醒山籌備禮物，沒替自己準備嗎？",
  str_homestory_810501001_42_dialog_content = "唔......？對不起，導航員，伊芙不明白你的意思。",
  str_homestory_810501001_43_dialog_content = "我需要替自己準備什麼？",
  str_homestory_810501001_44_dialog_content = "啊，我的意思是......",
  str_homestory_810501001_45_dialog_content = "妳看，妳之前跟我要了幾包營養土和黎花的種子，應該也是為了多恩吧？",
  str_homestory_810501001_46_dialog_content = "為了讓她能開心地在這裡種花。",
  str_homestory_810501001_47_dialog_content = "還和薇絲要來許多紅油扳手的小吃，八成是擔心醒山沒東西下酒吧？",
  str_homestory_810501001_48_dialog_content = "哎呀......原來都被導航員發現啦......",
  str_homestory_810501001_49_dialog_content = "你說得沒......沒錯啦......",
  str_homestory_810501001_50_dialog_content = "但是......",
  str_homestory_810501001_51_dialog_content = "妳不給自己準備什麼東西嗎？",
  str_homestory_810501001_52_dialog_content = "嗯......伊芙給哥哥和多恩準備東西，只是希望他們在這裡住得更開心～",
  str_homestory_810501001_53_dialog_content = "但伊芙......只要能和他們待在一起，就很高興。",
  str_homestory_810501001_54_dialog_content = "啊......還有導航員和薇絲！",
  str_homestory_810501001_55_dialog_content = "只要能和你們待在一起，伊芙......就覺得很幸福了。",
  str_homestory_810501001_56_dialog_content = "所以......伊芙不需要再給自己準備東西啦。",
  str_homestory_810501001_57_dialog_content = "原......原來是這樣。",
  str_homestory_810501001_58_dialog_content = "伊芙好貼心啊......",
  str_homestory_810501001_59_dialog_content = "導航員也很貼心呀！",
  str_homestory_810501001_60_dialog_content = "嗚......嗚嗚......",
  str_homestory_810501001_61_dialog_content = "怎......怎麼啦？",
  str_homestory_810501001_62_dialog_content = "導航員，你怎麼突然哭啦？",
  str_homestory_810501001_63_dialog_content = "嗚嗚......我也想要一個伊芙這樣的妹妹......<sprite=emo_daku size=60 />",
  str_homestory_811201001_0_dialog_content = "斯莫奇？！",
  str_homestory_811201001_1_dialog_content = "怎......怎麼了斯莫奇......",
  str_homestory_811201001_2_dialog_content = "妳為何這麼生氣的樣子......",
  str_homestory_811201001_3_dialog_content = "喂，導航員。",
  str_homestory_811201001_4_dialog_content = "你不覺得這商店裡東西太少了嗎？<sprite=emo_shengqi size=60 />",
  str_homestory_811201001_5_dialog_content = "啊！所以妳是為了這個原因生氣嗎？",
  str_homestory_811201001_6_dialog_content = "妳認為缺了哪些？可以告訴我。",
  str_homestory_811201001_7_dialog_content = "確定要我講？",
  str_homestory_811201001_8_dialog_content = "嗯，妳先說說看吧。",
  str_homestory_811201001_9_dialog_content = "好吧，那我就直說了。",
  str_homestory_811201001_10_dialog_content = "首先，商店裡沒有配件的清洗劑。",
  str_homestory_811201001_11_dialog_content = "其次，商店裡鈕扣的款式可說是乏善可陳！",
  str_homestory_811201001_12_dialog_content = "相信我，不會有人想把這樣的鈕扣放在衣服上。",
  str_homestory_811201001_13_dialog_content = "喔，當然，可能除了啟光的傢伙們吧。",
  str_homestory_811201001_14_dialog_content = "鈕扣......不是實用就好了嗎？",
  str_homestory_811201001_15_dialog_content = "還有，你也沒認識幾個真正懂時尚的人。",
  str_homestory_811201001_16_dialog_content = "不過你也不需要自卑，因為我會教你。",
  str_homestory_811201001_17_dialog_content = "......謝謝？",
  str_homestory_811201001_18_dialog_content = "還有，這裡的陽光比影鎮強烈多了。",
  str_homestory_811201001_19_dialog_content = "雖有陽傘，但舉凡防曬乳、墨鏡這些防曬小物，你也都沒有。",
  str_homestory_811201001_20_dialog_content = "啊......說得也對......",
  str_homestory_811201001_21_dialog_content = "（不過......除了斯莫奇，應該也有其他光靈覺得商店的東西不夠吧？）",
  str_homestory_811201001_22_dialog_content = "（這該怎麼辦......一個個去問好像太耽誤時間......）",
  str_homestory_811201001_23_dialog_content = "喂，你在嘀咕什麼！",
  str_homestory_811201001_24_dialog_content = "是不是覺得我很麻煩，害怕其他人也有樣學樣？",
  str_homestory_811201001_25_option_content = "（點頭）",
  str_homestory_811201001_26_dialog_content = "很好，居然就這麼老實承認。",
  str_homestory_811201001_27_dialog_content = "與其說麻煩，不如說是苦惱......",
  str_homestory_811201001_28_option_content = "（搖頭）",
  str_homestory_811201001_29_dialog_content = "不，斯莫奇，倒是不麻煩......",
  str_homestory_811201001_30_dialog_content = "其實並不是麻煩與否的問題。",
  str_homestory_811201001_31_dialog_content = "我只是在想，其他人可能也跟妳一樣想法，但我該怎麼——",
  str_homestory_811201001_32_dialog_content = "——你應該建立一個空之山谷的訂貨流程。",
  str_homestory_811201001_33_dialog_content = "每個人覺得缺少的東西，都可以透過這個流程定期從艾斯特拉大陸各地下單。",
  str_homestory_811201001_34_dialog_content = "唔，至於運貨方式嘛......你們的特殊科技能不能派上用場？",
  str_homestory_811201001_35_dialog_content = "信使公會<sprite=emo_gezitou size=60 />、螢盞之流。",
  str_homestory_811201001_36_dialog_content = "啊......好像有點道理......",
  str_homestory_811201001_37_dialog_content = "這樣你不用一個一個問，別人也不會像我照樣當面抱怨。",
  str_homestory_811201001_38_dialog_content = "况且說不定某些光靈還有特殊需求。",
  str_homestory_811201001_39_dialog_content = "比如有些人喜歡棺材、有些人喜歡不同型號的畫筆、有些人喜歡奇怪的蟲子......",
  str_homestory_811201001_40_dialog_content = "還有些人格外喜歡琴酒。",
  str_homestory_811201001_41_dialog_content = "等等，琴酒？",
  str_homestory_811201001_42_dialog_content = "妳是在說......吉納維芙！",
  str_homestory_811201001_43_dialog_content = "這世上喜歡喝酒的傢伙就只有她一個是嗎？",
  str_homestory_811201001_44_dialog_content = "......真不知道你滿腦子什麼想法！",
  str_homestory_811201001_45_dialog_content = "好好好......不是就不是吧！有其他人喜歡喝琴酒！",
  str_homestory_811201001_46_dialog_content = "當然！其他人也很愛喝酒好嗎？<sprite=emo_nuhuo size=60 />",
  str_homestory_811201001_47_dialog_content = "好......好......別生氣！也別放火......",
  str_homestory_811201001_48_dialog_content = "哼。",
  str_homestory_811201001_49_dialog_content = "總之真是謝謝妳了，斯莫奇。",
  str_homestory_811201001_50_dialog_content = "妳給的建議很有用！",
  str_homestory_811201001_51_dialog_content = "走了。再見。",
  str_homestory_811201001_52_dialog_content = "再......再見！",
  str_homestory_807101001_0_dialog_content = "瀧的風箏......",
  str_homestory_807101001_1_dialog_content = "咳，瀧......",
  str_homestory_807101001_2_dialog_content = "嗯？PlayerName？",
  str_homestory_807101001_3_dialog_content = "那個......我看到你的風箏......",
  str_homestory_807101001_4_dialog_content = "掉在地上了。",
  str_homestory_807101001_5_dialog_content = "......喔。",
  str_homestory_807101001_6_dialog_content = "但我很快把它撿起來了。",
  str_homestory_807101001_7_dialog_content = "......？<sprite=emo_yihuo size=60 />",
  str_homestory_807101001_8_dialog_content = "（這根本不是重點吧？）",
  str_homestory_807101001_9_dialog_content = "咳，好吧。不過就放風箏的技術而言，你其實......",
  str_homestory_807101001_10_option_content = "水準很高！",
  str_homestory_807101001_11_dialog_content = "小子，你想安慰我？",
  str_homestory_807101001_12_dialog_content = "咳，我只是想鼓勵你一下......",
  str_homestory_807101001_13_dialog_content = "能理解你的好意，但我不需要這種不真實的誇獎。",
  str_homestory_807101001_14_dialog_content = "嗯......我明白了。如果你沒失去信心的話......",
  str_homestory_807101001_15_option_content = "根本不會？",
  str_homestory_807101001_16_dialog_content = "想學的話，我可以教教你。",
  str_homestory_807101001_17_dialog_content = "嗯，那你小子就來教我。",
  str_homestory_807101001_18_dialog_content = "欸？居然這麼爽快就接受了？",
  str_homestory_807101001_19_dialog_content = "當然。",
  str_homestory_807101001_20_dialog_content = "讓技術更高超的人指導自己又不是什麼丟臉的事。",
  str_homestory_807101001_21_dialog_content = "不懂的事直說，可以省去很多溝通成本。這道理對生意人尤其受用。",
  str_homestory_807101001_22_dialog_content = "不愧是萬事屋的當家。",
  str_homestory_807101001_23_dialog_content = "所以，放風箏有何技巧？告訴我吧。",
  str_homestory_807101001_24_dialog_content = "嗯，首先要確定風的方向，然後逆風而立。",
  str_homestory_807101001_25_dialog_content = "因為風箏需要迎風始得高飛。",
  str_homestory_807101001_26_dialog_content = "風箏爬升的時候，要慢慢放線；風力不足時，則必須快速收線。",
  str_homestory_807101001_27_dialog_content = "放風箏的過程中，可以慢慢跑步，隨時觀察風箏的狀態。",
  str_homestory_807101001_28_dialog_content = "假如此時風箏飛得又高又穩......",
  str_homestory_807101001_29_dialog_content = "你就可以把線綁在樹上或路牌上，接著找個舒服的地方觀賞自己的風箏。",
  str_homestory_807101001_30_dialog_content = "嗯......風向......風力......跑步......注意與風箏的互動......<sprite=emo_wuyu size=60 />",
  str_homestory_807101001_31_dialog_content = "啊？你在默念嗎？",
  str_homestory_807101001_32_dialog_content = "我可以再複誦一遍，如果你需要的話......",
  str_homestory_807101001_33_dialog_content = "不，我已經記住了。",
  str_homestory_807101001_34_dialog_content = "嗯？那你為什麼還在碎碎念？",
  str_homestory_807101001_35_dialog_content = "呃，我的意思是，你不如先實際嘗試我說的？",
  str_homestory_807101001_36_dialog_content = "我在想「放風箏技巧」這本小冊子，該怎麼印刷才會更美觀，更好賣。",
  str_homestory_807101001_37_dialog_content = "......啊？",
  str_homestory_807101001_38_dialog_content = "試想一下，如果萬事屋開始賣風箏，並且加重宣傳力道......",
  str_homestory_807101001_39_dialog_content = "購買風箏就可以獲得限時指導。",
  str_homestory_807101001_40_dialog_content = "限時指導結束後，仍然沒學會怎麼辦？這時就可以購買「放風箏技巧」這本小冊子。",
  str_homestory_807101001_41_dialog_content = "至於風箏的樣式，更是多種多樣。試想一下，如果把影主的頭像印在風箏上......",
  str_homestory_807101001_42_dialog_content = "停，等......等等！",
  str_homestory_807101001_43_dialog_content = "所以你在這裡放風箏、引導我教你風箏技巧......",
  str_homestory_807101001_44_dialog_content = "全都是為了賺錢？！",
  str_homestory_807101001_45_dialog_content = "對啊。",
  str_homestory_807101001_46_dialog_content = "年輕人，我是個標準生意人。",
  str_homestory_807101001_47_dialog_content = "怎麼了嗎？哪裡有問題？",
  str_homestory_807101001_48_dialog_content = "不，沒有......",
  str_homestory_807101001_49_dialog_content = "我只是相當羨慕你的商業頭腦啊！！",
  str_homestory_807101001_50_dialog_content = "要是我也這麼善於利用身邊的資源賺錢，想必也不會天天超支了......",
  str_homestory_807101001_51_dialog_content = "唔嗯，原來你在擔心這個。",
  str_homestory_807101001_52_dialog_content = "不如這樣，既然此事是從你身上獲得靈感......",
  str_homestory_807101001_53_dialog_content = "等我真的開始在萬事屋做這碼生意的時候，就把利潤分你一半。",
  str_homestory_807101001_54_dialog_content = "......？！",
  str_homestory_807101001_55_dialog_content = "真......真的嗎？！",
  str_homestory_807101001_56_dialog_content = "嗯，但你別興奮得太早。",
  str_homestory_807101001_57_dialog_content = "說不定這行當根本就搞不起來。",
  str_homestory_807101001_58_dialog_content = "沒關係！瀧，我對你有信心！！",
  str_homestory_807101001_59_dialog_content = "罷了，我要繼續練習放風箏技巧了。",
  str_homestory_807101001_60_dialog_content = "至於你呢......年輕人應該很忙，該去哪就去哪吧。",
  str_homestory_807101001_61_dialog_content = "加油啊！瀧！",
  str_homestory_807101001_62_dialog_content = "（......嗯！我決定了！）",
  str_homestory_807101001_63_dialog_content = "（為了早點拿到分紅......我要天天來監督瀧的練習進度！）<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_0_dialog_content = "薇絲？",
  str_homestory_803301001_1_dialog_content = "呼吸......薇絲，妳辦得到！",
  str_homestory_803301001_2_dialog_content = "深呼吸......喘氣......<sprite=emo_tanqi size=60 />",
  str_homestory_803301001_3_dialog_content = "喘氣？",
  str_homestory_803301001_4_dialog_content = "薇絲，妳......妳在練習呼吸嗎？",
  str_homestory_803301001_5_dialog_content = "呀！PlayerName？",
  str_homestory_803301001_6_dialog_content = "......練習呼吸？",
  str_homestory_803301001_7_dialog_content = "不是啦......",
  str_homestory_803301001_8_dialog_content = "不然妳在做什麼？",
  str_homestory_803301001_9_dialog_content = "我只是在算帳而已。",
  str_homestory_803301001_10_dialog_content = "啊......想起那些支出帳目，確實讓人頭疼。",
  str_homestory_803301001_11_dialog_content = "好吧，現在我寧可自己只是在練習呼吸了......",
  str_homestory_803301001_12_dialog_content = "好歹練習呼吸是免費的，不會花到一分錢。",
  str_homestory_803301001_13_option_content = "（詢問薇絲）",
  str_homestory_803301001_14_dialog_content = "需要幫忙嗎？",
  str_homestory_803301001_15_dialog_content = "我昨晚看了我們的帳簿。",
  str_homestory_803301001_16_dialog_content = "雖然我不太會算帳......但我想我能加減幫上忙。",
  str_homestory_803301001_17_option_content = "（沉默）",
  str_homestory_803301001_18_dialog_content = "你怎麼不說話？",
  str_homestory_803301001_19_dialog_content = "啊，我沒有責怪你的意思......",
  str_homestory_803301001_20_dialog_content = "我知道，我只是在思索怎麼樣才能增加貢獻。",
  str_homestory_803301001_21_dialog_content = "我昨晚看了我們的帳簿，確實有一些超支的狀況......",
  str_homestory_803301001_22_dialog_content = "唉，薇絲......這段日子真的辛苦妳了！",
  str_homestory_803301001_23_dialog_content = "現在回想我昨晚看到的帳本內容......",
  str_homestory_803301001_24_dialog_content = "「光是祈望池、廣場和假山這三處的材料就已經是一筆超高額費用。」",
  str_homestory_803301001_25_dialog_content = "「更別提宅舍和陳列館需要的大量瑣碎物資......」",
  str_homestory_803301001_26_dialog_content = "「還得追蹤留意夥伴們各自的喜好......」",
  str_homestory_803301001_27_dialog_content = "「諸如木馬、吊椅和雕塑......」",
  str_homestory_803301001_28_dialog_content = "「縱然這些小物件單價不高，加總起來也是筆不小的支出。」",
  str_homestory_803301001_29_dialog_content = "「和工匠們打交道也是門學問，安裝這些東西確實很難。」",
  str_homestory_803301001_30_dialog_content = "「不過......只要大家住進來能感到安心舒適，我和PlayerName的努力也不算白費工夫吧？」",
  str_homestory_803301001_31_dialog_content = "啊......都被你看到啦。",
  str_homestory_803301001_32_dialog_content = "沒錯，我似乎改不了在各種本子上寫寫畫畫和碎碎念的毛病......哈哈。",
  str_homestory_803301001_33_dialog_content = "說真的，薇絲，我覺得妳實在太棒了！",
  str_homestory_803301001_34_dialog_content = "導航員，你怎麼......怎麼突然拍起馬屁來啦？",
  str_homestory_803301001_35_dialog_content = "這可是我誠心誠意的讚賞。",
  str_homestory_803301001_36_dialog_content = "妳想想，舉凡設計施工圖紙、安排施工計畫、規劃區域分類妳全包辦......",
  str_homestory_803301001_37_dialog_content = "哪像我，不會畫圖，又不懂如何詳盡計劃和安排。",
  str_homestory_803301001_38_dialog_content = "空庭能變成現在這樣，全多虧了妳的付出呢。",
  str_homestory_803301001_39_dialog_content = "......啊，這......這倒是......",
  str_homestory_803301001_40_dialog_content = "你不用這麼客套啦！",
  str_homestory_803301001_41_dialog_content = "不是客套，只希望妳能重新打起精神。",
  str_homestory_803301001_42_dialog_content = "乾脆我們一起討論，如何讓我們的收支情況維持穩健吧？",
  str_homestory_803301001_43_dialog_content = "嗯！沒錯沒錯！你說得對。",
  str_homestory_803301001_44_dialog_content = "喔喔，我突然想到......既然在空庭買東西很困難......",
  str_homestory_803301001_45_dialog_content = "我們把商店的物品漲價十倍出售，如何？<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_46_dialog_content = "......呃，不必做到這種程度吧......",
  str_homestory_803301001_47_dialog_content = "嘿嘿，導航員，我開玩笑的啦！",
  str_homestory_803301001_48_dialog_content = "不過......該怎樣才能賺到錢呢？哎呀，我得好好思考......",
  str_homestory_804101001_0_dialog_content = "白蘭女士......",
  str_homestory_804101001_1_dialog_content = "是你，PlayerName。",
  str_homestory_804101001_2_dialog_content = "天氣不錯呢<sprite=emo_pugongying size=60 />，白蘭女士。",
  str_homestory_804101001_3_dialog_content = "是啊。",
  str_homestory_804101001_4_dialog_content = "你在散步嗎？還是有其他計畫？",
  str_homestory_804101001_5_option_content = "在散步",
  str_homestory_804101001_6_dialog_content = "不錯的選擇。",
  str_homestory_804101001_7_dialog_content = "這裡風景優美，娛樂設施眾多......",
  str_homestory_804101001_8_dialog_content = "還有不少我沒見過的人呢。",
  str_homestory_804101001_9_option_content = "打算去釣魚",
  str_homestory_804101001_10_dialog_content = "啊，不曉得你的釣魚技術如何？",
  str_homestory_804101001_11_option_content = "不是蓋的",
  str_homestory_804101001_12_dialog_content = "真的嗎？",
  str_homestory_804101001_13_dialog_content = "我最後會驗收喔？",
  str_homestory_804101001_14_dialog_content = "沒問題！",
  str_homestory_804101001_15_dialog_content = "呵呵～真是充滿自信的年輕人啊。",
  str_homestory_804101001_16_option_content = "普通而已......",
  str_homestory_804101001_17_dialog_content = "釣魚這檔事......很需要耐心。",
  str_homestory_804101001_18_dialog_content = "沒想到你年紀輕輕，竟偏愛這種興趣？",
  str_homestory_804101001_19_dialog_content = "嗯......我覺得釣魚能幫助自己學習集中精力。",
  str_homestory_804101001_20_dialog_content = "唔......",
  str_homestory_804101001_21_dialog_content = "人們在日常生活中覺得「無法集中精力」時，就會不自覺想去做那些幫助自己集中精力的事。",
  str_homestory_804101001_22_dialog_content = "不過，長期鍛鍊確實會有幫助。",
  str_homestory_804101001_23_dialog_content = "嗯......",
  str_homestory_804101001_24_dialog_content = "不過，白蘭女士為何總是站在這塊木牌下呢？",
  str_homestory_804101001_25_dialog_content = "我在觀察這地方呀。",
  str_homestory_804101001_26_dialog_content = "觀察？",
  str_homestory_804101001_27_dialog_content = "也許是職業病的緣故囉～",
  str_homestory_804101001_28_dialog_content = "見到這麼多新奇的建築和道路，就忍不住想全部刻進腦袋裡呢。",
  str_homestory_804101001_29_dialog_content = "原來是這樣。",
  str_homestory_804101001_30_dialog_content = "不過這裡的道路並不複雜，我認為白蘭女士偶爾歇息一下也無妨。",
  str_homestory_804101001_31_dialog_content = "休息？",
  str_homestory_804101001_32_dialog_content = "多麼奢侈的願望呢......",
  str_homestory_804101001_33_dialog_content = "不過既然是你的提議，那我可以採納。",
  str_homestory_804101001_34_dialog_content = "PlayerName也要記得好好休息喔？",
  str_homestory_804101001_35_dialog_content = "過度疲累的話，人會老得特別快喔～<sprite=emo_guilian size=60 />",
  str_homestory_804101001_36_dialog_content = "好......好的。",
  str_homestory_804101001_37_dialog_content = "我會的！白蘭女士！",
  str_homestory_813801001_0_dialog_content = "希諾普！",
  str_homestory_813801001_1_dialog_content = "PlayerName？",
  str_homestory_813801001_2_dialog_content = "喔......幸好是你......<sprite=emo_tanqi size=60 />",
  str_homestory_813801001_3_dialog_content = "希諾普怎麼了？妳看起來有點疲憊。",
  str_homestory_813801001_4_dialog_content = "因為......我熬了一整夜，終於把陳列館裡的藏品們都看完了。",
  str_homestory_813801001_5_dialog_content = "這些藏品詳盡保存了空谷的過去和空裔們所使用的科技......",
  str_homestory_813801001_6_dialog_content = "不得不說，你們的科技水準真的很高耶。",
  str_homestory_813801001_7_dialog_content = "還好吧，啟光的科技發展也很驚人啊？",
  str_homestory_813801001_8_dialog_content = "不知道為什麼，我就是有個感覺......",
  str_homestory_813801001_9_dialog_content = "空裔的科技和啟光的科技，並不是同一個次元上的產物。",
  str_homestory_813801001_10_dialog_content = "啟光的高科技來自組合機械作業的精妙手法，四平八穩地由知識和儀器所鑄造堆疊......",
  str_homestory_813801001_11_dialog_content = "反觀空裔的科技......卻是相當地鮮明而有活力。",
  str_homestory_813801001_12_dialog_content = "彷彿......與遠古科技有種異曲同工之妙。",
  str_homestory_813801001_13_dialog_content = "這我就真的不清楚了......",
  str_homestory_813801001_14_dialog_content = "啊......",
  str_homestory_813801001_15_dialog_content = "好像真的有點睏了......<sprite=emo_xuanyun size=60 />",
  str_homestory_813801001_16_dialog_content = "那妳怎麼還站這裡？不如早點回去休息吧。",
  str_homestory_813801001_17_dialog_content = "我還在整理參觀時寫下的記錄，還想和我以前讀過的資料串連在一起，看看有沒有新奇的發現。",
  str_homestory_813801001_18_dialog_content = "說不定空裔的足跡很久以前就曾出現在大陸的其他地方......",
  str_homestory_813801001_19_dialog_content = "只不過當時人們還不知道這些人是空裔，因此也分不清遠古科技和空裔科技的差異。",
  str_homestory_813801001_20_dialog_content = "......噗哈哈，也罷。",
  str_homestory_813801001_21_dialog_content = "感覺自己的思考有點天馬行空。或許是太睏了吧。",
  str_homestory_813801001_22_dialog_content = "希諾普，妳現在的狀態令人免不了擔心啊。",
  str_homestory_813801001_23_dialog_content = "呃......為什麼一定要急著現在完成分析呢？",
  str_homestory_813801001_24_dialog_content = "這種狀態下的分析結果恐怕也不夠好吧......",
  str_homestory_813801001_25_dialog_content = "你身邊......不是還有不少白夜城的人嗎？",
  str_homestory_813801001_26_dialog_content = "雖說你是空裔，他們應該不至於對這裡的陳列館搞破壞......",
  str_homestory_813801001_27_dialog_content = "啊，但隱約間總是有些擔心呢！",
  str_homestory_813801001_28_dialog_content = "總覺得一定要趁現在趕快看完，記錄下所有看到的事物，全數分析完成才安心。",
  str_homestory_813801001_29_dialog_content = "天曉得那批極度反對科技的傢伙會怎麼看待這裡呢？",
  str_homestory_813801001_30_dialog_content = "原來是這樣啊......",
  str_homestory_813801001_31_dialog_content = "總之妳可以放一千兩百個心，據我所知，白夜城也有不少陳列館。",
  str_homestory_813801001_32_dialog_content = "再者他們在此地是客人，妳所擔心的那種情況肯定不會出現啦。",
  str_homestory_813801001_33_dialog_content = "難道真是我太多疑嗎......",
  str_homestory_813801001_34_dialog_content = "難道說......這便是超時工作而產生的苦思多慮？<sprite=emo_sikao size=60 />",
  str_homestory_813801001_35_dialog_content = "我覺得是妳太累的緣故。",
  str_homestory_813801001_36_dialog_content = "不如休息一下再繼續吧？",
  str_homestory_813801001_37_dialog_content = "好吧，那我就聽你的......PlayerName。",
  str_homestory_813801001_38_dialog_content = "我準備去休息囉，你呢？",
  str_homestory_813801001_39_dialog_content = "你最近應該也挺疲勞吧？",
  str_homestory_813801001_40_option_content = "（贊同）",
  str_homestory_813801001_41_dialog_content = "是啊，確實滿累的。",
  str_homestory_813801001_42_dialog_content = "不過......",
  str_homestory_813801001_43_option_content = "（反對）",
  str_homestory_813801001_44_dialog_content = "雖然身體很累，但內心卻非常充實！",
  str_homestory_813801001_45_dialog_content = "只要大家在這裡生活得開心，我累點也不算什麼。",
  str_homestory_813801001_46_dialog_content = "你還真是個很有領導意識的......少年呢。",
  str_homestory_813801001_47_dialog_content = "謝......謝謝。",
  str_homestory_813801001_48_dialog_content = "啊......不知道為什麼冥冥之中想要去一趟河畔，實在太睏，我要去休息了。",
  str_homestory_813801001_49_dialog_content = "我睡醒再找你討論空裔科技喔，PlayerName～",
  str_homestory_813801001_50_dialog_content = "嗯，還是好好休息吧，希諾普。",
  str_homestory_814501001_0_dialog_content = "她在看什麼？",
  str_homestory_814501001_1_dialog_content = "雨森？",
  str_homestory_814501001_2_dialog_content = "噓。<sprite=emo_baiyan size=60 />",
  str_homestory_814501001_3_dialog_content = "......？",
  str_homestory_814501001_4_dialog_content = "妳在做什麼？",
  str_homestory_814501001_5_dialog_content = "觀察。",
  str_homestory_814501001_6_dialog_content = "在下在非常仔細地觀察這個地方。",
  str_homestory_814501001_7_dialog_content = "這裡......莫非有什麼特別之處嗎？",
  str_homestory_814501001_8_dialog_content = "大人不覺得空庭的設計十分精妙嗎？",
  str_homestory_814501001_9_dialog_content = "在下年幼時，也曾幻想過要建立一個這樣的地方。",
  str_homestory_814501001_10_dialog_content = "進可攻，退可守。能讓志同道合之人都聚在一起。",
  str_homestory_814501001_11_dialog_content = "啊……",
  str_homestory_814501001_12_dialog_content = "雨森從那麼小開始就做了這麼長遠的計畫嗎？",
  str_homestory_814501001_13_dialog_content = "也許那樣的幻想對當時的我而言，只是一種「讓人能夠繼續生活」的動力而已吧。",
  str_homestory_814501001_14_dialog_content = "不過現在的我能在這上面生活，還算不錯。",
  str_homestory_814501001_15_dialog_content = "這......抱歉。",
  str_homestory_814501001_16_dialog_content = "需不需要我帶妳在這裡好好轉轉？",
  str_homestory_814501001_17_dialog_content = "不必。",
  str_homestory_814501001_18_dialog_content = "早在到達的第一天，我就已經把這裡給摸清了。",
  str_homestory_814501001_19_dialog_content = "好可怕的偵察能力！",
  str_homestory_814501001_20_dialog_content = "不過是忍者的本能罷了。",
  str_homestory_814501001_21_dialog_content = "其實在下只想知道一件事......這個神奇的地方究竟是誰設計的？",
  str_homestory_814501001_22_dialog_content = "大人您知道嗎？",
  str_homestory_814501001_23_option_content = "知道",
  str_homestory_814501001_24_dialog_content = "是薇絲結合了我和工匠們的意見設計的。",
  str_homestory_814501001_25_option_content = "不知道",
  str_homestory_814501001_26_dialog_content = "但我可以幫妳問問薇絲。",
  str_homestory_814501001_27_dialog_content = "雖然我確實參與了設計......但整體性的規劃還是她最清楚。",
  str_homestory_814501001_28_dialog_content = "話說，雨森知道這個又有何用？",
  str_homestory_814501001_29_dialog_content = "難道......妳想在雲島也建一個「雲島空庭」之類的東西嗎？",
  str_homestory_814501001_30_dialog_content = "我確實有這個想法。",
  str_homestory_814501001_31_dialog_content = "試想一下，一旦雲島擁有了這種水平的宅院，人們一定能生活得更好。",
  str_homestory_814501001_32_dialog_content = "當然，也不止這個方面......",
  str_homestory_814501001_33_dialog_content = "假設我們真的學會了如此先進的技術，那對付起敵人來也會更加得心應手。",
  str_homestory_814501001_34_dialog_content = "空裔的技術和這種精妙的規劃思路......值得我們學習。",
  str_homestory_814501001_35_dialog_content = "原來是這樣......我會記住。",
  str_homestory_814501001_36_dialog_content = "必定幫妳問個清楚明白！",
  str_homestory_814501001_37_dialog_content = "謝謝您，大人。",
  str_homestory_814601001_0_dialog_content = "搖頭晃腦的......",
  str_homestory_814601001_1_dialog_content = "芸芸眾光靈......",
  str_homestory_814601001_2_dialog_content = "均在空庭過。",
  str_homestory_814601001_3_dialog_content = "......？",
  str_homestory_814601001_4_dialog_content = "拱門平地起......",
  str_homestory_814601001_5_dialog_content = "包子手中握！<sprite=emo_yaosu size=60 />",
  str_homestory_814601001_6_dialog_content = "............",
  str_homestory_814601001_7_dialog_content = "瑤，妳在......吟詩嗎？",
  str_homestory_814601001_8_dialog_content = "呀！導航員，是你啊！",
  str_homestory_814601001_9_dialog_content = "說錯啦，我不是在吟詩。",
  str_homestory_814601001_10_dialog_content = "剛才那是我自己創作的一首詩！你覺得怎麼樣？",
  str_homestory_814601001_11_option_content = "好！",
  str_homestory_814601001_12_dialog_content = "太好了！",
  str_homestory_814601001_13_dialog_content = "瑤，妳真是個大文豪！",
  str_homestory_814601001_14_option_content = "還......還好",
  str_homestory_814601001_15_dialog_content = "我覺得這首詩的創作水準......大概介於卡戎和薇絲之間吧？",
  str_homestory_814601001_16_dialog_content = "既不過分浮誇，也不過分寫實，無意間流露出作者內心的某種嚮往......",
  str_homestory_814601001_17_dialog_content = "咳，不過話說回來，拱門和包子有什麼關係？",
  str_homestory_814601001_18_dialog_content = "你看這個拱門，它長得像不像我未來的包子店？",
  str_homestory_814601001_19_dialog_content = "妳又想開包子店了？",
  str_homestory_814601001_20_dialog_content = "難道，妳不想在江湖上行俠仗義了嗎？",
  str_homestory_814601001_21_dialog_content = "當然想呀，我兩件事都想做。",
  str_homestory_814601001_22_dialog_content = "我想把這包子店設定為自己年邁後的歸隱之地，豈不是挺好的嗎？",
  str_homestory_814601001_23_dialog_content = "你也知道，傳說中的大俠往往選擇歸隱在鬧市中的某個地方......",
  str_homestory_814601001_24_dialog_content = "然後偷聽別人談論自己在江湖留下的故事！",
  str_homestory_814601001_25_dialog_content = "傳奇大俠們......真有這麼閒嗎......",
  str_homestory_814601001_26_dialog_content = "先不管他們閒不閒，你先聽聽我的計畫吧！",
  str_homestory_814601001_27_dialog_content = "好好好，妳請講。",
  str_homestory_814601001_28_dialog_content = "首先，第一，包子店最好有三層樓。",
  str_homestory_814601001_29_dialog_content = "一層的一半給阿杏阿桃，請她們販賣美食。另一半給我自己，我也要賣好吃的！",
  str_homestory_814601001_30_dialog_content = "至於第二層，可以用做客棧。如此一來，我的朋友們就不愁沒地方住，我們還可以暢聊一整晚！",
  str_homestory_814601001_31_dialog_content = "再來第三層，就是我的居住區啦！",
  str_homestory_814601001_32_dialog_content = "當然，單有我的房間不夠。還要有雨森、凜音、導航員你、還有薇絲的......",
  str_homestory_814601001_33_dialog_content = "還有柏乃、林家的那些朋友、義姐、還有爸爸媽媽......",
  str_homestory_814601001_34_dialog_content = "有需要幫瀧留一間嗎？女孩子這麼多，他可能不願意來？<sprite=emo_sikao size=60 />",
  str_homestory_814601001_35_dialog_content = "此外，烈雀和知更需不需要呢？",
  str_homestory_814601001_36_dialog_content = "慢著，瑤，妳這樣安排根本賺不到錢......",
  str_homestory_814601001_37_dialog_content = "光是準備朋友的房間就會形成一筆超高額的支出耶？",
  str_homestory_814601001_38_dialog_content = "況且有些人或許更喜歡獨處，不樂見那麼多人擠在一起的生活吧......",
  str_homestory_814601001_39_dialog_content = "錢對我來說才不是問題呢！",
  str_homestory_814601001_40_dialog_content = "唔......不過你提到了「個人喜好」，這確實是個問題......",
  str_homestory_814601001_41_dialog_content = "既然我當他們是朋友，就該替他們準備房間才對啊。",
  str_homestory_814601001_42_dialog_content = "他們願不願意來玩是他們的事，我要不要替他們準備房間是我的事！",
  str_homestory_814601001_43_dialog_content = "嘿嘿，這豈不是兩全其美嗎？誰都不勉強誰嘛。",
  str_homestory_814601001_44_dialog_content = "嗯，妳說得很對......",
  str_homestory_814601001_45_dialog_content = "不過，我想這仍是富有的人才有的思維......",
  str_homestory_816301001_0_dialog_content = "在畫畫嗎？",
  str_homestory_816301001_1_dialog_content = "唔喔喔！<sprite=emo_wuzui size=60 />這豈不是我們的風船大大PlayerName嗎？",
  str_homestory_816301001_2_dialog_content = "終於見面了！我找你找得好苦啊......",
  str_homestory_816301001_3_dialog_content = "咦？找我有什麼事？",
  str_homestory_816301001_4_dialog_content = "我四處找人約稿的途中，發現擺放在這裡的畫板......",
  str_homestory_816301001_5_dialog_content = "薇絲小姐說這畫板是你力排眾議，特意採購來此。",
  str_homestory_816301001_6_dialog_content = "我是否可以把此事理解為......",
  str_homestory_816301001_7_dialog_content = "你終於願意為《白XX光》作畫了？<sprite=emo_yaosu size=60 />",
  str_homestory_816301001_8_option_content = "（肯定）",
  str_homestory_816301001_9_dialog_content = "嗯，確實有一點那個意思。",
  str_homestory_816301001_10_dialog_content = "唔喔喔！你終於肯正視自己的才華了！",
  str_homestory_816301001_11_dialog_content = "咳咳，主要是想找方法緩解財務的緊張狀況。",
  str_homestory_816301001_12_dialog_content = "但憑我的本事，一時半刻也提高不了多少。",
  str_homestory_816301001_13_dialog_content = "所以還是留給喜歡畫畫的人用為上，例如你......",
  str_homestory_816301001_14_option_content = "（否定）",
  str_homestory_816301001_15_dialog_content = "咳咳，我的本事我自己很清楚......",
  str_homestory_816301001_16_dialog_content = "把畫板擺在這裡，只是想讓熱愛繪畫的人有地方揮毫。",
  str_homestory_816301001_17_dialog_content = "風船大大，請摸摸自己的胸口。",
  str_homestory_816301001_18_dialog_content = "你沒發現有一顆熱愛繪畫的心臟在跳動嗎？",
  str_homestory_816301001_19_dialog_content = "若說對繪畫的熱愛，我覺得沒人比得過你耶？",
  str_homestory_816301001_20_dialog_content = "巡迴犬先生。",
  str_homestory_816301001_21_dialog_content = "......！",
  str_homestory_816301001_22_dialog_content = "你不分晝夜找人約稿、製作遊戲，有多久沒好好休息了？",
  str_homestory_816301001_23_dialog_content = "為了製作遊戲，我可以不眠不休。",
  str_homestory_816301001_24_dialog_content = "那你又有多久沒隨心所欲、塗塗畫畫了？",
  str_homestory_816301001_25_dialog_content = "唔喔喔......",
  str_homestory_816301001_26_dialog_content = "你說這麼多，講到底就是希望我在你的畫板上作畫嗎？<sprite=emo_yihuo size=60 />",
  str_homestory_816301001_27_dialog_content = "假使馳名艾斯特拉大陸的巡迴犬先生能在我這裡留下真跡......",
  str_homestory_816301001_28_dialog_content = "那真是再好不過了！",
  str_homestory_816301001_29_dialog_content = "先找出對方的弱點，透過討論治癒，然後恭維對方，最後再提出自己的要求。<sprite=emo_sikao size=60 />",
  str_homestory_816301001_30_dialog_content = "多麼無懈可擊的心理戰術啊。",
  str_homestory_816301001_31_dialog_content = "約稿無數的我，竟然差點被你反約稿。有趣、真有趣！",
  str_homestory_816301001_32_dialog_content = "真不愧是資方欽點的主角！",
  str_homestory_816301001_33_dialog_content = "只要有你在，我確實不必過度操心以後的遊戲劇本變得無聊。",
  str_homestory_816301001_34_option_content = "（詢問資方）",
  str_homestory_816301001_35_dialog_content = "資方？？？",
  str_homestory_816301001_36_dialog_content = "一群有實力且十分看好你的老闆。",
  str_homestory_816301001_37_dialog_content = "你不必介意他們的身分。",
  str_homestory_816301001_38_option_content = "（詢問主角）",
  str_homestory_816301001_39_dialog_content = "主角？？？",
  str_homestory_816301001_40_dialog_content = "遊戲劇本裡的中心人物，所有人都想跟隨的終極明星。",
  str_homestory_816301001_41_dialog_content = "此等地位可不是阿貓阿狗都能獲得。",
  str_homestory_816301001_42_dialog_content = "我越聽越糊塗......",
  str_homestory_816301001_43_dialog_content = "總而言之，風船大大。",
  str_homestory_816301001_44_dialog_content = "我願意免費為你畫一幅空庭圖卷！",
  str_homestory_816301001_45_dialog_content = "畢竟我從你身上學到獨家的約稿心理戰術。",
  str_homestory_816301001_46_dialog_content = "預祝我們合作愉快。<sprite=emo_guilian size=60 />",
  str_homestory_816301001_47_dialog_content = "合......合作愉快......",
  str_homestory_816301001_48_dialog_content = "很好，我要仔細思考這幅畫的構圖。",
  str_homestory_816301001_49_dialog_content = "過去照例我只需要三秒，但既是為風船大大作畫，必當奉上最大誠意。",
  str_homestory_816301001_50_dialog_content = "嗯......",
  str_homestory_816301001_51_dialog_content = "怎麼畫才好呢......",
  str_homestory_816301001_52_dialog_content = "那我......就先不打擾了......",
  str_homestory_816301001_53_dialog_content = "（他彷彿已經聽不見我說話了？）",
  str_homestory_816301001_54_dialog_content = "（趕快開溜。）",
  str_homestory_814801001_0_dialog_content = "她來了？",
  str_homestory_814801001_1_dialog_content = "青瞳......",
  str_homestory_814801001_2_dialog_content = "嗯？",
  str_homestory_814801001_3_dialog_content = "這是誰的小臉蛋啊，真可愛。",
  str_homestory_814801001_4_dialog_content = "過來呀，讓姐姐揉揉看手感好不好嘛。",
  str_homestory_814801001_5_dialog_content = "啊啊啊<sprite=emo_yundao size=60 />......住手！",
  str_homestory_814801001_6_dialog_content = "是我啦，我是PlayerName啊。",
  str_homestory_814801001_7_dialog_content = "PlayerName？這名字聽起來有點耳熟呢。",
  str_homestory_814801001_8_dialog_content = "喔～哈哈哈，我想起來了！",
  str_homestory_814801001_9_dialog_content = "是我那個空裔小男友的名字吧？",
  str_homestory_814801001_10_option_content = "（承認）",
  str_homestory_814801001_11_dialog_content = "......對啦，就是我。",
  str_homestory_814801001_12_dialog_content = "喔唷？承認了？",
  str_homestory_814801001_13_dialog_content = "既然承認，你可要負起責任啊。",
  str_homestory_814801001_14_option_content = "（否認）",
  str_homestory_814801001_15_dialog_content = "青瞳，請別胡說八道了......",
  str_homestory_814801001_16_dialog_content = "讓別人聽到了可會被當真的。",
  str_homestory_814801001_17_dialog_content = "喔唷？你在怕什麼呀？",
  str_homestory_814801001_18_dialog_content = "怕被啟光的龍尾巴小妹妹聽到？",
  str_homestory_814801001_19_dialog_content = "還是怕被白夜城的冷淡小公主聽到啊？",
  str_homestory_814801001_20_dialog_content = "......",
  str_homestory_814801001_21_dialog_content = "紅通通的小臉蛋，又急又氣......愈發可愛了呢，哈哈哈。",
  str_homestory_814801001_22_dialog_content = "我......我先走一步......<sprite=emo_hanshui size=60 />",
  str_homestory_814801001_23_dialog_content = "好啦好啦，姐姐不拿你尋開心了。",
  str_homestory_814801001_24_dialog_content = "你剛才找我，不是有事嗎？",
  str_homestory_814801001_25_dialog_content = "我只想問一句......妳住得還習慣嗎？",
  str_homestory_814801001_26_dialog_content = "喔唷？我的小空裔學會關心人了呢，真是感動呀。",
  str_homestory_814801001_27_dialog_content = "託你的福，我在這裡住得很開心喔。",
  str_homestory_814801001_28_dialog_content = "和燥熱荒涼的沙漠不同，這裡有許多綠色植物。",
  str_homestory_814801001_29_dialog_content = "溫度適宜、空氣濕潤，連風都輕柔暖和。",
  str_homestory_814801001_30_dialog_content = "令人生厭的傢伙也少了許多。",
  str_homestory_814801001_31_dialog_content = "簡直是個純天然美容療養院啊......",
  str_homestory_814801001_32_dialog_content = "你看，我最近是不是變漂亮了？",
  str_homestory_814801001_33_option_content = "（肯定）",
  str_homestory_814801001_34_dialog_content = "確實比以前更漂亮，已經漂亮到了極點......",
  str_homestory_814801001_35_option_content = "（否定）",
  str_homestory_814801001_36_dialog_content = "妳本來就漂亮到沒辦法更漂亮了。",
  str_homestory_814801001_37_dialog_content = "你剛剛是灌了幾升蜜啊，嘴這麼甜？",
  str_homestory_814801001_38_dialog_content = "看來我該在這裡多待一點時間，才對得起你的熱情款待囉？",
  str_homestory_814801001_39_dialog_content = "話說小空裔，你希望我在這裡長住嗎？",
  str_homestory_814801001_40_option_content = "（肯定）",
  str_homestory_814801001_41_dialog_content = "嗯......妳想住多久就住多久。",
  str_homestory_814801001_42_dialog_content = "這裡的大門永遠為妳敞開。",
  str_homestory_814801001_43_option_content = "（否定）",
  str_homestory_814801001_44_dialog_content = "我......我不會限制大家......",
  str_homestory_814801001_45_dialog_content = "大家想來就來，想走就走......",
  str_homestory_814801001_46_dialog_content = "既然你都這麼說，我就不跟你客氣了喔？",
  str_homestory_814801001_47_dialog_content = "請你叫商店再多進點好酒吧。",
  str_homestory_814801001_48_dialog_content = "姐姐我已經等不及了，懂嗎？",
  str_homestory_814801001_49_dialog_content = "嗯......",
  str_homestory_814801001_50_dialog_content = "那還不快去辦？<sprite=emo_emo size=60 />",
  str_homestory_814801001_51_dialog_content = "馬上去！",
  str_homestory_815001001_0_dialog_content = "一動也不動......",
  str_homestory_815001001_1_dialog_content = "PlayerName，你好。<sprite=emo_heimao size=60 />",
  str_homestory_815001001_2_dialog_content = "蓮很高興見到你。",
  str_homestory_815001001_3_dialog_content = "蓮，妳怎麼站在這裡發呆啊？",
  str_homestory_815001001_4_dialog_content = "不想四處逛逛嗎？",
  str_homestory_815001001_5_dialog_content = "四處逛逛？",
  str_homestory_815001001_6_dialog_content = "這是PlayerName對蓮下達的，新命令嗎？",
  str_homestory_815001001_7_dialog_content = "具體地說，需要去哪幾個地方逛逛呢？",
  str_homestory_815001001_8_dialog_content = "蓮，這不是命令，只算是一種建議吧。",
  str_homestory_815001001_9_dialog_content = "建議和命令有何不同？",
  str_homestory_815001001_10_dialog_content = "嗯......我想想。",
  str_homestory_815001001_11_dialog_content = "命令就是......別人要求妳必須達成某件事。",
  str_homestory_815001001_12_dialog_content = "建議就是別人告訴妳可以去做某件事，但妳也可以選擇不做。",
  str_homestory_815001001_13_dialog_content = "蓮明白了。",
  str_homestory_815001001_14_dialog_content = "PlayerName建議蓮四處逛逛，只是一個建議。",
  str_homestory_815001001_15_dialog_content = "所以蓮可以選擇四處逛逛，也可以選擇不去四處逛逛。",
  str_homestory_815001001_16_dialog_content = "蓮真聰明，這麼快就聽懂了！",
  str_homestory_815001001_17_dialog_content = "謝謝PlayerName的誇獎。",
  str_homestory_815001001_18_dialog_content = "不客氣～",
  str_homestory_815001001_19_dialog_content = "......",
  str_homestory_815001001_20_dialog_content = "......",
  str_homestory_815001001_21_dialog_content = "......",
  str_homestory_815001001_22_dialog_content = "呃，蓮？",
  str_homestory_815001001_23_dialog_content = "妳不打算四處逛逛嗎？",
  str_homestory_815001001_24_dialog_content = "那只是一個建議，不是嗎？",
  str_homestory_815001001_25_dialog_content = "蓮可以選擇不做。",
  str_homestory_815001001_26_dialog_content = "啊，這......",
  str_homestory_815001001_27_dialog_content = "我這幾天種了好多漂亮的花草樹木，還裝設多種娛樂設施！",
  str_homestory_815001001_28_dialog_content = "妳不想看看嗎？",
  str_homestory_815001001_29_dialog_content = "蓮應該想去，應該想看嗎？",
  str_homestory_815001001_30_option_content = "（命令）",
  str_homestory_815001001_31_dialog_content = "唉......實在沒轍。好吧，我命令蓮到處逛逛。",
  str_homestory_815001001_32_dialog_content = "收到，蓮會完成命令。",
  str_homestory_815001001_33_option_content = "（建議）",
  str_homestory_815001001_34_dialog_content = "雖然聽起來像自誇，但我覺得自己佈置得挺不錯。",
  str_homestory_815001001_35_dialog_content = "所以......我覺得妳應該會想去看？",
  str_homestory_815001001_36_dialog_content = "既然PlayerName都說到這個份上，蓮還是應允為佳。",
  str_homestory_815001001_37_dialog_content = "嗯，去看看吧。",
  str_homestory_815001001_38_dialog_content = "但是，蓮應該去看哪些地方？",
  str_homestory_815001001_39_dialog_content = "PlayerName想建議蓮去哪裡？",
  str_homestory_815001001_40_dialog_content = "欸！！！",
  str_homestory_815001001_41_dialog_content = "PlayerName，怎麼了？",
  str_homestory_815001001_42_dialog_content = "沒事沒事......",
  str_homestory_815001001_43_dialog_content = "忽然感覺蓮好像真的明白「建議」是什麼意思。",
  str_homestory_815001001_44_dialog_content = "意外地感動哩......",
  str_homestory_801901001_0_dialog_content = "維多利亞女士......",
  str_homestory_801901001_1_dialog_content = "您好，PlayerName。",
  str_homestory_801901001_2_dialog_content = "維多利亞女士！您好。",
  str_homestory_801901001_3_dialog_content = "我正在欣賞這些歡樂的水流。要加入我嗎？",
  str_homestory_801901001_4_dialog_content = "欣賞流水......？",
  str_homestory_801901001_5_dialog_content = "請問......山石上的流水有何欣賞價值呢？",
  str_homestory_801901001_6_dialog_content = "這道流水，在一無所知的情況下加入了無盡的循環。",
  str_homestory_801901001_7_dialog_content = "不覺得和光靈們有不少相似之處嗎？",
  str_homestory_801901001_8_option_content = "（點頭）",
  str_homestory_801901001_9_dialog_content = "好像有一點......",
  str_homestory_801901001_10_dialog_content = "但我不是很能體會維多利亞女士的意思......",
  str_homestory_801901001_11_option_content = "（搖頭）",
  str_homestory_801901001_12_dialog_content = "抱歉，維多利亞女士......",
  str_homestory_801901001_13_dialog_content = "我聽不懂。",
  str_homestory_801901001_14_dialog_content = "沒關係，我也只是發出一些毫無意義的感慨。",
  str_homestory_801901001_15_dialog_content = "維多利亞女士是怎麼得出這樣的感想？",
  str_homestory_801901001_16_dialog_content = "水流並不知道自己在遵照某種循環吧。",
  str_homestory_801901001_17_dialog_content = "因為水流本身毫無目的地在做這件事。",
  str_homestory_801901001_18_dialog_content = "不知道為什麼、不知道怎麼脫離循環、也不知道這種循環何時才會結束。",
  str_homestory_801901001_19_dialog_content = "和絕大部分人的生活豈不是很相似嗎？",
  str_homestory_801901001_20_dialog_content = "當然，對此我並不抱持指責或憐憫的態度。",
  str_homestory_801901001_21_dialog_content = "對我而言，怎樣的生活方式都沒有差。",
  str_homestory_801901001_22_dialog_content = "我只是在嘗試思考。",
  str_homestory_801901001_23_dialog_content = "......嘗試思考。",
  str_homestory_801901001_24_dialog_content = "是啊。",
  str_homestory_801901001_25_dialog_content = "要對思考致敬，能產生如此動力的往往是目前尚無法理解的事。",
  str_homestory_801901001_26_dialog_content = "......您的意思是，面對未知應該心懷尊敬嗎？",
  str_homestory_801901001_27_dialog_content = "差不多是如此，親愛的。",
  str_homestory_801901001_28_dialog_content = "不過，也許水流們本身很快樂，根本沒有我置喙的餘地。",
  str_homestory_801901001_29_dialog_content = "在這種循環中開心快樂，也是件好事。",
  str_homestory_801901001_30_dialog_content = "意思是說，不必像維多利亞女士這樣產生感慨的開心快樂嗎？",
  str_homestory_801901001_31_dialog_content = "呵呵～誰知道呢？",
  str_homestory_801901001_32_dialog_content = "不過說起來......你這裡的陽光還真強烈<sprite=emo_taiyang size=60 />呢。",
  str_homestory_801901001_33_dialog_content = "呃，那邊有遮陽傘，維多利亞女士不如到那邊歇一下吧？",
  str_homestory_801901001_34_dialog_content = "謝謝您的關心，PlayerName，但我想休息了。",
  str_homestory_801901001_35_dialog_content = "願真理祝福您。",
  str_homestory_800901001_0_dialog_content = "浮士德先生？",
  str_homestory_800901001_1_dialog_content = "親愛的導航員，又見面了。",
  str_homestory_800901001_2_dialog_content = "是啊。",
  str_homestory_800901001_3_dialog_content = "不過我沒想到會在白天見到你。",
  str_homestory_800901001_4_dialog_content = "請不要誤會，儘管我個人更喜歡夜晚，也不會抗拒來自白晝的能量。",
  str_homestory_800901001_5_dialog_content = "白箱似乎也很喜歡這裡。",
  str_homestory_800901001_6_dialog_content = "......等等，白箱喜歡這裡代表什麼意思......？",
  str_homestory_800901001_7_dialog_content = "難道這裡有著許多悲傷與絕望嗎？",
  str_homestory_800901001_8_dialog_content = "我記得這個「特別」的小箱子，曾經對我的束手無策流口水哩......",
  str_homestory_800901001_9_dialog_content = "也可能是其他東西讓白箱覺得舒適。",
  str_homestory_800901001_10_dialog_content = "或者是「悲傷記憶」、「噩夢」、「絕望信仰」以及「冰水」其中任一種......",
  str_homestory_800901001_11_dialog_content = "啊？！",
  str_homestory_800901001_12_dialog_content = "（回想之前照顧白箱的體驗......<sprite=emo_sikao size=60 />）",
  str_homestory_800901001_13_dialog_content = "（難道大家住在這裡，不僅感到悲傷，還會做噩夢？！）",
  str_homestory_800901001_14_dialog_content = "親愛的導航員，請勿多慮。",
  str_homestory_800901001_15_dialog_content = "白箱感到舒適的原因......",
  str_homestory_800901001_16_dialog_content = "也許來自光靈們過往的經歷，而不是他們當下的感受。",
  str_homestory_800901001_17_dialog_content = "據我所知，您認識不少懷著慘痛過去的人呢。",
  str_homestory_800901001_18_dialog_content = "這麼說來......",
  str_homestory_800901001_19_dialog_content = "嗯......確實是這樣。",
  str_homestory_800901001_20_dialog_content = "但我還是希望大家待在這裡都能盡量地感到開心啊。",
  str_homestory_800901001_21_dialog_content = "回憶和情緒向來無法完全控制，親愛的導航員。",
  str_homestory_800901001_22_dialog_content = "不過度地關心他人也是一個好習性。",
  str_homestory_800901001_23_dialog_content = "就讓一切順其自然吧。",
  str_homestory_800901001_24_dialog_content = "......好吧。",
  str_homestory_800901001_25_dialog_content = "所以你站在這裡的原因是？",
  str_homestory_800901001_26_option_content = "傳播真理？",
  str_homestory_800901001_27_dialog_content = "那倒不是，親愛的導航員。",
  str_homestory_800901001_28_option_content = "餵食白箱？",
  str_homestory_800901001_29_dialog_content = "是啊，親愛的導航員。",
  str_homestory_800901001_30_dialog_content = "此地是餵食白箱的最佳地點......",
  str_homestory_800901001_31_dialog_content = "白箱可以自由感知來往的人們。",
  str_homestory_800901001_32_dialog_content = "「白箱可以自由感知......」",
  str_homestory_800901001_33_dialog_content = "呃......難不成大家內心都抱著難以言明的痛苦嗎？",
  str_homestory_800901001_34_dialog_content = "親愛的導航員，我無法確定。",
  str_homestory_800901001_35_dialog_content = "不過......我唯一能確定的只有一件事。",
  str_homestory_800901001_36_dialog_content = "嗯？",
  str_homestory_800901001_37_dialog_content = "就是白箱出門前，在房間裡喝了不少冰水。",
  str_homestory_800901001_38_dialog_content = "......？",
  str_homestory_800901001_39_dialog_content = "所以說白箱之覺得舒適，只因為它喝了夠多冰水？！",
  str_homestory_800901001_40_dialog_content = "也就是說，大家沒那麼多負面情緒，諸如悲傷或痛苦之流。",
  str_homestory_800901001_41_dialog_content = "可惡，搞半天......我被你戲弄了吧？！",
  str_homestory_800901001_42_dialog_content = "恐怕是的，導航員。",
  str_homestory_800901001_43_dialog_content = "不過......此舉只是希望您不要過於勞心。",
  str_homestory_800901001_44_dialog_content = "不必把每件事、每個人都照顧得盡善盡美，不是嗎？",
  str_homestory_800901001_45_dialog_content = "願真理祝福您。",
  str_homestory_800901001_46_dialog_content = "......你這傢伙......！<sprite=emo_shengqi size=60 />",
  str_homestory_815101001_0_dialog_content = "這首童謠......",
  str_homestory_815101001_1_dialog_content = "「黑黑的羊羔叫以撒，燙手的絨毛真可怕......」",
  str_homestory_815101001_2_dialog_content = "嘿，賈爾斯！",
  str_homestory_815101001_3_dialog_content = "喔～是親愛的導航員啊。",
  str_homestory_815101001_4_dialog_content = "我差點忘了，這首童謠你已經聽過。",
  str_homestory_815101001_5_dialog_content = "看來是時候來點新玩意兒囉。",
  str_homestory_815101001_6_dialog_content = "以神祕空裔為主角的、帶有某種預言性質的新作品......<sprite=emo_baimao size=60 />",
  str_homestory_815101001_7_dialog_content = "呃......",
  str_homestory_815101001_8_dialog_content = "導航員先生？為什麼你一臉心不甘情不願的樣子呢？",
  str_homestory_815101001_9_dialog_content = "你這副樣子可是會讓我感到悲傷啊......",
  str_homestory_815101001_10_dialog_content = "你之前不是說最喜歡聽我的童謠嗎？",
  str_homestory_815101001_11_dialog_content = "（......我何年何月說過這樣的話？）",
  str_homestory_815101001_12_option_content = "你寫完了？",
  str_homestory_815101001_13_dialog_content = "若有靈感，寫起來很快的。",
  str_homestory_815101001_14_dialog_content = "剛好，靈感之源就站在我的面前......",
  str_homestory_815101001_15_option_content = "能等一下嗎？",
  str_homestory_815101001_16_dialog_content = "完全沒理由可推脫嗎？",
  str_homestory_815101001_17_dialog_content = "這對我來說可謂一種乾脆俐落的拒絕呢。",
  str_homestory_815101001_18_dialog_content = "迷人的空裔，靈巧的空裔，輕易就能讓人心靈失守的空裔......",
  str_homestory_815101001_19_dialog_content = "......要開始了嗎？",
  str_homestory_815101001_20_dialog_content = "「啦啦啦，啦啦啦，迷人的房子裡有鮮花。」",
  str_homestory_815101001_21_dialog_content = "「有小魚，有小蝦，他們把這裡當做家。」",
  str_homestory_815101001_22_dialog_content = "「這裡住著牠和她，簇擁著什麼也不怕的他。」",
  str_homestory_815101001_23_dialog_content = "「淅瀝瀝，嘩啦啦，時間的雨一點一滴地落下。」",
  str_homestory_815101001_24_dialog_content = "「建起高塔，武裝磚瓦，尋找變得更大更強的方法。」",
  str_homestory_815101001_25_dialog_content = "「啦啦啦，啦啦啦，那個他到哪去啦？」",
  str_homestory_815101001_26_dialog_content = "「原來家早已變高大，你看他在雲端，眼也不眨。」",
  str_homestory_815101001_27_dialog_content = "「啦啦啦，啦啦啦......迷人的房子裡有鮮花......」",
  str_homestory_815101001_28_dialog_content = "......這，這是你的預言嗎？",
  str_homestory_815101001_29_dialog_content = "只是一首單純的童謠而已喔，導航員？",
  str_homestory_815101001_30_dialog_content = "你為何害怕？我只是在創作而已......",
  str_homestory_815101001_31_dialog_content = "嗯......我知道。",
  str_homestory_815101001_32_dialog_content = "只不過，賈爾斯的童謠......經常給人一種既單純又晦澀的感覺。",
  str_homestory_815101001_33_dialog_content = "童謠就是童謠。",
  str_homestory_815101001_34_dialog_content = "導航員千萬別想太多。",
  str_homestory_815101001_35_dialog_content = "好吧，還是來說些更實際的東西好了......",
  str_homestory_815101001_36_dialog_content = "你覺得這裡怎麼樣？住得還習慣嗎？",
  str_homestory_815101001_37_dialog_content = "我和以撒都很喜歡這裡呢。",
  str_homestory_815101001_38_dialog_content = "此地經常激發我強烈的創作慾望......哈哈！",
  str_homestory_815101001_39_dialog_content = "無論是往來的人群，還是導航員本人......對我來說都是無與倫比的素材呢。<sprite=emo_emo size=60 />",
  str_homestory_815101001_40_dialog_content = "好吧......",
  str_homestory_815101001_41_dialog_content = "咩～咩咩～",
  str_homestory_815101001_42_dialog_content = "我要和以撒單獨相處一會，導航員。",
  str_homestory_815101001_43_dialog_content = "我們下次再見吧？",
  str_homestory_815101001_44_dialog_content = "嗯......那就下次見。",
  str_homestory_815301001_0_dialog_content = "大元帥？",
  str_homestory_815301001_1_dialog_content = "你這裡的基建做得不錯。<sprite=emo_dianzan size=60 />",
  str_homestory_815301001_2_dialog_content = "大元帥！謝謝您的誇獎！",
  str_homestory_815301001_3_dialog_content = "看慣啟光那方正統一的廣場，再看你這裡，感受截然不同哩。",
  str_homestory_815301001_4_dialog_content = "人人都說我們啟光不懂藝術、不追求美感。",
  str_homestory_815301001_5_dialog_content = "可惜那些格外追求藝術的地方還有好一部分人填不飽肚子。",
  str_homestory_815301001_6_dialog_content = "統一標準的東西成本低，效益高，這是個單純的道理。",
  str_homestory_815301001_7_dialog_content = "總之此處依然甚是美麗。",
  str_homestory_815301001_8_dialog_content = "美麗又整潔，想必你和薇絲下了不少工夫。",
  str_homestory_815301001_9_option_content = "（點頭）",
  str_homestory_815301001_10_dialog_content = "主要是薇絲在操勞......我對建築之類的研究真的很有限。",
  str_homestory_815301001_11_dialog_content = "嗯，能夠承認自己的不足已經是一種優點。",
  str_homestory_815301001_12_option_content = "（搖頭）",
  str_homestory_815301001_13_dialog_content = "還好啦，螢盞幫了我們不少忙，信使公會的朋友們也是。",
  str_homestory_815301001_14_dialog_content = "只要大家覺得開心就夠，我們其實也沒做什麼特別的事。",
  str_homestory_815301001_15_dialog_content = "這不就是你們身上最難得的特質嗎？",
  str_homestory_815301001_16_dialog_content = "對我來說，沒什麼特別就是一種特別。",
  str_homestory_815301001_17_dialog_content = "遵循你的安排，在這裡......",
  str_homestory_815301001_18_dialog_content = "我和薇絲住在一樣的房間，吃一樣的食物。",
  str_homestory_815301001_19_dialog_content = "這已經比其他大部分人對我的態度好很多了。",
  str_homestory_815301001_20_dialog_content = "不因他人身居高位而另眼相待，這種平等的對待方式很難得。",
  str_homestory_815301001_21_dialog_content = "（倒是沒想到大元帥會從這個角度思考事情......）",
  str_homestory_815301001_22_dialog_content = "（我該不該說實話呢？）",
  str_homestory_815301001_23_dialog_content = "（好吧，還是老實說吧......）",
  str_homestory_815301001_24_dialog_content = "咳，大元帥，其實......",
  str_homestory_815301001_25_dialog_content = "我們也沒有多餘的錢建造更好的房間......",
  str_homestory_815301001_26_dialog_content = "嗯，我知道。",
  str_homestory_815301001_27_dialog_content = "重點不是預算多寡，而是你最初的規劃——要怎麼花這筆錢。",
  str_homestory_815301001_28_dialog_content = "嗯，好像有點懂了......",
  str_homestory_815301001_29_dialog_content = "你懂就好。",
  str_homestory_815301001_30_dialog_content = "我想去看看其他啟光同胞們在做什麼。",
  str_homestory_815301001_31_dialog_content = "PlayerName，再見。",
  str_homestory_815301001_32_dialog_content = "再......再見，大元帥！",
  str_homestory_803801001_0_dialog_content = "又在玩遊戲嗎？",
  str_homestory_803801001_1_dialog_content = "嗨！PlayerName！",
  str_homestory_803801001_2_dialog_content = "嘿嘿......你特地來找我，肯定是要來跟我玩遊戲吧？",
  str_homestory_803801001_3_dialog_content = "呃，不是。",
  str_homestory_803801001_4_dialog_content = "我只是想問妳覺得這個地方如何，習不習慣這裡的生活。",
  str_homestory_803801001_5_dialog_content = "唔......",
  str_homestory_803801001_6_dialog_content = "還過得去啦，就是娛樂設施少了一點。",
  str_homestory_803801001_7_dialog_content = "喔～我懂了，貼心的PlayerName是想來幫我排遣無聊，對嗎？",
  str_homestory_803801001_8_dialog_content = "呃......我......",
  str_homestory_803801001_9_dialog_content = "嘿嘿！那麼我們索性來玩個簡單的小遊戲吧......",
  str_homestory_803801001_10_dialog_content = "非常簡單喔！不需要任何道具就能一起遊玩！",
  str_homestory_803801001_11_dialog_content = "妳是指......剪刀石頭布？",
  str_homestory_803801001_12_dialog_content = "才不是呢！是——問答遊戲！",
  str_homestory_803801001_13_dialog_content = "準備好了嗎？遊戲馬上就要開始囉。",
  str_homestory_803801001_14_dialog_content = "好吧......看妳這麼期待的樣子......開始吧。",
  str_homestory_803801001_15_dialog_content = "第一題！請回答是或否！",
  str_homestory_803801001_16_dialog_content = "「揭露啟光科研長貢露的神祕身世......她其實......是個——機器人！」",
  str_homestory_803801001_17_option_content = "是",
  str_homestory_803801001_18_dialog_content = "什麼嘛？人家才不是機器人呢！",
  str_homestory_803801001_19_option_content = "否",
  str_homestory_803801001_20_dialog_content = "叮咚！答對囉！<sprite=emo_dianzan size=60 />",
  str_homestory_803801001_21_dialog_content = "第二題！",
  str_homestory_803801001_22_dialog_content = "拉斐爾曾在「王座盃」比賽打敗過貢露！",
  str_homestory_803801001_23_option_content = "是",
  str_homestory_803801001_24_dialog_content = "喂，擺明是我比她厲害才對吧？",
  str_homestory_803801001_25_dialog_content = "我甚至還幫她改造過那些小玩具呢～",
  str_homestory_803801001_26_option_content = "否",
  str_homestory_803801001_27_dialog_content = "正確的選擇！年輕人！",
  str_homestory_803801001_28_dialog_content = "第三題！",
  str_homestory_803801001_29_dialog_content = "PlayerName會把這裡的系統運行權限移交給貢露！",
  str_homestory_803801001_30_dialog_content = "是......",
  str_homestory_803801001_31_dialog_content = "慢著，這壓根不是問答遊戲應該出現的問題吧？",
  str_homestory_803801001_32_dialog_content = "哎呀，不行嗎？",
  str_homestory_803801001_33_dialog_content = "咳......當然不行啊，貢露。",
  str_homestory_803801001_34_dialog_content = "哼哼，竟然拒絕我？",
  str_homestory_803801001_35_dialog_content = "你一定是被最終BOSS之類的給操控了吧！",
  str_homestory_803801001_36_dialog_content = "操控？為什麼這麼說？",
  str_homestory_803801001_37_dialog_content = "真正的空裔，怎麼會對我說出「不行」兩個字呢？",
  str_homestory_803801001_38_dialog_content = "和藹可親的空裔少年之前總是同意我的諸多請求啊！",
  str_homestory_803801001_39_dialog_content = "噗......",
  str_homestory_803801001_40_dialog_content = "其他的都可以，只有巨像和這裡的權限不行喔，貢露。",
  str_homestory_803801001_41_dialog_content = "喔......真沒意思......",
  str_homestory_803801001_42_dialog_content = "不過......",
  str_homestory_803801001_43_dialog_content = "既然你不讓我光明正大研究，那我只好偷偷來囉！",
  str_homestory_803801001_44_dialog_content = "總有一天......嘿嘿，總有一天，我會搞懂這裡的系統究竟如何運轉。",
  str_homestory_803801001_45_dialog_content = "好......好吧。",
  str_homestory_803801001_46_dialog_content = "祝妳好運？",
  str_homestory_803801001_47_dialog_content = "新遊戲已經開始了！真讓人期待呢......<sprite=emo_yaosu size=60 />",
  str_homestory_802601001_0_dialog_content = "烏列爾......",
  str_homestory_802601001_1_dialog_content = "......",
  str_homestory_802601001_2_dialog_content = "............",
  str_homestory_802601001_3_dialog_content = "你......有何貴幹......",
  str_homestory_802601001_4_dialog_content = "啊，是沒什麼特別的事情......只是來探望妳。",
  str_homestory_802601001_5_dialog_content = "尤其擔心妳哪裡不習慣，畢竟妳在巨像上經常失眠，輾轉反側。",
  str_homestory_802601001_6_dialog_content = "沒有什麼不習慣......",
  str_homestory_802601001_7_dialog_content = "畢竟我唯二習慣的事物......只有我的控火之環和羽衣......",
  str_homestory_802601001_8_dialog_content = "呃......那妳是否還需要其他東西？",
  str_homestory_802601001_9_dialog_content = "例如食物、玩具......或者其他喜歡的？",
  str_homestory_802601001_10_dialog_content = "有任何需求，都可以告訴我！",
  str_homestory_802601001_11_dialog_content = "我......我沒有想要什麼......",
  str_homestory_802601001_12_dialog_content = "反正我也會把它們燒<sprite=emo_nuhuo size=60 />個精光......",
  str_homestory_802601001_13_dialog_content = "不不不，不會的，烏列爾。",
  str_homestory_802601001_14_dialog_content = "我還特意做了防火設施，妳大可放心，請毫無顧慮地在此生活！",
  str_homestory_802601001_15_dialog_content = "這樣啊......",
  str_homestory_802601001_16_dialog_content = "嗯嗯！",
  str_homestory_802601001_17_dialog_content = "那，有想到任何需求嗎？",
  str_homestory_802601001_18_dialog_content = "......",
  str_homestory_802601001_19_dialog_content = "............沒有。",
  str_homestory_802601001_20_dialog_content = "玩具也好，娛樂設施也罷......這些帶來的快樂轉瞬即逝......",
  str_homestory_802601001_21_dialog_content = "不僅短暫，還很廉價......",
  str_homestory_802601001_22_dialog_content = "享受這種流逝於分秒間的快樂過後，緊接著又是無窮無盡的痛苦......",
  str_homestory_802601001_23_dialog_content = "一想到承受這種痛苦焚燒的代價只能換取那麼短暫的快樂......",
  str_homestory_802601001_24_dialog_content = "就覺得......還不如不要這種快樂......",
  str_homestory_802601001_25_dialog_content = "況且......並不是每次痛苦過後，都一定能得到「快樂」......",
  str_homestory_802601001_26_dialog_content = "相反地，這種短暫「快樂」還會讓人誤以為所有痛苦都有價值......",
  str_homestory_802601001_27_dialog_content = "但實際並不是這樣的......因為痛苦是無窮無盡的，而「快樂」是非常有限的......<sprite=emo_xinsui size=60 />",
  str_homestory_802601001_28_dialog_content = "......我說得不對嗎？PlayerName......",
  str_homestory_802601001_29_dialog_content = "（乍聽沒有錯誤，但為何我無法理解她的邏輯......）",
  str_homestory_802601001_30_option_content = "對",
  str_homestory_802601001_31_dialog_content = "某個層面上，或許妳說的沒錯，烏列爾。",
  str_homestory_802601001_32_option_content = "不對",
  str_homestory_802601001_33_dialog_content = "我能理解烏列爾的想法，但我的觀點可能不太一樣......",
  str_homestory_802601001_34_dialog_content = "（無論如何，還是先安撫她的情緒比較重要......）",
  str_homestory_802601001_35_dialog_content = "雖然烏列爾覺得痛苦之後的快樂很廉價，很短暫......",
  str_homestory_802601001_36_dialog_content = "但還是有很多人就指望著這些許的「快樂」而活著喔？",
  str_homestory_802601001_37_dialog_content = "有時候，人們會把經歷痛苦所得的「快樂」想成「希望」。",
  str_homestory_802601001_38_dialog_content = "這種「希望」引領人們期待下一次、再下一次的「快樂」......",
  str_homestory_802601001_39_dialog_content = "哪怕每次的快樂都很短暫，很微小，好歹是一時的慰藉呢。",
  str_homestory_802601001_40_dialog_content = "「快樂」並不是痛苦過後的獎勵。",
  str_homestory_802601001_41_dialog_content = "相反地，它不過是一種能讓人繼續忍受痛苦的食糧。",
  str_homestory_802601001_42_dialog_content = "......",
  str_homestory_802601001_43_dialog_content = "......食糧......",
  str_homestory_802601001_44_dialog_content = "......也許吧......",
  str_homestory_802601001_45_dialog_content = "（好吧，看來她並不這麼想......）",
  str_homestory_802601001_46_dialog_content = "啊......總之，烏列爾別把快樂當成一種負擔就好了！",
  str_homestory_802601001_47_dialog_content = "......嗯......",
  str_homestory_802601001_48_dialog_content = "......我知道，PlayerName......",
  str_homestory_802601001_49_dialog_content = "......謝謝......你的關心......",
  str_homestory_802601001_50_dialog_content = "別，千萬別客氣......",
  str_homestory_802601001_51_dialog_content = "啊......說到快樂......",
  str_homestory_802601001_52_dialog_content = "（我記得她好像滿喜歡看書？喜歡那種......在影鎮很流行的「文學作品」......）",
  str_homestory_802601001_53_dialog_content = "對了，烏列爾，不如我幫妳借幾本書吧？",
  str_homestory_802601001_54_dialog_content = "如果覺得無聊的話，妳可以看看書。",
  str_homestory_802601001_55_dialog_content = "放心，畢竟這裡住著很多人，每種書我都準備了很多本......",
  str_homestory_802601001_56_dialog_content = "......書啊......",
  str_homestory_802601001_57_dialog_content = "............",
  str_homestory_802601001_58_dialog_content = "......好吧......",
  str_homestory_802601001_59_dialog_content = "我會看......",
  str_homestory_802601001_60_dialog_content = "呼......那就好。",
  str_homestory_804401001_0_dialog_content = "薇薇安？",
  str_homestory_804401001_1_dialog_content = "盪鞦韆真的很好玩耶，PlayerName！",
  str_homestory_804401001_2_dialog_content = "嗯，我也覺得很有趣。",
  str_homestory_804401001_3_dialog_content = "風輕輕吹在臉上，拋開一切思緒......<sprite=emo_pugongying size=60 />",
  str_homestory_804401001_4_dialog_content = "鞦韆會緩緩地把身體的重量送進風裡......",
  str_homestory_804401001_5_dialog_content = "壓力，就這樣神奇地被消除了呢。",
  str_homestory_804401001_6_dialog_content = "能讓妳覺得輕鬆就好。",
  str_homestory_804401001_7_dialog_content = "唔，這麼說來，這項娛樂唯一的缺點可能是......",
  str_homestory_804401001_8_dialog_content = "盪完鞦韆後，髮型會稍微亂掉～哈哈。",
  str_homestory_804401001_9_dialog_content = "原來如此！",
  str_homestory_804401001_10_dialog_content = "怪不得薇絲每次盪完鞦韆之後都會整理髮型！",
  str_homestory_804401001_11_dialog_content = "喔喔～這麼說來，這鞦韆是你還是薇絲提議建造的呀？",
  str_homestory_804401001_12_option_content = "是我",
  str_homestory_804401001_13_dialog_content = "其實我沒有多少盪鞦韆的經驗......",
  str_homestory_804401001_14_dialog_content = "所以就想，放一個在這裡也不錯？",
  str_homestory_804401001_15_option_content = "是薇絲",
  str_homestory_804401001_16_dialog_content = "薇絲強烈要求在這裡設置一座鞦韆！",
  str_homestory_804401001_17_dialog_content = "本來我還有點猶豫的，但見她信心滿滿地開始畫施工圖紙，我就......",
  str_homestory_804401001_18_dialog_content = "放個鞦韆在這裡也不錯啊，相信大家都會喜歡。",
  str_homestory_804401001_19_dialog_content = "哎呀......",
  str_homestory_804401001_20_dialog_content = "這是個很棒的決定呢！",
  str_homestory_804401001_21_dialog_content = "嘿嘿......謝謝妳的誇獎，薇薇安。",
  str_homestory_804401001_22_dialog_content = "不過現在想想......",
  str_homestory_804401001_23_dialog_content = "啟光各地區好像很少看到鞦韆呢。",
  str_homestory_804401001_24_dialog_content = "嗯......好像是？",
  str_homestory_804401001_25_dialog_content = "或許這就是薇絲和薇薇安都很喜歡這座鞦韆的原因？",
  str_homestory_804401001_26_dialog_content = "對喔，也許就是因為少見，所以格外喜愛～",
  str_homestory_804401001_27_dialog_content = "唔......對耶......",
  str_homestory_804401001_28_dialog_content = "嗯？妳在想什麼？",
  str_homestory_804401001_29_dialog_content = "啊，沒什麼。",
  str_homestory_804401001_30_dialog_content = "我只是在計算這筆支出<sprite=emo_baiyebi size=60 />的必要性。",
  str_homestory_804401001_31_dialog_content = "支出？！",
  str_homestory_804401001_32_dialog_content = "什麼支出？",
  str_homestory_804401001_33_dialog_content = "我在想，假如要在啟光的每個孤兒院、學校......",
  str_homestory_804401001_34_dialog_content = "以及相關基地都設置一座鞦韆需要多少錢。",
  str_homestory_804401001_35_dialog_content = "喔？......這樣啊。",
  str_homestory_804401001_36_dialog_content = "但稍微算了一下，這筆開銷好像有點離譜呢......",
  str_homestory_804401001_37_dialog_content = "如果要完整執行這個方案，勢必得縮減其他模組的支出。",
  str_homestory_804401001_38_dialog_content = "哎呀，聽起來有點棘手呢。",
  str_homestory_804401001_39_dialog_content = "那......如果少立幾座鞦韆呢？",
  str_homestory_804401001_40_dialog_content = "減少鞦韆投放的數量，精確選擇鞦韆投放的位置？",
  str_homestory_804401001_41_dialog_content = "比如說......",
  str_homestory_804401001_42_dialog_content = "放在幾乎所有人都會經過的地方！",
  str_homestory_804401001_43_dialog_content = "像是各個地下城的交界處、幾所孤兒院或學校的中間......",
  str_homestory_804401001_44_dialog_content = "你說得很有道理，小PlayerName！",
  str_homestory_804401001_45_dialog_content = "能幫上忙就好。",
  str_homestory_804401001_46_dialog_content = "不過......",
  str_homestory_804401001_47_dialog_content = "我剛剛提到開銷離譜的時候，你何必那麼緊張？",
  str_homestory_804401001_48_dialog_content = "哈......啊哈......",
  str_homestory_804401001_49_dialog_content = "因為那句實在太像薇絲看帳本時常說的話......",
  str_homestory_804401001_50_dialog_content = "我大概是習慣性反應的緊張吧！",
  str_homestory_804401001_51_dialog_content = "哎呀～小薇絲和小PlayerName的感情還真好呢......<sprite=emo_guilian size=60 />",
  str_homestory_808501001_0_dialog_content = "珍？",
  str_homestory_808501001_1_dialog_content = "你好，PlayerName。",
  str_homestory_808501001_2_dialog_content = "啊，珍！",
  str_homestory_808501001_3_dialog_content = "妳......妳在記錄空庭嗎？",
  str_homestory_808501001_4_dialog_content = "嗯，我記錄著這裡發生的一切。",
  str_homestory_808501001_5_dialog_content = "但我現在沒有記錄，只是單純在放空。<sprite=emo_pugongying size=60 />",
  str_homestory_808501001_6_dialog_content = "放空？",
  str_homestory_808501001_7_dialog_content = "怎麼了？什麼事讓妳心情不好？",
  str_homestory_808501001_8_dialog_content = "還是最近壓力太大了？",
  str_homestory_808501001_9_dialog_content = "二者都有吧。",
  str_homestory_808501001_10_dialog_content = "PlayerName也知道，身為一名專業的「見證人」，我不可以插手某些事情。",
  str_homestory_808501001_11_dialog_content = "嗯，有所耳聞。",
  str_homestory_808501001_12_dialog_content = "那麼......",
  str_homestory_808501001_13_dialog_content = "假如你是一名「見證人」，你會幫助一位幫派火拼的受害者嗎？",
  str_homestory_808501001_14_option_content = "會",
  str_homestory_808501001_15_dialog_content = "見證人畢竟只是一份工作而已......",
  str_homestory_808501001_16_option_content = "不會",
  str_homestory_808501001_17_dialog_content = "其實對我而言，「保持絕對客觀」這件事沒那麼重要......",
  str_homestory_808501001_18_dialog_content = "也許我會立刻通知別人過來幫忙。",
  str_homestory_808501001_19_dialog_content = "還是會幫助別人，只是不自己親自動手？",
  str_homestory_808501001_20_dialog_content = "是的。",
  str_homestory_808501001_21_dialog_content = "那珍選了哪邊？",
  str_homestory_808501001_22_dialog_content = "妳問我這個問題，又一副苦惱的模樣，大概真的遇到這個狀況吧？",
  str_homestory_808501001_23_dialog_content = "嗯。我出手幫了那個小女孩。",
  str_homestory_808501001_24_dialog_content = "並且我仍在為了自己已經做出的選擇而煩惱。",
  str_homestory_808501001_25_dialog_content = "妳的擔憂是什麼？",
  str_homestory_808501001_26_dialog_content = "擔心自己的插手改變了事情的發展。",
  str_homestory_808501001_27_dialog_content = "一旦見證者的立場動搖，那麼這份見證就算不上中立。",
  str_homestory_808501001_28_dialog_content = "也許那個小女孩本該消失，因為這才是火拼該有的實際後果。",
  str_homestory_808501001_29_dialog_content = "但因為我救了她......",
  str_homestory_808501001_30_dialog_content = "......這份不中立的見證就沒有意義。",
  str_homestory_808501001_31_dialog_content = "但......在談職務之前，妳是個有感情的人，其次才是必須保持「中立」的「見證者」呀。",
  str_homestory_808501001_32_dialog_content = "道理我明白。",
  str_homestory_808501001_33_dialog_content = "......",
  str_homestory_808501001_34_dialog_content = "......我知道了。",
  str_homestory_808501001_35_dialog_content = "如果這麼擔心，不如把妳自己也寫進這份見證吧。",
  str_homestory_808501001_36_dialog_content = "把我也寫進見證......？",
  str_homestory_808501001_37_dialog_content = "就是......把事情如實地寫出來。",
  str_homestory_808501001_38_dialog_content = "因為見證者產生了情感波動，因此插手這次火拼的善後......也許會產生新的影響？",
  str_homestory_808501001_39_dialog_content = "......類似這樣的紀錄吧。",
  str_homestory_808501001_40_dialog_content = "......",
  str_homestory_808501001_41_dialog_content = "你的提議也不無道理。",
  str_homestory_808501001_42_dialog_content = "我會嘗試用這個角度記錄本次的事情。",
  str_homestory_808501001_43_dialog_content = "謝謝。",
  str_homestory_808801001_0_dialog_content = "瑪姬！",
  str_homestory_808801001_1_dialog_content = "導航員......你也來聽故事嗎？<sprite=emo_wuzui size=60 />",
  str_homestory_808801001_2_dialog_content = "故事？什麼故事？",
  str_homestory_808801001_3_dialog_content = "本來只想找妳聊個天而已，但現在我開始好奇這個故事了。",
  str_homestory_808801001_4_dialog_content = "糟......糟糕......說溜嘴了......",
  str_homestory_808801001_5_dialog_content = "嗯？瑪姬不希望我知道嗎？",
  str_homestory_808801001_6_dialog_content = "不......不是的......",
  str_homestory_808801001_7_dialog_content = "好吧......反正應該已經很多人知道了......",
  str_homestory_808801001_8_dialog_content = "究竟怎麼了？",
  str_homestory_808801001_9_dialog_content = "就是......前幾天，我在沙漠裡搜刮的時候......",
  str_homestory_808801001_10_dialog_content = "遇到了幾個小孩子。",
  str_homestory_808801001_11_dialog_content = "他們的樣子擺明就是從家裡偷跑出來，在沙漠裡迷路......",
  str_homestory_808801001_12_dialog_content = "我見他們在原地打轉，就問他們需不需要幫助。",
  str_homestory_808801001_13_dialog_content = "我把他們送到安全的地方之後，他......他們就問我叫什麼......還說以後要來謝謝我。",
  str_homestory_808801001_14_dialog_content = "我正要說出名字的時候，他們發現我的尾巴......他們......",
  str_homestory_808801001_15_option_content = "嘲笑妳？",
  str_homestory_808801001_16_dialog_content = "沒......沒有......",
  str_homestory_808801001_17_dialog_content = "他們幾個說......說我的尾巴很可愛！",
  str_homestory_808801001_18_dialog_content = "那不是很好嗎？",
  str_homestory_808801001_19_option_content = "他們認出妳是誰？",
  str_homestory_808801001_20_dialog_content = "沒有......",
  str_homestory_808801001_21_dialog_content = "我又不是弗勞爾，我一點也不出名......",
  str_homestory_808801001_22_dialog_content = "可......可是他們......",
  str_homestory_808801001_23_dialog_content = "他......他們居然以為我是一條龍！",
  str_homestory_808801001_24_dialog_content = "......？",
  str_homestory_808801001_25_dialog_content = "我當下的反應跟你差不多......",
  str_homestory_808801001_26_dialog_content = "我覺得這幾個傢伙真的很離譜！",
  str_homestory_808801001_27_dialog_content = "他們還說，第一次見到尾巴毛茸茸的龍......",
  str_homestory_808801001_28_dialog_content = "竟然還問我能不能讓他們摸摸尾巴......",
  str_homestory_808801001_29_dialog_content = "我當時真的很生氣......！<sprite=emo_wuyun size=60 />",
  str_homestory_808801001_30_dialog_content = "為什麼生氣？跟他們明講實際情況不就好了嗎？",
  str_homestory_808801001_31_dialog_content = "我不是因為被認錯而生氣，而是因為他們的態度！",
  str_homestory_808801001_32_dialog_content = "「能不能摸摸尾巴」......",
  str_homestory_808801001_33_dialog_content = "這是什麼話啊？！",
  str_homestory_808801001_34_dialog_content = "分明就是把人家當寵物的那種心態，才會這樣問甚至提出這種要求吧？！",
  str_homestory_808801001_35_dialog_content = "氣......氣死我了......",
  str_homestory_808801001_36_dialog_content = "我想讓一切都燃燒<sprite=emo_nuhuo size=60 />起來！現在！！",
  str_homestory_808801001_37_dialog_content = "（又要進入那種狀態了嗎？！）",
  str_homestory_808801001_38_dialog_content = "等......等等！瑪姬！",
  str_homestory_808801001_39_dialog_content = "萬一他們只是單純覺得妳的尾巴很可愛呢？",
  str_homestory_808801001_40_dialog_content = "畢......畢竟我也這麼覺得啊！",
  str_homestory_808801001_41_dialog_content = "......老實說，我甚至無法想像瑪姬沒有尾巴的樣子。",
  str_homestory_808801001_42_dialog_content = "............",
  str_homestory_808801001_43_dialog_content = "......真......真的嗎？",
  str_homestory_808801001_44_dialog_content = "（呼......她好像比較冷靜了......）",
  str_homestory_808801001_45_dialog_content = "真的，瑪姬。千真萬確！",
  str_homestory_808801001_46_dialog_content = "......那......那好吧......",
  str_homestory_808801001_47_dialog_content = "啊，對了。",
  str_homestory_808801001_48_dialog_content = "妳剛才為什麼說很多人聽過這個故事？",
  str_homestory_808801001_49_dialog_content = "就我所知，這件事好像沒幾個人知道......",
  str_homestory_808801001_50_dialog_content = "因......因為......",
  str_homestory_808801001_51_dialog_content = "狡木把這件事編進他的最新短篇小說集......",
  str_homestory_808801001_52_dialog_content = "......好吧，我早該想到是這樣......",
  str_homestory_800801001_0_dialog_content = "黑潮？",
  str_homestory_800801001_1_dialog_content = "哈哈！你來啦？<sprite=emo_yaosu size=60 />",
  str_homestory_800801001_2_dialog_content = "怎麼樣，你剛剛有看到嗎？我很帥吧？",
  str_homestory_800801001_3_dialog_content = "......你指哪方面，黑潮？",
  str_homestory_800801001_4_dialog_content = "我的拳擊動作啊！乾脆利落！挺拔瀟灑！",
  str_homestory_800801001_5_dialog_content = "咳，是還不錯......",
  str_homestory_800801001_6_dialog_content = "還不錯？這評價未免太平淡了吧？",
  str_homestory_800801001_7_dialog_content = "算了，反正你根本不會打拳擊，你八成是在嫉妒我吧。",
  str_homestory_800801001_8_dialog_content = "......？",
  str_homestory_800801001_9_dialog_content = "但你放心啦，PlayerName！就算嫉妒我，我也還是會對你好！",
  str_homestory_800801001_10_dialog_content = "我真的很想強調我沒有在嫉妒你......",
  str_homestory_800801001_11_dialog_content = "噓......我懂。",
  str_homestory_800801001_12_dialog_content = "我在你這年紀的時候，也很嚮往那些跟如今的我一樣的真男人！<sprite=emo_mojing size=60 />",
  str_homestory_800801001_13_dialog_content = "聽我一言，PlayerName！有志者事竟成！",
  str_homestory_800801001_14_dialog_content = "......好......好的，黑潮。",
  str_homestory_800801001_15_dialog_content = "不用客氣，為空庭提供燃料是我應盡的義務。",
  str_homestory_800801001_16_dialog_content = "照顧小弟弟什麼的，我最擅長了。",
  str_homestory_800801001_17_dialog_content = "等等......什麼燃料？什麼義務？",
  str_homestory_800801001_18_dialog_content = "這麼聽來，你還不知道我為你的付出？",
  str_homestory_800801001_19_dialog_content = "......願聞其詳。",
  str_homestory_800801001_20_dialog_content = "是這樣的。我前幾天去找歐緹，請她幫我把渦輪的顏色改成七彩。",
  str_homestory_800801001_21_dialog_content = "但她滿面愁容，拜託我幫你這個忙。",
  str_homestory_800801001_22_dialog_content = "什麼忙？",
  str_homestory_800801001_23_dialog_content = "歐緹告訴我......",
  str_homestory_800801001_24_dialog_content = "這個不倒翁拳擊假人的內部，裝載著一個熱力發動機。",
  str_homestory_800801001_25_dialog_content = "......？",
  str_homestory_800801001_26_dialog_content = "這個發動機負責為整座空庭的運轉提供動力！",
  str_homestory_800801001_27_dialog_content = "也就是說，我每天對這拳擊假人打個幾千下，就能保你空庭不停止運轉。",
  str_homestory_800801001_28_dialog_content = "哈哈！你那是什麼表情？不用不好意思啦！",
  str_homestory_800801001_29_dialog_content = "我很樂意這樣為你付出！",
  str_homestory_800801001_30_dialog_content = "......咳，那個，黑潮......我覺得......",
  str_homestory_800801001_31_option_content = "你被騙了",
  str_homestory_800801001_32_dialog_content = "這個不倒翁拳擊假人的內部只裝了填充物，並沒有所謂的機械結構......",
  str_homestory_800801001_33_dialog_content = "也就是說，空庭的運轉和這個假人沒牽連。",
  str_homestory_800801001_34_dialog_content = "咳，但是！",
  str_homestory_800801001_35_dialog_content = "但我覺得你每天練習拳擊還是很助於促進身心健康。",
  str_homestory_800801001_36_option_content = "非常謝謝你！",
  str_homestory_800801001_37_dialog_content = "咳，但是......",
  str_homestory_800801001_38_dialog_content = "但我覺得歐緹可能不夠瞭解空庭的構造。",
  str_homestory_800801001_39_dialog_content = "就是說......我的意思是......",
  str_homestory_800801001_40_dialog_content = "這個不倒翁拳擊假人的內部只裝了填充物，並沒有所謂的機械結構......",
  str_homestory_800801001_41_dialog_content = "噢！原來是這樣啊？",
  str_homestory_800801001_42_dialog_content = "哈哈！原來歐緹也有說錯的時候！",
  str_homestory_800801001_43_dialog_content = "那個，黑潮......",
  str_homestory_800801001_44_dialog_content = "我覺得她可能是在捉弄你。",
  str_homestory_800801001_45_dialog_content = "我想也是，反正大家經常捉弄我。",
  str_homestory_800801001_46_dialog_content = "那你不會生氣嗎？",
  str_homestory_800801001_47_dialog_content = "這有什麼好氣？",
  str_homestory_800801001_48_dialog_content = "這表示大家都很喜歡我啊！喜歡跟我一起玩！",
  str_homestory_800801001_49_dialog_content = "嗯......你說的也對。",
  str_homestory_800801001_50_dialog_content = "而且，退一萬步說......",
  str_homestory_800801001_51_dialog_content = "他們捉弄我，是因為他們都很愛戴我，很信任我。",
  str_homestory_800801001_52_dialog_content = "......愛戴？你確定？",
  str_homestory_800801001_53_dialog_content = "不然的話，他們為什麼不去捉弄醒山呢？",
  str_homestory_800801001_54_dialog_content = "你看，在「親和力」這方面，我肯定完勝吧？哈哈哈哈！<sprite=emo_dianzan size=60 />",
  str_homestory_806501001_0_dialog_content = "塔塔......？",
  str_homestory_806501001_1_dialog_content = "哇呀！先森......先森你來啦。",
  str_homestory_806501001_2_dialog_content = "塔塔是怎麼了？為何見到我這麼慌張？",
  str_homestory_806501001_3_dialog_content = "啊......有嗎？",
  str_homestory_806501001_4_dialog_content = "妳看看，妳身上的東西掉滿地了。",
  str_homestory_806501001_5_dialog_content = "啊！在辣裡在辣裡？",
  str_homestory_806501001_6_dialog_content = "妳腳下那團白色的、毛茸茸的東西......",
  str_homestory_806501001_7_dialog_content = "欸？偶看看......",
  str_homestory_806501001_8_dialog_content = "哇呀！這是塔塔森上滴羽毛？！",
  str_homestory_806501001_9_dialog_content = "嗚......看來果然不稜做虧心事捏。",
  str_homestory_806501001_10_dialog_content = "虧心事？",
  str_homestory_806501001_11_dialog_content = "怪不得塔塔的小尾巴都垂下來了。",
  str_homestory_806501001_12_dialog_content = "唔......",
  str_homestory_806501001_13_dialog_content = "所以到底發生什麼事？可以說給我聽聽嗎？",
  str_homestory_806501001_14_dialog_content = "還是告訴先森好了......",
  str_homestory_806501001_15_dialog_content = "塔塔今天是過來送信滴。",
  str_homestory_806501001_16_dialog_content = "是嗎？已經送到驛站啦？我等一下就去看！",
  str_homestory_806501001_17_dialog_content = "辣過......先森請等一下哇。",
  str_homestory_806501001_18_dialog_content = "信......偶還沒有送到驛站咧。",
  str_homestory_806501001_19_dialog_content = "塔塔這次來到空庭，發現這裡變囉好多喔！",
  str_homestory_806501001_20_dialog_content = "左飛飛，右逛逛，就忘記送信這檔事了......",
  str_homestory_806501001_21_dialog_content = "這就是塔塔口中的虧心事嗎？",
  str_homestory_806501001_22_option_content = "（生氣）",
  str_homestory_806501001_23_dialog_content = "怠忽職守，確實情節嚴重。",
  str_homestory_806501001_24_dialog_content = "身為空庭的主人，我好像該懲罰妳才說得過去呀？",
  str_homestory_806501001_25_dialog_content = "哇呀——！懲......懲罰？",
  str_homestory_806501001_26_dialog_content = "感覺尾巴上滴羽毛又要掉了......",
  str_homestory_806501001_27_dialog_content = "就懲罰塔塔......",
  str_homestory_806501001_28_option_content = "（安慰）",
  str_homestory_806501001_29_dialog_content = "沒關係啦，也不是著急的事。",
  str_homestory_806501001_30_dialog_content = "塔塔也能喜歡我佈置的空庭，對我來說是個好事呢。",
  str_homestory_806501001_31_dialog_content = "謝謝先森，先森真的是好好的人喔！",
  str_homestory_806501001_32_dialog_content = "所以是誰寄來的信呀？",
  str_homestory_806501001_33_dialog_content = "信拿給我看看吧。",
  str_homestory_806501001_34_dialog_content = "好滴喔！信屬公會！郵件必達！",
  str_homestory_806501001_35_dialog_content = "哇呀？信怎麼不見惹......",
  str_homestory_806501001_36_dialog_content = "背包裡莫有......",
  str_homestory_806501001_37_dialog_content = "帽子裡也莫有！",
  str_homestory_806501001_38_dialog_content = "別急，會不會掉在別處？",
  str_homestory_806501001_39_dialog_content = "塔塔剛剛去過哪些地方呢？",
  str_homestory_806501001_40_dialog_content = "整個空庭......偶都逛了一遍。",
  str_homestory_806501001_41_dialog_content = "......要找的範圍還真是挺大的。",
  str_homestory_806501001_42_dialog_content = "塔塔不想變成多孚前輩哇——",
  str_homestory_806501001_43_dialog_content = "欸？有東西從妳的尾巴掉出來了耶？",
  str_homestory_806501001_44_dialog_content = "塔塔尾巴上滴羽毛又掉了？再掉就禿了嗚！",
  str_homestory_806501001_45_dialog_content = "不對，看起來不像羽毛......",
  str_homestory_806501001_46_dialog_content = "欸……",
  str_homestory_806501001_47_dialog_content = "啊，這是塔塔要送滴信！",
  str_homestory_806501001_48_dialog_content = "原來藏在尾巴裡了呀！",
  str_homestory_805501001_0_dialog_content = "那個人是......？",
  str_homestory_805501001_1_dialog_content = "彼亞塔曼！",
  str_homestory_805501001_2_dialog_content = "......！",
  str_homestory_805501001_3_dialog_content = "你是彼亞塔曼吧？",
  str_homestory_805501001_4_dialog_content = "咳咳，你認錯人了。",
  str_homestory_805501001_5_dialog_content = "欸？可是這身一絲不苟的裝扮......還有臉上掛著的黑眼圈！",
  str_homestory_805501001_6_dialog_content = "你分明就是彼亞塔曼啊。",
  str_homestory_805501001_7_dialog_content = "噓......",
  str_homestory_805501001_8_dialog_content = "小聲點，不要被別人聽見......",
  str_homestory_805501001_9_option_content = "（表示疑問）",
  str_homestory_805501001_10_dialog_content = "嗯？白夜城的審判官也害怕被別人發現嗎？",
  str_homestory_805501001_11_option_content = "（表示理解）",
  str_homestory_805501001_12_dialog_content = "噢，我知道了。",
  str_homestory_805501001_13_dialog_content = "你是不希望別人發現你在這裡吧！",
  str_homestory_805501001_14_dialog_content = "難道你被白夜城通緝了？！",
  str_homestory_805501001_15_dialog_content = "我行得正、坐得端，對光之神虔誠，對白夜城忠誠。",
  str_homestory_805501001_16_dialog_content = "為何會被通緝？",
  str_homestory_805501001_17_dialog_content = "比如說......",
  str_homestory_805501001_18_dialog_content = "你一個人偷偷騎木馬玩！",
  str_homestory_805501001_19_dialog_content = "果......果然被你看見了嗎？<sprite=emo_daomei size=60 />",
  str_homestory_805501001_20_dialog_content = "喔～原來你真的是來騎木馬的？",
  str_homestory_805501001_21_dialog_content = "咳咳，我只是想檢查一下這個木馬的品質。",
  str_homestory_805501001_22_dialog_content = "近期市面上流傳著許多謊稱優良的次級品。",
  str_homestory_805501001_23_dialog_content = "這種欺騙消費者的行為，我們審判官必須嚴厲打擊。",
  str_homestory_805501001_24_dialog_content = "不過你這裡的木馬用料紮實、做工精良，起碼可以承重八十四公斤。",
  str_homestory_805501001_25_dialog_content = "你大可以放心使用。",
  str_homestory_805501001_26_dialog_content = "呃，謝謝你......",
  str_homestory_805501001_27_dialog_content = "我把木馬放在這裡，就是希望大家可以來坐一坐，放鬆放鬆。",
  str_homestory_805501001_28_dialog_content = "如果你想騎木馬的話，完全沒有必要偷偷摸摸嘛！",
  str_homestory_805501001_29_dialog_content = "你何出此言？",
  str_homestory_805501001_30_dialog_content = "因為你的想法都寫在臉上呀。",
  str_homestory_805501001_31_dialog_content = "彼亞塔曼真的很不會撒謊啊，哈哈哈。",
  str_homestory_805501001_32_dialog_content = "......好吧。",
  str_homestory_805501001_33_dialog_content = "但是我懇求你幫我守住這個祕密。",
  str_homestory_805501001_34_dialog_content = "為什麼啊？騎木馬哪裡需要保密了......",
  str_homestory_805501001_35_dialog_content = "我也滿喜歡騎木馬啊。",
  str_homestory_805501001_36_dialog_content = "身為一名主持正義的審判官，我希望展現令人信服的氣質。",
  str_homestory_805501001_37_dialog_content = "如果讓別人知道我有這樣幼稚的嗜好......",
  str_homestory_805501001_38_dialog_content = "恐怕難以信服我對案件的審判。",
  str_homestory_805501001_39_dialog_content = "是這樣嗎......",
  str_homestory_805501001_40_dialog_content = "所以，可以幫我保密嗎？PlayerName？",
  str_homestory_805501001_41_dialog_content = "好吧，雖然我覺得騎木馬和審案沒什麼直接影響......",
  str_homestory_805501001_42_dialog_content = "但既然你有此請求，我會答應！",
  str_homestory_805501001_43_dialog_content = "感謝你的體諒。",
  str_homestory_805501001_44_dialog_content = "還有......",
  str_homestory_805501001_45_dialog_content = "萬一你買到假冒劣質品，我一定會幫你討回公道！<sprite=emo_qingsong size=60 />",
  str_homestory_815501001_0_dialog_content = "收劍的聲音？",
  str_homestory_815501001_1_dialog_content = "空谷了不起的地方還真多啊，PlayerName！",
  str_homestory_815501001_2_dialog_content = "還......還好啦。",
  str_homestory_815501001_3_dialog_content = "空裔到底還有多少祕密沒被發現？",
  str_homestory_815501001_4_dialog_content = "......多想立刻得知全部。",
  str_homestory_815501001_5_dialog_content = "嘖嘖，你這地方真是非常不錯啊，小子。",
  str_homestory_815501001_6_dialog_content = "設施非常齊全，而且地勢險要，易守難攻。",
  str_homestory_815501001_7_dialog_content = "哪天真的打起來的話，用做長期後勤基地完全沒有任何問題！",
  str_homestory_815501001_8_dialog_content = "哇......你想得好遠啊，巴頓。",
  str_homestory_815501001_9_dialog_content = "當然！",
  str_homestory_815501001_10_dialog_content = "比起不斷追求力量，如何規劃現有資源也很重要。",
  str_homestory_815501001_11_dialog_content = "（巴頓變得不一樣了......）",
  str_homestory_815501001_12_dialog_content = "哎，我年輕的時候不懂，這兩件事其實——",
  str_homestory_815501001_13_dialog_content = "——對了，小子，你怎麼想？",
  str_homestory_815501001_14_dialog_content = "你覺得是先變強重要，還是先規劃資源重要？<sprite=emo_sikao size=60 />",
  str_homestory_815501001_15_option_content = "變強",
  str_homestory_815501001_16_dialog_content = "假如我只有十塊白夜幣，那怎麼規劃都沒用吧......",
  str_homestory_815501001_17_dialog_content = "所以當然是要先變強，也就是賺錢啊。",
  str_homestory_815501001_18_option_content = "規劃",
  str_homestory_815501001_19_dialog_content = "假如我只有十塊白夜幣，當然要先想該怎麼活下去，再去想怎麼賺錢吧......",
  str_homestory_815501001_20_dialog_content = "哈？你不會是認真的吧？",
  str_homestory_815501001_21_dialog_content = "你真的只有十塊錢啊？",
  str_homestory_815501001_22_dialog_content = "......我只是打個比方！！",
  str_homestory_815501001_23_dialog_content = "喔，好吧。",
  str_homestory_815501001_24_dialog_content = "我是想，假如你真的這麼缺錢，其實可以跟我借。",
  str_homestory_815501001_25_dialog_content = "這麼看來還是啟光好啊，至少很多東西都不用額外花錢。",
  str_homestory_815501001_26_dialog_content = "......？",
  str_homestory_815501001_27_dialog_content = "咳，扯遠了......",
  str_homestory_815501001_28_dialog_content = "我的本意是，我現在覺得追求力量和規劃資源可以同步進行。",
  str_homestory_815501001_29_dialog_content = "這兩件事本身也不矛盾。",
  str_homestory_815501001_30_dialog_content = "我之前就只顧著追求力量，其實忽略許多事情背後的意義。",
  str_homestory_815501001_31_dialog_content = "善加規劃自己手中的資源，可以讓前進的方向更加清晰！",
  str_homestory_815501001_32_dialog_content = "要對自己有透徹的認知！這樣前進的道路才會順利，我們才會變強。",
  str_homestory_815501001_33_dialog_content = "變得更強，才有更多話語權。",
  str_homestory_815501001_34_dialog_content = "嗯......特定程度上，你說的算對。",
  str_homestory_815501001_35_dialog_content = "那你就是答應把這裡借給我當後勤基地囉？",
  str_homestory_815501001_36_dialog_content = "......？！",
  str_homestory_815501001_37_dialog_content = "我可沒說過這種話啊！",
  str_homestory_815501001_38_dialog_content = "而且所謂的後勤基地，和空庭未免太不搭調了！",
  str_homestory_815501001_39_dialog_content = "哈哈，這種事可不能太鐵齒喔？說不定哪天真的開戰！",
  str_homestory_815501001_40_dialog_content = "喂，你千萬別烏鴉嘴！<sprite=emo_shengqi size=60 />",
  str_homestory_815501001_41_dialog_content = "什麼烏鴉嘴？這不過是最基本的風險觀測！",
  str_homestory_815501001_42_dialog_content = "嗯，既然這樣的話，需要趕緊再多弄幾場沙盤推演才行。",
  str_homestory_815501001_43_dialog_content = "至於我現在腦子裡的這些規劃......明天去和薇薇安口述一下好了。",
  str_homestory_815501001_44_dialog_content = "嘖，寫文書查資料什麼的最煩了......我可不想自己弄！",
  str_homestory_815501001_45_dialog_content = "（我決定收回剛剛的話......）",
  str_homestory_815501001_46_dialog_content = "（巴頓果然還是那個巴頓，根本和以前沒差別。）",
  str_homestory_801101001_0_dialog_content = "希羅娜！",
  str_homestory_801101001_1_dialog_content = "長官......",
  str_homestory_801101001_2_dialog_content = "妳在練習新招式嗎？",
  str_homestory_801101001_3_dialog_content = "嗯，是的。",
  str_homestory_801101001_4_dialog_content = "在這裡也不忘訓練<sprite=emo_yaling size=60 />，真不愧是負責正面對陣的第一軍團長啊......",
  str_homestory_801101001_5_dialog_content = "不，你誤會了，PlayerName。",
  str_homestory_801101001_6_dialog_content = "我練習新招式的原因，並不是因為我要把這套招式投入訓練。",
  str_homestory_801101001_7_dialog_content = "而是因為我最近看了一本小說。我練習的是這本小說裡提到的招式。",
  str_homestory_801101001_8_dialog_content = "妳......妳居然會看小說？",
  str_homestory_801101001_9_dialog_content = "不，等等......練習小說裡提到的招式？",
  str_homestory_801101001_10_dialog_content = "這......為什麼和我原本認識的希羅娜長官印象大不同？！",
  str_homestory_801101001_11_dialog_content = "這麼驚訝嗎？",
  str_homestory_801101001_12_option_content = "（點頭）",
  str_homestory_801101001_13_dialog_content = "感覺妳有很多大事要操心，看小說這種事......",
  str_homestory_801101001_14_dialog_content = "不，我並不是覺得看小說這個嗜好有問題！",
  str_homestory_801101001_15_option_content = "（搖頭）",
  str_homestory_801101001_16_dialog_content = "仔細思索覺得，好像也不該把對別人的印象框在一個固定範圍裡......",
  str_homestory_801101001_17_dialog_content = "只是感覺希羅娜長官一直很忙碌，沒什麼時間看小說。",
  str_homestory_801101001_18_dialog_content = "嗯，我確實沒看過幾本小說。",
  str_homestory_801101001_19_dialog_content = "因為這本書的書名叫做《叛逆雙龍的千年糾纏》，所以我才好奇拿來看。",
  str_homestory_801101001_20_dialog_content = "......",
  str_homestory_801101001_21_dialog_content = "敢......敢問妳是從哪......看到這本書......",
  str_homestory_801101001_22_dialog_content = "該不會是某位光靈賣給妳的吧？！",
  str_homestory_801101001_23_dialog_content = "嗯，是名影鎮的商人賣給我的。",
  str_homestory_801101001_24_dialog_content = "妳看起來很平靜耶......",
  str_homestory_801101001_25_dialog_content = "看來這書裡沒什麼違常的內容嘛？",
  str_homestory_801101001_26_dialog_content = "他賣給我的時候，告訴我這本書的噱頭是——",
  str_homestory_801101001_27_dialog_content = "「失傳已久的龍族祕技」、「遠古血脈的愛情故事」......",
  str_homestory_801101001_28_dialog_content = "什麼？！妳......妳沒生氣嗎？",
  str_homestory_801101001_29_dialog_content = "這沒什麼。",
  str_homestory_801101001_30_dialog_content = "就算生氣，我也不能怎樣。",
  str_homestory_801101001_31_dialog_content = "這本書的生產和銷售流程基本上都發生在影鎮，不屬於我管轄。",
  str_homestory_801101001_32_dialog_content = "更何況對我而言，書裡的內容不外乎無關緊要的心情發洩。",
  str_homestory_801101001_33_dialog_content = "但對那些創作者而言，這書可能是他們賴以維生的手段。",
  str_homestory_801101001_34_dialog_content = "......嗯，妳說得對......",
  str_homestory_801101001_35_dialog_content = "希羅娜......真是個好長官啊！",
  str_homestory_801101001_36_dialog_content = "話說回來，這本書提到的「龍族祕技」雖然很離譜......",
  str_homestory_801101001_37_dialog_content = "好歹還是能起到鍛鍊身體的作用。",
  str_homestory_801101001_38_dialog_content = "你要不要和我一起試試？",
  str_homestory_801101001_39_dialog_content = "按照書上說的，我們最好先簡單完成兩百個原地蹲，然後再輕鬆地——",
  str_homestory_801101001_40_dialog_content = "不不不，不了......",
  str_homestory_801101001_41_dialog_content = "我覺得我還是專精於空裔一族的能力就好了，希羅娜長官。",
  str_homestory_801101001_42_dialog_content = "我就先不打擾妳鍛鍊身體了......再見！",
  str_homestory_801101001_43_dialog_content = "再見。",
  str_homestory_810301001_0_dialog_content = "艾希來了？",
  str_homestory_810301001_1_dialog_content = "艾希，妳不去進去逛商店嗎？",
  str_homestory_810301001_2_dialog_content = "我記得妳很喜歡逛街啊。",
  str_homestory_810301001_3_dialog_content = "PlayerName，既然你還記得我的喜好......",
  str_homestory_810301001_4_dialog_content = "為何這麼小氣，只建了這一家商店？",
  str_homestory_810301001_5_dialog_content = "這個嘛，有很多原因......",
  str_homestory_810301001_6_dialog_content = "繼續說。",
  str_homestory_810301001_7_dialog_content = "如果說不出來，我可以解下眼罩......",
  str_homestory_810301001_8_dialog_content = "讓你看著我的「空虛之瞳」<sprite=emo_baimao size=60 />仔細回憶清楚。",
  str_homestory_810301001_9_option_content = "（解釋）",
  str_homestory_810301001_10_dialog_content = "好好好，我說！",
  str_homestory_810301001_11_dialog_content = "最主要原因就是預算有限......",
  str_homestory_810301001_12_dialog_content = "畢竟有這麼多地方需要建設，不可能一開始就十全十美。",
  str_homestory_810301001_13_option_content = "（不解釋）",
  str_homestory_810301001_14_dialog_content = "就算審問我也沒用啊......",
  str_homestory_810301001_15_dialog_content = "畢竟預算有限，無法一次開好幾家商店......",
  str_homestory_810301001_16_dialog_content = "我覺得......現在有一家商店已經很不錯了！",
  str_homestory_810301001_17_dialog_content = "你好像很理直氣壯喔？",
  str_homestory_810301001_18_dialog_content = "雖然只有一家商店，但是麻雀雖小，五臟俱全！",
  str_homestory_810301001_19_dialog_content = "我已經很努力和影鎮的各家商會聯絡了......",
  str_homestory_810301001_20_dialog_content = "還拜託信使公會不定期供貨給我們。",
  str_homestory_810301001_21_dialog_content = "不然妳先進去看看嘛？缺什麼我幫妳找。",
  str_homestory_810301001_22_dialog_content = "不必了，我已經進去逛過了。",
  str_homestory_810301001_23_dialog_content = "為了給你捧場，我買下了商店裡所有的商品。",
  str_homestory_810301001_24_dialog_content = "所有的商品？！",
  str_homestory_810301001_25_dialog_content = "嗯。",
  str_homestory_810301001_26_dialog_content = "包括今天剛釣上來的淡水魚......？",
  str_homestory_810301001_27_dialog_content = "那些五顏六色的魚？買了。我看牠們挺可愛的。",
  str_homestory_810301001_28_dialog_content = "但是買了以後發現沒有魚缸，就放生到附近的河裡了。",
  str_homestory_810301001_29_dialog_content = "包括那隻沒人要的爛皮鞋......？",
  str_homestory_810301001_30_dialog_content = "爛皮鞋？喔，買了，那不是最新款的花盆嗎？",
  str_homestory_810301001_31_dialog_content = "我已經拜託信使公會幫我運回真理結社了。",
  str_homestory_810301001_32_dialog_content = "包括......我手繪的空谷地圖？",
  str_homestory_810301001_33_dialog_content = "你是說那張線條歪歪扭扭的迷宮一樣的東西吧。",
  str_homestory_810301001_34_dialog_content = "原來是你的手筆？那我等下可要用心裱框掛牆上。",
  str_homestory_810301001_35_dialog_content = "謝謝艾希......妳是我們的商店開業以來最慷慨的客人！",
  str_homestory_810301001_36_dialog_content = "這有什麼好謝的，購物不就是要爽快才開心嗎？",
  str_homestory_810301001_37_dialog_content = "可是我逛完這一家店就沒得逛了，真是不禁令人惱火。",
  str_homestory_810301001_38_dialog_content = "其實艾希可以在周圍隨便逛逛呀。",
  str_homestory_810301001_39_dialog_content = "比如那邊的陳列館啦，還有祈望池啦......",
  str_homestory_810301001_40_dialog_content = "我保證，絕對是只有這裡才能逛到的景色！",
  str_homestory_810301001_41_dialog_content = "嗯，聽上去似乎值得體驗。",
  str_homestory_810301001_42_dialog_content = "不如這樣吧，我買下<sprite=emo_baiyebi size=60 />你了。",
  str_homestory_810301001_43_dialog_content = "咦？！買下......我？！",
  str_homestory_810301001_44_dialog_content = "買你今天一天的時間，帶我到處逛逛。",
  str_homestory_810301001_45_dialog_content = "價格就由你決定吧。",
  str_homestory_810301001_46_dialog_content = "好......好的！很高興為您服務！",
  str_homestory_802301001_0_dialog_content = "克娜莉......",
  str_homestory_802301001_1_dialog_content = "溫柔的光明啊......",
  str_homestory_802301001_2_dialog_content = "克娜莉，妳在說什麼呢？",
  str_homestory_802301001_3_dialog_content = "導......導航員！！<sprite=emo_wuzui size=60 />",
  str_homestory_802301001_4_dialog_content = "我......我只是在碎碎念，請不要理我......",
  str_homestory_802301001_5_dialog_content = "不......不是的！",
  str_homestory_802301001_6_dialog_content = "也可以理會我......我......我正在努力進行「脫敏訓練」......",
  str_homestory_802301001_7_dialog_content = "「脫敏訓練」？",
  str_homestory_802301001_8_dialog_content = "嗯......是，是薇絲教我的......",
  str_homestory_802301001_9_dialog_content = "因為這裡總是很亮，我本來很不習慣......",
  str_homestory_802301001_10_dialog_content = "薇絲在角落裡發現我......",
  str_homestory_802301001_11_dialog_content = "她發現妳需要幫助，對嗎？",
  str_homestory_802301001_12_dialog_content = "是......",
  str_homestory_802301001_13_dialog_content = "她告訴我，可以試試在這裡做自己喜歡的事，無視其他的人......",
  str_homestory_802301001_14_dialog_content = "或者把這裡看作假日咖啡館，把其他人都當成客人......",
  str_homestory_802301001_15_dialog_content = "我......我有在努力了......",
  str_homestory_802301001_16_option_content = "感覺如何？",
  str_homestory_802301001_17_dialog_content = "好像......比之前好了一些......",
  str_homestory_802301001_18_dialog_content = "畢竟巨像上有很多人......",
  str_homestory_802301001_19_option_content = "不用勉強",
  str_homestory_802301001_20_dialog_content = "如果妳覺得一直待在房間比較舒服，就那樣做也沒關係。",
  str_homestory_802301001_21_dialog_content = "其實，我......我想告訴你一件事，導航員......",
  str_homestory_802301001_22_dialog_content = "嗯？什麼事？",
  str_homestory_802301001_23_dialog_content = "我依照薇絲的建議，在這裡試著和「安東」一起吹奏了一支曲子<sprite=emo_yinfu size=60 />......",
  str_homestory_802301001_24_dialog_content = "結果......一位做著白夜城風格打扮的女士居然誇獎了我......",
  str_homestory_802301001_25_dialog_content = "我......",
  str_homestory_802301001_26_dialog_content = "啊，覺得這種亮堂堂的地方好受了一點，是嗎？",
  str_homestory_802301001_27_dialog_content = "果然，誇獎是一種很有用的鼓勵方式呢。",
  str_homestory_802301001_28_dialog_content = "克娜莉，我覺得妳超棒！",
  str_homestory_802301001_29_dialog_content = "又會做好喝的咖啡，兼具強大戰鬥力和可愛性格......",
  str_homestory_802301001_30_dialog_content = "謝謝你誇我，導航員，我......我都不知道該說些什麼好......",
  str_homestory_802301001_31_dialog_content = "只不過，那位女士的誇獎......和導航員的誇獎是不同的！",
  str_homestory_802301001_32_dialog_content = "因為導航員和薇絲都是克娜莉很好的朋友......",
  str_homestory_802301001_33_dialog_content = "你們都很想鼓勵我......所以會一直安慰我，一直誇獎我......",
  str_homestory_802301001_34_dialog_content = "但......但這位女士是陌生人......！",
  str_homestory_802301001_35_dialog_content = "所以對克娜莉來說，這是一種很純粹的肯定呀。",
  str_homestory_802301001_36_dialog_content = "是......是的......我也想表達這意思......",
  str_homestory_802301001_37_dialog_content = "總之......導航員可以幫我向薇絲轉達感謝嗎？",
  str_homestory_802301001_38_dialog_content = "若不是聽了她的建議，我應該還縮在房間裡不肯出來吧......",
  str_homestory_802301001_39_dialog_content = "沒問題！",
  str_homestory_802301001_40_dialog_content = "也......也謝謝你......導航員！",
  str_homestory_802301001_41_dialog_content = "我現在......準備和「安東」再多練習一下那首曲子......",
  str_homestory_802301001_42_dialog_content = "也可以試試新的曲子啊？",
  str_homestory_802301001_43_dialog_content = "那位神祕的女士應該也很樂意聽。",
  str_homestory_802301001_44_dialog_content = "啊......對喔......",
  str_homestory_802301001_45_dialog_content = "嗯......嗯！導航員，那我先去練習了......！",
  str_homestory_802301001_46_dialog_content = "加油啊！",
  str_homestory_803001001_0_dialog_content = "醒山......",
  str_homestory_803001001_1_dialog_content = "你好啊，醒山！",
  str_homestory_803001001_2_dialog_content = "啊哈<sprite=emo_yaosu size=60 />，這不是我們的空之末裔PlayerName嗎？",
  str_homestory_803001001_3_dialog_content = "別來無恙啊？",
  str_homestory_803001001_4_dialog_content = "我挺好的，你呢？住得還習慣嗎？",
  str_homestory_803001001_5_dialog_content = "還算可以吧。",
  str_homestory_803001001_6_dialog_content = "短短時間你就把這鳥不生蛋的地方建成這樣......",
  str_homestory_803001001_7_dialog_content = "真不愧是我醒山看上的人啊哈哈哈。",
  str_homestory_803001001_8_dialog_content = "話說，你考慮得怎麼樣啦？",
  str_homestory_803001001_9_dialog_content = "到底打算什麼時候加入我們紅油扳手啊？",
  str_homestory_803001001_10_dialog_content = "這個......那個......",
  str_homestory_803001001_11_dialog_content = "不過若用紅油扳手的標準來看......",
  str_homestory_803001001_12_dialog_content = "你這裡還缺幾個能放肆打架和飆車的地方啊！",
  str_homestory_803001001_13_option_content = "（拒絕）",
  str_homestory_803001001_14_dialog_content = "我不希望空庭裡發生任何衝突......",
  str_homestory_803001001_15_dialog_content = "所以也不想給那種暴力活動提供任何場所。",
  str_homestory_803001001_16_dialog_content = "唉，已經數不清是第幾次被無情拒絕啦。",
  str_homestory_803001001_17_dialog_content = "不過啊，PlayerName，你這種想法還是太嫩了。",
  str_homestory_803001001_18_dialog_content = "聽我一句勸，你越想禁止的事情往往越會發生。",
  str_homestory_803001001_19_dialog_content = "不要問我如何明白這個道理......",
  str_homestory_803001001_20_dialog_content = "......",
  str_homestory_803001001_21_option_content = "（同意）",
  str_homestory_803001001_22_dialog_content = "嘶，雖然一開始沒有那種規劃......",
  str_homestory_803001001_23_dialog_content = "但是如果有人隨便打架、飆車，說不定會毀壞我辛苦建造起來的房屋。",
  str_homestory_803001001_24_dialog_content = "以後還是規劃一個專門的地方比較好......",
  str_homestory_803001001_25_dialog_content = "哈哈哈，你小子最近真的成長了不少啊。",
  str_homestory_803001001_26_dialog_content = "原來你還挺聽勸的嘛！",
  str_homestory_803001001_27_dialog_content = "話說，你能帶我去女生的空庭宅舍裡面看看嗎？",
  str_homestory_803001001_28_dialog_content = "欸？！",
  str_homestory_803001001_29_dialog_content = "幹嘛用那種驚恐的眼神看著我？",
  str_homestory_803001001_30_dialog_content = "你沒事去女生房間幹嘛啊？",
  str_homestory_803001001_31_dialog_content = "當然是去參觀囉。",
  str_homestory_803001001_32_dialog_content = "參觀？！",
  str_homestory_803001001_33_dialog_content = "不是啊<sprite=emo_qingsong size=60 />，我想看看女生宅舍的環境如何，適不適合我家伊芙住呀。",
  str_homestory_803001001_34_dialog_content = "呼......原來是這樣啊。",
  str_homestory_803001001_35_dialog_content = "我要檢查床墊夠不夠軟......",
  str_homestory_803001001_36_dialog_content = "床頭燈的顏色夠不夠護眼......",
  str_homestory_803001001_37_dialog_content = "床單是不是伊芙喜歡的圖案......",
  str_homestory_803001001_38_dialog_content = "房間裡有沒有大衣櫃讓伊芙掛漂亮裙子......",
  str_homestory_803001001_39_dialog_content = "對對，還有最重要的！房間裡有沒有保溫水杯！",
  str_homestory_803001001_40_option_content = "（同意）",
  str_homestory_803001001_41_dialog_content = "我會請薇絲去確認......",
  str_homestory_803001001_42_dialog_content = "哈哈哈，夠哥們！",
  str_homestory_803001001_43_option_content = "（不同意）",
  str_homestory_803001001_44_dialog_content = "醒山，我覺得你要學著給伊芙一點獨立空間啊。",
  str_homestory_803001001_45_dialog_content = "你說什麼？！",
  str_homestory_803001001_46_dialog_content = "好......好吧！我會請薇絲去確認......",
  str_homestory_811601001_0_dialog_content = "這吭哧吭哧的聲音！",
  str_homestory_811601001_1_dialog_content = "導航員，你來找我修東西嗎？？",
  str_homestory_811601001_2_dialog_content = "來得正好！我今天還沒接到委託呢！",
  str_homestory_811601001_3_dialog_content = "修東西？",
  str_homestory_811601001_4_dialog_content = "你站在貨站這裡，該不會是在......承接訂單吧？！",
  str_homestory_811601001_5_dialog_content = "對啊，我先站在這裡招攬顧客，然後再回房間修東西。",
  str_homestory_811601001_6_dialog_content = "啊，不過你放心，我一律不收費。",
  str_homestory_811601001_7_dialog_content = "那你為什麼......",
  str_homestory_811601001_8_dialog_content = "問我為什麼免費幫大家維修嗎？",
  str_homestory_811601001_9_dialog_content = "對啊，照理說你不是寧可在屋子裡埋頭做自己喜歡的事嗎......？",
  str_homestory_811601001_10_dialog_content = "研究各種零件之類的活動。",
  str_homestory_811601001_11_dialog_content = "因為你這邊聚集了很多來自不同地方來的人嘛。<sprite=emo_sikao size=60 />",
  str_homestory_811601001_12_dialog_content = "他們拜託我修的東西也有不同地方的風格，我覺得滿有趣。",
  str_homestory_811601001_13_dialog_content = "例如卡戎之前希望我能幫他擴大他那台唱片機<sprite=emo_yinfu size=60 />的音量......",
  str_homestory_811601001_14_dialog_content = "我本來以為他那台唱片機是啟光的東西，隨便修修就好了。",
  str_homestory_811601001_15_dialog_content = "天曉得那台唱片機非但不是啟光的產物，還是不知道從哪出產的老古董！",
  str_homestory_811601001_16_dialog_content = "哈哈，所以我就把那台唱片機翻來覆去地好好研究了一遍！",
  str_homestory_811601001_17_dialog_content = "呃......那你......那你真的幫卡戎加大了音量？！",
  str_homestory_811601001_18_dialog_content = "好吧，我承認，我只幫他加大了一點點，做為研究新玩意的報酬......",
  str_homestory_811601001_19_dialog_content = "但......但是！我也知道他偶爾音樂放很大聲，所以我只幫他加大一點點！",
  str_homestory_811601001_20_dialog_content = "好吧......看來你在這裡還挺怡然自得。",
  str_homestory_811601001_21_dialog_content = "那當然！",
  str_homestory_811601001_22_dialog_content = "我能接觸到很多不同的技術、新的零件和設備......簡直太棒了！<sprite=emo_aixin size=60 />",
  str_homestory_811601001_23_dialog_content = "好吧，你習慣就好？",
  str_homestory_811601001_24_dialog_content = "挺習慣的，我覺得我很快就能造成新機甲！",
  str_homestory_811601001_25_dialog_content = "......果然還是為了這個吧？！",
  str_homestory_811601001_26_dialog_content = "沒有啊，我也很關心你喔！你來之前我還幫你檢查過這個貨站的結構。",
  str_homestory_811601001_27_dialog_content = "我拿扳手和螺絲起子敲了敲，發現這亭子還挺穩固，不需要我幫忙。",
  str_homestory_811601001_28_dialog_content = "畢竟這裡使用空谷的材料建造而成啊。",
  str_homestory_811601001_29_dialog_content = "是啊，你看，待在這裡還可以研究空谷的材料，我覺得很棒！",
  str_homestory_811601001_30_dialog_content = "好吧......好吧，那我就不打擾你......呃，接單。",
  str_homestory_811601001_31_dialog_content = "你沒有打擾到我啊，我甚至覺得你可以在這裡跟我一起接單。",
  str_homestory_811601001_32_option_content = "（同意）",
  str_homestory_811601001_33_dialog_content = "好吧......我來看看大家有哪些維修需求。",
  str_homestory_811601001_34_dialog_content = "沒問題！",
  str_homestory_811601001_35_dialog_content = "......不過今天的生意有點冷清呢。",
  str_homestory_811601001_36_dialog_content = "......如果一直沒人找你修東西，那怎麼辦？",
  str_homestory_811601001_37_option_content = "（拒絕）",
  str_homestory_811601001_38_dialog_content = "算了，我還有事要做......",
  str_homestory_811601001_39_dialog_content = "啊，對了。",
  str_homestory_811601001_40_dialog_content = "如果一直沒人找你修東西，那怎麼辦？",
  str_homestory_811601001_41_dialog_content = "就一直傻傻站在這裡嗎？",
  str_homestory_811601001_42_dialog_content = "對啊。",
  str_homestory_811601001_43_dialog_content = "但我要糾正你一點，導航員。",
  str_homestory_811601001_44_dialog_content = "我並非在這裡「傻傻站著」，我的腦中隨時都在進行激烈的機械大戰。",
  str_homestory_811601001_45_dialog_content = "在你來之前，我就在思考PlayerName號機甲和歐緹號機甲的實戰結果。",
  str_homestory_811601001_46_dialog_content = "PlayerName號機甲的攻擊偏向輕盈靈動，而歐緹號機甲的武器裝備比較多......",
  str_homestory_811601001_47_dialog_content = "你們打得真的很激烈啊！",
  str_homestory_811601001_48_dialog_content = "好吧......現在我是真的不想打擾你了......",
  str_homestory_811701001_0_dialog_content = "老克？",
  str_homestory_811701001_1_dialog_content = "克，你在商店做什麼呢？",
  str_homestory_811701001_2_dialog_content = "呃......難道你在沉思嗎？",
  str_homestory_811701001_3_dialog_content = "還是你覺得商店缺少某物？",
  str_homestory_811701001_4_dialog_content = "是你小子啊。",
  str_homestory_811701001_5_dialog_content = "我只是想在這裡找點配料。因為我準備用一些快到期的配給肉做點串燒。",
  str_homestory_811701001_6_dialog_content = "快到期的肉<sprite=emo_rou size=60 />......？",
  str_homestory_811701001_7_dialog_content = "只是快到期，不是過期，沒問題不用怕。",
  str_homestory_811701001_8_dialog_content = "再者，烹飪水準並不取決於食材的好壞，只取決於廚師的技巧！",
  str_homestory_811701001_9_dialog_content = "是！老克你說的沒錯！",
  str_homestory_811701001_10_dialog_content = "說起來，我還沒吃過你做的串燒呢......",
  str_homestory_811701001_11_dialog_content = "遲早有機會。",
  str_homestory_811701001_12_dialog_content = "串燒這任務，對我來說太簡單了。",
  str_homestory_811701001_13_dialog_content = "......簡單？",
  str_homestory_811701001_14_dialog_content = "果然老克你在這方面確實天賦異稟啊......",
  str_homestory_811701001_15_dialog_content = "廚藝，靠天賦？真是前所未聞。",
  str_homestory_811701001_16_dialog_content = "哼，現在的年輕人太喜歡強調天賦了！",
  str_homestory_811701001_17_dialog_content = "很多成就靠的是刻苦努力和勤奮練習，而不是靠什麼破天賦就能夠得到！",
  str_homestory_811701001_18_dialog_content = "我做東西好吃，是因為我之前在廚房待了很多年。",
  str_homestory_811701001_19_dialog_content = "廚藝可說是最不依賴於「天賦」的一種技能了。",
  str_homestory_811701001_20_option_content = "不太懂",
  str_homestory_811701001_21_dialog_content = "我也試著做過，可是就算嚴格按照菜譜指示，做出的菜還是......",
  str_homestory_811701001_22_dialog_content = "也不怎麼好吃。",
  str_homestory_811701001_23_option_content = "好像懂了",
  str_homestory_811701001_24_dialog_content = "廚藝可以透過不斷練習來增進......？",
  str_homestory_811701001_25_dialog_content = "任何事都可以透過不斷練習來增進。",
  str_homestory_811701001_26_dialog_content = "但要想做東西好吃，首先心中不能少了「情感」這玩意。",
  str_homestory_811701001_27_dialog_content = "情感？",
  str_homestory_811701001_28_dialog_content = "這麼說來，薇絲之前做的那些菜......",
  str_homestory_811701001_29_dialog_content = "是一點情感也沒有，還是情感過於濃烈？",
  str_homestory_811701001_30_dialog_content = "顯然她讓那些操作順序和指示的重要性蓋過了情感。",
  str_homestory_811701001_31_dialog_content = "不過也可以說是她患得患失吧。",
  str_homestory_811701001_32_dialog_content = "唔，感覺我自己也是這樣。",
  str_homestory_811701001_33_dialog_content = "既害怕搞砸，又特別希望做出來的料理能好吃，然後就會陷入那種手忙腳亂的境地......",
  str_homestory_811701001_34_dialog_content = "舉個最簡單的例子。",
  str_homestory_811701001_35_dialog_content = "做後勤那時候，儘管我更想上戰場，但還能把食材弄好吃的原因只有一個。",
  str_homestory_811701001_36_dialog_content = "那就是我希望弟兄們都能吃得好，吃得好才有力氣打仗。",
  str_homestory_811701001_37_dialog_content = "如今我在這裡做飯也是基於同樣的原因。",
  str_homestory_811701001_38_dialog_content = "我希望所有年輕人都能吃好！吃好了才有精神戰鬥！",
  str_homestory_811701001_39_dialog_content = "想把東西做好吃就這麼簡單。",
  str_homestory_811701001_40_dialog_content = "只要按照步驟和指示操作，拋棄那些亂七八糟的念頭就行。",
  str_homestory_811701001_41_dialog_content = "想多了反而容易出錯，懂吧？",
  str_homestory_811701001_42_dialog_content = "嗯！我懂了！",
  str_homestory_811701001_43_dialog_content = "你說的太對了，老克！",
  str_homestory_811701001_44_dialog_content = "說真的，我覺得你應該出本書，專門講烹飪技巧。",
  str_homestory_811701001_45_dialog_content = "連紅油沙漠的人都出書了......你也行！",
  str_homestory_811701001_46_dialog_content = "如果你願意，我可以幫你聯絡影鎮的人。",
  str_homestory_811701001_47_dialog_content = "再說吧，我考慮考慮。",
  str_homestory_811701001_48_dialog_content = "假如到時我做好串燒，你要來一起吃嗎，小子？",
  str_homestory_811701001_49_dialog_content = "嗯......嗯嗯！",
  str_homestory_807701001_0_dialog_content = "女王陛下？",
  str_homestory_807701001_1_dialog_content = "女王陛下......",
  str_homestory_807701001_2_dialog_content = "嗯，你來了，擁有未來之人。",
  str_homestory_807701001_3_option_content = "歡迎您",
  str_homestory_807701001_4_dialog_content = "您跋山涉水到達這裡，空谷蓬蓽生輝。",
  str_homestory_807701001_5_dialog_content = "PlayerName，就不必多禮了。",
  str_homestory_807701001_6_dialog_content = "我剛剛一直在看這座風信塔。",
  str_homestory_807701001_7_option_content = "有打擾到您嗎？",
  str_homestory_807701001_8_dialog_content = "看您非常專注的樣子......",
  str_homestory_807701001_9_dialog_content = "沒錯，我在看這座風信塔。",
  str_homestory_807701001_10_dialog_content = "風信塔？它怎麼了？",
  str_homestory_807701001_11_dialog_content = "嗯......這座風信塔，對空裔來說意義非凡。",
  str_homestory_807701001_12_dialog_content = "沒錯！它是一座非常巨大的建築物。",
  str_homestory_807701001_13_dialog_content = "也許從這裡看不那麼清楚，但它其實非常巨大，內部也非常寬敞！",
  str_homestory_807701001_14_dialog_content = "畢竟它還具備生產巨像和維修巨像的功能。",
  str_homestory_807701001_15_dialog_content = "況且根據資料所示，許多空裔都在這裡接受教育。",
  str_homestory_807701001_16_dialog_content = "簡直就像是培養導航員的家園一樣。",
  str_homestory_807701001_17_dialog_content = "家園......是嗎？",
  str_homestory_807701001_18_dialog_content = "看，它在這片天空之下，格外地奪目、耀眼。",
  str_homestory_807701001_19_dialog_content = "更像是空裔的......精神圖騰。",
  str_homestory_807701001_20_dialog_content = "PlayerName，你知道人們之間的凝聚力如何產生嗎？",
  str_homestory_807701001_21_dialog_content = "突然這樣問......",
  str_homestory_807701001_22_dialog_content = "抱歉，我沒仔細想過。",
  str_homestory_807701001_23_dialog_content = "沒關係，這個問題對曾經的你並不重要。",
  str_homestory_807701001_24_dialog_content = "但現在不同，你應該以全新的視角觀察這片大陸。",
  str_homestory_807701001_25_dialog_content = "這裡的芸芸眾生，或高或矮，或強壯或瘦弱，或年老或年幼。",
  str_homestory_807701001_26_dialog_content = "只要有共同的信仰，同樣的信念。",
  str_homestory_807701001_27_dialog_content = "就能凝聚在一起。",
  str_homestory_807701001_28_dialog_content = "我們並非單打獨鬥就能戰勝自然的生物。",
  str_homestory_807701001_29_dialog_content = "沒有銳利的爪或尖牙，沒有岩石般的皮膚和能在天空飛翔的翅膀。",
  str_homestory_807701001_30_dialog_content = "但只要團結在一起，就能激發出難以想像的力量......",
  str_homestory_807701001_31_dialog_content = "這麼說來......",
  str_homestory_807701001_32_dialog_content = "女王陛下其實也像剛剛所說的，那個「精神圖騰」。",
  str_homestory_807701001_33_dialog_content = "......",
  str_homestory_807701001_34_dialog_content = "嗯，確實如此。",
  str_homestory_807701001_35_dialog_content = "大家或因為信賴，或因為仰慕，或因為需要我的庇護而圍繞在我身邊。",
  str_homestory_807701001_36_dialog_content = "這並不是壞事。",
  str_homestory_807701001_37_dialog_content = "團結一致的人，永遠比一盤散沙更有力量。",
  str_homestory_807701001_38_dialog_content = "不管是啟光，還是白夜城，都用他們認為正確的方式維繫著這種團結。",
  str_homestory_807701001_39_dialog_content = "是的......這一點我現在非常能夠理解。",
  str_homestory_807701001_40_dialog_content = "你也成長了，擁有未來的空裔。",
  str_homestory_807701001_41_dialog_content = "這座潔白的塔——空裔的圖騰，就像你一樣......",
  str_homestory_807701001_42_dialog_content = "有著團結眾人的力量。",
  str_homestory_807701001_43_dialog_content = "我也可以團結眾人，守護空谷嗎......啊，女王陛下，我有個冒昧的問題。",
  str_homestory_807701001_44_dialog_content = "無妨，請說吧。",
  str_homestory_807701001_45_dialog_content = "在您預見的未來之中......也看到了今天的空谷嗎？",
  str_homestory_807701001_46_dialog_content = "......當然，而且不止如此。",
  str_homestory_804201001_0_dialog_content = "巴頓！",
  str_homestory_804201001_1_dialog_content = "嘿，導航員！",
  str_homestory_804201001_2_dialog_content = "巴頓——",
  str_homestory_804201001_3_dialog_content = "噓......跟我一起觀察。<sprite=emo_mojing size=60 />",
  str_homestory_804201001_4_dialog_content = "......觀察？",
  str_homestory_804201001_5_dialog_content = "你在觀察什麼？",
  str_homestory_804201001_6_dialog_content = "你這裡有不少人才啊！導航員！",
  str_homestory_804201001_7_dialog_content = "怎麼以前在巨像上的時候，我都沒發現呢？",
  str_homestory_804201001_8_dialog_content = "啊，可能是因為這地方比巨像寬敞很多，所以在這裡施放拳腳的人也更多了吧！",
  str_homestory_804201001_9_dialog_content = "......人才？",
  str_homestory_804201001_10_dialog_content = "你想挖角他們加入啟光嗎......？",
  str_homestory_804201001_11_dialog_content = "加入？不不不，不需要加入。",
  str_homestory_804201001_12_dialog_content = "我問你，PlayerName。你知道我是第幾軍團的統帥吧？",
  str_homestory_804201001_13_option_content = "第二軍團",
  str_homestory_804201001_14_dialog_content = "沒錯！",
  str_homestory_804201001_15_option_content = "第四軍團",
  str_homestory_804201001_16_dialog_content = "你有沒有搞錯？<sprite=emo_shengqi size=60 />小子，我麾下的兵可比那女人多得多多多多了！",
  str_homestory_804201001_17_dialog_content = "哼，雷霆的精銳預備隊根本不堪一擊！",
  str_homestory_804201001_18_dialog_content = "我統帥的是兵力最多的第二軍團，記住了嗎？",
  str_homestory_804201001_19_dialog_content = "記......記住了......",
  str_homestory_804201001_20_dialog_content = "知道大元帥親自託付給我的職責是什麼嗎？",
  str_homestory_804201001_21_option_content = "快速支援？",
  str_homestory_804201001_22_dialog_content = "......那是緋和薇絲的工作。",
  str_homestory_804201001_23_dialog_content = "喂，小子，這一點都記不住？",
  str_homestory_804201001_24_dialog_content = "我的職責是守備！",
  str_homestory_804201001_25_dialog_content = "......現在你總該清楚了吧？",
  str_homestory_804201001_26_dialog_content = "是，是的......",
  str_homestory_804201001_27_option_content = "守備",
  str_homestory_804201001_28_dialog_content = "很好！看來我平時沒有白教你！",
  str_homestory_804201001_29_dialog_content = "所以，既然你都清楚了，那你就該明白我在此的用意。",
  str_homestory_804201001_30_dialog_content = "你想想，這裡有這麼多身懷絕技的傢伙......",
  str_homestory_804201001_31_dialog_content = "他們又時不時就會大打出手......",
  str_homestory_804201001_32_dialog_content = "偷襲！暗器！體術攻擊！",
  str_homestory_804201001_33_dialog_content = "嘖嘖，真是精彩萬分。",
  str_homestory_804201001_34_dialog_content = "對我來說，我不需要他們加入啟光，明白嗎？",
  str_homestory_804201001_35_dialog_content = "我只需要在這裡觀察他們的進攻和防守方式就夠了。",
  str_homestory_804201001_36_dialog_content = "不只我能從不同地方的人身上學到東西，更可以傳授給我的士兵！",
  str_homestory_804201001_37_dialog_content = "這可都是寶貴的資料！",
  str_homestory_804201001_38_dialog_content = "竟然是這樣......",
  str_homestory_804201001_39_dialog_content = "等等，我突然想到，你說的頻繁打架是怎麼回事？！",
  str_homestory_804201001_40_dialog_content = "互相看不順眼的光靈還少嗎？",
  str_homestory_804201001_41_dialog_content = "想想巨像上每天的乒乒乓乓，我還以為你早就習慣了呢。",
  str_homestory_804201001_42_dialog_content = "但是——",
  str_homestory_804201001_43_dialog_content = "你就當他們在友好切磋吧！",
  str_homestory_804201001_44_dialog_content = "我得去思考琢磨昨天看到的那個技巧了......",
  str_homestory_804201001_45_dialog_content = "他到底是怎麼擋住她那一腿的？",
  str_homestory_804201001_46_dialog_content = "嗯，我也得快點學會才行，這樣下次雷霆再來挑釁我的時候，就可以......",
  str_homestory_804201001_47_dialog_content = "嘿——喝！<sprite=emo_nuhuo size=60 />",
  str_homestory_804201001_48_dialog_content = "......好吧，巴頓。加油......",
  str_homestory_807601001_0_dialog_content = "克萊肯......",
  str_homestory_807601001_1_dialog_content = "啊，看來航行的勇者終於著陸了。",
  str_homestory_807601001_2_dialog_content = "嗨，克萊肯。",
  str_homestory_807601001_3_dialog_content = "你很喜歡這座池瀑山石嗎？我看你經常在這附近閒逛.....",
  str_homestory_807601001_4_dialog_content = "這難得有些水流呢。",
  str_homestory_807601001_5_dialog_content = "這裡的水流太過豐沛，我感動得幾乎要落淚<sprite=emo_hanshui size=60 />呢。",
  str_homestory_807601001_6_dialog_content = "是在反諷吧？",
  str_homestory_807601001_7_dialog_content = "畢竟這裡只有些觀賞性質的水流......",
  str_homestory_807601001_8_dialog_content = "跟你平時老是叨念的「大海」、「淹沒」可是完全不同規模。",
  str_homestory_807601001_9_dialog_content = "我是在感謝你呢。",
  str_homestory_807601001_10_dialog_content = "......為了什麼感謝我？",
  str_homestory_807601001_11_dialog_content = "你馬上就會見證到我的「窺視之術」在此成真。",
  str_homestory_807601001_12_dialog_content = "我可以從你那可愛的小腦袋瓜看出你最近做了什麼......",
  str_homestory_807601001_13_dialog_content = "只需要注視著你這雙迷人的眼睛，我就會得到答案。",
  str_homestory_807601001_14_dialog_content = "謝謝你成為我的第一個見證者。",
  str_homestory_807601001_15_dialog_content = "呃......",
  str_homestory_807601001_16_option_content = "窺視之術？",
  str_homestory_807601001_17_dialog_content = "你開始好奇了，我的小伙計......",
  str_homestory_807601001_18_option_content = "能拒絕嗎？",
  str_homestory_807601001_19_dialog_content = "可以。",
  str_homestory_807601001_20_dialog_content = "但我身後那些靈動的小傢伙可不會放過你。",
  str_homestory_807601001_21_dialog_content = "它們最喜歡在你熟睡的時候觀察你了，PlayerName......",
  str_homestory_807601001_22_dialog_content = "（......這是什麼毛骨悚然的場景啊！）",
  str_homestory_807601001_23_dialog_content = "好吧......就一會，我很忙的。",
  str_homestory_807601001_24_dialog_content = "究竟什麼是「窺視之術」？",
  str_homestory_807601001_25_dialog_content = "我馬上向你說明，勇者。",
  str_homestory_807601001_26_dialog_content = "我想你最近一定去了影鎮......",
  str_homestory_807601001_27_dialog_content = "你在街上悠哉閒逛，卻發現一個可憐的小女孩。",
  str_homestory_807601001_28_dialog_content = "小女孩請你幫她進去看路邊眾多餐廳的價格......",
  str_homestory_807601001_29_dialog_content = "她手裡的錢實在是太少了，又不敢貿然走進餐廳用餐。",
  str_homestory_807601001_30_dialog_content = "只點一片麵包的話，真不敢想像那些服務生的臉色啊......",
  str_homestory_807601001_31_dialog_content = "你帶著她去了一家又一家餐廳，告訴她一個又一個餐點價格。",
  str_homestory_807601001_32_dialog_content = "不過她每次都搖頭。",
  str_homestory_807601001_33_dialog_content = "最後你實在是難以釋懷，索性請她吃了頓美食......",
  str_homestory_807601001_34_dialog_content = "誰知用完餐後，她對你道了聲謝就飛快跑走，還把餐費留在桌子上。",
  str_homestory_807601001_35_dialog_content = "......你怎麼知道？！",
  str_homestory_807601001_36_dialog_content = "（......這個「窺視之術」居然真的這麼神奇？）",
  str_homestory_807601001_37_dialog_content = "總之......好吧，我確實很費解。",
  str_homestory_807601001_38_dialog_content = "她既然有餐費的話，為什麼最開始不直接進店吃飯呢？",
  str_homestory_807601001_39_dialog_content = "跟你說的一樣......她幾乎看了影鎮每一家餐廳和每一道菜的價格！",
  str_homestory_807601001_40_dialog_content = "哈哈......哈哈哈<sprite=emo_guilian size=60 />。",
  str_homestory_807601001_41_dialog_content = "因為是我讓她這麼做的啊。",
  str_homestory_807601001_42_dialog_content = "這本來是伊斯塔萬大人指派給我的任務......",
  str_homestory_807601001_43_dialog_content = "「調查影鎮的餐飲價格」。",
  str_homestory_807601001_44_dialog_content = "我請我持續援助的女孩幫我一個小小的忙，既可以讓她覺得自己「有用」......",
  str_homestory_807601001_45_dialog_content = "又可以讓無所事事的空裔替我完成工作，何樂而不為呢？",
  str_homestory_807601001_46_dialog_content = "畢竟......走路這種事，對我來說太累了啊。",
  str_homestory_807601001_47_dialog_content = "......",
  str_homestory_807601001_48_dialog_content = "哎呀，這就是「窺視之術」的真相呢，PlayerName。",
  str_homestory_807601001_49_dialog_content = "看看你這一臉失望的表情......真是太有意思了。",
  str_homestory_804601001_0_dialog_content = "是他啊。",
  str_homestory_804601001_1_dialog_content = "導航員來，導航員到♪",
  str_homestory_804601001_2_dialog_content = "導航員對皮耶爾笑笑，而皮耶爾卻只想鬧鬧。",
  str_homestory_804601001_3_dialog_content = "你在逛商店嗎？",
  str_homestory_804601001_4_dialog_content = "逛商店，大人覺得皮耶爾在逛商店<sprite=emo_yinfu size=60 />",
  str_homestory_804601001_5_dialog_content = "迪亞姆會說不對，卡拉會說沒錯，尼爾會說差不多......而皮耶爾只說「咕咕！」<sprite=emo_muji size=60 />",
  str_homestory_804601001_6_dialog_content = "那麼，大人覺得我到底在說什麼呢？",
  str_homestory_804601001_7_dialog_content = "......％￥＃",
  str_homestory_804601001_8_dialog_content = "算了，我還是放棄猜謎吧......",
  str_homestory_804601001_9_dialog_content = "我本來想問問你在這裡生活得如何......",
  str_homestory_804601001_10_dialog_content = "不過，見你還是這副人小鬼大的樣子，我就放心了。",
  str_homestory_804601001_11_dialog_content = "大人關心基汀，皮耶爾倍感榮幸♪",
  str_homestory_804601001_12_dialog_content = "大人不好奇我最近遇到了什麼人嗎？",
  str_homestory_804601001_13_dialog_content = "......我怎麼有種不好的預感？<sprite=emo_tanqi size=60 />",
  str_homestory_804601001_14_dialog_content = "你遇到誰來著？",
  str_homestory_804601001_15_dialog_content = "除了你，其他幾個小鬼也要稍微注意一點啊，不要對誰都出言嘲諷......",
  str_homestory_804601001_16_dialog_content = "這裡可不是白夜城，有些地方的光靈脾氣很壞！",
  str_homestory_804601001_17_dialog_content = "還有些光靈很敏感，我覺得那些光靈被你們說兩句就會哭......",
  str_homestory_804601001_18_dialog_content = "大人擔心我們，大人擔心夥伴♪",
  str_homestory_804601001_19_dialog_content = "我們遇到了長尾巴的維修工，請他幫我們製作抓雞機械手；",
  str_homestory_804601001_20_dialog_content = "我們遇到了圓乎乎的小鳥兒，她送了我們好多個滾滾雪球；",
  str_homestory_804601001_21_dialog_content = "我們遇到了穿西裝的小狗狗，正在為賣不出去的假畫發愁；",
  str_homestory_804601001_22_dialog_content = "皮耶爾遇到了矮胖的導航員，在我的對面擔心自己的朋友♪",
  str_homestory_804601001_23_dialog_content = "......好吧，聽起來沒出什麼亂子。",
  str_homestory_804601001_24_dialog_content = "不過老實說，我覺得這大概是你說過最溫和的一段話吧......",
  str_homestory_804601001_25_dialog_content = "溫和的話語，往往事出有因。",
  str_homestory_804601001_26_dialog_content = "書櫃裡有迪亞姆喜歡的書籍；",
  str_homestory_804601001_27_dialog_content = "房間裡有尼爾需要的拭鏡布；",
  str_homestory_804601001_28_dialog_content = "餐廳裡有卡拉必備的置帽架；",
  str_homestory_804601001_29_dialog_content = "草地上有咕咕和皮耶爾最愛的零食♪",
  str_homestory_804601001_30_dialog_content = "大人對我們如此貼心，大人真是我們的知音；",
  str_homestory_804601001_31_dialog_content = "大人是明日之星；",
  str_homestory_804601001_32_dialog_content = "一定會長高的明日之星♪",
  str_homestory_804601001_33_dialog_content = "......不加最後一句其實也很押韻了。",
  str_homestory_804601001_34_dialog_content = "大人準備去做什麼？",
  str_homestory_804601001_35_option_content = "回去休息",
  str_homestory_804601001_36_dialog_content = "小睡一下吧。",
  str_homestory_804601001_37_option_content = "隨便繞繞",
  str_homestory_804601001_38_dialog_content = "我準備去看看其他人在做什麼。",
  str_homestory_804601001_39_dialog_content = "知道了，皮耶爾知道了。",
  str_homestory_804601001_40_dialog_content = "雖然皮耶爾其實並不關心，但還是有句話要告訴大人；",
  str_homestory_804601001_41_dialog_content = "咕咕正在大人的花圃附近施肥，施肥♪",
  str_homestory_804601001_42_dialog_content = "......？！",
  str_homestory_804601001_43_dialog_content = "施肥？！",
  str_homestory_804601001_44_dialog_content = "皮耶爾好心告訴你，還是快去看看情況吧♪",
  str_homestory_804601001_45_dialog_content = "......還真是謝謝你的好心！",
  str_homestory_805701001_0_dialog_content = "這是......貓毛？",
  str_homestory_805701001_1_dialog_content = "呵——欠——",
  str_homestory_805701001_2_dialog_content = "欸？菲莉詩？",
  str_homestory_805701001_3_dialog_content = "呼......呼......<sprite=emo_kun size=60 />",
  str_homestory_805701001_4_dialog_content = "......菲莉詩？",
  str_homestory_805701001_5_dialog_content = "呼......呼喵！",
  str_homestory_805701001_6_dialog_content = "什麼嘛，原來是PlayerName喵。",
  str_homestory_805701001_7_dialog_content = "沒看到人家正在睡覺嗎喵。",
  str_homestory_805701001_8_dialog_content = "不管有什麼事......等我睡醒了再說吧喵。",
  str_homestory_805701001_9_dialog_content = "現在我就要鑽進這個暖暖的稻草堆......舒舒服服睡上一覺喵......",
  str_homestory_805701001_10_dialog_content = "等......等一下，菲莉詩，我有話要說！",
  str_homestory_805701001_11_dialog_content = "呼......呼......喵！",
  str_homestory_805701001_12_dialog_content = "真是的......到底有什麼話要說呀喵。",
  str_homestory_805701001_13_dialog_content = "如果不是重要的事，我可是會生氣的喵！",
  str_homestory_805701001_14_dialog_content = "那個......其實有其他光靈找上我......",
  str_homestory_805701001_15_dialog_content = "菲莉詩妳最近是不是......",
  str_homestory_805701001_16_option_content = "身體不適？",
  str_homestory_805701001_17_dialog_content = "比如說......身上癢癢的......",
  str_homestory_805701001_18_dialog_content = "或者食慾不振之類的？",
  str_homestory_805701001_19_dialog_content = "你在說什麼呀喵。",
  str_homestory_805701001_20_dialog_content = "菲莉詩完全不懂你的話喔～",
  str_homestory_805701001_21_option_content = "換毛期？",
  str_homestory_805701001_22_dialog_content = "環喵器喵......？",
  str_homestory_805701001_23_dialog_content = "那是什麼呀？",
  str_homestory_805701001_24_dialog_content = "（裝傻也太明顯了！）",
  str_homestory_805701001_25_dialog_content = "總......總之，菲莉詩完全沒感覺！",
  str_homestory_805701001_26_dialog_content = "（摸了摸菲莉詩的尾巴）",
  str_homestory_805701001_27_dialog_content = "喵！",
  str_homestory_805701001_28_dialog_content = "PlayerName怎麼能突然摸淑女的尾巴！",
  str_homestory_805701001_29_dialog_content = "雖......雖然有點舒服，不對喵！",
  str_homestory_805701001_30_dialog_content = "菲莉詩妳抖起來，掉毛更嚴重了！",
  str_homestory_805701001_31_dialog_content = "這，這不是......！",
  str_homestory_805701001_32_dialog_content = "嗚......嗚喵，但是人家沒有辦法嘛！",
  str_homestory_805701001_33_dialog_content = "每到這個季節就會......換毛，不對喵！",
  str_homestory_805701001_34_dialog_content = "這是毛毛吸收了太陽的力量，在進行全新的進化喵！",
  str_homestory_805701001_35_dialog_content = "等它們都換完了......人家就會變成超——級菲莉詩囉！",
  str_homestory_805701001_36_dialog_content = "但是......放任貓毛亂飛的話......",
  str_homestory_805701001_37_dialog_content = "有些容易過敏的光靈可能會很難受喔？",
  str_homestory_805701001_38_dialog_content = "唔......那，那要怎麼辦嘛。",
  str_homestory_805701001_39_dialog_content = "菲莉詩也不想這樣的喵。<sprite=emo_tanqi size=60 />",
  str_homestory_805701001_40_dialog_content = "也是呢......我想想......",
  str_homestory_805701001_41_dialog_content = "對了！不如我來幫妳梳毛吧。",
  str_homestory_805701001_42_dialog_content = "只要經常梳理，毛髮不僅會更順滑，也不會到處亂飛了。",
  str_homestory_805701001_43_dialog_content = "這是伊斯塔萬教我的理論。",
  str_homestory_805701001_44_dialog_content = "嗯......那麼看在你在空谷準備了這麼舒服的稻草堆的份上。",
  str_homestory_805701001_45_dialog_content = "勉強允許你幫我梳毛吧喵！",
  str_homestory_803601001_0_dialog_content = "修拉德？",
  str_homestory_803601001_1_dialog_content = "你在做什麼呢？",
  str_homestory_803601001_2_dialog_content = "看不出來嗎？",
  str_homestory_803601001_3_dialog_content = "我在站立。",
  str_homestory_803601001_4_dialog_content = "......我，我看得出來。",
  str_homestory_803601001_5_dialog_content = "......",
  str_homestory_803601001_6_dialog_content = "............",
  str_homestory_803601001_7_dialog_content = "喂。",
  str_homestory_803601001_8_dialog_content = "嗯？",
  str_homestory_803601001_9_dialog_content = "我昨天受傷了。",
  str_homestory_803601001_10_dialog_content = "......？！",
  str_homestory_803601001_11_option_content = "你還好嗎？",
  str_homestory_803601001_12_dialog_content = "這不是沒死嗎。",
  str_homestory_803601001_13_option_content = "你去了哪裡？",
  str_homestory_803601001_14_dialog_content = "我知道你在擔心什麼。",
  str_homestory_803601001_15_dialog_content = "我不是在這裡受的傷。",
  str_homestory_803601001_16_dialog_content = "我......我只是有點擔心你的健康狀況。",
  str_homestory_803601001_17_dialog_content = "現在呢，傷勢好些了嗎？",
  str_homestory_803601001_18_dialog_content = "差不多吧。",
  str_homestory_803601001_19_dialog_content = "恢復得這麼迅速，多虧了影狼。",
  str_homestory_803601001_20_dialog_content = "好吧......你能不能告訴我，為什麼會受傷？",
  str_homestory_803601001_21_dialog_content = "難道你熱衷此道？",
  str_homestory_803601001_22_dialog_content = "為了和別人搶東西才受傷的。",
  str_homestory_803601001_23_dialog_content = "在影鎮黑市裡。",
  str_homestory_803601001_24_dialog_content = "什麼東西這麼重要？",
  str_homestory_803601001_25_dialog_content = "據說是一種古文明的產物。",
  str_homestory_803601001_26_dialog_content = "「據說」？",
  str_homestory_803601001_27_dialog_content = "就是說，其實你不知道那玩意是真的還是假的？",
  str_homestory_803601001_28_dialog_content = "那也要試試。",
  str_homestory_803601001_29_dialog_content = "......究竟什麼東西這麼重要？",
  str_homestory_803601001_30_dialog_content = "一種能把「幻覺」或者「影魔法」一類的靈體給完全實體化的儀器。",
  str_homestory_803601001_31_dialog_content = "呃......可你的影狼不是一直在你身邊嗎？",
  str_homestory_803601001_32_dialog_content = "嗯，但我想每天都能摸到牠們的皮毛。",
  str_homestory_803601001_33_dialog_content = "真的皮毛，從皮膚上長出來的皮毛。不是換毛期才會掉下來的零星的毛髮。",
  str_homestory_803601001_34_dialog_content = "原來是這樣啊......",
  str_homestory_803601001_35_dialog_content = "（修拉德是不是......有些孤單呢？）",
  str_homestory_803601001_36_dialog_content = "但我覺得應該是假的。",
  str_homestory_803601001_37_dialog_content = "那種儀器嗎？",
  str_homestory_803601001_38_dialog_content = "嗯。",
  str_homestory_803601001_39_dialog_content = "反正我從來沒聽說過這種東西。",
  str_homestory_803601001_40_dialog_content = "（如果說是假的話，他會比較好受吧？）",
  str_homestory_803601001_41_dialog_content = "嗯，我也覺得是假的。",
  str_homestory_803601001_42_dialog_content = "如果真有這種東西，早就成為珍奇的傳家之寶了......",
  str_homestory_803601001_43_dialog_content = "不大可能會在黑市出現。",
  str_homestory_803601001_44_dialog_content = "......嗯。",
  str_homestory_803601001_45_dialog_content = "既然你都這麼說了。",
  str_homestory_803601001_46_dialog_content = "我走了。",
  str_homestory_803601001_47_dialog_content = "再......再見！",
  str_homestory_803601001_48_dialog_content = "（如果真的有這種東西......我又會想拿來做什麼呢？）",
  str_homestory_811401001_0_dialog_content = "這匹馬......",
  str_homestory_811401001_1_dialog_content = "噢，尊敬的導航員先生。",
  str_homestory_811401001_2_dialog_content = "安娜擋住你的路了嗎？",
  str_homestory_811401001_3_dialog_content = "還是說你是來找我的？",
  str_homestory_811401001_4_dialog_content = "抱歉，我在這裡待了這麼久，只是因為被這些花朵迷人的芬芳給套住了而已......",
  str_homestory_811401001_5_dialog_content = "不，我沒什麼事，妳可以盡情地在這裡賞花。",
  str_homestory_811401001_6_dialog_content = "這麼快就到了嗎，這些花......",
  str_homestory_811401001_7_dialog_content = "數量比我想像得要多啊。",
  str_homestory_811401001_8_dialog_content = "嗯？導航員先生，你在說什麼？",
  str_homestory_811401001_9_dialog_content = "啊，我是在說這些花。",
  str_homestory_811401001_10_dialog_content = "是我委託信使公會<sprite=emo_gezitou size=60 />前幾天剛送來的。",
  str_homestory_811401001_11_dialog_content = "因為有人覺得這裡到處都是岩石和樹，也該有點花兒才行。",
  str_homestory_811401001_12_dialog_content = "喔？居然有人和我持相同看法？",
  str_homestory_811401001_13_dialog_content = "我前幾天也在和安娜說呢，我覺得這裡需要更多鮮花。",
  str_homestory_811401001_14_dialog_content = "嗯，是的。所以我才讓信使公會送了點過來。",
  str_homestory_811401001_15_dialog_content = "但這花兒現在的數量，好像比我需要的更多......",
  str_homestory_811401001_16_dialog_content = "因為在完成上一單任務之後，我也順手在那附近買了點花。",
  str_homestory_811401001_17_dialog_content = "原來是這樣......",
  str_homestory_811401001_18_dialog_content = "不過你這裡還真不錯呢，導航員先生。",
  str_homestory_811401001_19_dialog_content = "我去商店看了看，居然有我最愛的琴酒......",
  str_homestory_811401001_20_dialog_content = "不僅如此，還有些調酒必備的植物、糖漿和香料。",
  str_homestory_811401001_21_dialog_content = "哈哈，真是出乎我的意料！",
  str_homestory_811401001_22_dialog_content = "你似乎變得更體貼了嘛？",
  str_homestory_811401001_23_dialog_content = "體......體貼......",
  str_homestory_811401001_24_dialog_content = "之前那個毛頭小子到底是經歷了什麼～才變得如此體貼呢？",
  str_homestory_811401001_25_dialog_content = "吉納維芙的體貼......是指商店裡放了琴酒這件事嗎？",
  str_homestory_811401001_26_dialog_content = "不僅如此喔，你還主動讓小鳥們送來了女士們都很愛的鮮花呢。",
  str_homestory_811401001_27_dialog_content = "那個......其......其實......",
  str_homestory_811401001_28_dialog_content = "請我在商店裡放上琴酒，並請我預定鮮花的那個人是......",
  str_homestory_811401001_29_dialog_content = "......是斯莫奇。",
  str_homestory_811401001_30_dialog_content = "............喔？",
  str_homestory_811401001_31_dialog_content = "不過她還額外提出了很多要求，我想她並不是在針對妳......",
  str_homestory_811401001_32_dialog_content = "這麼說來......我那天在這裡和安娜說話的時候，確實感覺身邊有股灼熱的氣息。",
  str_homestory_811401001_33_dialog_content = "不過你這裡會用火<sprite=emo_nuhuo size=60 />的傢伙很多，所以我就沒往她身上想。",
  str_homestory_811401001_34_dialog_content = "......這傢伙......",
  str_homestory_811401001_35_dialog_content = "她大概也不希望我知道這件事吧？",
  str_homestory_811401001_36_dialog_content = "嗯......我覺得......",
  str_homestory_811401001_37_option_content = "她希望",
  str_homestory_811401001_38_dialog_content = "不然憑她的本事，自己也能弄到不少琴酒和花來這裡才對吧......",
  str_homestory_811401001_39_dialog_content = "我的意思是，她不一定得透過我才能完成這些事情。",
  str_homestory_811401001_40_option_content = "她不希望",
  str_homestory_811401001_41_dialog_content = "我上次問了她是不是特地為妳準備這些琴酒，然後她狠狠地否認了......",
  str_homestory_811401001_42_dialog_content = "原來是這樣嗎？",
  str_homestory_811401001_43_dialog_content = "她還真是彆扭啊。",
  str_homestory_811401001_44_dialog_content = "不過無論如何，還是請導航員先生別把我們今天的對話告訴她吧。",
  str_homestory_811401001_45_dialog_content = "儘管我知道了她的好意，但若她的好意被別人當面指摘的話......",
  str_homestory_811401001_46_dialog_content = "她恐怕會透過放火和暴躁地叫囂這兩種方式來掩飾自己的害羞。",
  str_homestory_811401001_47_dialog_content = "好，我知道了......",
  str_homestory_811401001_48_dialog_content = "不過，妳還真是了解她啊！",
  str_homestory_811401001_49_dialog_content = "是嗎？我可不這麼覺得。",
  str_homestory_801801001_0_dialog_content = "這股狂野的氣息......",
  str_homestory_801801001_1_dialog_content = "不！必！在！乎！",
  str_homestory_801801001_2_dialog_content = "更............不必多說！",
  str_homestory_801801001_3_dialog_content = "愚蠢的人有那麼那麼多！火焰！焦灼！<sprite=emo_nuhuo size=60 />",
  str_homestory_801801001_4_dialog_content = "（她好忘我啊！）",
  str_homestory_801801001_5_dialog_content = "嗨，蕾吉娜！",
  str_homestory_801801001_6_dialog_content = "導航員，怎麼樣？這是我新寫的demo！",
  str_homestory_801801001_7_dialog_content = "剛剛含糊不清的那些發音......是不是髒話？",
  str_homestory_801801001_8_dialog_content = "這樣都被你發現了？",
  str_homestory_801801001_9_dialog_content = "是啊！",
  str_homestory_801801001_10_dialog_content = "哎，可惜，我已經盡量含蓄表達了！",
  str_homestory_801801001_11_dialog_content = "你居然還能聽出來？",
  str_homestory_801801001_12_dialog_content = "你肯定是被帶壞了吧！",
  str_homestory_801801001_13_dialog_content = "......？",
  str_homestory_801801001_14_dialog_content = "咳，沒有......",
  str_homestory_801801001_15_dialog_content = "沒有就沒有吧，都無所謂！",
  str_homestory_801801001_16_dialog_content = "我的新歌還沒寫完，你有沒有想法？給我來點熱烈的建議吧！",
  str_homestory_801801001_17_dialog_content = "題材？歌詞？旋律？",
  str_homestory_801801001_18_dialog_content = "我......我真的不太懂音樂。",
  str_homestory_801801001_19_dialog_content = "那又怎麼樣？我最討厭那些給音樂樹立門檻的老頑固了！",
  str_homestory_801801001_20_dialog_content = "隨便說點什麼！",
  str_homestory_801801001_21_dialog_content = "......",
  str_homestory_801801001_22_option_content = "芭芭拉最棒",
  str_homestory_801801001_23_dialog_content = "哈？你在說什麼？！",
  str_homestory_801801001_24_dialog_content = "我明白了，這一定是嘲諷吧。",
  str_homestory_801801001_25_option_content = "金屬不死！",
  str_homestory_801801001_26_dialog_content = "說得好啊！！",
  str_homestory_801801001_27_dialog_content = "我記下來了！",
  str_homestory_801801001_28_dialog_content = "哈，加入了空裔創意的新作品，一定會比同行們更炸裂！",
  str_homestory_801801001_29_dialog_content = "啊，原來妳不光和芭芭拉在不同的領域競爭，也和同行們競爭嗎？",
  str_homestory_801801001_30_dialog_content = "拜託，搞音樂的誰不是自己第一名啊？<sprite=emo_shengqi size=60 />",
  str_homestory_801801001_31_dialog_content = "尤其是我那幫同行，多得是什麼也不懂又愛裝的人！",
  str_homestory_801801001_32_dialog_content = "每次碰面就是一副他最懂搖滾、最資深的樣子，實際上一首歌也沒自己寫過！",
  str_homestory_801801001_33_dialog_content = "哼，每次見到他們，我都恨不得直接把這群虛偽的人燒個精光......",
  str_homestory_801801001_34_dialog_content = "比起和在他們一起「交流金屬」，我寧願去聽芭芭拉的新單曲！",
  str_homestory_801801001_35_dialog_content = "......喔，原來妳也沒那麼討厭芭芭拉嘛。",
  str_homestory_801801001_36_dialog_content = "兩秒。",
  str_homestory_801801001_37_dialog_content = "......？",
  str_homestory_801801001_38_dialog_content = "芭芭拉的新單曲，我只能忍受兩秒。",
  str_homestory_801801001_39_dialog_content = "好......好吧......",
  str_homestory_809201001_0_dialog_content = "是......",
  str_homestory_809201001_1_dialog_content = "是妳呀，契法。",
  str_homestory_809201001_2_dialog_content = "不然還能是誰？<sprite=emo_baiyan size=60 />",
  str_homestory_809201001_3_dialog_content = "咳咳，因為有很多人都挺喜歡在這裡盪鞦韆......",
  str_homestory_809201001_4_dialog_content = "所以，妳也喜歡盪鞦韆嗎？",
  str_homestory_809201001_5_dialog_content = "你這樣問我，不算很嚴謹。",
  str_homestory_809201001_6_dialog_content = "首先應該詳細定義「喜歡」的含義。",
  str_homestory_809201001_7_option_content = "（下定義）",
  str_homestory_809201001_8_dialog_content = "我覺得喜歡就是經常想做這件事吧。",
  str_homestory_809201001_9_dialog_content = "「經常」是指多頻繁？這個概念也很模糊。",
  str_homestory_809201001_10_dialog_content = "是無時無刻不在想做這件事？",
  str_homestory_809201001_11_dialog_content = "還是閒下來才會想到做這件事？",
  str_homestory_809201001_12_dialog_content = "還是雖然不經常想起這件事，但是偶爾想起來還是會去做？",
  str_homestory_809201001_13_dialog_content = "（救命，我只是想和契法閒聊啊......）",
  str_homestory_809201001_14_dialog_content = "可能是閒下來就會想去做一件事的程度？",
  str_homestory_809201001_15_option_content = "（拒絕定義）",
  str_homestory_809201001_16_dialog_content = "喜歡就是喜歡啊......這還用定義嗎？",
  str_homestory_809201001_17_dialog_content = "就像我閒下來的時候，就喜歡到處逛逛一樣。",
  str_homestory_809201001_18_dialog_content = "閒下來的時候會想到要做的事情嗎？",
  str_homestory_809201001_19_dialog_content = "我明白了。",
  str_homestory_809201001_20_dialog_content = "從這個層次去理解的話，我確實喜歡坐在這個鞦韆上。",
  str_homestory_809201001_21_dialog_content = "吊掛懸空的座椅，給人以恰到好處的失重感......",
  str_homestory_809201001_22_dialog_content = "我從中感受到了一種難以言喻的喜悅。",
  str_homestory_809201001_23_dialog_content = "真的嗎？那真是太好了！",
  str_homestory_809201001_24_dialog_content = "起初在建造鞦韆的時候，我還有點遲疑呢。",
  str_homestory_809201001_25_dialog_content = "看契法也這麼喜歡，我就放心了！",
  str_homestory_809201001_26_dialog_content = "不過，也有麻煩的時候。",
  str_homestory_809201001_27_dialog_content = "「獵石」在背後幫我推鞦韆的力度總是掌握得不好。",
  str_homestory_809201001_28_dialog_content = "有一次我還直接被推下來！",
  str_homestory_809201001_29_dialog_content = "哈哈哈......",
  str_homestory_809201001_30_dialog_content = "你是在嘲笑我嗎？！<sprite=emo_shengqi size=60 />",
  str_homestory_809201001_31_option_content = "（否認）",
  str_homestory_809201001_32_dialog_content = "沒有沒有......",
  str_homestory_809201001_33_dialog_content = "還說沒有？那拜託你解釋一下你上揚的嘴角到底是怎麼回事？",
  str_homestory_809201001_34_option_content = "（承認）",
  str_homestory_809201001_35_dialog_content = "抱歉......",
  str_homestory_809201001_36_dialog_content = "一不小心在腦海裡想像了一下當時的畫面......",
  str_homestory_809201001_37_dialog_content = "咳咳，總之妳沒有受傷吧？",
  str_homestory_809201001_38_dialog_content = "如你所見，我不是會輕易受傷的角色。",
  str_homestory_809201001_39_dialog_content = "沒有受傷就好！但既然妳這麼喜歡盪鞦韆......",
  str_homestory_809201001_40_dialog_content = "我幫妳在後面推鞦韆怎麼樣？",
  str_homestory_809201001_41_dialog_content = "咦？可以嗎......",
  str_homestory_809201001_42_dialog_content = "只要妳不嫌棄我的力氣並不比「獵石」大。",
  str_homestory_809201001_43_dialog_content = "那就要看你怎麼定義「嫌棄」這個詞了。",
  str_homestory_809201001_44_dialog_content = "呃......",
  str_homestory_809201001_45_dialog_content = "走吧，我們還是去盪鞦韆吧！",
  str_homestory_809201001_46_dialog_content = "嗯......沒辦法，既然你這麼誠懇邀約，那就走吧。",
  str_homestory_809901001_0_dialog_content = "艾蕾雅......",
  str_homestory_809901001_1_dialog_content = "啊，是PlayerName......",
  str_homestory_809901001_2_dialog_content = "謝謝你邀我來這裡，我......很開心！",
  str_homestory_809901001_3_dialog_content = "不用這麼客氣！",
  str_homestory_809901001_4_dialog_content = "這附近妳還不熟吧，要不要我帶妳四處走走？",
  str_homestory_809901001_5_dialog_content = "真的可以勞煩PlayerName嗎？",
  str_homestory_809901001_6_dialog_content = "當然，我可是最熟悉這裡的人囉。",
  str_homestory_809901001_7_dialog_content = "不過......",
  str_homestory_809901001_8_dialog_content = "我......我想我還是回房去吧。",
  str_homestory_809901001_9_dialog_content = "欸？艾蕾雅不喜歡外面的景色嗎？",
  str_homestory_809901001_10_dialog_content = "簡單說，我很喜歡這裡的氛圍！",
  str_homestory_809901001_11_dialog_content = "我從沒來過這麼幽靜又愜意的地方呢。",
  str_homestory_809901001_12_option_content = "（表示感謝）",
  str_homestory_809901001_13_dialog_content = "謝謝妳喜歡這裡！",
  str_homestory_809901001_14_dialog_content = "不過這裡可不止幽靜愜意的地方，還有歡樂熱鬧的地方呢。",
  str_homestory_809901001_15_dialog_content = "我帶妳去逛逛吧。",
  str_homestory_809901001_16_dialog_content = "可是我會怕......",
  str_homestory_809901001_17_option_content = "（表示疑問）",
  str_homestory_809901001_18_dialog_content = "那為什麼急著回房間呢？",
  str_homestory_809901001_19_dialog_content = "我害怕......",
  str_homestory_809901001_20_dialog_content = "怕身上的詛咒和黑棘......會毀掉這片景色。",
  str_homestory_809901001_21_dialog_content = "那樣會給PlayerName添很多麻煩......",
  str_homestory_809901001_22_dialog_content = "艾蕾雅，謝謝妳這麼為我著想。",
  str_homestory_809901001_23_dialog_content = "但是我不覺得妳會毀掉這裡的景色呀。",
  str_homestory_809901001_24_dialog_content = "欸？",
  str_homestory_809901001_25_dialog_content = "妳看我們認識這麼久，妳的詛咒並沒有轉移到我身上呀？",
  str_homestory_809901001_26_dialog_content = "但我身上的黑棘......",
  str_homestory_809901001_27_dialog_content = "它們是幫妳抵禦詛咒侵蝕身體的朋友，不是嗎？",
  str_homestory_809901001_28_dialog_content = "嗯......",
  str_homestory_809901001_29_dialog_content = "艾蕾雅的朋友，就是我的朋友！",
  str_homestory_809901001_30_dialog_content = "況且......",
  str_homestory_809901001_31_dialog_content = "我記得妳仍持續在尋找消除身上詛咒的辦法。",
  str_homestory_809901001_32_dialog_content = "說不定在這裡多逛逛，能發現消除詛咒的辦法呢？",
  str_homestory_809901001_33_dialog_content = "呼呼呼......就算是PlayerName說的，我也難以採信呢。",
  str_homestory_809901001_34_dialog_content = "畢竟過了這麼多年，哪可能說找到就找到呢......",
  str_homestory_809901001_35_dialog_content = "以前妳是不是除了工作，很少出門？",
  str_homestory_809901001_36_dialog_content = "嗯......",
  str_homestory_809901001_37_dialog_content = "其實在外面接觸大自然，心情會好很多喔。",
  str_homestory_809901001_38_dialog_content = "心情好了，那些亂七八糟的詛咒之類的，很有可能減弱！",
  str_homestory_809901001_39_dialog_content = "......",
  str_homestory_809901001_40_dialog_content = "哈哈哈......",
  str_homestory_809901001_41_dialog_content = "謝謝你，我已經感覺到心情開朗許多呢。<sprite=emo_aixin size=60 />",
  str_homestory_809901001_42_dialog_content = "既然這樣......我想去挖礦的地方看看，可以嗎？",
  str_homestory_809901001_43_dialog_content = "欸？",
  str_homestory_801601001_0_dialog_content = "卡夫卡？",
  str_homestory_801601001_1_dialog_content = "等等，卡夫卡......地上這灘已經乾涸的水漬<sprite=emo_hanshui size=60 />是怎麼來的？",
  str_homestory_801601001_2_dialog_content = "噢......抱歉，是法蘭茲<sprite=emo_goutou size=60 />的口水，我剛擦乾。",
  str_homestory_801601001_3_dialog_content = "他最近一開心就流口水，我好不容易才把這個新毛病給糾正過來。",
  str_homestory_801601001_4_dialog_content = "呃，至少他把口水流在我床上的次數少了很多。",
  str_homestory_801601001_5_dialog_content = "好吧，確實值得獎勵......不過法蘭茲向來相當乖巧吧？",
  str_homestory_801601001_6_dialog_content = "你這麼誇他，他會得意忘形的。",
  str_homestory_801601001_7_dialog_content = "不過我能看出來，他在這裡待得很開心就是了。",
  str_homestory_801601001_8_dialog_content = "嗯？是因為這裡比巨像寬敞嗎？",
  str_homestory_801601001_9_dialog_content = "也可能是因為他總能遇到奇怪的人吧......",
  str_homestory_801601001_10_dialog_content = "不過你也知道，他特別喜歡「奇怪」的東西。",
  str_homestory_801601001_11_dialog_content = "奇怪的東西，例如什麼？",
  str_homestory_801601001_12_dialog_content = "應該用「奇怪的生物」來形容會更精準。",
  str_homestory_801601001_13_dialog_content = "奇怪的生物......",
  str_homestory_801601001_14_dialog_content = "我知道了，妳一定是在說......他吧？",
  str_homestory_801601001_15_option_content = "巡迴犬？",
  str_homestory_801601001_16_dialog_content = "呃，好像是叫這麼個名字吧，我跟他沒說過幾句話。",
  str_homestory_801601001_17_dialog_content = "總之，法蘭茲一見到他就把尾巴搖得飛快，還會想去咬人家的耳朵。",
  str_homestory_801601001_18_dialog_content = "啊？那對方的反應如何？",
  str_homestory_801601001_19_dialog_content = "沒什麼特別的，他拿著筆盯著法蘭茲一會，有點欲言又止的樣子。",
  str_homestory_801601001_20_dialog_content = "（......該不會是想讓法蘭茲幫他畫畫吧？！）",
  str_homestory_801601001_21_dialog_content = "但最後他看了看法蘭茲的爪子，然後很遺憾似地搖了搖頭走掉。",
  str_homestory_801601001_22_dialog_content = "呼......那就好......",
  str_homestory_801601001_23_dialog_content = "順道一提，我覺得他的耳朵看起來很好摸。",
  str_homestory_801601001_24_dialog_content = "也許我下次該直接上手試試......",
  str_homestory_801601001_25_option_content = "蜂和銀城？",
  str_homestory_801601001_26_dialog_content = "反正是兩個毛茸茸的幼稚傢伙，還把自己打扮得特別成熟。",
  str_homestory_801601001_27_dialog_content = "他們一見到法蘭茲就高呼：「哇喔！真正的小狗狗！」",
  str_homestory_801601001_28_dialog_content = "法蘭茲大概也很喜歡他們吧，不停地磨蹭他們的尾巴。",
  str_homestory_801601001_29_dialog_content = "總覺得那畫面非常奇怪......",
  str_homestory_801601001_30_dialog_content = "但不知道為什麼，又很想親眼看看......",
  str_homestory_801601001_31_dialog_content = "總之，法蘭茲在這兒生活得頗為愜意。",
  str_homestory_801601001_32_dialog_content = "話說......你最近是不是老跟法蘭茲混在一起？",
  str_homestory_801601001_33_dialog_content = "嗯？沒有吧......",
  str_homestory_801601001_34_dialog_content = "那我為什麼總能從法蘭茲身上聞到你的味道？",
  str_homestory_801601001_35_dialog_content = "難道他偷偷溜進你房間？",
  str_homestory_801601001_36_dialog_content = "嗯......不是沒有這種可能。",
  str_homestory_801601001_37_dialog_content = "等等......",
  str_homestory_801601001_38_dialog_content = "妳剛才說什麼來著？！",
  str_homestory_801601001_39_dialog_content = "法蘭茲在妳床上流口水<sprite=emo_hanshui size=60 />的次數變少了......？",
  str_homestory_801601001_40_dialog_content = "呃......難道說......",
  str_homestory_801601001_41_dialog_content = "......怪不得我最近覺得我的床單老是濕濕的！！",
  str_homestory_801601001_42_dialog_content = "真相大白了......",
  str_homestory_801601001_43_dialog_content = "聽起來法蘭茲也很喜歡你呢。",
  str_homestory_801601001_44_dialog_content = "......我現在應該開心嗎？",
  str_homestory_801601001_45_dialog_content = "這是在尋求我的建議嗎？",
  str_homestory_801601001_46_dialog_content = "嗯......我建議你現在馬上回去洗床單。",
  str_homestory_804501001_0_dialog_content = "什麼聲音？",
  str_homestory_804501001_1_dialog_content = "是聖釘？",
  str_homestory_804501001_2_dialog_content = "噓......稍候片刻。",
  str_homestory_804501001_3_dialog_content = "啊！您的臉龐宛如光潔的瓷盤，映照出我骯髒的身軀......",
  str_homestory_804501001_4_dialog_content = "您的眼眸如深邃的夜空，看穿我內心的不堪......",
  str_homestory_804501001_5_dialog_content = "請寬恕我身上的罪孽吧......",
  str_homestory_804501001_6_dialog_content = "還是說......寬恕我會使您蒙羞？",
  str_homestory_804501001_7_dialog_content = "......",
  str_homestory_804501001_8_dialog_content = "抱歉讓您久等了，PlayerName！",
  str_homestory_804501001_9_dialog_content = "我的聲音驚擾到您了嗎？",
  str_homestory_804501001_10_dialog_content = "萬分抱歉！我的聲音是那樣的不堪入耳，罪孽深重......",
  str_homestory_804501001_11_dialog_content = "千萬不要這麼想，你沒有打擾到我！",
  str_homestory_804501001_12_dialog_content = "我只是在好奇，你在跟誰說話呀？",
  str_homestory_804501001_13_dialog_content = "您誤會了，我並沒有在同誰說話，我是在懺悔身上的罪孽。",
  str_homestory_804501001_14_dialog_content = "這還要感謝您！",
  str_homestory_804501001_15_dialog_content = "感謝您為我們建造這樣一個可以懺悔的場所。",
  str_homestory_804501001_16_dialog_content = "我便可以在這裡，以不驚擾維多利亞大人的方式......自白懺悔。",
  str_homestory_804501001_17_option_content = "（否認）",
  str_homestory_804501001_18_dialog_content = "我......我不記得建造過可以懺悔的場所耶......",
  str_homestory_804501001_19_dialog_content = "您請不必謙虛，這座恢弘壯闊的噴泉水池，想必花費了您不少心思。",
  str_homestory_804501001_20_dialog_content = "但這個是祈望池呀。",
  str_homestory_804501001_21_option_content = "（承認）",
  str_homestory_804501001_22_dialog_content = "不用謝，不用謝，大家喜歡就好......",
  str_homestory_804501001_23_dialog_content = "等等！你說什麼？懺悔的場所？",
  str_homestory_804501001_24_dialog_content = "該不會是這座祈望池吧？",
  str_homestory_804501001_25_dialog_content = "祈望池，多麼溫柔的名字。",
  str_homestory_804501001_26_dialog_content = "我只看到大家在此地合掌懺悔，竟對此地的名字一無所知！",
  str_homestory_804501001_27_dialog_content = "我有罪，我懺悔......",
  str_homestory_804501001_28_dialog_content = "竟然還可以這樣解讀？而且......我想其他人在這裡應該都在許願吧？",
  str_homestory_804501001_29_dialog_content = "我也要替PlayerName懺悔......",
  str_homestory_804501001_30_dialog_content = "欸？！",
  str_homestory_804501001_31_dialog_content = "懺悔不應被打斷......",
  str_homestory_804501001_32_dialog_content = "都怪我未能向PlayerName提前說明這一點。",
  str_homestory_804501001_33_dialog_content = "寄宿在祈望池中的真理啊......",
  str_homestory_804501001_34_dialog_content = "請原諒聖釘的再次打擾！",
  str_homestory_804501001_35_dialog_content = "我有罪，我懺悔，請懲罰我......",
  str_homestory_804501001_36_option_content = "（懲罰）",
  str_homestory_804501001_37_dialog_content = "天吶！我剛才感應到了祈望池的回應。",
  str_homestory_804501001_38_dialog_content = "回應？真理終於降臨了？！",
  str_homestory_804501001_39_dialog_content = "咳咳，祈望池說......",
  str_homestory_804501001_40_option_content = "（安慰）",
  str_homestory_804501001_41_dialog_content = "聖釘，我覺得這真的不是需要懺悔的事情。",
  str_homestory_804501001_42_dialog_content = "與其在這裡懺悔......不如想想你接下來該做什麼。",
  str_homestory_804501001_43_dialog_content = "！！！",
  str_homestory_804501001_44_dialog_content = "我剛才怎麼沒想到呢......",
  str_homestory_804501001_45_dialog_content = "我果然......罪孽深重......",
  str_homestory_804501001_46_dialog_content = "這......",
  str_homestory_808601001_0_dialog_content = "這熟悉的白花......",
  str_homestory_808601001_1_dialog_content = "PlayerName先生。",
  str_homestory_808601001_2_dialog_content = "想不到空谷是如此美麗。",
  str_homestory_808601001_3_dialog_content = "這片一眼望不到盡頭的綠茵......是白夜城裡看不到的景色呢。",
  str_homestory_808601001_4_dialog_content = "就連這些白花<sprite=emo_huaduo size=60 />，也都很喜歡空谷......",
  str_homestory_808601001_5_dialog_content = "對啊......其實我也有點意外。",
  str_homestory_808601001_6_dialog_content = "嗯？您不也是空谷的一分子嗎？",
  str_homestory_808601001_7_dialog_content = "喔，對了......",
  str_homestory_808601001_8_dialog_content = "我想起您上次說過......您幼時就被迫離開空谷。",
  str_homestory_808601001_9_dialog_content = "是的，雖然透過臨空者老師的教導，了解過空谷......",
  str_homestory_808601001_10_dialog_content = "但實際走入空谷，才發現這震撼的美麗依然令我內心奔騰。<sprite=emo_pugongying size=60 />",
  str_homestory_808601001_11_dialog_content = "無論看多少次，這種感覺都未曾減弱。",
  str_homestory_808601001_12_dialog_content = "也許這就是......「家」的感覺，我能感覺到空谷像與我連接在一起。",
  str_homestory_808601001_13_dialog_content = "是呀......這裡的一切都充滿靈性，自然與空裔的建築和諧共存。",
  str_homestory_808601001_14_dialog_content = "因為我平時經常接觸「逝去」的關係，我能感覺到......",
  str_homestory_808601001_15_dialog_content = "這裡是充滿「生命本源之美」的地方。",
  str_homestory_808601001_16_dialog_content = "一切擁有生命，歌頌生命的人，應該都會喜歡空谷。",
  str_homestory_808601001_17_dialog_content = "PlayerName的家，真的是很美麗的地方。",
  str_homestory_808601001_18_dialog_content = "我很高興你能擁有這樣的歸宿。",
  str_homestory_808601001_19_dialog_content = "謝謝妳，尤萊雅。",
  str_homestory_808601001_20_dialog_content = "我很高興妳對空谷的評價這麼高。",
  str_homestory_808601001_21_option_content = "（有事相求）",
  str_homestory_808601001_22_dialog_content = "其實......有件事想拜託尤萊雅小姐，不知道妳願不願意幫忙。",
  str_homestory_808601001_23_dialog_content = "呵呵......PlayerName突然變得客氣起來了呢。",
  str_homestory_808601001_24_dialog_content = "這種有點嚴肅又有點曖昧的氣氛......",
  str_homestory_808601001_25_dialog_content = "難道光是找我約會已經不夠，這次是要求婚了嗎？",
  str_homestory_808601001_26_dialog_content = "什......什麼？！",
  str_homestory_808601001_27_dialog_content = "不是啦！",
  str_homestory_808601001_28_dialog_content = "呵呵呵......您現在樣子還滿可愛的。",
  str_homestory_808601001_29_dialog_content = "請別拿我開玩笑啦！",
  str_homestory_808601001_30_option_content = "（表示歡迎）",
  str_homestory_808601001_31_dialog_content = "希望妳能多來空谷玩，這裡非常歡迎尤萊雅小姐。",
  str_homestory_808601001_32_dialog_content = "我當然願意。",
  str_homestory_808601001_33_dialog_content = "這裡的美麗如此懾人心魄，而且又是你的家園。",
  str_homestory_808601001_34_dialog_content = "我很期待PlayerName您會把它建設成為何等偉大的家園。",
  str_homestory_808601001_35_dialog_content = "嗯......尤萊雅小姐，您是負責為逝者祈福，讓他們的靈魂能夠安息的修女吧？",
  str_homestory_808601001_36_dialog_content = "是的，我在白夜城的職責正是如此。",
  str_homestory_808601001_37_dialog_content = "......原來如此，我知道您的意思了。",
  str_homestory_808601001_38_dialog_content = "嗯，我想為那些逝去的同族......祈求安息。",
  str_homestory_808601001_39_dialog_content = "果然是這樣呀......",
  str_homestory_808601001_40_dialog_content = "真沒想到，您已變得如此成熟，能夠坦然地接受生與死。",
  str_homestory_808601001_41_dialog_content = "我，葬儀祈禱，修女尤萊雅一定會為空谷的靈魂祈求安息。",
  str_homestory_808601001_42_dialog_content = "讓他們的靈魂能夠安息，讓白花開滿空谷。",
  str_homestory_808601001_43_dialog_content = "謝謝。",
  str_homestory_810201001_0_dialog_content = "這股電流是......",
  str_homestory_810201001_1_dialog_content = "泰莎？",
  str_homestory_810201001_2_dialog_content = "如果覺得睏的話，可以去空庭宅舍裡休息呀。",
  str_homestory_810201001_3_dialog_content = "哈——欠<sprite=emo_kun size=60 />。",
  str_homestory_810201001_4_dialog_content = "什麼啊，原耐是禮？",
  str_homestory_810201001_5_dialog_content = "妳說什麼？",
  str_homestory_810201001_6_dialog_content = "唉，非要讓我把棒棒糖從嘴裡拿出來，你才能聽懂我說什麼嗎？",
  str_homestory_810201001_7_dialog_content = "嗯......我只是想提醒妳，在外面睡覺小心著涼。",
  str_homestory_810201001_8_dialog_content = "難道有人規定過睡覺必須在屋子裡面嗎？",
  str_homestory_810201001_9_dialog_content = "是沒有這樣強硬規定......",
  str_homestory_810201001_10_dialog_content = "就算有那種規定，我也不在乎。",
  str_homestory_810201001_11_dialog_content = "我，想在哪裡睡覺，就在哪裡睡覺。",
  str_homestory_810201001_12_option_content = "（贊同）",
  str_homestory_810201001_13_dialog_content = "當然可以......當然可以！",
  str_homestory_810201001_14_dialog_content = "泰莎的這種生活方式真是很讓人羨慕呢。",
  str_homestory_810201001_15_dialog_content = "我只是想找個地方清淨一會，不需要誰的羨慕。",
  str_homestory_810201001_16_option_content = "（無法贊同）",
  str_homestory_810201001_17_dialog_content = "雖然可以理解泰莎的想法，但是......",
  str_homestory_810201001_18_dialog_content = "我只是想找個地方清淨一會，不需要誰來理解我。",
  str_homestory_810201001_19_dialog_content = "好吧......",
  str_homestory_810201001_20_dialog_content = "商店裡有遮陽傘和帳篷，妳需要的話隨時找我要。",
  str_homestory_810201001_21_dialog_content = "不必了，我覺得樹蔭下面挺好的。",
  str_homestory_810201001_22_dialog_content = "對了，這裡的商店裡有棒棒糖嗎？",
  str_homestory_810201001_23_dialog_content = "我的棒棒糖快吃完了。",
  str_homestory_810201001_24_dialog_content = "有是有，不過......",
  str_homestory_810201001_25_dialog_content = "妳是不是還沒進空庭宅舍裡面看過？",
  str_homestory_810201001_26_dialog_content = "唔......都說了不想去屋子裡悶著了。",
  str_homestory_810201001_27_dialog_content = "而且這件事和棒棒糖有什麼關係？",
  str_homestory_810201001_28_dialog_content = "其實，為了迎接泰莎的到來......",
  str_homestory_810201001_29_dialog_content = "我特意在宅舍裡準備了很多棒棒糖......",
  str_homestory_810201001_30_dialog_content = "棒棒糖？！",
  str_homestory_810201001_31_dialog_content = "我剛才去看了一下，已經一個都不剩了。",
  str_homestory_810201001_32_dialog_content = "本來以為是泰莎拿走了呢，現在看來是被別人搶先享受了。",
  str_homestory_810201001_33_dialog_content = "有這種事，為什麼不早說？",
  str_homestory_810201001_34_dialog_content = "我以為大家都會先去空庭宅舍裡面休息一下的......",
  str_homestory_810201001_35_dialog_content = "哼，算了。",
  str_homestory_810201001_36_dialog_content = "我再去買就罷。",
  str_homestory_810201001_37_dialog_content = "（泰莎竟然意外地通情達理啊......）",
  str_homestory_810201001_38_dialog_content = "你這裡有沒有缺人？會付酬勞的那種。",
  str_homestory_810201001_39_dialog_content = "欸，妳不是要休息嗎？怎麼忽然找起工作了？",
  str_homestory_810201001_40_dialog_content = "我剛想去商店，結果發現身上已經沒錢了。",
  str_homestory_810201001_41_dialog_content = "如果沒有工作的話，我只能去賒帳了。",
  str_homestory_810201001_42_dialog_content = "......",
  str_homestory_810201001_43_dialog_content = "那就麻煩妳去檢查......空庭宅舍的電路吧。",
  str_homestory_810201001_44_dialog_content = "成交！",
  str_homestory_801501001_0_dialog_content = "真稀罕......",
  str_homestory_801501001_1_dialog_content = "難得見你沒和銀城黏在一起。",
  str_homestory_801501001_2_dialog_content = "啊～PlayerName，你聞到了嗎？這股味道！",
  str_homestory_801501001_3_dialog_content = "白夜幣<sprite=emo_baiyebi size=60 />的味道，到處都是白夜幣的味道！",
  str_homestory_801501001_4_option_content = "（表示懷疑）",
  str_homestory_801501001_5_dialog_content = "我怎麼沒聞到？",
  str_homestory_801501001_6_dialog_content = "況且白夜幣能有什麼味道啊......",
  str_homestory_801501001_7_dialog_content = "PlayerName，這不外乎一種藝術的表達手法而已。重點是......",
  str_homestory_801501001_8_dialog_content = "我這裡有價值幾個億的項目想與你商談！",
  str_homestory_801501001_9_dialog_content = "幾個億？！",
  str_homestory_801501001_10_option_content = "（詢問味道）",
  str_homestory_801501001_11_dialog_content = "白夜幣是什麼味道？",
  str_homestory_801501001_12_dialog_content = "三分鐵鏽的腥甜，四分汗水的鹹鮮......",
  str_homestory_801501001_13_dialog_content = "還有五分的......嗅～",
  str_homestory_801501001_14_dialog_content = "純淨的果木香！",
  str_homestory_801501001_15_dialog_content = "這樣加起來已經十二分了耶？",
  str_homestory_801501001_16_dialog_content = "十二分，就是我想與PlayerName商談的誠意。",
  str_homestory_801501001_17_dialog_content = "喔對了，提前聲明一下，滿分是十分不是一百分唷。",
  str_homestory_801501001_18_dialog_content = "你又在打什麼歪主意......",
  str_homestory_801501001_19_dialog_content = "先說好啊，我的畫不賣，你也別想臨摹......",
  str_homestory_801501001_20_dialog_content = "PlayerName，把眼光放長遠一點嘛。",
  str_homestory_801501001_21_dialog_content = "你坐擁這樣一座純天然的展覽會場，還在乎那麼一兩副畫嗎？",
  str_homestory_801501001_22_dialog_content = "展覽會場？",
  str_homestory_801501001_23_dialog_content = "曠闊的自然空間與人文生態相互結合的最好範本。",
  str_homestory_801501001_24_dialog_content = "這裡是一處絕佳的天然展覽會場。",
  str_homestory_801501001_25_dialog_content = "PlayerName，我們已經不能更喜歡<sprite=emo_aixin size=60 />這裡了！",
  str_homestory_801501001_26_dialog_content = "所以，剛剛我做出了一個艱難的決定！",
  str_homestory_801501001_27_dialog_content = "我決定——",
  str_homestory_801501001_28_dialog_content = "轉行成為策展人！",
  str_homestory_801501001_29_dialog_content = "策展人？具體上都在做些什麼？",
  str_homestory_801501001_30_dialog_content = "咳咳，簡單來說就是負責鑑定、研究、保管和陳列各項藝術品......",
  str_homestory_801501001_31_dialog_content = "並且在特定場所策劃組織藝術展覽的專業經理人。",
  str_homestory_801501001_32_dialog_content = "雖然聽不太懂，但感覺倒是個正經的職業。",
  str_homestory_801501001_33_dialog_content = "這麼說你同意了？",
  str_homestory_801501001_34_dialog_content = "我同不同意，你都可以轉行當策展人啊。",
  str_homestory_801501001_35_dialog_content = "只要別破壞這裡的環境......畢竟我好不容易才建設成這副模樣。",
  str_homestory_801501001_36_dialog_content = "我明白了。",
  str_homestory_801501001_37_dialog_content = "PlayerName不想要我改動這裡的建築和花草。",
  str_homestory_801501001_38_dialog_content = "是的。",
  str_homestory_801501001_39_dialog_content = "PlayerName不想要我設計和舉辦充滿藝術氛圍的展覽和藝術節。",
  str_homestory_801501001_40_dialog_content = "是的。",
  str_homestory_801501001_41_dialog_content = "PlayerName也不想要因為展覽和藝術節而慕名前來的觀光客。",
  str_homestory_801501001_42_dialog_content = "嗯......",
  str_homestory_801501001_43_dialog_content = "PlayerName更不想要因此所帶來的不菲收入。",
  str_homestory_801501001_44_dialog_content = "欸......",
  str_homestory_801501001_45_dialog_content = "PlayerName不想改善他的財務狀況。",
  str_homestory_801501001_46_dialog_content = "咳咳咳......等一下。",
  str_homestory_801501001_47_dialog_content = "這件事我可以再考慮一下。",
  str_homestory_801501001_48_dialog_content = "哈哈，PlayerName終於也聞到了白夜幣的味道了！",
  str_homestory_815401001_0_dialog_content = "又去了？",
  str_homestory_815401001_1_dialog_content = "薇絲，最近妳好像成天泡在陳列館裡喔。",
  str_homestory_815401001_2_dialog_content = "難道陳列館裡面也有生財之道？",
  str_homestory_815401001_3_dialog_content = "你啊......",
  str_homestory_815401001_4_dialog_content = "我們的經濟狀況確實需要改善，但我們不是說好了嗎？",
  str_homestory_815401001_5_dialog_content = "陳列館是為了向世人展示空谷歷史和空裔科技的公益性場所。",
  str_homestory_815401001_6_dialog_content = "所以不會向人們收門票，更別提想辦法從中牟利......",
  str_homestory_815401001_7_option_content = "（道歉）",
  str_homestory_815401001_8_dialog_content = "抱歉，薇絲......",
  str_homestory_815401001_9_dialog_content = "我這幾天一直在想這個，有點走火入魔了。",
  str_homestory_815401001_10_dialog_content = "哈哈哈，沒關係！我也有過這種時候。",
  str_homestory_815401001_11_dialog_content = "出現這種現象，就證明你該好好休息了！",
  str_homestory_815401001_12_dialog_content = "薇絲，別光說我，妳自己也要照做呀。",
  str_homestory_815401001_13_dialog_content = "這幾天妳總是憂心忡忡待在陳列館裡......",
  str_homestory_815401001_14_dialog_content = "都沒有好好休息吧？",
  str_homestory_815401001_15_option_content = "（關心）",
  str_homestory_815401001_16_dialog_content = "放心，我一直都這麼認為！",
  str_homestory_815401001_17_dialog_content = "身為空之末裔，我不能讓空裔的文明斷送在我手上。",
  str_homestory_815401001_18_dialog_content = "不過......",
  str_homestory_815401001_19_dialog_content = "妳這幾天為什麼經常待在陳列館裡若有所思呀？",
  str_homestory_815401001_20_dialog_content = "唉，還真是瞞不過PlayerName呢。<sprite=emo_wuzui size=60 />",
  str_homestory_815401001_21_dialog_content = "我最近在調查陳列館裡的展覽品。",
  str_homestory_815401001_22_dialog_content = "調查？啟光的新任務嗎？",
  str_homestory_815401001_23_dialog_content = "不是，這只是出於我個人想法而做。",
  str_homestory_815401001_24_dialog_content = "當然啦，也不能算是調查吧。",
  str_homestory_815401001_25_dialog_content = "只是想嘗試，期待找到足以啟發自己的線索。",
  str_homestory_815401001_26_dialog_content = "你也知道，我的身體發生了這樣那樣的變化......",
  str_homestory_815401001_27_dialog_content = "還零零散散地想起許多以前的事情。",
  str_homestory_815401001_28_dialog_content = "可是關於自己的身世，我卻怎麼也捕捉不到一絲訊息......",
  str_homestory_815401001_29_dialog_content = "所以......妳想在陳列館裡找到關於自己身世的線索？",
  str_homestory_815401001_30_dialog_content = "嘿嘿嘿，很奇怪是吧？",
  str_homestory_815401001_31_dialog_content = "也是啊，空裔的陳列館怎麼會有我身世的線索呢？",
  str_homestory_815401001_32_dialog_content = "那也說不定吧。",
  str_homestory_815401001_33_dialog_content = "世界雖然很大，但是「巧合」的事情也不少。",
  str_homestory_815401001_34_dialog_content = "哈哈哈哈，跟剛剛認識的時候相比，你變樂觀了呢。",
  str_homestory_815401001_35_dialog_content = "需要我陪妳再逛一次陳列館嗎？",
  str_homestory_815401001_36_dialog_content = "說不定這次就能發現有用的線索，例如家族信件？",
  str_homestory_815401001_37_dialog_content = "好呀。",
  str_homestory_815401001_38_dialog_content = "不過萬一發現我其實是你的親姐姐......<sprite=emo_sikao size=60 />",
  str_homestory_815401001_39_dialog_content = "你該怎麼辦？",
  str_homestory_815401001_40_dialog_content = "憑什麼妳是姐姐啊？",
  str_homestory_815401001_41_dialog_content = "怎麼看都應該是妳喊我一聲「哥哥」才對！",
  str_homestory_815401001_42_dialog_content = "PlayerName......",
  str_homestory_815401001_43_dialog_content = "噫......完全無法相信。",
  str_homestory_815401001_44_dialog_content = "咳咳，我還是希望不要有這種「巧合」！",
  str_homestory_805702001_0_dialog_content = "下雨了？",
  str_homestory_805702001_1_dialog_content = "喵——嗚——",
  str_homestory_805702001_2_dialog_content = "菲莉詩，是不是下雨了？我們快找個地方躲起來吧。",
  str_homestory_805702001_3_dialog_content = "欸～剛才是菲莉詩在甩干身上的水滴喵。",
  str_homestory_805702001_4_dialog_content = "PlayerName，抱歉喵，是不是甩到你身上了？",
  str_homestory_805702001_5_dialog_content = "原來是這樣啊，怪不得妳剛剛一直在搖頭晃腦的......",
  str_homestory_805702001_6_dialog_content = "PlayerName不要取笑我了喵～",
  str_homestory_805702001_7_dialog_content = "可是剛才又沒下雨，妳身上哪來的水呀？",
  str_homestory_805702001_8_dialog_content = "唔......都怪河裡那隻會閃光的小魚乾喵！<sprite=emo_shengqi size=60 />",
  str_homestory_805702001_9_option_content = "閃光？",
  str_homestory_805702001_10_dialog_content = "小魚乾怎麼會閃光呢？",
  str_homestory_805702001_11_dialog_content = "我也想知道為什麼嘛，所以才想去抓住喵。",
  str_homestory_805702001_12_option_content = "小魚乾？",
  str_homestory_805702001_13_dialog_content = "等等，河裡怎麼會有小魚乾？",
  str_homestory_805702001_14_dialog_content = "抓上來拿到太陽底下曬一曬，就是小魚乾了嘛。",
  str_homestory_805702001_15_dialog_content = "可我怎麼都抓不到，一不小心就掉進河裡了喵～",
  str_homestory_805702001_16_dialog_content = "哈啾！河水也太涼了喵嗚～",
  str_homestory_805702001_17_dialog_content = "菲莉詩還是快回屋子裡暖一暖吧，在外面容易感冒。",
  str_homestory_805702001_18_dialog_content = "可是……",
  str_homestory_805702001_19_dialog_content = "啊，PlayerName，既然你是這裡的主人......",
  str_homestory_805702001_20_dialog_content = "不如你去幫我抓住那只會閃光的小魚乾吧！",
  str_homestory_805702001_21_dialog_content = "咦？",
  str_homestory_805702001_22_dialog_content = "記得......帮我晒一晒......呼......呼......<sprite=emo_kun size=60 />",
  str_homestory_805702001_23_dialog_content = "在外面睡覺容易著涼的......菲莉詩？",
  str_homestory_805702001_24_dialog_content = "呼......呼......<sprite=emo_kun size=60 />小魚乾......",
  str_homestory_814101001_0_dialog_content = "興高采烈的......",
  str_homestory_814101001_1_dialog_content = "嗨～PlayerName，你也出來探險呀？",
  str_homestory_814101001_2_option_content = "是的",
  str_homestory_814101001_3_dialog_content = "我精心布置的空庭之中，也有許多可以探險的地方。",
  str_homestory_814101001_4_option_content = "並不是。",
  str_homestory_814101001_5_dialog_content = "我就是出來透透氣而已。",
  str_homestory_814101001_6_dialog_content = "空庭好不容易建成今天的規模，我想多在這裡逛逛。",
  str_homestory_814101001_7_dialog_content = "你說的沒錯！",
  str_homestory_814101001_8_dialog_content = "你打造的這座探險島真的酷斃了！我很喜歡！",
  str_homestory_814101001_9_dialog_content = "剛才我就去旁邊那條河裡探險了。",
  str_homestory_814101001_10_dialog_content = "欸，是嗎？有什麼收穫嗎？",
  str_homestory_814101001_11_dialog_content = "哈哈哈，就知道你會問我這個！",
  str_homestory_814101001_12_dialog_content = "看到你這有條小河，說時遲那時快，我噗通一聲就跳進去了！",
  str_homestory_814101001_13_dialog_content = "我先是撥開水草，從河底的淤泥里撿到一枚沒見過的硬幣<sprite=emo_baiyebi size=60 />......",
  str_homestory_814101001_14_dialog_content = "轉身又逮到一條肥美的鬥豔魚......",
  str_homestory_814101001_15_dialog_content = "剛遊了沒多遠，又看見了一個神祕的遺物！",
  str_homestory_814101001_16_dialog_content = "我反手就是一抓，把那東西抓上了岸，結果你猜那東西是什麼？",
  str_homestory_814101001_17_dialog_content = "是......什麼？",
  str_homestory_814101001_18_dialog_content = "是一隻長滿了水草的破鞋，哈哈哈哈哈！",
  str_homestory_814101001_19_dialog_content = "把那破鞋拿去商店，連一個白夜幣都兌換不了，真是笑死我了哈哈哈。",
  str_homestory_814101001_20_dialog_content = "那條魚呢，還有一開始撿到的硬幣？",
  str_homestory_814101001_21_dialog_content = "欸，對啊......我記得我放進口袋裡了啊......",
  str_homestory_814101001_22_dialog_content = "沒關係沒關係，肯定是撿破鞋的時候掉在那附近了。",
  str_homestory_814101001_23_dialog_content = "你要是感興趣，可以去找找看！",
  str_homestory_814101001_24_dialog_content = "不過那隻魚嘛，肯定早就游走了。",
  str_homestory_814101001_25_dialog_content = "露比......真是百分之百的樂天派啊。",
  str_homestory_814101001_26_dialog_content = "哎呀，對了！這件事你千萬別告訴花芸！",
  str_homestory_814101001_27_dialog_content = "否則她又要給我餵什麼防止發燒的苦藥水了。",
  str_homestory_801001001_0_dialog_content = "沒睡醒嗎？",
  str_homestory_801001001_1_dialog_content = "露易絲，妳還好嗎？怎麼看起來很睏的樣子？",
  str_homestory_801001001_2_dialog_content = "啊，是PlayerName呀。",
  str_homestory_801001001_3_dialog_content = "還以為我終於等到了呢......",
  str_homestory_801001001_4_dialog_content = "妳在等人嗎？",
  str_homestory_801001001_5_dialog_content = "露易絲剛剛在等住在河裡的仙子。",
  str_homestory_801001001_6_dialog_content = "仙子？",
  str_homestory_801001001_7_dialog_content = "PlayerName沒有聽說過那個很著名的童話故事嗎？",
  str_homestory_801001001_8_dialog_content = "遠離喧囂的小河裡，住著一位非常美麗的仙子。",
  str_homestory_801001001_9_dialog_content = "如果路人不小心把東西掉進小河裡，仙子就會騰空出現。",
  str_homestory_801001001_10_dialog_content = "誠實地回答仙子提問的好孩子，會得到仙子的獎勵喔！",
  str_homestory_801001001_11_option_content = "小河......",
  str_homestory_801001001_12_dialog_content = "露易絲覺得這條河裡也住著仙子嗎？",
  str_homestory_801001001_13_dialog_content = "唔，不是每條小河裡都住著仙子嗎......",
  str_homestory_801001001_14_dialog_content = "北境的小河裡住著北境仙子，空谷的小河裡住著空谷仙子......",
  str_homestory_801001001_15_option_content = "童話......",
  str_homestory_801001001_16_dialog_content = "妳這麼一說，我也覺得好像在哪裡聽說過這個故事。",
  str_homestory_801001001_17_dialog_content = "有個人丟了一把鐵斧頭，卻貪心地說自己丟的是金斧頭？",
  str_homestory_801001001_18_dialog_content = "不過重點是......",
  str_homestory_801001001_19_dialog_content = "露易絲是不小心把什麼東西掉進河裡了嗎？",
  str_homestory_801001001_20_dialog_content = "嗯！不過那個也不是露易絲的東西啦。",
  str_homestory_801001001_21_dialog_content = "是我在河邊撿到的硬幣，上面畫著很複雜的圖案......",
  str_homestory_801001001_22_dialog_content = "但我還沒有看清，硬幣就滾落進小河裡了。",
  str_homestory_801001001_23_dialog_content = "露易絲剛剛等了好久，仙子都沒有出現。",
  str_homestory_801001001_24_dialog_content = "看來PlayerName這的小河裡，真的沒有仙子呀......<sprite=emo_sikao size=60 />",
  str_homestory_801001001_25_dialog_content = "還是讓我去看看能不能撈上來吧。",
  str_homestory_801001001_26_dialog_content = "唔，原來仙子就是PlayerName啊？！",
  str_homestory_804102001_0_dialog_content = "好認真......",
  str_homestory_804102001_1_dialog_content = "白蘭女士，妳好呀。",
  str_homestory_804102001_2_dialog_content = "親愛的PlayerName，您好。",
  str_homestory_804102001_3_dialog_content = "妳還在觀察空庭的道路和建築嗎？",
  str_homestory_804102001_4_dialog_content = "我很高興，您還記得我的「職業病」。",
  str_homestory_804102001_5_option_content = "好敬業！",
  str_homestory_804102001_6_dialog_content = "可是……",
  str_homestory_804102001_7_option_content = "抱歉！",
  str_homestory_804102001_8_dialog_content = "為什麼這麼說呢？",
  str_homestory_804102001_9_dialog_content = "我一直在建設空庭，建築和道路都在不斷地增多。",
  str_homestory_804102001_10_dialog_content = "這樣會讓妳的工作量變大吧？",
  str_homestory_804102001_11_dialog_content = "PlayerName，永遠不要小看職業女性的專業能力喔。",
  str_homestory_804102001_12_dialog_content = "只要能在腦海中留下主要建築和道路的方位、坐標......",
  str_homestory_804102001_13_dialog_content = "增加再多的道路和建築，我都不需要費太多功夫就能記住。",
  str_homestory_804102001_14_dialog_content = "好強大的記憶力！",
  str_homestory_804102001_15_dialog_content = "那......剛剛妳眉頭緊鎖，是遇到什麼問題了嗎？",
  str_homestory_804102001_16_dialog_content = "哎呀，不小心被PlayerName看到了嗎？",
  str_homestory_804102001_17_dialog_content = "確實，我遇到了一個小問題......告訴您也無妨。",
  str_homestory_804102001_18_dialog_content = "其實我正在思考空庭的導遊詞該如何撰寫。",
  str_homestory_804102001_19_dialog_content = "正巧寫到這附近的小河......",
  str_homestory_804102001_20_dialog_content = "可這河裡除了各種各樣的魚，似乎還有個閃著光的東西。",
  str_homestory_804102001_21_dialog_content = "為了保證導遊詞的準確性，我非常想知道那究竟是什麼......",
  str_homestory_804102001_22_dialog_content = "閃著光的東西......",
  str_homestory_804102001_23_dialog_content = "既然您是空庭的主人，那這件事可以拜託您去調查看看嗎？",
  str_homestory_804102001_24_dialog_content = "嗯，當然沒問題！",
  str_homestory_801502001_0_dialog_content = "又在到處嗅嗅？",
  str_homestory_801502001_1_dialog_content = "咳咳，蜂，你這是......？",
  str_homestory_801502001_2_dialog_content = "啊～這不是我們親愛的PlayerName嘛！<sprite=emo_yaosu size=60 />",
  str_homestory_801502001_3_dialog_content = "怎麼樣，想清楚了嗎？",
  str_homestory_801502001_4_dialog_content = "什麼考慮好了沒......",
  str_homestory_801502001_5_dialog_content = "哦哈，我理解！我們的貴人多忘事嘛～",
  str_homestory_801502001_6_dialog_content = "我說的是......把空庭打造成一處自然展覽會場的事情呀。",
  str_homestory_801502001_7_option_content = "在考慮",
  str_homestory_801502001_8_dialog_content = "那個啊，還在考慮，還在考慮......",
  str_homestory_801502001_9_option_content = "還是算了",
  str_homestory_801502001_10_dialog_content = "你的展望很美好，但我還是希望空庭可以保持現在的清凈和安寧。",
  str_homestory_801502001_11_dialog_content = "唉，好吧。",
  str_homestory_801502001_12_dialog_content = "可是，你可要想清楚囉，機會不等人唷！",
  str_homestory_801502001_13_dialog_content = "嗯……",
  str_homestory_801502001_14_dialog_content = "嗅～嗅～～",
  str_homestory_801502001_15_dialog_content = "你在到處聞什麼呢？",
  str_homestory_801502001_16_dialog_content = "哈～～你聞不見嗎？這硬幣的味道......",
  str_homestory_801502001_17_dialog_content = "又是......「白夜幣」<sprite=emo_baiyebi size=60 />的味道？",
  str_homestory_801502001_18_dialog_content = "不，這次不一樣！",
  str_homestory_801502001_19_dialog_content = "這是一種全新的、不可名狀的硬幣氣息......嗅～",
  str_homestory_801502001_20_dialog_content = "比白夜幣多了一絲咸鮮和潮濕，鑄造的時間更久遠......",
  str_homestory_801502001_21_dialog_content = "花紋也更繁複......",
  str_homestory_801502001_22_dialog_content = "花紋也能聞出來嗎？！",
  str_homestory_801502001_23_dialog_content = "不要小看狗狗的鼻子唷。",
  str_homestory_801502001_24_dialog_content = "無論是商業風向還是硬幣的氣息，我都能為您指明方向，哈哈哈。",
  str_homestory_801502001_25_dialog_content = "這次呢，我就把尋找這枚硬幣的機會讓給你了，親愛的PlayerName。",
  str_homestory_801502001_26_dialog_content = "咦？",
  str_homestory_801502001_27_dialog_content = "希望你再考慮考慮我們的合作事宜喔～",
  str_homestory_805602001_0_dialog_content = "康斯坦丁？",
  str_homestory_805602001_1_dialog_content = "PlayerName，你好。",
  str_homestory_805602001_2_dialog_content = "康斯坦丁，你這是從哪裡回來？",
  str_homestory_805602001_3_dialog_content = "孩子，我剛剛釣魚回來。",
  str_homestory_805602001_4_dialog_content = "喔～這幾天經常看見你去釣魚呢。",
  str_homestory_805602001_5_dialog_content = "康斯坦丁是專業的獵人，這幾天應該釣到不少魚吧？",
  str_homestory_805602001_6_dialog_content = "一條魚都沒有釣到。",
  str_homestory_805602001_7_dialog_content = "欸，不......不會吧？我記得你打獵的技術很高超啊......",
  str_homestory_805602001_8_dialog_content = "雖說釣魚可以算是打獵的一種，但兩者其實區別很大。<sprite=emo_sikao size=60 />",
  str_homestory_805602001_9_dialog_content = "打獵，是去打倒目標獵物。",
  str_homestory_805602001_10_dialog_content = "釣魚則需要將主動性降到最低，收穫主動靠近的東西。",
  str_homestory_805602001_11_option_content = "我明白了。",
  str_homestory_805602001_12_dialog_content = "釣魚的時候，大家都不知道會釣上來什麼。",
  str_homestory_805602001_13_dialog_content = "但是打獵的時候，應該都是先找到目標再去行動吧。",
  str_homestory_805602001_14_option_content = "不懂。",
  str_homestory_805602001_15_dialog_content = "但是你經常說打獵需要耐心，我覺得釣魚也很需要耐心啊。",
  str_homestory_805602001_16_dialog_content = "釣魚的時候，大家根本不知道什麼時候能釣上來什麼。",
  str_homestory_805602001_17_dialog_content = "是的，你說的沒錯。",
  str_homestory_805602001_18_dialog_content = "不妨向你坦白，我在釣魚之初沒摸清方法......",
  str_homestory_805602001_19_dialog_content = "總是先鎖定目標，再去行動，但往往事倍功半。",
  str_homestory_805602001_20_dialog_content = "為了讓自己記住這個教訓，我將自己的魚鉤掰直了。",
  str_homestory_805602001_21_dialog_content = "啊？那樣能釣上來魚嗎？",
  str_homestory_805602001_22_dialog_content = "不知道，也無所謂。我只是想磨練自己的耐心。",
  str_homestory_805602001_23_dialog_content = "那你打算一直這樣嗎？",
  str_homestory_805602001_24_dialog_content = "我給自己定了一個期限——",
  str_homestory_805602001_25_dialog_content = "到河畔那枚硬幣被淤泥覆蓋、被河水沖走......或是被人撈走的時候。",
  str_homestory_805602001_26_dialog_content = "在那之前，我將一直用直魚鉤垂釣。",
  str_homestory_805602001_27_dialog_content = "（硬幣......？）",
  str_homestory_805602001_28_dialog_content = "（那我也去試試能不能把硬幣釣上來吧。）",
  str_homestory_808502001_0_dialog_content = "手速好快......",
  str_homestory_808502001_1_dialog_content = "珍，妳剛剛是在做記錄嗎？",
  str_homestory_808502001_2_dialog_content = "是的，我在記錄我所看到的空庭。",
  str_homestory_808502001_3_dialog_content = "如果我不知道妳的職業，一定以為妳剛剛是在畫畫！",
  str_homestory_808502001_4_dialog_content = "可我剛剛的確是在畫畫。",
  str_homestory_808502001_5_dialog_content = "欸......<sprite=emo_wuzui size=60 />",
  str_homestory_808502001_6_dialog_content = "做記錄不止需要文字，更需要適當的插圖示意。",
  str_homestory_808502001_7_dialog_content = "什麼時候需要插圖呢？",
  str_homestory_808502001_8_dialog_content = "很簡單，當你用文字無法輕易描繪一種事物時，就需要用繪畫輔助了。",
  str_homestory_808502001_9_dialog_content = "比如說，我剛才在記錄我在河中所看到的一切事物。",
  str_homestory_808502001_10_dialog_content = "用文字描述「紅瓏鰭」的樣子和形態，讀者幻想半天也只能有個模糊的印象。",
  str_homestory_808502001_11_dialog_content = "這時我只需要將這種魚的體態、色澤用圖畫描繪出來......",
  str_homestory_808502001_12_dialog_content = "讀者一眼就可以了解到這種魚的詳細情況。",
  str_homestory_808502001_13_dialog_content = "原來是這樣……",
  str_homestory_808502001_14_dialog_content = "再舉個例子。當我記錄「河底還躺著一枚硬幣」時......",
  str_homestory_808502001_15_dialog_content = "讀者只能在腦海中浮現自己使用過的硬幣的樣子。",
  str_homestory_808502001_16_dialog_content = "這種時候，就需要我將這種也許誰都沒見過的硬幣紋樣描繪出來。",
  str_homestory_808502001_17_dialog_content = "讓讀者清晰地知曉，究竟是怎樣的一枚硬幣躺在空庭的河底。",
  str_homestory_808502001_18_dialog_content = "所以......那枚硬幣現在在哪裡？",
  str_homestory_808502001_19_dialog_content = "還在河底。",
  str_homestory_808502001_20_dialog_content = "欸？好不容易發現的硬幣，為什麼不從河裡撈出來呢？",
  str_homestory_808502001_21_dialog_content = "我只負責記錄，不負責干預。",
  str_homestory_808502001_22_dialog_content = "同樣，我不會阻止您去將硬幣撈出來。",
  str_homestory_808502001_23_dialog_content = "當然，這一切，我都會如實記錄。",
  str_homestory_805502001_0_dialog_content = "在生氣？",
  str_homestory_805502001_1_dialog_content = "彼亞塔曼，發生什麼了？你看起來好生氣的樣子......",
  str_homestory_805502001_2_dialog_content = "PlayerName，你來得正好。我剛好在找你！",
  str_homestory_805502001_3_dialog_content = "呃......是跟我有關的事情嗎？",
  str_homestory_805502001_4_dialog_content = "還不能確定，但是......",
  str_homestory_805502001_5_dialog_content = "白夜至上！我以白夜城審判官的名義，詢問你......",
  str_homestory_805502001_6_dialog_content = "你有沒有在空庭私自鑄造白夜幣？",
  str_homestory_805502001_7_option_content = "沒有！",
  str_homestory_805502001_8_dialog_content = "雖然我確實很需要白夜幣，但也還沒到那麼缺錢的地步......",
  str_homestory_805502001_9_option_content = "我倒是想",
  str_homestory_805502001_10_dialog_content = "但是鑄造白夜幣的技術和機器都很貴的吧......想要造錢，首先需要錢啊。",
  str_homestory_805502001_11_dialog_content = "你也知道的，還沒有那麼多富餘的錢。",
  str_homestory_805502001_12_dialog_content = "你敢發誓？",
  str_homestory_805502001_13_dialog_content = "我，PlayerName，絕對沒有私自鑄造白夜幣。",
  str_homestory_805502001_14_dialog_content = "否則......我任你處置！",
  str_homestory_805502001_15_dialog_content = "那你是否發現其他來過空庭的人有這樣的嫌疑？",
  str_homestory_805502001_16_dialog_content = "尤其是那幾個從影鎮來的，還有那幾個從沙漠裡來的。",
  str_homestory_805502001_17_dialog_content = "大家都是我的朋友，我不想懷疑大家......",
  str_homestory_805502001_18_dialog_content = "無論是誰，在法律面前都應該被一視同仁。",
  str_homestory_805502001_19_dialog_content = "可是......你到底為什麼要這樣懷疑大家啊？",
  str_homestory_805502001_20_dialog_content = "既然你已經發過毒誓......好吧，我可以告訴你。",
  str_homestory_805502001_21_dialog_content = "剛才我在河畔撿到一枚硬幣，材質很像白夜幣！",
  str_homestory_805502001_22_dialog_content = "可以讓我看看那枚硬幣嗎？",
  str_homestory_805502001_23_dialog_content = "我剛才太過氣憤，手一抖，硬幣掉河裡去了。",
  str_homestory_805502001_24_dialog_content = "雖然只是推測......但我猜你看到的那枚硬幣可能是我們空裔的東西。",
  str_homestory_805502001_25_dialog_content = "啊......是，是這樣嗎？",
  str_homestory_805502001_26_dialog_content = "確實，我並沒有看得太仔細......",
  str_homestory_805502001_27_dialog_content = "如果真的是這樣......我要為我剛才的魯莽為你道歉。",
  str_homestory_805502001_28_dialog_content = "對不起！",
  str_homestory_805502001_29_dialog_content = "沒關係，我也還不清楚事實究竟怎樣。",
  str_homestory_805502001_30_dialog_content = "等我找到那枚硬幣再給你仔細看看。",
  str_homestory_805502001_31_dialog_content = "多謝了，PlayerName！",
  str_homestory_815701001_0_dialog_content = "早苗......",
  str_homestory_815701001_1_dialog_content = "唔啊啊啊......PlayerName先生......",
  str_homestory_815701001_2_dialog_content = "我單純只是在欣賞這些花<sprite=emo_huaduo size=60 />！",
  str_homestory_815701001_3_dialog_content = "才不是因為剛才又在附近摔倒了所以在這裡休息......",
  str_homestory_815701001_4_dialog_content = "妳摔倒了？受傷了嗎？",
  str_homestory_815701001_5_dialog_content = "我已經習慣了......啊，竟然露餡了嗎？",
  str_homestory_815701001_6_dialog_content = "其實......早苗真的很好懂呢。",
  str_homestory_815701001_7_dialog_content = "請您不要因為我笨手笨腳的就辭退我......",
  str_homestory_815701001_8_dialog_content = "不會的，不過......妳剛才發呆的時候是在想什麼嗎？",
  str_homestory_815701001_9_dialog_content = "如果對空庭的建設有什麼建議的話，可以直接告訴我！",
  str_homestory_815701001_10_dialog_content = "啊......沒有啊......",
  str_homestory_815701001_11_dialog_content = "我......我真的一點都沒有在幻想PlayerName先生為什麼要在這裡種花！",
  str_homestory_815701001_12_dialog_content = "咳咳，妳這麼說反而很可疑啊......",
  str_homestory_815701001_13_dialog_content = "咦？",
  str_homestory_815701001_14_dialog_content = "PlayerName先生為了紀念心愛之人，在這裡種下思念這種事......",
  str_homestory_815701001_15_dialog_content = "我，我是不會知道的......",
  str_homestory_815701001_16_option_content = "心愛之人？",
  str_homestory_815701001_17_dialog_content = "嗯！她不經意間與PlayerName先生相識......",
  str_homestory_815701001_18_dialog_content = "衝破種種世俗的束縛，來到您的身邊......",
  str_homestory_815701001_19_dialog_content = "為您在艾斯特拉大陸上的旅程出謀劃策......",
  str_homestory_815701001_20_dialog_content = "啊，那一定是一位非常優秀的女孩子！",
  str_homestory_815701001_21_dialog_content = "這花圃裡的，一定是她最喜歡的花吧？",
  str_homestory_815701001_22_option_content = "種下思念？",
  str_homestory_815701001_23_dialog_content = "曾經拋下所有來到您身邊的那個人......",
  str_homestory_815701001_24_dialog_content = "為您的旅程保駕護航的那個人......",
  str_homestory_815701001_25_dialog_content = "如今卻因為某種世俗的束縛，無法與您相聚。",
  str_homestory_815701001_26_dialog_content = "為了表達對她的思念......",
  str_homestory_815701001_27_dialog_content = "您便把她最愛的花朵種在了花圃裡面！",
  str_homestory_815701001_28_dialog_content = "妳在說什麼，把我弄糊塗了......",
  str_homestory_815701001_29_dialog_content = "是嗎......<sprite=emo_sikao size=60 />！",
  str_homestory_815701001_30_dialog_content = "果然是不能輕易向我這種外人透露的事情呢......",
  str_homestory_815701001_31_dialog_content = "如果妳想問的是，這裡為什麼有花圃......",
  str_homestory_815701001_32_dialog_content = "我的回答是，出於某種景觀設計的需要。",
  str_homestory_815701001_33_dialog_content = "景觀設計？好複雜的詞彙......",
  str_homestory_815701001_34_dialog_content = "薇絲很懂工程製圖，所以設計空庭的時候薇絲給了我很多建議。",
  str_homestory_815701001_35_dialog_content = "加百列、娜席里絲、尤拉他們很懂植物......",
  str_homestory_815701001_36_dialog_content = "在種植什麼植物比較美觀這個方面，我也諮詢過他們的意見。",
  str_homestory_815701001_37_dialog_content = "集合了大家的智慧，才有了今天妳在空庭看到的一草一木。",
  str_homestory_815701001_38_dialog_content = "大家的智慧......",
  str_homestory_815701001_39_dialog_content = "嗯！早苗也不要覺得自己是什麼「外人」啦。",
  str_homestory_815701001_40_dialog_content = "自從妳來到這裡的那一刻起，就是自己人囉！",
  str_homestory_815701001_41_dialog_content = "嗚嗚嗚嗚......",
  str_homestory_815701001_42_dialog_content = "啊啊，妳怎麼哭了？我沒有在責怪妳的意思啊......",
  str_homestory_815701001_43_dialog_content = "PlayerName先生真的是個好人......",
  str_homestory_815701001_44_dialog_content = "我也要......貢獻自己的力量才可以。",
  str_homestory_815701001_45_dialog_content = "有了！以後這片「愛之花圃<sprite=emo_aixin size=60 />」就讓我來照顧吧！",
  str_homestory_815601001_0_dialog_content = "我沒看錯吧？",
  str_homestory_815601001_1_dialog_content = "妮娜剛剛是在騎木馬嗎？",
  str_homestory_815601001_2_dialog_content = "......木馬？",
  str_homestory_815601001_3_dialog_content = "還以為妳不喜歡這種玩具呢。",
  str_homestory_815601001_4_dialog_content = "我......我也沒說過喜歡......",
  str_homestory_815601001_5_dialog_content = "只不過是走路走累了，想找個地方休息下而已。",
  str_homestory_815601001_6_dialog_content = "本小姐才不會對這種東西感興趣呢。",
  str_homestory_815601001_7_dialog_content = "說得也是呢......",
  str_homestory_815601001_8_dialog_content = "重點難道不是「本小姐走累了沒有地方休息」這件事嗎？",
  str_homestory_815601001_9_option_content = "（表示抱歉）",
  str_homestory_815601001_10_dialog_content = "這個......抱歉！",
  str_homestory_815601001_11_dialog_content = "我是不是應該在附近多放幾個石板凳？",
  str_homestory_815601001_12_dialog_content = "石板凳？哈哈哈，你一定是在開玩笑吧？",
  str_homestory_815601001_13_dialog_content = "不會真的有人能忍受坐在那種硬邦邦的東西上吧？",
  str_homestory_815601001_14_dialog_content = "要是你需要......",
  str_homestory_815601001_15_dialog_content = "本小姐倒是可以為你設計一些既美觀又舒適的遊客座椅喔。",
  str_homestory_815601001_16_dialog_content = "只要你可以告訴我，那堆木頭究竟有什麼好玩的......",
  str_homestory_815601001_17_option_content = "（詢問心情）",
  str_homestory_815601001_18_dialog_content = "看來妮娜今天逛了不少地方啊。",
  str_homestory_815601001_19_dialog_content = "不知道我這裡合不合大小姐您的心意呀？",
  str_homestory_815601001_20_dialog_content = "既然你問我，就別怪我做出嚴苛的評價喔。",
  str_homestory_815601001_21_dialog_content = "你這個地方真的是太偏僻了！",
  str_homestory_815601001_22_dialog_content = "......還真是完全沒有反駁的理由呢。",
  str_homestory_815601001_23_dialog_content = "不過風景確實不錯，可以加入我的度假地點備選。",
  str_homestory_815601001_24_dialog_content = "要知道，本小姐的評論一旦刊登在影鎮的報紙上，會影響很多人的選擇呢。",
  str_homestory_815601001_25_dialog_content = "前提是......你給我解釋一下，那堆木頭究竟有什麼好玩的......",
  str_homestory_815601001_26_dialog_content = "妮娜不是對木馬不感興趣嗎？",
  str_homestory_815601001_27_dialog_content = "......我改變主意了。",
  str_homestory_815601001_28_dialog_content = "瞭解大家的興趣也是本小姐的功課之一。",
  str_homestory_815601001_29_dialog_content = "這種支撐不穩定的木頭塊，明明一坐上去就會晃動啊。",
  str_homestory_815601001_30_dialog_content = "原來妮娜沒有騎過木馬？",
  str_homestory_815601001_31_dialog_content = "本小姐怎麼會沒有騎過木馬呢？",
  str_homestory_815601001_32_dialog_content = "可是......騎木馬就是要體驗這種搖晃的感覺。",
  str_homestory_815601001_33_dialog_content = "原......原來是這樣......啊，別誤會，我早就知道了！",
  str_homestory_815601001_34_dialog_content = "剛才那只是......只是想考驗一下你罷了。",
  str_homestory_815601001_35_option_content = "（相信）",
  str_homestory_815601001_36_dialog_content = "那我一定是經受住了考驗......",
  str_homestory_815601001_37_dialog_content = "嗯！PlayerName比看起來更聰明呢，哈哈哈。",
  str_homestory_815601001_38_option_content = "（不相信）",
  str_homestory_815601001_39_dialog_content = "我才不相信呢。",
  str_homestory_815601001_40_dialog_content = "PlayerName......傻瓜！哼。",
  str_homestory_815601001_41_dialog_content = "……",
  str_homestory_815601001_42_dialog_content = "可是……",
  str_homestory_815601001_43_dialog_content = "大家為什麼不騎真正的馬匹，反而製作這種木頭做的馬呢？",
  str_homestory_815601001_44_dialog_content = "我也不太清楚......",
  str_homestory_815601001_45_dialog_content = "不過木馬也有木馬的樂趣，反正比騎在馬背上安全多了......",
  str_homestory_815601001_46_dialog_content = "而且我猜不是所有人都有機會騎馬吧。",
  str_homestory_815601001_47_dialog_content = "你的意思是......他們買不起真正的馬匹？<sprite=emo_wuzui size=60 />",
  str_homestory_815601001_48_dialog_content = "恐怕有人連木馬都買不起吧。",
  str_homestory_815601001_49_dialog_content = "……",
  str_homestory_815601001_50_dialog_content = "......我決定了！",
  str_homestory_815601001_51_dialog_content = "決定什麼？",
  str_homestory_815601001_52_dialog_content = "我要學習木工設計，造出更好玩的木馬......",
  str_homestory_815601001_53_dialog_content = "送給需要木馬的孩子！",
  str_homestory_810401001_0_dialog_content = "多恩？",
  str_homestory_810401001_1_dialog_content = "這個腳步聲......",
  str_homestory_810401001_2_dialog_content = "是PlayerName嗎？",
  str_homestory_810401001_3_dialog_content = "欸，多恩可以聽出我的腳步聲嗎？",
  str_homestory_810401001_4_dialog_content = "嗯！<sprite=emo_yaosu size=60 />",
  str_homestory_810401001_5_dialog_content = "雖然這裡比巨像多了很多種聲音......",
  str_homestory_810401001_6_dialog_content = "但多恩總是可以從中聽出哪些聲音是熟悉的人發出的。",
  str_homestory_810401001_7_dialog_content = "比如PlayerName和伊芙，你們走路的聲音就不太一樣。",
  str_homestory_810401001_8_dialog_content = "走路聲音的不同嗎......",
  str_homestory_810401001_9_option_content = "（問問自己的）",
  str_homestory_810401001_10_dialog_content = "導航員走路的時候比較急，但是在靠近多恩的時候又會很小心。",
  str_homestory_810401001_11_dialog_content = "這麼說的話，好像不太明確......",
  str_homestory_810401001_12_dialog_content = "但無論如何，多恩就是知道來的那個人是導航員！",
  str_homestory_810401001_13_dialog_content = "啊，還有一點......",
  str_homestory_810401001_14_dialog_content = "當導航員靠近的時候，多恩就會開心。",
  str_homestory_810401001_15_dialog_content = "嗯，這種開心的心情就會讓多恩知道，是PlayerName來了。",
  str_homestory_810401001_16_option_content = "（問問伊芙的）",
  str_homestory_810401001_17_dialog_content = "伊芙走路的聲音很可愛！",
  str_homestory_810401001_18_dialog_content = "......「可愛」這個詞，可以用來形容走路的聲音嗎？",
  str_homestory_810401001_19_dialog_content = "當然，伊芙的一切都很可愛<sprite=emo_aixin size=60 />。",
  str_homestory_810401001_20_dialog_content = "呃……",
  str_homestory_810401001_21_dialog_content = "好吧，不如說因為伊芙的身體構造比較特殊......",
  str_homestory_810401001_22_dialog_content = "所以她走起路來幾乎沒有聲音。",
  str_homestory_810401001_23_dialog_content = "可是當伊芙靠近的時候，多恩就會開心。",
  str_homestory_810401001_24_dialog_content = "嗯，所以這種開心就會讓多恩知道，是伊芙來了。",
  str_homestory_810401001_25_dialog_content = "原來是這樣……",
  str_homestory_810401001_26_dialog_content = "多恩好厲害！",
  str_homestory_810401001_27_dialog_content = "因為看不到，所以聽覺就會被放大。",
  str_homestory_810401001_28_dialog_content = "啊，對了。",
  str_homestory_810401001_29_dialog_content = "那醒山呢？",
  str_homestory_810401001_30_dialog_content = "你們應該也算熟悉了吧，醒山走路的聲音是怎樣的？",
  str_homestory_810401001_31_dialog_content = "比起聽聲音，通常我有更簡單的方法判斷來者是不是他。",
  str_homestory_810401001_32_dialog_content = "是什麼方法？",
  str_homestory_810401001_33_dialog_content = "他比較臭。",
  str_homestory_810401001_34_dialog_content = "......？",
  str_homestory_810401001_35_dialog_content = "也許是因為他動作比較大的關係吧......所以更容易出汗？",
  str_homestory_810401001_36_dialog_content = "原......原來是這樣......",
  str_homestory_810401001_37_dialog_content = "雖然他不算是紅油扳手那群人裡最臭的......",
  str_homestory_810401001_38_dialog_content = "但是比起你和伊芙，他確實更臭一點。",
  str_homestory_810401001_39_dialog_content = "幸好你沒有那樣的味道，導航員。",
  str_homestory_810401001_40_dialog_content = "呃，謝謝？",
  str_homestory_810401001_41_dialog_content = "可是為什麼......為什麼我不覺得醒山身上有什麼味道呢？",
  str_homestory_810401001_42_dialog_content = "沒有嗎？",
  str_homestory_810401001_43_dialog_content = "難道只是我因為對他霸佔伊芙的時間太長而不滿......<sprite=emo_sikao size=60 />",
  str_homestory_810401001_44_dialog_content = "才會覺得他很臭嗎？",
  str_homestory_810401001_45_dialog_content = "......要我說這才是真正的原因吧！！",
  str_homestory_810401001_46_dialog_content = "......我不管，一定是他真的很臭才對。",
  str_homestory_810401001_47_dialog_content = "臭，臭臭，醒山臭<sprite=emo_kulou size=60 />！",
  str_homestory_809001001_0_dialog_content = "芭芭拉？",
  str_homestory_809001001_1_dialog_content = "愛情♪究竟是不是騙人的東西～",
  str_homestory_809001001_2_dialog_content = "<sprite=emo_aixin size=60 />一定要將機油燃盡，來換取真心～",
  str_homestory_809001001_3_dialog_content = "喔喔～只要真心～",
  str_homestory_809001001_4_dialog_content = "芭芭拉是在練習新單曲嗎？",
  str_homestory_809001001_5_dialog_content = "嘿嘿，單曲？不是喔！",
  str_homestory_809001001_6_dialog_content = "芭芭拉可是準備出新專輯了呢！",
  str_homestory_809001001_7_option_content = "專輯？",
  str_homestory_809001001_8_dialog_content = "專輯？就是會包含很多歌曲的光碟嗎？",
  str_homestory_809001001_9_dialog_content = "沒錯喔～",
  str_homestory_809001001_10_option_content = "超過蕾吉娜了？",
  str_homestory_809001001_11_dialog_content = "哼哼～那是自然！",
  str_homestory_809001001_12_dialog_content = "為了這次的銷量和簽售情況，芭芭拉可得好好努力才行呢！",
  str_homestory_809001001_13_dialog_content = "好刻苦啊。",
  str_homestory_809001001_14_dialog_content = "當然啦，最近各地都出現了不少新鮮的音樂風格......",
  str_homestory_809001001_15_dialog_content = "芭芭拉可不能被比下去呀！",
  str_homestory_809001001_16_dialog_content = "芭芭拉是在擔心自己的歌壇地位不保嗎？",
  str_homestory_809001001_17_dialog_content = "地位不保......？哎呀，人家才不會擔心這種事呢！",
  str_homestory_809001001_18_dialog_content = "芭芭拉也很希望看到更多類型的音樂和音樂人呀～",
  str_homestory_809001001_19_dialog_content = "那「不能被比下去」是指......？",
  str_homestory_809001001_20_dialog_content = "意思就是芭芭拉也要更加努力才行呢<sprite=emo_yinfu size=60 />！",
  str_homestory_809001001_21_dialog_content = "要和新人一起進步，一起創作出更好的作品！",
  str_homestory_809001001_22_dialog_content = "芭芭拉最討厭被甩在後面了！",
  str_homestory_809001001_23_dialog_content = "聽起來很勵志！",
  str_homestory_809001001_24_dialog_content = "嗯嗯，雖說不怎麼擔心自己的人氣～",
  str_homestory_809001001_25_dialog_content = "但是如果看到熟悉的歌迷跑去別人那邊......",
  str_homestory_809001001_26_dialog_content = "還是會產生挫敗感啦！",
  str_homestory_809001001_27_dialog_content = "是在說蕾吉娜？",
  str_homestory_809001001_28_dialog_content = "PlayerName......也太直接了吧！",
  str_homestory_809001001_29_dialog_content = "果然還是會偷偷在意蕾吉娜的音樂吧？",
  str_homestory_809001001_30_dialog_content = "該怎麼說呢？",
  str_homestory_809001001_31_dialog_content = "感覺如果要說「完全不在意」的話，那就是在撒謊<sprite=emo_tanqi size=60 />......",
  str_homestory_809001001_32_dialog_content = "嗯，應該這麼說～",
  str_homestory_809001001_33_dialog_content = "我是在從「拓展音樂多樣性」的角度來聽她的歌曲啦。",
  str_homestory_809001001_34_dialog_content = "唔～雖然她的粉絲數量比不上我，但是感覺都特別死忠欸～",
  str_homestory_809001001_35_dialog_content = "雖然做音樂本身要從質量取勝，但其實我還是會好奇......",
  str_homestory_809001001_36_dialog_content = "她到底是怎麼留住粉絲的呢？",
  str_homestory_809001001_37_dialog_content = "與其自己苦想，不如直接問問蕾吉娜？",
  str_homestory_809001001_38_dialog_content = "唔呀～",
  str_homestory_809001001_39_dialog_content = "既然是PlayerName的建議，那我就勉強接受好啦......",
  str_homestory_809001001_40_dialog_content = "問問她也沒什麼的啦！",
  str_homestory_809001001_41_dialog_content = "嗯......前提是要再過二十年喔<sprite=emo_emo size=60 />～～",
  str_homestory_809001001_42_dialog_content = "......那和不問根本沒區別吧！",
  str_homestory_807001001_0_dialog_content = "莉奧娜......",
  str_homestory_807001001_1_dialog_content = "你來了，小鬼。",
  str_homestory_807001001_2_dialog_content = "有事找我？",
  str_homestory_807001001_3_dialog_content = "抱歉，我暫時沒空。",
  str_homestory_807001001_4_dialog_content = "如你所見，我正忙著緩解情緒——",
  str_homestory_807001001_5_dialog_content = "啊，打沙袋算是緩解情緒的一種方式嗎？",
  str_homestory_807001001_6_dialog_content = "當然<sprite=emo_baiyan size=60 />。",
  str_homestory_807001001_7_dialog_content = "你沒有聽過這種說法嗎？",
  str_homestory_807001001_8_dialog_content = "運動一定程度上能夠化解負面情緒。",
  str_homestory_807001001_9_dialog_content = "這我倒是聽說過。",
  str_homestory_807001001_10_dialog_content = "那莉奧娜現在的負面情緒......",
  str_homestory_807001001_11_option_content = "是因為什麼？",
  str_homestory_807001001_12_dialog_content = "沒什麼具體原因。",
  str_homestory_807001001_13_option_content = "被化解了嗎？",
  str_homestory_807001001_14_dialog_content = "嗯，差不多吧。",
  str_homestory_807001001_15_dialog_content = "你可以把負面情緒理解為你身體裡的一個「結」。",
  str_homestory_807001001_16_dialog_content = "「結」......？是指繩子打結的那種結嗎......",
  str_homestory_807001001_17_dialog_content = "類似。",
  str_homestory_807001001_18_dialog_content = "一旦你察覺到自己有負面情緒的話......",
  str_homestory_807001001_19_dialog_content = "就一定要透過某種自己喜歡的方式來讓它離開身體才行。",
  str_homestory_807001001_20_dialog_content = "任何能夠讓你感到放鬆的方式都可以。",
  str_homestory_807001001_21_dialog_content = "不過對我而言，這種類似戰鬥的放鬆是最適合的。",
  str_homestory_807001001_22_dialog_content = "負面情緒要是一直停滯在體內，這個「結」就會越來越亂。",
  str_homestory_807001001_23_dialog_content = "最終，甚至會影響你的生命。",
  str_homestory_807001001_24_dialog_content = "這是我花了很久才學會的東西。",
  str_homestory_807001001_25_dialog_content = "被仇恨蒙蔽的心靈和血脈......",
  str_homestory_807001001_26_dialog_content = "......說遠了，小鬼。",
  str_homestory_807001001_27_dialog_content = "嗯......莉奧娜說得很有道理。",
  str_homestory_807001001_28_dialog_content = "下次你也可以試試。",
  str_homestory_807001001_29_dialog_content = "沒問題！",
  str_homestory_807001001_30_dialog_content = "也許上次希羅娜在這裡練習拳擊也是出於同樣的理由吧？",
  str_homestory_807001001_31_dialog_content = "……你說什麼？",
  str_homestory_807001001_32_dialog_content = "這沙袋希羅娜也打過？",
  str_homestory_807001001_33_dialog_content = "啊......啊？我，我亂講的！",
  str_homestory_807001001_34_dialog_content = "（好像說了不該說的話......）",
  str_homestory_807001001_35_dialog_content = "……",
  str_homestory_807001001_36_dialog_content = "莉奧娜，妳怎麼了？為什麼突然......",
  str_homestory_807001001_37_dialog_content = "呵呵，又和我親愛的妹妹做了一樣的事呢。",
  str_homestory_807001001_38_dialog_content = "為了不把這裡全部燒<sprite=emo_nuhuo size=60 />個精光......",
  str_homestory_807001001_39_dialog_content = "我想我現在應該馬上回到影鎮。",
  str_homestory_807001001_40_dialog_content = "再見，小鬼。",
  str_homestory_807001001_41_dialog_content = "那……那個……",
  str_homestory_807001001_42_dialog_content = "也可以多回來看看......",
  str_homestory_811501001_0_dialog_content = "納努塞爾！",
  str_homestory_811501001_1_dialog_content = "尊敬的PlayerName。",
  str_homestory_811501001_2_dialog_content = "一定是自然之力指引著您，才使我們再度相聚於此。",
  str_homestory_811501001_3_dialog_content = "納努塞爾這是在和辛格還有波伊特聊天嗎？",
  str_homestory_811501001_4_dialog_content = "是呀。",
  str_homestory_811501001_5_dialog_content = "想不到您還記得他們的名字......",
  str_homestory_811501001_6_dialog_content = "他們很開心。",
  str_homestory_811501001_7_dialog_content = "這是應該的。",
  str_homestory_811501001_8_dialog_content = "看著再度矗立的空之山谷，確實令人感慨萬千<sprite=emo_pugongying size=60 />。",
  str_homestory_811501001_9_dialog_content = "而這片空庭能有今天的景象......",
  str_homestory_811501001_10_dialog_content = "想必也離不開自然的餽贈，還有PlayerName的萬分努力。",
  str_homestory_811501001_11_dialog_content = "不過......我有些為您擔心。",
  str_homestory_811501001_12_dialog_content = "最近經歷了這麼多事情的您，心情還好嗎？",
  str_homestory_811501001_13_option_content = "（點頭）",
  str_homestory_811501001_14_dialog_content = "其實，能和大家一起在這裡生活，我就很開心了。",
  str_homestory_811501001_15_dialog_content = "只是偶爾也會因為一些期許而感到壓力吧。",
  str_homestory_811501001_16_option_content = "（搖頭）",
  str_homestory_811501001_17_dialog_content = "雖然說不上心情一直很差......",
  str_homestory_811501001_18_dialog_content = "但總能感到某種莫名的焦慮和壓力。",
  str_homestory_811501001_19_dialog_content = "我明白了。",
  str_homestory_811501001_20_dialog_content = "不知道您現在是否願意和我一起稍稍放鬆一下呢？",
  str_homestory_811501001_21_dialog_content = "好的。",
  str_homestory_811501001_22_dialog_content = "我們可以一起嘗試一下這種「呼吸」練習。",
  str_homestory_811501001_23_dialog_content = "「呼吸」練習？",
  str_homestory_811501001_24_dialog_content = "是的。",
  str_homestory_811501001_25_dialog_content = "這種練習可以幫助您隨時平衡身體內在的能量。",
  str_homestory_811501001_26_dialog_content = "簡單來說......",
  str_homestory_811501001_27_dialog_content = "它可以讓我們身體內部的能量重新流動起來。",
  str_homestory_811501001_28_dialog_content = "明白了！現在就開始吧？",
  str_homestory_811501001_29_dialog_content = "好。",
  str_homestory_811501001_30_dialog_content = "肩膀放鬆，先做一個深呼吸。",
  str_homestory_811501001_31_dialog_content = "很好。現在，我們嘗試捏住鼻子。",
  str_homestory_811501001_32_dialog_content = "（捏住鼻子......唔......）",
  str_homestory_811501001_33_dialog_content = "先捏緊右邊的鼻翼，嘗試用左邊吸氣。",
  str_homestory_811501001_34_dialog_content = "然後馬上捏緊左邊的鼻翼，用右側吐氣——",
  str_homestory_811501001_35_dialog_content = "（吸氣，吐氣......）",
  str_homestory_811501001_36_dialog_content = "就是這樣，慢慢地調整自己的呼吸。",
  str_homestory_811501001_37_dialog_content = "保持持續均勻的吸氣和吐氣......",
  str_homestory_811501001_38_dialog_content = "我們會感受到這種呼吸法帶給整個身心的放鬆。",
  str_homestory_811501001_39_dialog_content = "確實，感覺自己的心情變得很平靜。",
  str_homestory_811501001_40_dialog_content = "甚至還有點想睡<sprite=emo_kun size=60 />......",
  str_homestory_811501001_41_dialog_content = "呵呵～",
  str_homestory_811501001_42_dialog_content = "這種呼吸法除了能夠舒緩情緒，確實還有助眠的作用。",
  str_homestory_811501001_43_dialog_content = "您在睡前不妨再嘗試一下這種方法。",
  str_homestory_811501001_44_dialog_content = "也許閉著眼睛調整呼吸，會有更好的效果呢。",
  str_homestory_811501001_45_dialog_content = "嗯，我記住了。",
  str_homestory_811501001_46_dialog_content = "謝謝妳，納努塞爾！",
  str_homestory_803302001_0_dialog_content = "妳好，薇絲。",
  str_homestory_803302001_1_dialog_content = "PlayerName！你現在有空嗎？",
  str_homestory_803302001_2_dialog_content = "當然，請說吧。",
  str_homestory_803302001_3_dialog_content = "我在水邊散步時，發現水裡似乎有什麼東西。",
  str_homestory_803302001_4_dialog_content = "但忙活了半天也沒弄上來。那似乎是......某種設計圖？",
  str_homestory_803302001_5_dialog_content = "如果你感興趣的話，可以去那個地方看看！",
  str_homestory_803302001_6_dialog_content = "嗯嗯，沒問題。",
  str_homestory_803303001_0_dialog_content = "你在做什麼？",
  str_homestory_803303001_1_dialog_content = "在思考......我要怎麼才能把那個東西釣上來呢......",
  str_homestory_803303001_2_dialog_content = "什麼東西？",
  str_homestory_803303001_3_dialog_content = "河裡有個很奇怪的物品，我相當在意<sprite=emo_sikao size=60 />。",
  str_homestory_803303001_4_dialog_content = "可是我釣到手酸也沒釣起來。",
  str_homestory_803303001_5_dialog_content = "你能幫幫我嗎？就在那邊！",
  str_homestory_803303001_6_dialog_content = "我......我試試看。",
  str_homestory_803304001_0_dialog_content = "你找我？",
  str_homestory_803304001_1_dialog_content = "啊，你怎麼知道我在找你？",
  str_homestory_803304001_2_dialog_content = "我發現一個有趣的東西！<sprite=emo_yaosu size=60 />",
  str_homestory_803304001_3_dialog_content = "不會又是什麼巨型蜘蛛或者會跳舞的螞蚱吧。",
  str_homestory_803304001_4_dialog_content = "不是啦！是新家具的設計圖喔！",
  str_homestory_803304001_5_dialog_content = "不過它沉在水底，好像很難撈起來。",
  str_homestory_803304001_6_dialog_content = "哈，交給我吧。這個我熟。",
  str_homestory_803304001_7_dialog_content = "就在那邊！我指給你看！",
  str_homestory_809301001_0_dialog_content = "這個眼神......",
  str_homestory_809301001_1_dialog_content = "找......找我有事嗎？",
  str_homestory_809301001_2_dialog_content = "幾日不見你成長了許多嘛，我還沒開口你就知道我找你有事。",
  str_homestory_809301001_3_dialog_content = "剛剛覺得背脊發涼，好像有一雙眼睛緊盯著我不放......",
  str_homestory_809301001_4_dialog_content = "抬起頭就發現妳盯著我看。",
  str_homestory_809301001_5_dialog_content = "「抬起頭」？看來這幾日你還是沒有長個子。",
  str_homestory_809301001_6_option_content = "我長高了！",
  str_homestory_809301001_7_dialog_content = "是嗎？我怎麼看不出來。要不要去我的實驗室？",
  str_homestory_809301001_8_dialog_content = "我可以解剖一下，看看你的骨頭究竟有沒有生長。",
  str_homestory_809301001_9_option_content = "是的……",
  str_homestory_809301001_10_dialog_content = "這樣就承認了？實在是讓人於心不忍。要不要去我的實驗室？",
  str_homestory_809301001_11_dialog_content = "我可以解剖一下，看看你的骨頭還會不會分泌生長激素。",
  str_homestory_809301001_12_dialog_content = "那......那個就不必了吧......",
  str_homestory_809301001_13_dialog_content = "放心，讓我解剖一下，我就可以為你定製一套長高方案。",
  str_homestory_809301001_14_dialog_content = "我暫時還是順其自然吧。",
  str_homestory_809301001_15_dialog_content = "順其自然？不是吧？",
  str_homestory_809301001_16_dialog_content = "我看你這空庭裡面，可是有不少基因改良過的樹木啊。",
  str_homestory_809301001_17_dialog_content = "而且用的應該是那種......",
  str_homestory_809301001_18_dialog_content = "雜糅不同樹木種子，混合成獨特樹種的生物科技。",
  str_homestory_809301001_19_dialog_content = "欸，只看樹木的外表就能看出來嗎？",
  str_homestory_809301001_20_dialog_content = "你忘了？我是啟光的科研長官，專攻生物科技方向。",
  str_homestory_809301001_21_dialog_content = "像這種生物實驗，我做過的次數已經數不過來了。",
  str_homestory_809301001_22_dialog_content = "不過，我沒想到你竟然還有這種科研天賦？",
  str_homestory_809301001_23_dialog_content = "我只是依樣畫葫蘆，所以也不是特別厲害啦。",
  str_homestory_809301001_24_dialog_content = "嗯，看出來了。",
  str_homestory_809301001_25_dialog_content = "……",
  str_homestory_809301001_26_dialog_content = "沒有經歷過九十九次的失敗，就無法獲得那一次的成功。",
  str_homestory_809301001_27_dialog_content = "這是我在工作中得到的啟示。而你呢......",
  str_homestory_809301001_28_dialog_content = "要想得到稀世珍種，還需要那樣一下，再這樣一下才可以。",
  str_homestory_809301001_29_dialog_content = "「那樣一下，再這樣一下」？完全沒有聽懂......",
  str_homestory_809301001_30_dialog_content = "沒有科研背景，理解起來確實很困難。找機會再和你交流吧。",
  str_homestory_809301001_31_dialog_content = "好呀，現在就可以。",
  str_homestory_809301001_32_dialog_content = "現在？先讓我睡一覺再說吧。",
  str_homestory_809301001_33_dialog_content = "……",
  str_homestory_809301001_34_dialog_content = "啊，等等。我差點忘了要找你說的正事。",
  str_homestory_809301001_35_dialog_content = "可以把我的房間換到可愛女孩子比較多的那座宅舍裡嗎？",
  str_homestory_809301001_36_option_content = "（答應）",
  str_homestory_809301001_37_dialog_content = "可以是可以......不過要妳自己和大家商量好才行。",
  str_homestory_809301001_38_option_content = "（拒絕）",
  str_homestory_809301001_39_dialog_content = "住在哪裡是大家的自由，我不方便干涉。",
  str_homestory_809301001_40_dialog_content = "要是妳能和大家商量好，也不是不可以。",
  str_homestory_809301001_41_dialog_content = "聽起來有點麻煩啊。",
  str_homestory_809301001_42_dialog_content = "不過值得一試。實在不行，就試一百次。",
  str_homestory_809301001_43_dialog_content = "（在這種事情上也需要用到這樣的科研精神嗎？）",
  str_homestory_815702001_0_dialog_content = "在看什麼呢？",
  str_homestory_815702001_1_dialog_content = "唔啊啊啊......",
  str_homestory_815702001_2_dialog_content = "對不起，是我又嚇到妳了嗎？",
  str_homestory_815702001_3_dialog_content = "（......不過我為什麼會說「又」啊。）",
  str_homestory_815702001_4_dialog_content = "沒有沒有，是我在這裡想事情想得太入迷了......",
  str_homestory_815702001_5_dialog_content = "所以才沒有發現PlayerName先生站在旁邊。",
  str_homestory_815702001_6_dialog_content = "該說抱歉的人，是我......",
  str_homestory_815702001_7_dialog_content = "妳沒事就好，不用想這麼多啦。",
  str_homestory_815702001_8_dialog_content = "妳是剛從河邊走過來的吧？難道妳剛剛是在想......",
  str_homestory_815702001_9_option_content = "釣魚？",
  str_homestory_815702001_10_dialog_content = "釣魚......需要很昂貴的釣具吧？",
  str_homestory_815702001_11_dialog_content = "我......我沒有那種非分之想啦。",
  str_homestory_815702001_12_option_content = "游泳？",
  str_homestory_815702001_13_dialog_content = "游泳......需要穿上那種很貼身的泳衣吧？",
  str_homestory_815702001_14_dialog_content = "我......我還有點不好意思呢。",
  str_homestory_815702001_15_dialog_content = "其實，我是在思考......",
  str_homestory_815702001_16_dialog_content = "曾經在空谷里耕耘的農民，會不會和雲島的農民們一樣辛苦？",
  str_homestory_815702001_17_dialog_content = "這個嘛，我也不太清楚。但我想無論是空谷，還是雲島......",
  str_homestory_815702001_18_dialog_content = "在豐收的時候，大家都是同樣開心吧。",
  str_homestory_815702001_19_dialog_content = "話說回來，妳為什麼忽然想到這個問題呀？",
  str_homestory_815702001_20_dialog_content = "是因為......我剛剛在河邊撿到一個閃光的東西，樣子好像一枚硬幣<sprite=emo_baiyebi size=60 />。",
  str_homestory_815702001_21_dialog_content = "有硬幣就有交易，有交易就有糧食，而有糧食的地方......就有農民！",
  str_homestory_815702001_22_dialog_content = "竟然可以這樣去聯想？！",
  str_homestory_815702001_23_dialog_content = "啊，請......請不要生氣！",
  str_homestory_815702001_24_dialog_content = "我我我我我沒有想要獨吞硬幣的意思。",
  str_homestory_815702001_25_dialog_content = "我這就把硬幣交給您......",
  str_homestory_815702001_26_dialog_content = "沒關係，不用這麼著急。",
  str_homestory_815702001_27_dialog_content = "我找找，我放在哪裡來著？",
  str_homestory_815702001_28_dialog_content = "欸，怎麼不見了......",
  str_homestory_815702001_29_dialog_content = "啊！",
  str_homestory_815702001_30_dialog_content = "怎麼了？",
  str_homestory_815702001_31_dialog_content = "我想起剛剛離開河邊的時候，聽見噗通一聲。",
  str_homestory_815702001_32_dialog_content = "現在想來，一定是硬幣被我不小心丟進河裡去了！",
  str_homestory_815702001_33_dialog_content = "沒關係，我去把它撈上來。",
  str_homestory_815702001_34_dialog_content = "唔啊啊啊......可......可以嗎？那就拜託您了！",
  str_homestory_815602001_0_dialog_content = "在找什麼？",
  str_homestory_815602001_1_dialog_content = "喂，快過來呀！",
  str_homestory_815602001_2_dialog_content = "妮娜？",
  str_homestory_815602001_3_dialog_content = "如果我沒看錯的話，妳剛剛是不是在找東西？",
  str_homestory_815602001_4_dialog_content = "沒錯。",
  str_homestory_815602001_5_dialog_content = "你有沒有見過一個圓圓的東西？",
  str_homestory_815602001_6_dialog_content = "有更具體點的形容嗎？",
  str_homestory_815602001_7_dialog_content = "嗯......是這樣的。",
  str_homestory_815602001_8_dialog_content = "我從來沒有見過那種印花的物品......",
  str_homestory_815602001_9_dialog_content = "所以我剛剛把它緊緊地攥在手裡！",
  str_homestory_815602001_10_dialog_content = "可是，等我鬆開手之後，它就不小心掉進水裡了。",
  str_homestory_815602001_11_dialog_content = "等等，我怎麼覺得妳說的是......",
  str_homestory_815602001_12_dialog_content = "不，你先聽我說。",
  str_homestory_815602001_13_dialog_content = "等我鬆手之後，我發現手心出現了奇異的紋路！",
  str_homestory_815602001_14_option_content = "光能變異了？！",
  str_homestory_815602001_15_dialog_content = "什麼啊，你最近是不是小說讀太多啦？",
  str_homestory_815602001_16_option_content = "妮娜要變身了？！",
  str_homestory_815602001_17_dialog_content = "你在說些什麼啊？",
  str_homestory_815602001_18_dialog_content = "是因為「那個東西」本身的造型和印花都很獨特啦！",
  str_homestory_815602001_19_dialog_content = "所以，握在手裡才會形成相應的紋路呢。",
  str_homestory_815602001_20_dialog_content = "這種倒映在掌心的紋路，有種奇異的設計感......",
  str_homestory_815602001_21_dialog_content = "試想一下，要是用這樣的方式去設計服裝的話......",
  str_homestory_815602001_22_dialog_content = "不行，我一定得找到那枚硬幣才行！",
  str_homestory_815602001_23_dialog_content = "果然是硬幣吧！",
  str_homestory_815602001_24_dialog_content = "我來幫妳找吧。",
  str_homestory_815602001_25_dialog_content = "那，那就先謝......啊，等等！<sprite=emo_wuzui size=60 />",
  str_homestory_815602001_26_dialog_content = "因為這枚硬幣是我在空庭發現的，所以應該算是......你的財產吧？",
  str_homestory_815602001_27_dialog_content = "這樣一來，要是我想要借走研究一段時間的話......",
  str_homestory_815602001_28_dialog_content = "沒問題。但是我得先找到這枚硬幣才行。",
  str_homestory_815602001_29_dialog_content = "哇啊！答應得好快？",
  str_homestory_815602001_30_dialog_content = "咳咳，那個，倒不是本小姐有多想做這種研究......",
  str_homestory_815602001_31_dialog_content = "我只是為了服裝設計而已！",
  str_homestory_815602001_32_dialog_content = "這點你是知道的吧？",
  str_homestory_815602001_33_dialog_content = "我知道。",
  str_homestory_815602001_34_dialog_content = "哼哼，那就好。",
  str_homestory_812601001_0_dialog_content = "在思考什麼？",
  str_homestory_812601001_1_dialog_content = "貝菲爾？",
  str_homestory_812601001_2_dialog_content = "妳看起來正在一臉嚴肅地思考著什麼......",
  str_homestory_812601001_3_dialog_content = "噓......<sprite=emo_chidai size=60 />",
  str_homestory_812601001_4_dialog_content = "好不容易才處理完總商會的那些報表，我正在想事情。",
  str_homestory_812601001_5_dialog_content = "在想什麼？",
  str_homestory_812601001_6_dialog_content = "我的新劇本！",
  str_homestory_812601001_7_dialog_content = "啊，乾脆問問你好了。",
  str_homestory_812601001_8_dialog_content = "嗯，也行。如果我能幫上忙的話。",
  str_homestory_812601001_9_dialog_content = "咳，聽好了，劇情是這樣展開的。",
  str_homestory_812601001_10_dialog_content = "男主角和女主角來到了溪水邊......",
  str_homestory_812601001_11_dialog_content = "這時，女主角的手帕突然掉進了水裡！",
  str_homestory_812601001_12_dialog_content = "提問，你覺得該讓女主角去撿手帕，還是讓男主角去撿手帕呢？",
  str_homestory_812601001_13_option_content = "女主角",
  str_homestory_812601001_14_dialog_content = "唔......",
  str_homestory_812601001_15_dialog_content = "這樣好像確實能體現女主角那種「凡事都要自己完成」的獨立感。",
  str_homestory_812601001_16_option_content = "男主角",
  str_homestory_812601001_17_dialog_content = "唔......",
  str_homestory_812601001_18_dialog_content = "這樣好像能比較快速地推進情節，還能展開一些關於手帕的話題。",
  str_homestory_812601001_19_dialog_content = "好，我明白了！",
  str_homestory_812601001_20_dialog_content = "就這樣寫！<sprite=emo_yaosu size=60 />",
  str_homestory_812601001_21_dialog_content = "貝菲爾為什麼會想到安排這種橋段啊？",
  str_homestory_812601001_22_dialog_content = "因為我剛剛看到有什麼東西掉進水裡了。",
  str_homestory_812601001_23_dialog_content = "所以我覺得，其實安排一段這樣的情節也不錯......",
  str_homestory_812601001_24_dialog_content = "嗯？是什麼東西掉進水裡了？",
  str_homestory_812601001_25_dialog_content = "我也沒太看清楚欸，好像是一個小小圓圓的東西。<sprite=emo_sikao size=60 />",
  str_homestory_812601001_26_dialog_content = "小小圓圓的東西......",
  str_homestory_812601001_27_dialog_content = "我知道那是什麼了。",
  str_homestory_816401001_0_dialog_content = "卡蓮？",
  str_homestory_816401001_1_dialog_content = "PlayerName？",
  str_homestory_816401001_2_dialog_content = "卡蓮，妳在做什麼？",
  str_homestory_816401001_3_dialog_content = "我......在思考。",
  str_homestory_816401001_4_dialog_content = "怎麼感覺妳有點低落......？",
  str_homestory_816401001_5_dialog_content = "低落嗎......",
  str_homestory_816401001_6_dialog_content = "因為最近白夜城發生了一些自然災害。",
  str_homestory_816401001_7_dialog_content = "抱歉，卡蓮......",
  str_homestory_816401001_8_dialog_content = "現在的情況怎麼樣？有什麼我能幫上忙的嗎？",
  str_homestory_816401001_9_dialog_content = "謝謝你的關心，PlayerName。",
  str_homestory_816401001_10_dialog_content = "人員傷亡統計和財產損失情況都進入正常的災後處理流程了。",
  str_homestory_816401001_11_dialog_content = "除了把意外去世的人們重新「還」給家屬......",
  str_homestory_816401001_12_dialog_content = "我實在想不出還有什麼方法能彌補他們心中的傷痛。",
  str_homestory_816401001_13_dialog_content = "我能理解妳的心情，卡蓮。",
  str_homestory_816401001_14_dialog_content = "呼......<sprite=emo_tanqi size=60 />",
  str_homestory_816401001_15_dialog_content = "把困擾著我的事情說出來之後，感覺自己的思路清晰了一些。",
  str_homestory_816401001_16_dialog_content = "卡蓮是在思考該如何避免這種災害嗎？",
  str_homestory_816401001_17_dialog_content = "不是的。",
  str_homestory_816401001_18_dialog_content = "我們身為渺小的個體，很難和這麼龐大的命題相抗衡。",
  str_homestory_816401001_19_dialog_content = "我只是在默默地祈禱，順帶向我自己確認一件事......",
  str_homestory_816401001_20_option_content = "自己的信仰？",
  str_homestory_816401001_21_dialog_content = "嗯……",
  str_homestory_816401001_22_option_content = "祈禱的作用？",
  str_homestory_816401001_23_dialog_content = "該怎麼說呢……",
  str_homestory_816401001_24_dialog_content = "我只是想確認，祈禱是否仍然會為我帶來內心的慰藉吧。",
  str_homestory_816401001_25_dialog_content = "我知道了……",
  str_homestory_816401001_26_dialog_content = "我們難免會對那些無法干預的「無常」心生敬畏。",
  str_homestory_816401001_27_dialog_content = "可這種「無常」又沒有任何解決辦法，只能眼睜睜地看著它發生。",
  str_homestory_816401001_28_dialog_content = "因此，卡蓮會產生一種莫名的挫敗感吧？",
  str_homestory_816401001_29_dialog_content = "是的。",
  str_homestory_816401001_30_dialog_content = "每當這種挫敗感浮現的時候，我就會在心裡默默地祈禱一番。",
  str_homestory_816401001_31_dialog_content = "同時我也在思考，祈禱真正能為我帶來的東西是什麼。",
  str_homestory_816401001_32_dialog_content = "思來想去，我覺得是一種精神上的支撐，以及......",
  str_homestory_816401001_33_dialog_content = "那種能夠讓人繼續前行的動力。",
  str_homestory_816401001_34_dialog_content = "確實。",
  str_homestory_816401001_35_dialog_content = "祈禱可以很好地幫助卡蓮度過這段心情灰暗的日子吧......",
  str_homestory_816401001_36_dialog_content = "嗯......也讓我明白了一個道理。",
  str_homestory_816401001_37_dialog_content = "為什麼我們總是熱衷於給萬物都創造一個相應的神明？",
  str_homestory_816401001_38_dialog_content = "因為這世間，我們想叩問的問題太多，而答案太少。",
  str_homestory_816401001_39_dialog_content = "所以，祈禱其實是個折中的選項。<sprite=emo_sikao size=60 />",
  str_homestory_816401001_40_dialog_content = "它既不解決問題，也不提供答案。",
  str_homestory_816401001_41_dialog_content = "但它會讓你獲得內心的平靜，從而更好地投入到往後的生活中。",
  str_homestory_816401001_42_dialog_content = "嗯......這確實是種很重要的動力。",
  str_homestory_816401001_43_dialog_content = "也許下次我也可以試試「祈禱」。",
  str_homestory_816401001_44_dialog_content = "我也很期待與你交流關於「祈禱」的感受。",
  str_homestory_811101001_0_dialog_content = "拜里厄……",
  str_homestory_811101001_1_dialog_content = "……",
  str_homestory_811101001_2_dialog_content = "拜里厄！",
  str_homestory_811101001_3_dialog_content = "啊？你怎麼了？",
  str_homestory_811101001_4_dialog_content = "我看到妳一直看著河邊，是有什麼不開心的事情嗎？",
  str_homestory_811101001_5_dialog_content = "你是在擔心我？",
  str_homestory_811101001_6_option_content = "是的",
  str_homestory_811101001_7_dialog_content = "難道我站在河邊，看起來就像在想不開心的事情？<sprite=emo_wuzui size=60 />",
  str_homestory_811101001_8_dialog_content = "啊，這個，拜里厄，妳不要這麼想。",
  str_homestory_811101001_9_dialog_content = "我也只是來河邊散步的，妳看，今天天氣很好呢。哈哈。",
  str_homestory_811101001_10_dialog_content = "你的表情好奇怪。",
  str_homestory_811101001_11_option_content = "無",
  str_homestory_811101001_12_dialog_content = "只是覺得妳站在河邊很久，不知道在做什麼。",
  str_homestory_811101001_13_dialog_content = "我來到河邊，不是散步就是釣魚，不會一動不動地站著的。",
  str_homestory_811101001_14_dialog_content = "所以......拜里厄妳在做什麼呢？",
  str_homestory_811101001_15_dialog_content = "我在想晶石與空庭的事情。",
  str_homestory_811101001_16_dialog_content = "晶石......",
  str_homestory_811101001_17_dialog_content = "對，上次薇絲說，你最近正在為了建設空庭發愁。",
  str_homestory_811101001_18_dialog_content = "尤其是資金<sprite=emo_baiyebi size=60 />，經常捉襟見肘，所以我在想怎麼讓你致富。",
  str_homestory_811101001_19_dialog_content = "於是我就想到了晶石，我的這個能力......",
  str_homestory_811101001_20_dialog_content = "如果將空庭的石頭變成晶石，然後賣給影鎮的珠寶商。",
  str_homestory_811101001_21_dialog_content = "這個真的可以嗎？",
  str_homestory_811101001_22_dialog_content = "嗯，聽說打碎後當做碎水晶，也能賣不少錢呢。",
  str_homestory_811101001_23_dialog_content = "真，真的？",
  str_homestory_811101001_24_dialog_content = "騙你的......",
  str_homestory_811101001_25_dialog_content = "居，居然！拜里厄妳也學會開玩笑了！",
  str_homestory_811101001_26_dialog_content = "或許是我來到空庭之後有了改變吧，畢竟這裡真的能讓人放鬆。",
  str_homestory_811101001_27_dialog_content = "尤其是看著這河裡的魚......",
  str_homestory_811101001_28_dialog_content = "等一下，拜里厄，要觀賞魚的話，可以去祈望池啊。",
  str_homestory_811101001_29_dialog_content = "那裡應該有不少，而且很多還很漂亮呢。",
  str_homestory_811101001_30_dialog_content = "這裡......似乎只能看到一些小魚。",
  str_homestory_811101001_31_dialog_content = "對，我就是在看那些小魚。",
  str_homestory_811101001_32_dialog_content = "尤其是牠們在水草中穿梭，在石頭旁休息的樣子。",
  str_homestory_811101001_33_dialog_content = "真的能令人感到放鬆，牠們與環境融合得那麼好。",
  str_homestory_811101001_34_dialog_content = "不得不說，拜里厄妳的眼神還真是好......",
  str_homestory_811101001_35_dialog_content = "居然能隔著水面，看清楚那些游得飛快的小魚。",
  str_homestory_811101001_36_dialog_content = "牠們也並不是總在游，很多時候都在河底休息。",
  str_homestory_811101001_37_dialog_content = "有的小魚還會鑽進河底的石頭縫隙，露出一個小腦袋......",
  str_homestory_811101001_38_dialog_content = "有的小魚則會隨著水草飄動而隨意游動，感覺特別......自由。",
  str_homestory_811101001_39_dialog_content = "我明白了，拜里厄妳不是在看魚，而是在看牠們的生活。",
  str_homestory_811101001_40_dialog_content = "生活？",
  str_homestory_811101001_41_dialog_content = "就是牠們這種自由閒適的生活方式。",
  str_homestory_811101001_42_dialog_content = "是的，在別的地方，我一直沒有這種感覺。",
  str_homestory_811101001_43_dialog_content = "只有來到空庭，在這河邊看到牠們，才涌上來的。",
  str_homestory_811101001_44_dialog_content = "這就是空庭的魅力？",
  str_homestory_811101001_45_dialog_content = "不是魅力，是放鬆感吧......",
  str_homestory_811101001_46_dialog_content = "對，放鬆<sprite=emo_pugongying size=60 />......",
  str_homestory_816501001_0_dialog_content = "琪爾......",
  str_homestory_816501001_1_dialog_content = "導航員！有沒有工作呀？",
  str_homestory_816501001_2_option_content = "有的",
  str_homestory_816501001_3_dialog_content = "是什麼？報酬如何？",
  str_homestory_816501001_4_dialog_content = "不過感覺可能不適合妳......是一些裝點建築的活......",
  str_homestory_816501001_5_dialog_content = "那些活對於琪爾來說，都是大材小用啊。",
  str_homestory_816501001_6_option_content = "無",
  str_homestory_816501001_7_dialog_content = "真的什麼都沒有嗎？",
  str_homestory_816501001_8_dialog_content = "本來空庭的事情就不多，而且大部分都是丘布們在做。",
  str_homestory_816501001_9_dialog_content = "那有沒有一些大型的工作？例如開山、挖隧道。",
  str_homestory_816501001_10_dialog_content = "你看我的這身機甲，就是專門負責這種工作的！<sprite=emo_dianzan size=60 />",
  str_homestory_816501001_11_dialog_content = "現在沒有。妳為什麼突然想要工作，不想好好休息嗎？",
  str_homestory_816501001_12_dialog_content = "沒辦法休息的，我太缺錢了。",
  str_homestory_816501001_13_dialog_content = "錢？我聽說啟光那邊都是配給制，妳想要什麼特別的東西？",
  str_homestory_816501001_14_dialog_content = "我，我想要一台機械計算器，上次只在科研室看到過一次。",
  str_homestory_816501001_15_dialog_content = "自己造一台吧，反正在空庭裡妳有很多空閒時間。",
  str_homestory_816501001_16_dialog_content = "不行的，那個採用了很多非標準化的零件，又特別精密。",
  str_homestory_816501001_17_dialog_content = "自己製作那些零件的話，非常花時間......",
  str_homestory_816501001_18_dialog_content = "可是如果請人製作，就會花很多錢。",
  str_homestory_816501001_19_dialog_content = "但是又十分想要，所以只能想著打工掙點錢了。",
  str_homestory_816501001_20_dialog_content = "說起來，妳為什麼這麼急切地想要這機器？",
  str_homestory_816501001_21_dialog_content = "因為我覺得設計圖有問題，有處地方計算了多次，總是對不上。",
  str_homestory_816501001_22_dialog_content = "計算太複雜了，頭腦可能會出差錯，但是計算器絕對不會的。",
  str_homestory_816501001_23_dialog_content = "原來是要進行驗證工作。",
  str_homestory_816501001_24_dialog_content = "沒錯！我之前按照這套設計圖製作了一套動力裝甲。",
  str_homestory_816501001_25_dialog_content = "然而因為我的失誤，那套損壞了，設計圖還差點被毀。",
  str_homestory_816501001_26_dialog_content = "設計圖是我從火場中搶救出來的，但是......",
  str_homestory_816501001_27_dialog_content = "因為現在這處地方對不上，我懷疑現設計圖可能少了一些。<sprite=emo_daomei size=60 />",
  str_homestory_816501001_28_dialog_content = "按照現在的設計圖來製作動力裝甲，在某些地方總是特別不靈便。",
  str_homestory_816501001_29_dialog_content = "按道理來說......如果設計圖缺了，應該製作不出來吧？",
  str_homestory_816501001_30_dialog_content = "一般來說是這樣的。",
  str_homestory_816501001_31_dialog_content = "所以是不是理解的角度不同呢？",
  str_homestory_816501001_32_dialog_content = "比如有一次我看到巨像上有個線路不太對，弄了半天也沒搞好。",
  str_homestory_816501001_33_dialog_content = "但是看到螢盞來，只要那麼動一下，就修好了。",
  str_homestory_816501001_34_dialog_content = "理解角度......",
  str_homestory_816501001_35_dialog_content = "我想到了！就像那個硬幣<sprite=emo_baiyebi size=60 />一樣！",
  str_homestory_816501001_36_dialog_content = "硬幣？",
  str_homestory_816501001_37_dialog_content = "我昨天在河邊看到一枚硬幣，啊，或許是瓶蓋、金屬片什麼的。",
  str_homestory_816501001_38_dialog_content = "那個不重要，重要是它居然能在水面自己彈起來！",
  str_homestory_816501001_39_dialog_content = "現在想來，那片水面看起來很平靜，然而下面或許有湍流......",
  str_homestory_816501001_40_dialog_content = "原來如此，那些公式暗示的是設計的方向啊！",
  str_homestory_816501001_41_dialog_content = "等等，妳說在河邊看到了硬幣？",
  str_homestory_816501001_42_dialog_content = "啊？對，對。我去重新設計了，再見！",
  str_homestory_816501001_43_dialog_content = "好……好的。",
  str_homestory_810001001_0_dialog_content = "妳在想什麼？",
  str_homestory_810001001_1_dialog_content = "希卡蕾？",
  str_homestory_810001001_2_dialog_content = "啊，原來是小白，正好有事情問你。",
  str_homestory_810001001_3_dialog_content = "請問。",
  str_homestory_810001001_4_dialog_content = "你是怎麼看待空庭這個地方的呢？",
  str_homestory_810001001_5_dialog_content = "啊？平時都是我問別人，妳這麼突然一問......讓我想一下。",
  str_homestory_810001001_6_option_content = "家園",
  str_homestory_810001001_7_dialog_content = "這裡自然是我的家園。",
  str_homestory_810001001_8_option_content = "休息之處",
  str_homestory_810001001_9_dialog_content = "是一個很好的休息之處。",
  str_homestory_810001001_10_dialog_content = "原來如此……",
  str_homestory_810001001_11_dialog_content = "不過，小白你不覺得空庭這裡也是一處牢籠嗎？",
  str_homestory_810001001_12_dialog_content = "就像我守護的星空墓穴那樣......",
  str_homestory_810001001_13_dialog_content = "我不太明白。",
  str_homestory_810001001_14_dialog_content = "因為這裡實在太舒適了，舒適得令人不會去想什麼其他的事情。",
  str_homestory_810001001_15_dialog_content = "似乎也有其他人這麼和我說過。",
  str_homestory_810001001_16_dialog_content = "這在某種意義上也是一種舒服，就像大陸上流傳四方的那句俗語。",
  str_homestory_810001001_17_dialog_content = "最可怕的利刃乃是一張好床，它是無數英雄的墳塚。",
  str_homestory_810001001_18_dialog_content = "太過舒適，人會忘記職責的，尤其是那些只有眼下的草履蟲<sprite=emo_wuyu size=60 />。",
  str_homestory_810001001_19_dialog_content = "妳為什麼突然想到這些？",
  str_homestory_810001001_20_dialog_content = "昨天我在河邊，看到一團水草，在水中起伏。",
  str_homestory_810001001_21_dialog_content = "而那團水草中，似乎有個金屬片，跟著水草一起起伏。",
  str_homestory_810001001_22_dialog_content = "一瞬間，我突然能理解到剛才那句話了。",
  str_homestory_810001001_23_dialog_content = "放心，妳能想到這句話，就代表妳並不是那金屬片了。",
  str_homestory_810001001_24_dialog_content = "畢竟我們是可以自己行動起來的，對不對？",
  str_homestory_810001001_25_dialog_content = "我果然沒有看錯你，小白，你和那些草履蟲不一樣。",
  str_homestory_816601001_0_dialog_content = "真好......",
  str_homestory_816601001_1_dialog_content = "菲雅今天也很開心的樣子呢。",
  str_homestory_816601001_2_dialog_content = "看來妳已經完全適應在這裡的生活了。",
  str_homestory_816601001_3_dialog_content = "不要隨便揣測神奇動物專家的心情啦！",
  str_homestory_816601001_4_dialog_content = "我明明什麼都沒說......<sprite=emo_shengqi size=60 />",
  str_homestory_816601001_5_dialog_content = "但是妳的行為已經暴露了「妳很開心」的事實呀。",
  str_homestory_816601001_6_dialog_content = "咦？",
  str_homestory_816601001_7_dialog_content = "哪有？我不信。",
  str_homestory_816601001_8_dialog_content = "嗯......好吧，正好我有幾個問題來請教一下專家。",
  str_homestory_816601001_9_dialog_content = "請教我？",
  str_homestory_816601001_10_dialog_content = "哼，說來讓菲雅聽聽。",
  str_homestory_816601001_11_dialog_content = "小狗<sprite=emo_goutou size=60 />開心的時候，有什麼表現？",
  str_homestory_816601001_12_dialog_content = "這個你都不知道嗎？",
  str_homestory_816601001_13_dialog_content = "小狗很容易開心的，而且牠們開心的時候會搖尾巴，很明顯喔。",
  str_homestory_816601001_14_dialog_content = "那小貓<sprite=emo_baimao size=60 />開心的時候，有什麼表現？",
  str_homestory_816601001_15_dialog_content = "這個問題也難不倒我。",
  str_homestory_816601001_16_dialog_content = "雖然貓咪警惕性很高，不過一旦你能主動逗貓咪開心......",
  str_homestory_816601001_17_dialog_content = "牠們就會主動貼近你，還會發出「呼嚕呼嚕」的聲音。",
  str_homestory_816601001_18_dialog_content = "那神奇動物呢，比如凱羅......",
  str_homestory_816601001_19_dialog_content = "凱羅開心的時候也超級明顯的，哈哈哈哈。",
  str_homestory_816601001_20_dialog_content = "牠開不開心，我閉著眼睛都能感覺得到！",
  str_homestory_816601001_21_dialog_content = "嗯嗯，看來不管是不是神奇動物......",
  str_homestory_816601001_22_dialog_content = "開心的時候都會有一些外在的表現呢。",
  str_homestory_816601001_23_dialog_content = "......為什麼忽然覺得你問我這些問題有些不懷好意？",
  str_homestory_816601001_24_dialog_content = "怎麼會呢。",
  str_homestory_816601001_25_dialog_content = "我只是想確認一下我對菲雅的觀察是否正確而已。",
  str_homestory_816601001_26_dialog_content = "欸......我？",
  str_homestory_816601001_27_dialog_content = "菲雅是神奇動物專家，從來都是我觀察小動物......",
  str_homestory_816601001_28_dialog_content = "你，你為什麼要觀察菲雅？",
  str_homestory_816601001_29_dialog_content = "大概是因為......",
  str_homestory_816601001_30_option_content = "好奇",
  str_homestory_816601001_31_dialog_content = "菲雅的情緒比我豐富很多，所以我很好奇。",
  str_homestory_816601001_32_option_content = "無聊",
  str_homestory_816601001_33_dialog_content = "菲雅是個有趣的孩子，所以我想多觀察一下。",
  str_homestory_816601001_34_dialog_content = "總之，據我觀察......",
  str_homestory_816601001_35_dialog_content = "菲雅開心的時候，兔耳朵就會豎起來。",
  str_homestory_816601001_36_dialog_content = "啊啊啊啊<sprite=emo_hanshui size=60 />......不，不要看菲雅的耳朵！",
  str_homestory_816601001_37_dialog_content = "……",
  str_homestory_816601001_38_dialog_content = "等等！",
  str_homestory_816601001_39_dialog_content = "菲雅的兔耳朵明明是髮夾，一直都是豎起來的呀？",
  str_homestory_816601001_40_dialog_content = "菲雅剛剛捂住兔耳朵的時候，就已經在承認自己很開心了吧？",
  str_homestory_816601001_41_dialog_content = "可惡！PlayerName竟然耍我？",
  str_homestory_816601001_42_dialog_content = "好啦好啦，對不起！",
  str_homestory_816601001_43_dialog_content = "為表歉意......我陪妳一起去玩滑梯，好不好？",
  str_homestory_816601001_44_dialog_content = "......這還差不多。",
  str_homestory_816701001_0_dialog_content = "睡著了嗎......",
  str_homestory_816701001_1_dialog_content = "一個很好的問題。",
  str_homestory_816701001_2_dialog_content = "如果風是這個世界的呼吸......",
  str_homestory_816701001_3_dialog_content = "那麼此時此刻的世界也許正在醞釀睡意<sprite=emo_kun size=60 />。",
  str_homestory_816701001_4_dialog_content = "啊，原來你還醒著？",
  str_homestory_816701001_5_dialog_content = "我還以為剛才你在躺椅上睡著了呢。",
  str_homestory_816701001_6_dialog_content = "大海像是從未醒來過的暴君......",
  str_homestory_816701001_7_dialog_content = "若您有幸在海洋上被那狂亂呼嘯的風割傷過髮梢。",
  str_homestory_816701001_8_dialog_content = "傑諾？",
  str_homestory_816701001_9_dialog_content = "我親愛的觀眾，有什麼事嗎？",
  str_homestory_816701001_10_dialog_content = "你剛才在說什麼？我好像沒聽懂。",
  str_homestory_816701001_11_dialog_content = "不對，我一點都沒聽懂。",
  str_homestory_816701001_12_dialog_content = "言語在說出口的一剎那，就不再屬於發出聲音的喉嚨。",
  str_homestory_816701001_13_dialog_content = "詞彙在進入耳朵的瞬間，被另一顆大腦曲解成它想要的模樣。",
  str_homestory_816701001_14_dialog_content = "這世界就是一場最盛大的幻想嘉年華。",
  str_homestory_816701001_15_dialog_content = "我不止一次這樣認為。",
  str_homestory_816701001_16_option_content = "（聽不懂）",
  str_homestory_816701001_17_dialog_content = "好深奧啊......我真的很難理解傑諾在說什麼。",
  str_homestory_816701001_18_option_content = "（聽懂了）",
  str_homestory_816701001_19_dialog_content = "你認為世界上永遠都不會有真正的相互理解。",
  str_homestory_816701001_20_dialog_content = "親愛的觀眾。",
  str_homestory_816701001_21_dialog_content = "這些都無所謂，我們要做的只是享受其中。",
  str_homestory_816701001_22_dialog_content = "咳咳，我總覺得......",
  str_homestory_816701001_23_dialog_content = "你也不知道自己到底在說什麼吧？",
  str_homestory_816701001_24_dialog_content = "也許吧，也許有時候我的確詞不達意。",
  str_homestory_816701001_25_dialog_content = "但我的魔術絕對不會讓人失望<sprite=emo_mojing size=60 />。",
  str_homestory_816701001_26_dialog_content = "嗯......這倒是。",
  str_homestory_816701001_27_dialog_content = "呃，等等！",
  str_homestory_816701001_28_dialog_content = "你不會是利用魔術製造了一個幻象給我看吧？",
  str_homestory_816701001_29_dialog_content = "其實你還在躺椅上睡覺，對不對？！",
  str_homestory_816701001_30_dialog_content = "還是被您發現了嗎？",
  str_homestory_816701001_31_dialog_content = "果然？！",
  str_homestory_816701001_32_dialog_content = "別急，我還沒有說完。",
  str_homestory_816701001_33_dialog_content = "您只答對了一點——現在這裡有個人在睡覺。",
  str_homestory_816701001_34_dialog_content = "但是……",
  str_homestory_816701001_35_dialog_content = "您怎麼就能知道，那個睡著的人不是您呢？",
  str_homestory_816701001_36_dialog_content = "肯定不是我！",
  str_homestory_816701001_37_dialog_content = "因為剛才我離很遠就看到是你在躺椅上睡覺。",
  str_homestory_816701001_38_dialog_content = "那麼，再往前的事情您還記得嗎？",
  str_homestory_816701001_39_dialog_content = "我剛才去......",
  str_homestory_816701001_40_dialog_content = "嗯？我剛才在幹什麼來著？",
  str_homestory_816701001_41_dialog_content = "哈哈哈。",
  str_homestory_816701001_42_dialog_content = "不會吧......難道我在不知不覺中被你催眠了？",
  str_homestory_816701001_43_dialog_content = "能不能讓我醒過來啊......<sprite=emo_tanqi size=60 />",
  str_homestory_816701001_44_dialog_content = "這個簡單，只要您去躺椅上睡一覺就行。",
  str_homestory_816701001_45_dialog_content = "好吧……",
  str_homestory_816801001_0_dialog_content = "在做什麼呢？",
  str_homestory_816801001_1_dialog_content = "PlayerName，你來啦！",
  str_homestory_816801001_2_dialog_content = "你把這裡搞得滿不錯嘛。尤其是那邊那個東西......",
  str_homestory_816801001_3_dialog_content = "來回搓一搓，就能放出不一樣的音樂<sprite=emo_yinfu size=60 />欸！",
  str_homestory_816801001_4_dialog_content = "真的嗎？太好了......",
  str_homestory_816801001_5_dialog_content = "我還害怕這個東西占用太多空間。",
  str_homestory_816801001_6_dialog_content = "擔心沒人會喜歡呢。",
  str_homestory_816801001_7_dialog_content = "喜歡！",
  str_homestory_816801001_8_dialog_content = "非常喜歡！",
  str_homestory_816801001_9_dialog_content = "PlayerName，你能教教我怎麼用嗎？",
  str_homestory_816801001_10_dialog_content = "其實我也不太會用這個東西。",
  str_homestory_816801001_11_dialog_content = "那，說明書之類的東西呢？",
  str_homestory_816801001_12_dialog_content = "嘶，好像也沒有......",
  str_homestory_816801001_13_dialog_content = "只能靠自學了嗎？",
  str_homestory_816801001_14_dialog_content = "依靠自己的力量去探索機器的使用方法，感覺更有趣了呢！",
  str_homestory_816801001_15_dialog_content = "想不到虹霞也很喜歡音樂呀。",
  str_homestory_816801001_16_dialog_content = "美好的事物當然惹人喜歡啦，更何況......",
  str_homestory_816801001_17_dialog_content = "如果我能完全掌握這台機器的使用方法，然後用在表演上......",
  str_homestory_816801001_18_dialog_content = "以後一定會有更多人享受馬戲團的開場表演！",
  str_homestory_816801001_19_dialog_content = "虹霞真是無論去哪裡都想著馬戲團的工作啊。",
  str_homestory_816801001_20_dialog_content = "妳一定非常熱愛妳的職業吧？",
  str_homestory_816801001_21_dialog_content = "嗯......其實我從來都沒有考慮過這個問題欸<sprite=emo_wuzui size=60 />。",
  str_homestory_816801001_22_dialog_content = "我只是覺得自己生來就是綠榴石號的守護者。",
  str_homestory_816801001_23_dialog_content = "修理、維護船舶機械，是守護綠榴石號的方式。",
  str_homestory_816801001_24_dialog_content = "用碧海之槍制裁來船上作惡的人，是守護綠榴石號的方式。",
  str_homestory_816801001_25_dialog_content = "在馬戲團演出，讓綠榴石號被更多人看見、喜歡和欣賞......",
  str_homestory_816801001_26_dialog_content = "也是守護綠榴石號的一種方式。",
  str_homestory_816801001_27_dialog_content = "原來是這樣……",
  str_homestory_816801001_28_dialog_content = "「守護」的方式也可以是多種多樣的啊。",
  str_homestory_816801001_29_dialog_content = "PlayerName就把空庭守護得很好呀。",
  str_homestory_816801001_30_dialog_content = "啊......不過你可能要多清理一下河道了。",
  str_homestory_816801001_31_dialog_content = "剛才我去河邊給碧海之槍補充水的時候......",
  str_homestory_816801001_32_dialog_content = "發現河底有個亮閃閃的雜物。",
  str_homestory_816801001_33_dialog_content = "亮閃閃的雜物......？",
  str_homestory_816801001_34_dialog_content = "說到這個，你想要涼快一下嗎？",
  str_homestory_816801001_35_option_content = "想",
  str_homestory_816801001_36_dialog_content = "我剛才忙活了半天，正覺得熱呢。",
  str_homestory_816801001_37_dialog_content = "這個好辦！",
  str_homestory_816801001_38_dialog_content = "準備接招吧～",
  str_homestory_816801001_39_dialog_content = "咦？！",
  str_homestory_816801001_40_option_content = "不想",
  str_homestory_816801001_41_dialog_content = "妳，妳該不會要拿水槍噴我吧？",
  str_homestory_816801001_42_dialog_content = "嘿嘿嘿，不然呢？",
  str_homestory_816801001_43_dialog_content = "真的不用啦。",
  str_homestory_816801001_44_dialog_content = "我去河邊吹吹風<sprite=emo_pugongying size=60 />就好！",
  str_homestory_801602001_0_dialog_content = "卡夫卡？",
  str_homestory_801602001_1_dialog_content = "啊！",
  str_homestory_801602001_2_dialog_content = "嚇我一跳，原來是PlayerName。",
  str_homestory_801602001_3_dialog_content = "不好意思，嚇到妳了......",
  str_homestory_801602001_4_dialog_content = "有什麼事嗎？",
  str_homestory_801602001_5_option_content = "嗯",
  str_homestory_801602001_6_dialog_content = "我只是看妳在這裡站了好久......",
  str_homestory_801602001_7_dialog_content = "害怕妳會中暑。",
  str_homestory_801602001_8_dialog_content = "別擔心，我只是在盯梢。",
  str_homestory_801602001_9_option_content = "沒事",
  str_homestory_801602001_10_dialog_content = "我只是看妳在這裡站了好久......",
  str_homestory_801602001_11_dialog_content = "有點好奇妳在做什麼。",
  str_homestory_801602001_12_dialog_content = "很明顯，我在盯梢。",
  str_homestory_801602001_13_dialog_content = "盯梢？",
  str_homestory_801602001_14_dialog_content = "雖然很感謝卡夫卡，但是空庭很安全......",
  str_homestory_801602001_15_dialog_content = "卡夫卡不用這麼警惕的。",
  str_homestory_801602001_16_dialog_content = "我不是在為空庭盯梢，而是......",
  str_homestory_801602001_17_dialog_content = "為一群小兔子。",
  str_homestory_801602001_18_dialog_content = "小兔子？在哪裡？",
  str_homestory_801602001_19_dialog_content = "我已經讓牠們鑽回洞穴去了。",
  str_homestory_801602001_20_dialog_content = "放心，你永遠都找不到牠們。",
  str_homestory_801602001_21_dialog_content = "把我也當成潛在的壞人了嗎......",
  str_homestory_801602001_22_dialog_content = "說起來，卡夫卡真的很喜歡小動物呢。",
  str_homestory_801602001_23_dialog_content = "咳咳，有......有嗎？",
  str_homestory_801602001_24_dialog_content = "我只是不想看到那些小傢伙們走進牠們不該走進的地方。",
  str_homestory_801602001_25_dialog_content = "忽然覺得卡夫卡有點像牧羊人呢。",
  str_homestory_801602001_26_dialog_content = "帶著一隻大狗<sprite=emo_goutou size=60 />，把動物指引到沒有危險的地方......",
  str_homestory_801602001_27_dialog_content = "什麼牧羊人啊，我不稀罕。",
  str_homestory_801602001_28_dialog_content = "喔，對了，我剛才在河邊看到一個閃光的東西。",
  str_homestory_801602001_29_dialog_content = "你去幫我看看到底是什麼吧？",
  str_homestory_801602001_30_dialog_content = "別讓那東西嚇到這附近的小動物。",
  str_homestory_801602001_31_dialog_content = "好的！",
  str_homestory_817001001_0_dialog_content = "好難得......",
  str_homestory_817001001_1_dialog_content = "什麼人？！",
  str_homestory_817001001_2_dialog_content = "是我，PlayerName......",
  str_homestory_817001001_3_dialog_content = "抱歉，每次聽到忽然停下的腳步聲，我都會警覺起來。",
  str_homestory_817001001_4_dialog_content = "放心啦，空庭裡面很安全的。",
  str_homestory_817001001_5_dialog_content = "嗯，其實我很早就聽聞......",
  str_homestory_817001001_6_dialog_content = "橫空出世的空裔在空谷裡重新建立起一座世外桃源。",
  str_homestory_817001001_7_dialog_content = "要不是親眼所見，我還真是很懷疑這個消息的真實性。",
  str_homestory_817001001_8_dialog_content = "想不到你小小年紀，就有這樣出色的治理能力。",
  str_homestory_817001001_9_option_content = "（承認）",
  str_homestory_817001001_10_dialog_content = "嘿嘿，謝謝誇獎。",
  str_homestory_817001001_11_dialog_content = "你還真不謙虛。",
  str_homestory_817001001_12_dialog_content = "不過，我倒是喜歡你這種初出茅廬不怕虎的勁頭。",
  str_homestory_817001001_13_option_content = "（否認）",
  str_homestory_817001001_14_dialog_content = "其實我的朋友們也幫了我很多忙。",
  str_homestory_817001001_15_dialog_content = "哦，是嗎？",
  str_homestory_817001001_16_dialog_content = "像你這樣謙虛的孩子已經很少見了。",
  str_homestory_817001001_17_dialog_content = "也難怪空庭能長久地維持著這份平靜。",
  str_homestory_817001001_18_dialog_content = "沒有暗鬼滋擾，也沒有幫派盤亙。",
  str_homestory_817001001_19_dialog_content = "回想起來，能夠這樣安心自在地享受陽光傾灑在眼皮上的日子......",
  str_homestory_817001001_20_dialog_content = "仿佛還是在上輩子。",
  str_homestory_817001001_21_dialog_content = "所以說，珀拉珂可以試著放鬆一下嘛。",
  str_homestory_817001001_22_dialog_content = "放鬆嗎？",
  str_homestory_817001001_23_dialog_content = "我好像還是第一次意識到......",
  str_homestory_817001001_24_dialog_content = "保持警覺，對我來說已經成為了像呼吸一樣自然的行為。",
  str_homestory_817001001_25_dialog_content = "雖然已經離開了尤佛里亞......",
  str_homestory_817001001_26_dialog_content = "但是身體卻還保持著在那裡養成的習慣。",
  str_homestory_817001001_27_dialog_content = "在瞭望台眺望周圍的人、事、物......",
  str_homestory_817001001_28_dialog_content = "也是來自尤佛里亞的習慣嗎？",
  str_homestory_817001001_29_dialog_content = "觀察客人的一舉一動也是東道主的禮儀嗎？",
  str_homestory_817001001_30_dialog_content = "呵，你還真是沒辦法讓人輕視呢。",
  str_homestory_817001001_31_dialog_content = "啊......千萬別誤會。",
  str_homestory_817001001_32_dialog_content = "我是偶然路過，才看到妳在瞭望台上的。",
  str_homestory_817001001_33_dialog_content = "哈哈哈，別緊張。我也不是什麼不守規矩的客人。",
  str_homestory_817001001_34_dialog_content = "我喜歡站在高處，眺望尤佛里亞正在發生的一切。",
  str_homestory_817001001_35_dialog_content = "通常你會看到......",
  str_homestory_817001001_36_dialog_content = "陰沉厚重的雨雲之下，各種各樣的欲望都在肆意生長。",
  str_homestory_817001001_37_dialog_content = "但在這裡不同。",
  str_homestory_817001001_38_dialog_content = "目之所及，寧靜悠遠，一派祥和。",
  str_homestory_817001001_39_dialog_content = "PlayerName，我有一個請求。",
  str_homestory_817001001_40_dialog_content = "不用這麼客氣，有什麼需要儘管告訴我。",
  str_homestory_817001001_41_dialog_content = "下次我可以帶著教堂的孩子們一起過來嗎？",
  str_homestory_817001001_42_dialog_content = "當然沒問題！",
  str_homestory_817001001_43_dialog_content = "哦對了......",
  str_homestory_817001001_44_dialog_content = "我在河邊看到一個東西，也許你會感興趣。",
  str_homestory_817001001_45_dialog_content = "現在過去找，應該還能找到。",
  str_homestory_817001001_46_dialog_content = "欸？我......我這就去看看！",
  str_homestory_817101001_0_dialog_content = "卡斯特？",
  str_homestory_817101001_1_dialog_content = "哦，是你啊。",
  str_homestory_817101001_2_dialog_content = "最近在空庭住得還習慣嗎？",
  str_homestory_817101001_3_dialog_content = "不習慣。",
  str_homestory_817101001_4_dialog_content = "啊？卡斯特對哪裡不滿意呢？",
  str_homestory_817101001_5_dialog_content = "我會好好整改的！",
  str_homestory_817101001_6_dialog_content = "你這個地方......",
  str_homestory_817101001_7_dialog_content = "沒有化不開的濃霧。",
  str_homestory_817101001_8_dialog_content = "陽光讓我的眼睛感到乾澀。",
  str_homestory_817101001_9_dialog_content = "沒有來找茬的混混。",
  str_homestory_817101001_10_dialog_content = "和平讓我的四肢感到乏力。",
  str_homestory_817101001_11_dialog_content = "要是再這樣下去，我射擊的準頭都要下降了<sprite=emo_daomei size=60 />。",
  str_homestory_817101001_12_option_content = "（道歉）",
  str_homestory_817101001_13_dialog_content = "對，對不起！",
  str_homestory_817101001_14_dialog_content = "空庭的生活是不是太無聊了？",
  str_homestory_817101001_15_option_content = "（無奈）",
  str_homestory_817101001_16_dialog_content = "可是......",
  str_homestory_817101001_17_dialog_content = "這些地方沒辦法整改......",
  str_homestory_817101001_18_dialog_content = "你聽不出來我是在誇你嗎？",
  str_homestory_817101001_19_dialog_content = "欸？",
  str_homestory_817101001_20_dialog_content = "是我自己過慣了陰溝裡的生活。",
  str_homestory_817101001_21_dialog_content = "來到這種安逸的地方，反而變得不習慣了。",
  str_homestory_817101001_22_dialog_content = "想想也真是可笑啊。",
  str_homestory_817101001_23_dialog_content = "其實空庭裡也有很多很有趣的事可以做的！",
  str_homestory_817101001_24_dialog_content = "嗯，我也是剛發現。",
  str_homestory_817101001_25_dialog_content = "這個看板很有趣，使用這種配色和圖案的......",
  str_homestory_817101001_26_dialog_content = "一定是賭場的廣告吧！",
  str_homestory_817101001_27_dialog_content = "......",
  str_homestory_817101001_28_dialog_content = "幹嘛露出這副表情<sprite=emo_baiyan size=60 />？",
  str_homestory_817101001_29_dialog_content = "我只是想給教堂的孩子們贏點紀念品回去......",
  str_homestory_817101001_30_dialog_content = "不會把你的空庭給贏垮了的。",
  str_homestory_817101001_31_dialog_content = "這，這其實只是一副裝飾畫而已。",
  str_homestory_817101001_32_dialog_content = "空庭裡沒有賭場的......",
  str_homestory_817101001_33_dialog_content = "哈？",
  str_homestory_817101001_34_dialog_content = "比起這個，卡斯特可以試試釣魚啊！",
  str_homestory_817101001_35_dialog_content = "釣魚？",
  str_homestory_817101001_36_dialog_content = "拋下魚鉤，靜靜等待魚兒上鉤。",
  str_homestory_817101001_37_dialog_content = "這項活動很考驗一個人的運氣的！",
  str_homestory_817101001_38_dialog_content = "既然是考驗運氣的活動，那我肯定不會錯過這項活動囉。",
  str_homestory_817101001_39_dialog_content = "啊，差點忘了......",
  str_homestory_817101001_40_dialog_content = "卡斯特是「幸運女神的寵兒」<sprite=emo_dianzan size=60 />！",
  str_homestory_817101001_41_dialog_content = "河裡的魚今天要遭殃了......",
  str_homestory_813001001_0_dialog_content = "很好看吧？",
  str_homestory_813001001_1_dialog_content = "呃？",
  str_homestory_813001001_2_dialog_content = "咳咳......",
  str_homestory_813001001_3_dialog_content = "原來是PlayerName。",
  str_homestory_813001001_4_dialog_content = "下次打招呼記得小點聲，你這樣是會嚇到別人的。",
  str_homestory_813001001_5_dialog_content = "可別怪我沒提醒過你啊。",
  str_homestory_813001001_6_dialog_content = "要是把別人嚇出什麼心臟病來......",
  str_homestory_813001001_7_dialog_content = "你可能要被判處終身監禁！",
  str_homestory_813001001_8_dialog_content = "多，多謝提醒......",
  str_homestory_813001001_9_dialog_content = "嗯，知道就好。哦對了，你找我有事？",
  str_homestory_813001001_10_dialog_content = "是空庭裡需要什麼案件要我去審判嗎？",
  str_homestory_813001001_11_dialog_content = "啊......沒有沒有。",
  str_homestory_813001001_12_dialog_content = "我只是看到你在這雕像前若有所思，還來回比劃......",
  str_homestory_813001001_13_dialog_content = "有點好奇而已。",
  str_homestory_813001001_14_dialog_content = "我，我哪裡有來回比劃？！",
  str_homestory_813001001_15_dialog_content = "朗朗乾坤之下，切不可隨意造謠。",
  str_homestory_813001001_16_dialog_content = "按照《白夜城名譽法》規定，隨意捏造謠言的被告......",
  str_homestory_813001001_17_dialog_content = "將被監禁一百日，或被處一百萬白夜幣的罰款。",
  str_homestory_813001001_18_dialog_content = "欸？",
  str_homestory_813001001_19_option_content = "（反駁）",
  str_homestory_813001001_20_dialog_content = "可這裡是空庭，不是白夜城呀？",
  str_homestory_813001001_21_dialog_content = "你......你你你，豈有此理！",
  str_homestory_813001001_22_dialog_content = "你怎麼能容許空庭沒有法律呢？",
  str_homestory_813001001_23_option_content = "（附和）",
  str_homestory_813001001_24_dialog_content = "啊，那可能是我剛才看錯了吧......",
  str_homestory_813001001_25_dialog_content = "PlayerName，看來你要多加提升自己的修養啊。",
  str_homestory_813001001_26_dialog_content = "要不然看到什麼都是骯髒的。",
  str_homestory_813001001_27_dialog_content = "長此以往，空庭是要完蛋的呀！",
  str_homestory_813001001_28_dialog_content = "嗯......",
  str_homestory_813001001_29_dialog_content = "不如......",
  str_homestory_813001001_30_dialog_content = "這樣吧！你把這個雕像給我。",
  str_homestory_813001001_31_dialog_content = "我們剛才發生的這些恩怨就可以一筆勾銷。",
  str_homestory_813001001_32_dialog_content = "啊？可是......",
  str_homestory_813001001_33_dialog_content = "這個雕像對我來說很重要。",
  str_homestory_813001001_34_dialog_content = "它所雕刻的是某位空裔祖先，對我來說很重要的。",
  str_homestory_813001001_35_dialog_content = "法外之地，果然不可理喻。",
  str_homestory_813001001_36_dialog_content = "如果你真的很喜歡這尊雕像......",
  str_homestory_813001001_37_dialog_content = "我可以用泥巴幫你重新做一個。",
  str_homestory_813001001_38_dialog_content = "這樣......",
  str_homestory_813001001_39_dialog_content = "也不是不行<sprite=emo_woshou size=60 />。",
  str_homestory_813001001_40_dialog_content = "咳咳，別讓我等太久啊。",
  str_homestory_812101001_0_dialog_content = "普律瑪？",
  str_homestory_812101001_1_dialog_content = "哦？是你？",
  str_homestory_812101001_2_dialog_content = "對不起......",
  str_homestory_812101001_3_dialog_content = "我是不是把妳吵醒了？",
  str_homestory_812101001_4_dialog_content = "你知道的，跟我說話不用帶上那些虛情假意的關心。",
  str_homestory_812101001_5_dialog_content = "直說就好。",
  str_homestory_812101001_6_dialog_content = "你是不是想來問我對空庭的滿意度？",
  str_homestory_812101001_7_option_content = "（否認）",
  str_homestory_812101001_8_dialog_content = "也沒有啦......",
  str_homestory_812101001_9_dialog_content = "只是想和妳打個招呼而已。",
  str_homestory_812101001_10_option_content = "（承認）",
  str_homestory_812101001_11_dialog_content = "被妳說中了......",
  str_homestory_812101001_12_dialog_content = "我的確很在意普律瑪的評價。",
  str_homestory_812101001_13_dialog_content = "其實不管你承不承認，我都要說......",
  str_homestory_812101001_14_dialog_content = "......",
  str_homestory_812101001_15_dialog_content = "我不討厭這個地方。",
  str_homestory_812101001_16_dialog_content = "太好了！",
  str_homestory_812101001_17_dialog_content = "還以為普律瑪又要發表什麼批判意見呢......",
  str_homestory_812101001_18_dialog_content = "嗯？你說什麼？",
  str_homestory_812101001_19_dialog_content = "哦，我是說......",
  str_homestory_812101001_20_dialog_content = "還期待普律瑪能發表什麼建設性的意見呢！",
  str_homestory_812101001_21_dialog_content = "意見嗎，也不是沒有。",
  str_homestory_812101001_22_dialog_content = "既然你這麼擅長開發、建設、管理......",
  str_homestory_812101001_23_dialog_content = "有沒有興趣把白夜城的那些貴族給趕走，接管碧空島呢？",
  str_homestory_812101001_24_dialog_content = "欸？！",
  str_homestory_812101001_25_dialog_content = "這種事情，我從來都沒有想過。",
  str_homestory_812101001_26_dialog_content = "嘴上說著「沒興趣」，暗地裡卻在大搞文章的人......",
  str_homestory_812101001_27_dialog_content = "我都數不清見過多少了。",
  str_homestory_812101001_28_dialog_content = "我......我只想守護自己的家園。",
  str_homestory_812101001_29_dialog_content = "白夜城的人們也一定和我一樣，想要守護自己的家園吧？",
  str_homestory_812101001_30_dialog_content = "家園？",
  str_homestory_812101001_31_dialog_content = "我不就是被趕出家園的人嗎。",
  str_homestory_812101001_32_dialog_content = "對我而言，家園早就是一個沒有實際含義的空虛詞彙。",
  str_homestory_812101001_33_dialog_content = "普律瑪......別忘了，妳還有空庭啊。",
  str_homestory_812101001_34_dialog_content = "如果可以的話......",
  str_homestory_812101001_35_dialog_content = "妳完全可以把空庭當作自己的家園！",
  str_homestory_812101001_36_dialog_content = "哦？難道你不會覺得領地被別人佔有了？",
  str_homestory_812101001_37_dialog_content = "空庭能有今天，離不開各位朋友的幫助......",
  str_homestory_812101001_38_dialog_content = "所以，我希望空庭也可以成為大家的避風港。",
  str_homestory_812101001_39_dialog_content = "空裔啊空裔，果真是名不虛傳的「傻」呢。<sprite=emo_baiyan size=60 />",
  str_homestory_812101001_40_dialog_content = "也許......",
  str_homestory_812101001_41_dialog_content = "我也可以試著在我的詞典裡，給「家園」增添一條解釋。",
  str_homestory_812101001_42_dialog_content = "什麼解釋啊？",
  str_homestory_812101001_43_dialog_content = "......空庭。",
  str_homestory_812001001_0_dialog_content = "海蒂在這裡？",
  str_homestory_812001001_1_dialog_content = "啊......",
  str_homestory_812001001_2_dialog_content = "海蒂，發生什麼了？",
  str_homestory_812001001_3_dialog_content = "白夜至上......",
  str_homestory_812001001_4_dialog_content = "那台機器看見我之後，一直在發出充滿惡意的低吼！",
  str_homestory_812001001_5_dialog_content = "PlayerName，告訴我這是不是邪惡的舊時代產物？",
  str_homestory_812001001_6_dialog_content = "再這樣下去......",
  str_homestory_812001001_7_dialog_content = "我不得不召喚「明光騎士」來幫我銷毀它了<sprite=emo_shengqi size=60 />。",
  str_homestory_812001001_8_option_content = "（安慰）",
  str_homestory_812001001_9_dialog_content = "海蒂，不用擔心。",
  str_homestory_812001001_10_dialog_content = "這只是一台自動冰淇淋機而已。",
  str_homestory_812001001_11_option_content = "（道歉）",
  str_homestory_812001001_12_dialog_content = "抱歉，我忘記向妳介紹了。",
  str_homestory_812001001_13_dialog_content = "這是一台自動冰淇淋機！",
  str_homestory_812001001_14_dialog_content = "自動......冰淇淋機？<sprite=emo_wuzui size=60 />",
  str_homestory_812001001_15_dialog_content = "嗯，只要把杯子放在上面，按下按鈕......",
  str_homestory_812001001_16_dialog_content = "機器就會自動產出美味的冰淇淋。",
  str_homestory_812001001_17_dialog_content = "其......其實我看到機器上的雪花圖案就猜到了它是冰淇淋機。",
  str_homestory_812001001_18_dialog_content = "但是冰淇淋卻一直沒有出來......",
  str_homestory_812001001_19_dialog_content = "所以我才很擔心這是不是一台披著冰淇淋機外衣的邪惡科技造物。",
  str_homestory_812001001_20_dialog_content = "嗯？冰淇淋又被吃光了嗎......？",
  str_homestory_812001001_21_dialog_content = "吃光了？",
  str_homestory_812001001_22_dialog_content = "因為這台機器做的冰淇淋實在太好吃了......",
  str_homestory_812001001_23_dialog_content = "所以如果不早點來排隊，就會搶不到。",
  str_homestory_812001001_24_dialog_content = "本來以為這幾天天氣稍微冷了一些，吃冰淇淋的人會少一點的。",
  str_homestory_812001001_25_dialog_content = "沒想到還是這麼火爆啊。",
  str_homestory_812001001_26_dialog_content = "海蒂，妳喜歡什麼口味？",
  str_homestory_812001001_27_dialog_content = "我去再買點原料回來。",
  str_homestory_812001001_28_dialog_content = "冰淇淋的口味......",
  str_homestory_812001001_29_dialog_content = "咳，你喜歡什麼口味呢？",
  str_homestory_812001001_30_dialog_content = "奶油香草、巧克力、抹茶、香橙、紅豆等等等等......",
  str_homestory_812001001_31_dialog_content = "這些我都喜歡！",
  str_homestory_812001001_32_dialog_content = "原來有這麼多種口味嗎......",
  str_homestory_812001001_33_dialog_content = "海蒂，妳沒有吃過冰淇淋嗎？這些都是最基本的口味......",
  str_homestory_812001001_34_dialog_content = "你......你在說什麼？",
  str_homestory_812001001_35_dialog_content = "冰淇淋這種東西，我當然吃過！",
  str_homestory_812001001_36_dialog_content = "我只是覺得你說的口味都太一般了。",
  str_homestory_812001001_37_dialog_content = "我以前只吃「古書」口味的冰淇淋。",
  str_homestory_812001001_38_dialog_content = "不過，這台機器可能做不出來吧。<sprite=emo_emo size=60 />",
  str_homestory_812001001_39_dialog_content = "「古書」口味的冰淇淋？！",
  str_homestory_812001001_40_dialog_content = "我還真的沒有吃過欸。",
  str_homestory_812001001_41_dialog_content = "但我會試著找找這種口味的配方的！",
  str_homestory_812001001_42_dialog_content = "啊，不用麻煩了......",
  str_homestory_812001001_43_dialog_content = "怎麼了？",
  str_homestory_812001001_44_dialog_content = "偶爾也想試試......",
  str_homestory_812001001_45_dialog_content = "奶油香草、巧克力、抹茶、香橙、紅豆冰淇淋是什麼滋味。",
  str_homestory_806801001_0_dialog_content = "溫蒂？",
  str_homestory_806801001_1_dialog_content = "妳要準備去做什麼呀？",
  str_homestory_806801001_2_dialog_content = "原來是PlayerName啊。",
  str_homestory_806801001_3_dialog_content = "我正準備找個地方練習一下垂直飛行呢。",
  str_homestory_806801001_4_dialog_content = "垂直飛行？",
  str_homestory_806801001_5_dialog_content = "對呀，就是直直地飛上去，再直直地飛下來。",
  str_homestory_806801001_6_dialog_content = "這非常考驗飛行的技術呢。",
  str_homestory_806801001_7_dialog_content = "其實平時看妳飛得那麼高，我總害怕妳會摔下來。",
  str_homestory_806801001_8_dialog_content = "哦呀？竟然在擔心這個？",
  str_homestory_806801001_9_dialog_content = "放心，那種高度對我來說都是小意思啦。",
  str_homestory_806801001_10_dialog_content = "難道你忘了，我可是荒漠颶風小導彈<sprite=emo_mojing size=60 />！",
  str_homestory_806801001_11_option_content = "忘了",
  str_homestory_806801001_12_dialog_content = "那我就再重複一遍！",
  str_homestory_806801001_13_option_content = "沒忘",
  str_homestory_806801001_14_dialog_content = "這麼重要的設定我怎麼會忘呢？",
  str_homestory_806801001_15_dialog_content = "以防萬一我還是要重複一遍！",
  str_homestory_806801001_16_dialog_content = "溫蒂是荒漠颶風小導彈～",
  str_homestory_806801001_17_dialog_content = "速度是我的標籤，勇猛是我的代名詞！",
  str_homestory_806801001_18_dialog_content = "好好好，知道啦。",
  str_homestory_806801001_19_dialog_content = "不過，妳為什麼要練習垂直飛行呢？",
  str_homestory_806801001_20_dialog_content = "我當然是為了送信啦！",
  str_homestory_806801001_21_dialog_content = "送信？",
  str_homestory_806801001_22_dialog_content = "PlayerName有沒有見過那些長著長長觸手的傢伙？",
  str_homestory_806801001_23_dialog_content = "妳說的難道是浮游水母氣球嗎？",
  str_homestory_806801001_24_dialog_content = "管他是不是氣球呢。",
  str_homestory_806801001_25_dialog_content = "只要是客戶讓我送的信，我就一定要送到！",
  str_homestory_806801001_26_dialog_content = "欸，PlayerName認識那種氣球嗎？",
  str_homestory_806801001_27_dialog_content = "我知道那種家具，這應該算得上是......認識吧？",
  str_homestory_806801001_28_dialog_content = "那個氣球的名字是不是「克萊肯」？",
  str_homestory_806801001_29_dialog_content = "呃，如果妳的收件人是「克萊肯」......",
  str_homestory_806801001_30_dialog_content = "我想妳應該是找錯了，克萊肯他不是一隻氣球。",
  str_homestory_806801001_31_dialog_content = "欸？！真的嗎？",
  str_homestory_806801001_32_dialog_content = "我聽寄件人說克萊肯身上有好多長長的滑溜溜的觸手。",
  str_homestory_806801001_33_dialog_content = "頭上經常帶著一頂黑色的禮帽。",
  str_homestory_806801001_34_dialog_content = "那種氣球頭上有沒有帽子呢。",
  str_homestory_806801001_35_dialog_content = "總之浮游水母氣球不是妳的收件人啦。",
  str_homestory_806801001_36_dialog_content = "啊......這封信就要打破我「最長時間沒送到」的記錄了。",
  str_homestory_806801001_37_dialog_content = "不說了，不說了。",
  str_homestory_806801001_38_dialog_content = "雖然我剛才在空中發現河邊有什麼東西在閃光，很想去看看......",
  str_homestory_806801001_39_dialog_content = "但我要繼續送信啦！<sprite=emo_dianzan size=60 />",
  str_homestory_817201001_0_dialog_content = "欸，莉莉卡......",
  str_homestory_817201001_1_dialog_content = "PlayerName，你快來看！",
  str_homestory_817201001_2_dialog_content = "怎麼了？",
  str_homestory_817201001_3_dialog_content = "這個玩具好好玩呀！",
  str_homestory_817201001_4_dialog_content = "用球棒敲一敲、打一打，就會從裡面蹦出來好多彩條！<sprite=emo_caitiao size=60 />",
  str_homestory_817201001_5_dialog_content = "有時候還會有糖果蹦出來！",
  str_homestory_817201001_6_dialog_content = "我還是第一次見到這種樣子的玩具呢。",
  str_homestory_817201001_7_dialog_content = "那當然了，彩偶是空谷才有的傳統裝飾品。",
  str_homestory_817201001_8_dialog_content = "在別的地方可見不到。",
  str_homestory_817201001_9_dialog_content = "彩偶？空谷的傳統裝飾品......",
  str_homestory_817201001_10_dialog_content = "你這麼一說，我好像有點印象！",
  str_homestory_817201001_11_dialog_content = "過節之前把種子塞進一個陶罐裡......",
  str_homestory_817201001_12_dialog_content = "然後過節的時候「啪」地一聲把它砸開......",
  str_homestory_817201001_13_dialog_content = "這樣就能獲得來自大自然的祝福！",
  str_homestory_817201001_14_dialog_content = "對不對？",
  str_homestory_817201001_15_dialog_content = "欸，莉莉卡，我沒想到妳竟然對空谷有這麼多的瞭解？",
  str_homestory_817201001_16_dialog_content = "嘿嘿嘿，也不算是瞭解啦。",
  str_homestory_817201001_17_dialog_content = "以前拍過一個電影，讓我演一名歷史老師。",
  str_homestory_817201001_18_dialog_content = "雖然沒有什麼特寫鏡頭，但是我必須要一直在背景裡講課。",
  str_homestory_817201001_19_dialog_content = "當時給我的台詞，恰好就是空谷傳統裝飾品的解說呢！",
  str_homestory_817201001_20_dialog_content = "欸，竟然還有這種電影？",
  str_homestory_817201001_21_dialog_content = "電影叫什麼名字啊？",
  str_homestory_817201001_22_dialog_content = "咳咳，我說的台詞真的只是背景音而已啦。",
  str_homestory_817201001_23_dialog_content = "電影裡根本聽不清我在說什麼......",
  str_homestory_817201001_24_option_content = "（失落）",
  str_homestory_817201001_25_dialog_content = "好吧……",
  str_homestory_817201001_26_dialog_content = "還以為能看到關於空谷的電影呢。",
  str_homestory_817201001_27_dialog_content = "振作起來，PlayerName，難道你忘了我是幹什麼的啦？",
  str_homestory_817201001_28_option_content = "（激動）",
  str_homestory_817201001_29_dialog_content = "就算是背景音也好，空谷還能出現在電影的鏡頭當中......",
  str_homestory_817201001_30_dialog_content = "這件事已經讓我很感動了！",
  str_homestory_817201001_31_dialog_content = "咳咳，不至於吧......PlayerName，別忘了我是幹什麼的喔！",
  str_homestory_817201001_32_dialog_content = "我可是新晉的青年導演喔！",
  str_homestory_817201001_33_dialog_content = "不如......",
  str_homestory_817201001_34_dialog_content = "就讓我來拍一部關於空谷的電影吧？",
  str_homestory_817201001_35_dialog_content = "欸，可以嗎？",
  str_homestory_817201001_36_dialog_content = "當然沒問題！",
  str_homestory_817201001_37_dialog_content = "莉莉卡已經有什麼拍攝的想法了嗎？",
  str_homestory_817201001_38_dialog_content = "唔......讓我想想。<sprite=emo_sikao size=60 />",
  str_homestory_817201001_39_dialog_content = "嗯，有了！",
  str_homestory_817201001_40_dialog_content = "就拍一部莉莉卡在空谷跳舞的電影吧！",
  str_homestory_817201001_41_dialog_content = "欸？",
  str_homestory_817201001_42_dialog_content = "這也算是......關於空谷的電影嗎？",
  str_homestory_817201001_43_dialog_content = "不算嗎？",
  str_homestory_817201001_44_dialog_content = "真是傷腦筋呢。",
  str_homestory_817201001_45_dialog_content = "要不然就拍一部PlayerName在空谷跳舞的電影吧？",
  str_homestory_817201001_46_dialog_content = "應該沒有人想看吧......",
  str_homestory_817301001_0_dialog_content = "米洛斯......",
  str_homestory_817301001_1_dialog_content = "PlayerName，日安<sprite=emo_mojing size=60 />。",
  str_homestory_817301001_2_dialog_content = "米洛斯，你好啊。",
  str_homestory_817301001_3_dialog_content = "PlayerName有什麼吩咐嗎？",
  str_homestory_817301001_4_option_content = "（肯定）",
  str_homestory_817301001_5_dialog_content = "呃......的確有件事情想拜託米洛斯呢。",
  str_homestory_817301001_6_dialog_content = "您請講。",
  str_homestory_817301001_7_dialog_content = "希望米洛斯可以在空庭裡放鬆一下......",
  str_homestory_817301001_8_dialog_content = "不用一直對我這麼畢恭畢敬的。",
  str_homestory_817301001_9_option_content = "（否定）",
  str_homestory_817301001_10_dialog_content = "沒、沒有啊……",
  str_homestory_817301001_11_dialog_content = "米洛斯在空庭的時候，我幾乎什麼都不用操心。",
  str_homestory_817301001_12_dialog_content = "不過我還是希望，米洛斯可以放鬆一下自己。",
  str_homestory_817301001_13_dialog_content = "再怎麼說，你可是我請來空庭做客的客人。",
  str_homestory_817301001_14_dialog_content = "嗯，您說得有道理。",
  str_homestory_817301001_15_dialog_content = "作為客人，我的確不應該喧賓奪主，剝奪主人招待客人的樂趣。",
  str_homestory_817301001_16_dialog_content = "您的吩咐我已經記下了。",
  str_homestory_817301001_17_dialog_content = "接下來，我會要求自己成為您的完美客人。",
  str_homestory_817301001_18_dialog_content = "其實，不「完美」也沒關係的。",
  str_homestory_817301001_19_dialog_content = "「不完美的客人」嗎？",
  str_homestory_817301001_20_dialog_content = "這聽起來是個難題。",
  str_homestory_817301001_21_dialog_content = "欸嘿嘿，這不是什麼需要思考的問題。比起這個......",
  str_homestory_817301001_22_dialog_content = "我剛才看見你一抬手，這些蠟燭就亮了。",
  str_homestory_817301001_23_dialog_content = "好神奇啊，米洛斯是怎麼做到的？",
  str_homestory_817301001_24_dialog_content = "您觀察得很仔細。",
  str_homestory_817301001_25_dialog_content = "我剛剛是在調教這些蠟燭，您過來的時候我正好調教完畢。",
  str_homestory_817301001_26_dialog_content = "調教......蠟燭？",
  str_homestory_817301001_27_dialog_content = "是的，只有工作過多年的老管家才會知道......",
  str_homestory_817301001_28_dialog_content = "不管是多麼貴重的家具，還是多麼精巧的擺件......",
  str_homestory_817301001_29_dialog_content = "都需要一些有技巧的調教，才能讓它們更好地與環境融為一體。",
  str_homestory_817301001_30_dialog_content = "就比如這件蠟燭擺件。",
  str_homestory_817301001_31_dialog_content = "蠟燭的內部安裝有自動點燃、自動熄滅的功能。",
  str_homestory_817301001_32_dialog_content = "如果放任不管，這些蠟燭就會隨意點燃與熄滅，毫無章法。",
  str_homestory_817301001_33_dialog_content = "不過請您放心，現在您只需要依照順序走到蠟燭面前。",
  str_homestory_817301001_34_dialog_content = "它們就會乖巧地依次點燃。",
  str_homestory_817301001_35_dialog_content = "好......好厲害。",
  str_homestory_817301001_36_dialog_content = "啊，抱歉......",
  str_homestory_817301001_37_dialog_content = "調教家具這件事，似乎不是我作為客人應該做的事。",
  str_homestory_817301001_38_dialog_content = "沒關係啦。",
  str_homestory_817301001_39_dialog_content = "要不是米洛斯，我都不知道這個蠟燭擺件還能這麼玩！",
  str_homestory_817301001_40_dialog_content = "感謝您能原諒我的過失。",
  str_homestory_817301001_41_dialog_content = "不過多虧了這個小小的失誤......",
  str_homestory_817301001_42_dialog_content = "我完美地成為了一個「不完美的客人」。",
  str_homestory_817301001_43_dialog_content = "希望您能滿意我的表現<sprite=emo_baimao size=60 />，PlayerName。",
  str_homestory_815901001_0_dialog_content = "喔，塞提！",
  str_homestory_815901001_1_dialog_content = "是你啊，難道是有委託找我？",
  str_homestory_815901001_2_dialog_content = "不是啦，我是被剛才那段音樂<sprite=emo_yinfu size=60 />吸引來的。",
  str_homestory_815901001_3_dialog_content = "那充滿韻律感的節奏和令人興奮的鼓點......",
  str_homestory_815901001_4_dialog_content = "讓我忍不住想要跟著音樂躍動起來了！",
  str_homestory_815901001_5_dialog_content = "看來你是被嘻哈音樂的魅力所感染了。",
  str_homestory_815901001_6_dialog_content = "不過這是正常的，沒有人會不喜歡嘻哈音樂。",
  str_homestory_815901001_7_dialog_content = "原來這就是嘻哈音樂啊。",
  str_homestory_815901001_8_dialog_content = "PlayerName，難道你以前從沒聽過嘻哈音樂嗎？",
  str_homestory_815901001_9_option_content = "（肯定）",
  str_homestory_815901001_10_dialog_content = "我很少專門去聽嘻哈音樂，我的確缺少對它的瞭解。",
  str_homestory_815901001_11_option_content = "（否定）",
  str_homestory_815901001_12_dialog_content = "沒有那回事，我對每個種類的音樂都很感興趣。",
  str_homestory_815901001_13_dialog_content = "不過我之前只聽過妳的說唱表演。",
  str_homestory_815901001_14_dialog_content = "關於嘻哈音樂旋律的瞭解就比較少了。",
  str_homestory_815901001_15_dialog_content = "所以沒能聽出妳演奏的是嘻哈音樂。",
  str_homestory_815901001_16_dialog_content = "那還真是可惜，我剛來空庭的時候就覺得這裡少了點什麼。",
  str_homestory_815901001_17_dialog_content = "看到這台鼓我才想起來，這裡沒有嘻哈音樂！",
  str_homestory_815901001_18_dialog_content = "沒想到僅用鼓也能演奏出那樣動感的音樂......",
  str_homestory_815901001_19_dialog_content = "看來PlayerName已經完全沉迷其中了......",
  str_homestory_815901001_20_dialog_content = "既然這樣，作為俠盜的我就不得不「出手」了。",
  str_homestory_815901001_21_dialog_content = "出手？",
  str_homestory_815901001_22_dialog_content = "沒錯，我要把演奏這台鼓的方法教給你。",
  str_homestory_815901001_23_dialog_content = "這樣你就可以隨時隨地聽到嘻哈音樂了。",
  str_homestory_815901001_24_dialog_content = "咦？等等，如果我教會了你的話......",
  str_homestory_815901001_25_dialog_content = "那所有來空庭的人不就都可以聽到你演奏的嘻哈音樂了？！",
  str_homestory_815901001_26_dialog_content = "沒想到嘻哈音樂風靡艾斯特拉竟然是由我做到的......",
  str_homestory_815901001_27_dialog_content = "塞......塞提，打斷妳的暢想我很抱歉......",
  str_homestory_815901001_28_dialog_content = "但不論是鼓還是嘻哈音樂，我都是初學者。",
  str_homestory_815901001_29_dialog_content = "想要教會我的話，應該不簡單吧。",
  str_homestory_815901001_30_dialog_content = "不需要擔心這種事，興趣是最好的老師<sprite=emo_dianzan size=60 />。",
  str_homestory_815901001_31_dialog_content = "嘻哈音樂最重要的組成部分就是鼓點和旋律。",
  str_homestory_815901001_32_dialog_content = "只要鼓點有規律，音樂就會有旋律。",
  str_homestory_815901001_33_dialog_content = "把自己當作鼓槌，根據心中的節奏盡情地跳動。",
  str_homestory_815901001_34_dialog_content = "自在隨心，這就是最純粹的嘻哈音樂！",
  str_homestory_815901001_35_dialog_content = "只要跟隨自己的內心，就可以像妳一樣演奏出嘻哈音樂嗎？",
  str_homestory_815901001_36_dialog_content = "當然！不如你現在就試試看？",
  str_homestory_815901001_37_dialog_content = "只要連續不停地讓鼓發出鼓點，就可以組成流暢的音樂！",
  str_homestory_815901001_38_dialog_content = "連......連續不停嗎......",
  str_homestory_815901001_39_dialog_content = "你難道不想讓更多人感受到嘻哈音樂的魅力了嗎？",
  str_homestory_815901001_40_dialog_content = "當然想，只是我現在沒什麼力氣了。",
  str_homestory_815901001_41_dialog_content = "看來，PlayerName距離成為一名真正的嘻哈音樂者還很遠啊。",
  str_homestory_815901001_42_dialog_content = "那今天就到此為止吧。",
  str_homestory_815901001_43_dialog_content = "謝......謝謝妳......",
  str_homestory_807901001_0_dialog_content = "米潔妮......",
  str_homestory_807901001_1_dialog_content = "米潔妮？",
  str_homestory_807901001_2_dialog_content = "PlayerName，您來了。",
  str_homestory_807901001_3_dialog_content = "哈哈，妳在欣賞這個裝飾物嗎？",
  str_homestory_807901001_4_dialog_content = "作為一名理性的稅務官，「欣賞」這個行為對我來說太過於感性。",
  str_homestory_807901001_5_dialog_content = "我只是在衡量這個物品的價值而已。",
  str_homestory_807901001_6_dialog_content = "啊......這裡不是白夜城，米潔妮偶爾也可以放鬆一下嘛<sprite=emo_sikao size=60 />。",
  str_homestory_807901001_7_dialog_content = "鍛鍊出理性的思維，可沒有那麼容易。",
  str_homestory_807901001_8_dialog_content = "要成為稅法方面的頂尖學者，更是難上加難。",
  str_homestory_807901001_9_dialog_content = "我不想因為一時的懈怠，就浪費之前所經歷過的學術訓練。",
  str_homestory_807901001_10_dialog_content = "而且我閑著也是閑著，可以順手幫你分擔一些空庭的稅務工作。",
  str_homestory_807901001_11_dialog_content = "空庭似乎還不需要進行這樣的工作呢......",
  str_homestory_807901001_12_dialog_content = "您的語氣柔和，距離「態度堅定」還有10個白夜幣<sprite=emo_baiyebi size=60 />的距離。",
  str_homestory_807901001_13_dialog_content = "看樣子，我被您拒絕了。",
  str_homestory_807901001_14_option_content = "（承認）",
  str_homestory_807901001_15_dialog_content = "我也不忍心拒絕妳......但空庭真的請不起稅務官。",
  str_homestory_807901001_16_dialog_content = "原來是囊中羞澀。",
  str_homestory_807901001_17_dialog_content = "沒關係，我可以免費為您提供稅務諮詢。",
  str_homestory_807901001_18_dialog_content = "因為「衡量空庭的價值」也會為我帶來一定的情緒價值。",
  str_homestory_807901001_19_option_content = "（否認）",
  str_homestory_807901001_20_dialog_content = "沒......沒有！",
  str_homestory_807901001_21_dialog_content = "如果空庭真的有需要稅務官的那一天，我一定回去找米潔妮的！",
  str_homestory_807901001_22_dialog_content = "有交易和管理的地方，就會有稅務。",
  str_homestory_807901001_23_dialog_content = "既然您願意相信我，我就繼續為您衡量空庭的價值。",
  str_homestory_807901001_24_dialog_content = "好，好吧......",
  str_homestory_807901001_25_dialog_content = "言歸正傳，關於這個裝飾物，您還知道多少？",
  str_homestory_807901001_26_dialog_content = "我需要更多資訊用於衡量它的價值。",
  str_homestory_807901001_27_dialog_content = "這個裝飾物叫做「溫德嵐節枝巢」。",
  str_homestory_807901001_28_dialog_content = "雖然這些大蛋殼只是裝飾，但它真的能吸引小動物<sprite=emo_gezitou size=60 />來築巢下蛋呢。",
  str_homestory_807901001_29_dialog_content = "不能產生任何經濟價值，還會浪費一定的土地資源。",
  str_homestory_807901001_30_dialog_content = "小動物孵化以後，會進一步消耗空庭的糧食資源。",
  str_homestory_807901001_31_dialog_content = "我判斷，這個裝飾物和其中的動物卵沒有任何價值。",
  str_homestory_807901001_32_dialog_content = "放在這裡，對空庭來說是個損失。",
  str_homestory_807901001_33_dialog_content = "可，可是......那些蛋也是一條條鮮活的小生命。",
  str_homestory_807901001_34_dialog_content = "怎麼能用理性去衡量他們的價值呢？",
  str_homestory_807901001_35_dialog_content = "如果真的要衡量，我覺得它們對我來說是無價的。",
  str_homestory_807901001_36_dialog_content = "無價的？",
  str_homestory_807901001_37_dialog_content = "啊，有了！",
  str_homestory_807901001_38_dialog_content = "米潔妮，我想拜託妳當這個「溫德嵐節枝巢」的看護官！",
  str_homestory_807901001_39_dialog_content = "沒問題，我需要做什麼呢？",
  str_homestory_807901001_40_dialog_content = "在這裡等著小動物破殼而出，守護牠們茁壯長大。",
  str_homestory_807901001_41_dialog_content = "我等一下送妳一本書，上面會教妳如何孵化小動物。",
  str_homestory_807901001_42_dialog_content = "有教科書的話，就好辦很多了。",
  str_homestory_807901001_43_dialog_content = "放心，我不會讓你失望的。",
  str_homestory_817601001_0_dialog_content = "貝爾塔！",
  str_homestory_817601001_1_dialog_content = "貝爾塔，你在做什麼呢？",
  str_homestory_817601001_2_dialog_content = "是PlayerName呀！",
  str_homestory_817601001_3_dialog_content = "我剛剛在鍛鍊身體。",
  str_homestory_817601001_4_dialog_content = "跑步路過這裡的時候，恍惚間好像看到了拉斐爾大人的臉。",
  str_homestory_817601001_5_dialog_content = "我就停下來仔細看了一下。",
  str_homestory_817601001_6_dialog_content = "發現這張卡片上有她的照片！",
  str_homestory_817601001_7_dialog_content = "啊，這個架子上的是大家之前寄給我的明信片！",
  str_homestory_817601001_8_dialog_content = "也有一些是我去一個新地方的時候，帶回來的留念照片。",
  str_homestory_817601001_9_dialog_content = "這張好像是拉斐爾出遠門的時候，硬拖著米迦勒一起拍的。",
  str_homestory_817601001_10_dialog_content = "我就說為什麼米迦勒大人一臉的無奈！<sprite=emo_wuzui size=60 />",
  str_homestory_817601001_11_dialog_content = "不過PlayerName的人緣可真好啊。",
  str_homestory_817601001_12_dialog_content = "這數量也太多了，我甚至看到了海蒂大人的落款……",
  str_homestory_817601001_13_dialog_content = "咦？這張風景照……是紅油沙漠嗎？",
  str_homestory_817601001_14_dialog_content = "嗯，是的。",
  str_homestory_817601001_15_dialog_content = "這張是之前去紅油扳手玩的時候，帶回來的紀念。",
  str_homestory_817601001_16_option_content = "還有北境的。",
  str_homestory_817601001_17_dialog_content = "哇！沙漠和雪原，也太美了吧？",
  str_homestory_817601001_18_option_content = "還有海邊的。",
  str_homestory_817601001_19_dialog_content = "哇！沙漠和海灘，也太美了吧？",
  str_homestory_817601001_20_dialog_content = "PlayerName去過好多地方啊，真羡慕你！",
  str_homestory_817601001_21_dialog_content = "貝爾塔平時不會四處去旅遊嗎？",
  str_homestory_817601001_22_dialog_content = "嗯，因為工作性質的關係，我很少有能夠安心休假的機會。",
  str_homestory_817601001_23_dialog_content = "畢竟病人可不會因為你休假就不受傷。",
  str_homestory_817601001_24_dialog_content = "平時就算出去，也都是出差去支援。",
  str_homestory_817601001_25_dialog_content = "確實如此，當醫生真的是很辛苦呢……",
  str_homestory_817601001_26_dialog_content = "辛苦是辛苦。",
  str_homestory_817601001_27_dialog_content = "不過一想到可以幫助別人減輕痛苦，甚至救下一條生命……",
  str_homestory_817601001_28_dialog_content = "這些小事就完全不值一提了！",
  str_homestory_817601001_29_dialog_content = "況且，我現在多努力一點，才可以更快地進步。",
  str_homestory_817601001_30_dialog_content = "才能更快建立起自己的醫療團隊，在大陸各地巡迴治療。",
  str_homestory_817601001_31_dialog_content = "到時候不僅能幫助更多的人，還能看到沒見過的風景！",
  str_homestory_817601001_32_dialog_content = "一舉兩得～<sprite=emo_guilian size=60 />",
  str_homestory_817601001_33_dialog_content = "……感覺貝爾塔好厲害啊！",
  str_homestory_817601001_34_dialog_content = "你說這些話的時候感覺整個人都在閃閃發光！",
  str_homestory_817601001_35_dialog_content = "哈哈哈哈，我還差得遠呢！",
  str_homestory_817601001_36_dialog_content = "我的目標是成為拉斐爾大人、約翰先生那樣強大的醫生。",
  str_homestory_817601001_37_dialog_content = "但是需要學習的還有很多很多。",
  str_homestory_817601001_38_dialog_content = "不光是醫學技術，還有體力和精神力也得要跟得上才行。",
  str_homestory_817601001_39_dialog_content = "約翰醫生幫我動手術的時候，可是在手術台旁站了整整三天！",
  str_homestory_817601001_40_dialog_content = "以我現在的程度，是肯定沒辦法做到的。",
  str_homestory_817601001_41_dialog_content = "啊，這麼說來我得趕快繼續鍛鍊了，不能再閒聊了！",
  str_homestory_817601001_42_dialog_content = "拜拜PlayerName。",
  str_homestory_817601001_43_dialog_content = "等我日後在大陸巡迴治療的時候，也會寄明信片給你的！",
  str_homestory_817601001_44_dialog_content = "哈哈，還真是一如既往的急性子呢。",
  str_homestory_817601001_45_dialog_content = "那我就先期待一下吧，加油，貝爾塔。",
  str_homestory_817501001_0_dialog_content = "阿克希亞？",
  str_homestory_817501001_1_dialog_content = "你好呀，阿克希亞。",
  str_homestory_817501001_2_dialog_content = "你好，PlayerName。",
  str_homestory_817501001_3_dialog_content = "最近妳的身體是不是好一點了？",
  str_homestory_817501001_4_dialog_content = "感覺還蠻經常能在空庭裡看到妳的。",
  str_homestory_817501001_5_dialog_content = "嗯<sprite=emo_chidai size=60 />……其實阿克希亞在結束空庭探索後，仍然需要回到休眠艙中休息。",
  str_homestory_817501001_6_dialog_content = "但這裡有很多有趣的東西在吸引阿克希亞。",
  str_homestory_817501001_7_dialog_content = "比如阿克希亞經常光顧的這面回聲鼓？",
  str_homestory_817501001_8_dialog_content = "咳、咳。",
  str_homestory_817501001_9_dialog_content = "原來PlayerName一直在關注阿克希亞的行動路線嗎？",
  str_homestory_817501001_10_option_content = "當然！",
  str_homestory_817501001_11_dialog_content = "雖然三次方總是跟在妳身邊，理論上不會出現什麼意外才對。",
  str_homestory_817501001_12_dialog_content = "但總覺得，我需要更多地關注阿克希亞的身體狀況才行。",
  str_homestory_817501001_13_dialog_content = "……謝謝關心。",
  str_homestory_817501001_14_option_content = "沒有啦",
  str_homestory_817501001_15_dialog_content = "只是每次偶然見到妳的時候，妳都在這面鼓附近。",
  str_homestory_817501001_16_dialog_content = "嗯……",
  str_homestory_817501001_17_dialog_content = "阿克希亞對這樣的鼓有一點好奇。",
  str_homestory_817501001_18_dialog_content = "嗯，我記得阿克希亞對音樂還挺感興趣的來著。",
  str_homestory_817501001_19_dialog_content = "但是，阿克希亞喜歡那種「電子感」音樂的原因是什麼呢？",
  str_homestory_817501001_20_dialog_content = "原因……",
  str_homestory_817501001_21_dialog_content = "也許是因為這樣的音樂沒有歌詞吧。<sprite=emo_sikao size=60 />",
  str_homestory_817501001_22_dialog_content = "沒有歌詞？",
  str_homestory_817501001_23_dialog_content = "嗯。",
  str_homestory_817501001_24_dialog_content = "沒有歌詞的話，就給聽眾留出了足夠的想像空間。",
  str_homestory_817501001_25_dialog_content = "聽者只需要單純地感知那種韻律就可以了，不需要在樂曲中投入多餘的情感。",
  str_homestory_817501001_26_dialog_content = "果然，還是這種非常「阿克希亞」的理由啊。",
  str_homestory_817501001_27_dialog_content = "儘管這樣說會被父親唾棄，但我認為比起其他音樂……",
  str_homestory_817501001_28_dialog_content = "電子感的音樂，閃爍著創作者和冰冷的音符融合在一起的理性之光。",
  str_homestory_817501001_29_dialog_content = "被妳這麼一說的話，好像確實是這樣。",
  str_homestory_817501001_30_dialog_content = "這種音樂好像並不會調動起人們的情感？",
  str_homestory_817501001_31_dialog_content = "是的。",
  str_homestory_817501001_32_dialog_content = "所以……",
  str_homestory_817501001_33_dialog_content = "阿克希亞總是出現在這面鼓旁邊，是因為這種音樂裡會有鼓聲嗎？",
  str_homestory_817501001_34_dialog_content = "還是說，阿克希亞想要試著在那些旋律中加入鼓聲呢？",
  str_homestory_817501001_35_dialog_content = "阿克希亞只是想多聽一聽它們的聲音而已。",
  str_homestory_817501001_36_dialog_content = "但PlayerName剛剛的話，給了阿克希亞一種啟發。",
  str_homestory_817501001_37_dialog_content = "阿克希亞……以後也會常待在這裡的。",
  str_homestory_817501001_38_dialog_content = "嗯！有任何其他需要的話，也可以隨時告訴我。",
  str_homestory_817501001_39_dialog_content = "謝謝，PlayerName。",
  str_homestory_805401001_0_dialog_content = "是娜汀？",
  str_homestory_805401001_1_dialog_content = "PlayerName，您來了！",
  str_homestory_805401001_2_dialog_content = "娜汀，妳怎麼一個人站在這裡呀？",
  str_homestory_805401001_3_dialog_content = "為什麼不和大家一起去屋子裡休息，或者去附近釣魚呢？",
  str_homestory_805401001_4_dialog_content = "因為我要完成我的工作！",
  str_homestory_805401001_5_dialog_content = "妳的工作？",
  str_homestory_805401001_6_dialog_content = "沒錯，作為空庭的第一個守夜人……",
  str_homestory_805401001_7_dialog_content = "我當然要站好自己的每一班崗！",
  str_homestory_805401001_8_dialog_content = "咦，等等……",
  str_homestory_805401001_9_dialog_content = "我怎麼不記得拜託過妳來當空庭的守夜人<sprite=emo_yueliang size=60 />呀？",
  str_homestory_805401001_10_dialog_content = "PlayerName請我來空庭做客、玩耍。",
  str_homestory_805401001_11_dialog_content = "不僅提供住處、食物，還準備了那麼多好玩的傢俱、擺設……",
  str_homestory_805401001_12_dialog_content = "我真的很開心！",
  str_homestory_805401001_13_dialog_content = "從來沒有想過，我也能成為PlayerName這種大人物的朋友。",
  str_homestory_805401001_14_dialog_content = "更沒有想過自己能走出白夜城，來到空庭這麼遠的地方。",
  str_homestory_805401001_15_dialog_content = "可我一沒錢，二沒才藝……不知道要怎麼才能回報您。",
  str_homestory_805401001_16_dialog_content = "想來想去，我好像只會做守夜人的工作。",
  str_homestory_805401001_17_dialog_content = "所以……我就想用這種方式來感謝PlayerName！",
  str_homestory_805401001_18_option_content = "（感謝）",
  str_homestory_805401001_19_dialog_content = "謝謝妳，娜汀。聽到妳這麼說我很欣慰。",
  str_homestory_805401001_20_dialog_content = "但我可不能讓我的客人在這裡為我工作呀。",
  str_homestory_805401001_21_option_content = "（安慰）",
  str_homestory_805401001_22_dialog_content = "妳能覺得開心就是給我最好的回報了！",
  str_homestory_805401001_23_dialog_content = "真的不用這麼辛苦的。",
  str_homestory_805401001_24_dialog_content = "沒關係，我早就習慣了，一點都不覺得辛苦。",
  str_homestory_805401001_25_dialog_content = "況且……",
  str_homestory_805401001_26_dialog_content = "空庭真的很美！",
  str_homestory_805401001_27_dialog_content = "您又總是按照大家的喜好去添置一些傢俱……",
  str_homestory_805401001_28_dialog_content = "這讓我漸漸地有了一種「家」的感覺。",
  str_homestory_805401001_29_dialog_content = "既然是「家」，娜汀也不用那麼客氣了。",
  str_homestory_805401001_30_dialog_content = "不用總想著回報不回報的。",
  str_homestory_805401001_31_dialog_content = "正因為是「家」，所以我才湧起了一種責任感……",
  str_homestory_805401001_32_dialog_content = "我想守護我們的「家」，不讓空庭受到任何傷害！",
  str_homestory_805401001_33_dialog_content = "這對我來說，已經不是一份工作那麼簡單了。",
  str_homestory_805401001_34_dialog_content = "這……是一種守護的本能和使命！",
  str_homestory_805401001_35_dialog_content = "娜汀……",
  str_homestory_805401001_36_dialog_content = "謝謝妳！",
  str_homestory_805401001_37_dialog_content = "我會想辦法給妳一份酬勞的。",
  str_homestory_805401001_38_dialog_content = "咦？！",
  str_homestory_817801001_0_dialog_content = "你好呀，維克。",
  str_homestory_817801001_1_dialog_content = "難得看到維克你竟然在外面活動！",
  str_homestory_817801001_2_dialog_content = "今天怎麼沒躺在房間裡喝酒睡覺<sprite=emo_kun size=60 />？",
  str_homestory_817801001_3_dialog_content = "哇，你就是這麼看待我的嗎，PlayerName？",
  str_homestory_817801001_4_dialog_content = "真令人傷心，我好歹也是個神奇動物專家。",
  str_homestory_817801001_5_dialog_content = "在房間裡的時候都是在整理資料，寫我的新書。",
  str_homestory_817801001_6_dialog_content = "幹的都是正經事，喝酒只是幫助發散思維而已！",
  str_homestory_817801001_7_dialog_content = "喔，是嗎？那你的新書進度怎麼樣了？",
  str_homestory_817801001_8_dialog_content = "話說回來，我發現你這個地方的環境真是越來越好了。",
  str_homestory_817801001_9_dialog_content = "話題轉移得真生硬。",
  str_homestory_817801001_10_dialog_content = "才不是呢，你知道我剛剛在這裡做什麼嗎？",
  str_homestory_817801001_11_dialog_content = "嗯……放風散步發呆？",
  str_homestory_817801001_12_dialog_content = "……",
  str_homestory_817801001_13_dialog_content = "我在調查你這片樹林裡的物種種類和數量。",
  str_homestory_817801001_14_dialog_content = "調查這些做什麼？",
  str_homestory_817801001_15_dialog_content = "你可不要小看這些資訊哦！",
  str_homestory_817801001_16_dialog_content = "它們可以反映很多深層現象呢。",
  str_homestory_817801001_17_dialog_content = "比如這裡的環境適合什麼類型的生物生存",
  str_homestory_817801001_18_dialog_content = "這裡的動植物捕食關係是什麼樣的等等，諸如此類的事。",
  str_homestory_817801001_19_dialog_content = "而我剛剛想到<sprite=emo_wuzui size=60 />——",
  str_homestory_817801001_20_dialog_content = "你這裡簡直就是一個完美的調查研究場所！",
  str_homestory_817801001_21_dialog_content = "我打算將一些神奇動物引進到這裡。",
  str_homestory_817801001_22_dialog_content = "這樣我的書會有更多的……",
  str_homestory_817801001_23_dialog_content = "等等，你要做什麼？",
  str_homestory_817801001_24_dialog_content = "嗯？收集資訊，寫進我的書裡？",
  str_homestory_817801001_25_dialog_content = "不是，我是問上一句。",
  str_homestory_817801001_26_dialog_content = "你要把神奇動物養在森林裡？",
  str_homestory_817801001_27_dialog_content = "我已經單獨分給你那麼多空房間了，還不夠嗎！",
  str_homestory_817801001_28_dialog_content = "哎呀，那怎麼能一樣~",
  str_homestory_817801001_29_dialog_content = "室內的模擬場景終究還是無法完全還原外界的真實環境。",
  str_homestory_817801001_30_dialog_content = "肯定還是在原生態的環境下，動物的表現最真實準確啦~",
  str_homestory_817801001_31_dialog_content = "重點不是這個！",
  str_homestory_817801001_32_dialog_content = "你在巨像上養了那麼多神奇動物，已經有很多光靈投訴了！",
  str_homestory_817801001_33_dialog_content = "神奇動物們在凌晨的叫聲吵到其他光靈睡覺的事你還沒解決。",
  str_homestory_817801001_34_dialog_content = "它們每天的糞便和毛髮你自己從來也不打掃清理。",
  str_homestory_817801001_35_dialog_content = "現在又要給我找新的麻煩嗎！",
  str_homestory_817801001_36_dialog_content = "你好冷漠喔，PlayerName。",
  str_homestory_817801001_37_dialog_content = "這怎麼能叫麻煩呢？",
  str_homestory_817801001_38_dialog_content = "這是為整個大陸的神奇動物組織奉獻一份力啊！",
  str_homestory_817801001_39_dialog_content = "你這是在無理取鬧！ <sprite=emo_shengqi size=60 />",
  str_homestory_817801001_40_dialog_content = "總之，不許打這片森林的主意。",
  str_homestory_817801001_41_dialog_content = "草地、山谷、河流也不行！",
  str_homestory_817801001_42_dialog_content = "唉，好好好。",
  str_homestory_817801001_43_dialog_content = "真是的，現在的年輕人，對老人家可真是一點耐心都沒有呢。",
  str_homestory_817701001_0_dialog_content = "歌爾蒂！",
  str_homestory_817701001_1_dialog_content = "啊，發現歌爾蒂了！<sprite=emo_yaosu size=60 />",
  str_homestory_817701001_2_dialog_content = "PlayerName，剛剛我在舞台上演唱了我的新歌。",
  str_homestory_817701001_3_dialog_content = "呼，好緊張，不知道大家會不會喜歡……",
  str_homestory_817701001_4_dialog_content = "你覺得怎麼樣？",
  str_homestory_817701001_5_dialog_content = "很好聽喔~",
  str_homestory_817701001_6_dialog_content = "大家一定會喜歡的！",
  str_homestory_817701001_7_dialog_content = "嘿嘿，PlayerName這麼說我就放心了~",
  str_homestory_817701001_8_dialog_content = "其實，我有一件很糾結的事情。",
  str_homestory_817701001_9_dialog_content = "想要參考PlayerName的建議。",
  str_homestory_817701001_10_dialog_content = "什麼事情？很少見到歌爾蒂會糾結呢。",
  str_homestory_817701001_11_dialog_content = "其實是新專輯的主打歌啦~",
  str_homestory_817701001_12_dialog_content = "有一首是歌爾蒂平時的風格，陽光元氣<sprite=emo_taiyang size=60 />的歌曲。",
  str_homestory_817701001_13_dialog_content = "另外一首是酷酷風格<sprite=emo_mojing size=60 />的歌曲，也算是我的新嘗試了~",
  str_homestory_817701001_14_dialog_content = "那，PlayerName覺得歌爾蒂需不需要改變呢？",
  str_homestory_817701001_15_option_content = "可以改變",
  str_homestory_817701001_16_dialog_content = "偶爾嘗試一下新風格，很不錯呢！",
  str_homestory_817701001_17_option_content = "不需要改變",
  str_homestory_817701001_18_dialog_content = "也對，熟悉的風格，歌爾蒂可以駕馭得更好！",
  str_homestory_817701001_19_dialog_content = "不過，還是要看整張專輯的主題吧？",
  str_homestory_817701001_20_dialog_content = "嗯！新專輯的主題是「成長的滋味」。",
  str_homestory_817701001_21_dialog_content = "是公司斥鉅資打造的正規專輯~",
  str_homestory_817701001_22_dialog_content = "欸，經紀人有沒有提供什麼建議呢？",
  str_homestory_817701001_23_dialog_content = "經紀人認為歌爾蒂不需要改變。",
  str_homestory_817701001_24_dialog_content = "因為有的粉絲們或許不喜歡新風格……",
  str_homestory_817701001_25_dialog_content = "是一個保守的建議呢。",
  str_homestory_817701001_26_dialog_content = "不過我認為粉絲喜歡的是真正的歌爾蒂。",
  str_homestory_817701001_27_dialog_content = "無論歌爾蒂改變與否，他們一定會一如既往支持妳的！",
  str_homestory_817701001_28_dialog_content = "所以，歌爾蒂不如遵循自己內心的想法——",
  str_homestory_817701001_29_dialog_content = "選擇妳真正想選擇的風格。",
  str_homestory_817701001_30_dialog_content = "好！",
  str_homestory_817701001_31_dialog_content = "歌爾蒂決定了！要選擇——",
  str_homestory_817701001_32_dialog_content = "要選擇的是——",
  str_homestory_817701001_33_dialog_content = "陽光元氣的主打歌！",
  str_homestory_817701001_34_dialog_content = "欸？",
  str_homestory_817701001_35_dialog_content = "因為我真正的性格就是這樣的嘛~",
  str_homestory_817701001_36_dialog_content = "果然還是這樣最適合我了！",
  str_homestory_817701001_37_dialog_content = "看來經紀人還是了解歌爾蒂的啊……",
  str_homestory_818001001_0_dialog_content = "珀蘭蒂？",
  str_homestory_818001001_1_dialog_content = "唔……把應援棒放在這裡？好像還是怪怪的？",
  str_homestory_818001001_2_dialog_content = "妳在幹什麼？",
  str_homestory_818001001_3_dialog_content = "啊！你來得正好！",
  str_homestory_818001001_4_dialog_content = "幫忙看一下，把應援棒放在左邊好看，還是右邊？",
  str_homestory_818001001_5_option_content = "左邊。",
  str_homestory_818001001_6_dialog_content = "還是放在右邊好看些。",
  str_homestory_818001001_7_option_content = "都一樣。",
  str_homestory_818001001_8_dialog_content = "確實都一樣，那就放在右邊吧。",
  str_homestory_818001001_9_dialog_content = "……",
  str_homestory_818001001_10_dialog_content = "妳擺弄這個做什麼？",
  str_homestory_818001001_11_dialog_content = "我在為《歌爾蒂空庭演出大獲成功》這篇新聞報導拍攝照片。",
  str_homestory_818001001_12_dialog_content = "現在在拍攝歌爾蒂的應援物——",
  str_homestory_818001001_13_dialog_content = "這裡有螢光棒、燈牌、還有貼紙、小卡。",
  str_homestory_818001001_14_dialog_content = "甚至還有印著歌爾蒂頭像的T恤，真是太可愛啦！",
  str_homestory_818001001_15_dialog_content = "說起來，這裡感覺還缺少歌爾蒂的人形立牌。",
  str_homestory_818001001_16_dialog_content = "如果有的話，我一定要偷偷拿回房間……<sprite=emo_sikao size=60 />",
  str_homestory_818001001_17_dialog_content = "哎呀！該不會原本是有人形立牌的？！",
  str_homestory_818001001_18_dialog_content = "但是已經被某位沒公德心的粉絲搬回自己房間了？",
  str_homestory_818001001_19_dialog_content = "真可惡！怎麼能做這種事呢？",
  str_homestory_818001001_20_dialog_content = "明明妳自己就想做啊……",
  str_homestory_818001001_21_dialog_content = "算了，先拍這些吧。",
  str_homestory_818001001_22_dialog_content = "本人就在旁邊，卻拍攝應援物？",
  str_homestory_818001001_23_dialog_content = "完全本末倒置了吧。",
  str_homestory_818001001_24_dialog_content = "你不懂，這是一種側面烘托的手法，能夠充分體現……",
  str_homestory_818001001_25_dialog_content = "啊？等一下！",
  str_homestory_818001001_26_dialog_content = "怎麼神經兮兮的？",
  str_homestory_818001001_27_dialog_content = "有一片樹影灑了下來，正好落在燈牌上。",
  str_homestory_818001001_28_dialog_content = "斑駁的光影變幻，隱隱帶著樹狀紋理，讓整個場景都生動了。",
  str_homestory_818001001_29_dialog_content = "正是拍照的好時機！",
  str_homestory_818001001_30_dialog_content = "拍得真好啊~我從來沒有見過這麼完美的照片~",
  str_homestory_818001001_31_dialog_content = "這次新聞的照片就用這個了！",
  str_homestory_818001001_32_dialog_content = "倒是用歌爾蒂本人的照片啊！",
  str_homestory_818001001_33_dialog_content = "拍完了，我要回去洗照片了。",
  str_homestory_818001001_34_dialog_content = "對了，來這裡的路上好像看到水裡有東西，你要不要去看一看？",
  str_homestory_818001001_35_dialog_content = "妳是不是完全沒在聽我說話……",
  str_homestory_818101001_0_dialog_content = "仲胥？",
  str_homestory_818101001_1_dialog_content = "仲胥，你在看什麼呢？",
  str_homestory_818101001_2_dialog_content = "你看這個貨架裡面。",
  str_homestory_818101001_3_dialog_content = "這個貨架有什麼不同嗎？<sprite=emo_sikao size=60 />",
  str_homestory_818101001_4_dialog_content = "啊！我看到了，一心在裡面！",
  str_homestory_818101001_5_dialog_content = "牠趁我不注意的時候，鑽了進去。",
  str_homestory_818101001_6_dialog_content = "沒想到一心是這麼調皮的小貓。",
  str_homestory_818101001_7_dialog_content = "其實，一夢和一諾也在裡面。",
  str_homestory_818101001_8_dialog_content = "欸？小貓們這麼喜歡這個貨架嗎？",
  str_homestory_818101001_9_dialog_content = "應該是因為貓咪喜歡狹窄與漆黑的地方。",
  str_homestory_818101001_10_dialog_content = "這麼說來貨架裡面黑黑的，而且分成了很多層。",
  str_homestory_818101001_11_dialog_content = "嗯，看來這個是新式的貓窩呢！",
  str_homestory_818101001_12_dialog_content = "新式貓窩？說得有理。",
  str_homestory_818101001_13_dialog_content = "擇日我也請匠人仿造這個樣式，訂製一個。",
  str_homestory_818101001_14_dialog_content = "當然可以，隨時歡迎！",
  str_homestory_818101001_15_dialog_content = "我也沒想到這個貨架還有這個用途。",
  str_homestory_818101001_16_dialog_content = "謝過小友。",
  str_homestory_818101001_17_dialog_content = "不過，是不是給你帶來了麻煩？",
  str_homestory_818101001_18_option_content = "完全不會！",
  str_homestory_818101001_19_option_content = "一點點",
  str_homestory_818101001_20_dialog_content = "失禮了，我會好好批評牠們的。",
  str_homestory_818101001_21_dialog_content = "不過現在的問題是，要怎麼把牠們抓出來呢？",
  str_homestory_818101001_22_dialog_content = "現在看起來，牠們在裡面睡得很香～",
  str_homestory_818101001_23_dialog_content = "平時只要我呼喚名字，牠們便會過來，今天卻不曾回應。",
  str_homestory_818101001_24_dialog_content = "嗯……說不定是因為小貓太過瞭解你。",
  str_homestory_818101001_25_dialog_content = "何出此言？<sprite=emo_wuzui size=60 />",
  str_homestory_818101001_26_dialog_content = "因為仲胥平時叫小貓們，是需要牠們辦事。",
  str_homestory_818101001_27_dialog_content = "但是今天只是因為，仲胥希望小貓們不要待在貨架裡。",
  str_homestory_818101001_28_dialog_content = "所以牠們選擇不聽你的指令。",
  str_homestory_818101001_29_dialog_content = "三隻小貓都很聰明！",
  str_homestory_818101001_30_dialog_content = "……看來這個貨架真有非同一般的魔力。",
  str_homestory_818101001_31_dialog_content = "必須要為牠們準備一個了。",
  str_homestory_818101001_32_dialog_content = "小貓們怎麼辦呢？",
  str_homestory_818101001_33_dialog_content = "既然如此，我便等牠們睡醒好了。",
  str_homestory_818101001_34_dialog_content = "貓貓們的勝利！",
  str_homestory_818101001_35_dialog_content = "不過這可真是奇妙的景象——",
  str_homestory_818101001_36_dialog_content = "不知道的人，還以為仲胥又在思考著什麼哲學問題……",
  str_homestory_818301001_0_dialog_content = "厘青？",
  str_homestory_818301001_1_dialog_content = "唔，去哪裡了……",
  str_homestory_818301001_2_dialog_content = "厘青，真巧呀，你在做什麼？",
  str_homestory_818301001_3_dialog_content = "你、你好啊，PlayerName。",
  str_homestory_818301001_4_dialog_content = "我正在找小尾巴！你看到他了嗎？",
  str_homestory_818301001_5_dialog_content = "沒有，發生什麼事了？",
  str_homestory_818301001_6_dialog_content = "哼，還能怎麼樣，當然是他又偷懶了！<sprite=emo_shengqi size=60 />",
  str_homestory_818301001_7_dialog_content = "本來我帶他到院子裡採草藥。",
  str_homestory_818301001_8_dialog_content = "結果一轉眼就不見了！",
  str_homestory_818301001_9_dialog_content = "空庭裡面也有草藥？",
  str_homestory_818301001_10_dialog_content = "那是當然。",
  str_homestory_818301001_11_dialog_content = "良方常常藏在意想不到的地方。",
  str_homestory_818301001_12_dialog_content = "重要的是，要有一雙善於發現的眼睛<sprite=emo_mojing size=60 />。",
  str_homestory_818301001_13_dialog_content = "真不愧是厘青！",
  str_homestory_818301001_14_dialog_content = "話說回來……",
  str_homestory_818301001_15_option_content = "你找了多久？",
  str_homestory_818301001_16_dialog_content = "這個……嗯……大概就，半個小時吧。",
  str_homestory_818301001_17_dialog_content = "這麼久？",
  str_homestory_818301001_18_dialog_content = "我說錯了！可能也就十分鐘吧！",
  str_homestory_818301001_19_option_content = "你採了什麼藥？",
  str_homestory_818301001_20_dialog_content = "就、就是……草藥！",
  str_homestory_818301001_21_dialog_content = "厘青，你怎麼說話結結巴巴的？",
  str_homestory_818301001_22_dialog_content = "我才沒有！",
  str_homestory_818301001_23_dialog_content = "難道說……",
  str_homestory_818301001_24_dialog_content = "厘青你也偷懶了？",
  str_homestory_818301001_25_dialog_content = "才才才才沒有！",
  str_homestory_818301001_26_dialog_content = "我和小尾巴來這裡，就是為了採草藥的！",
  str_homestory_818301001_27_dialog_content = "可是……",
  str_homestory_818301001_28_dialog_content = "可是？",
  str_homestory_818301001_29_dialog_content = "這裡太舒服了……",
  str_homestory_818301001_30_dialog_content = "我就睡<sprite=emo_kun size=60 />了一下，就一下下！",
  str_homestory_818301001_31_dialog_content = "醒來的時候，小尾巴就不見了……",
  str_homestory_818301001_32_dialog_content = "哈哈哈，看來你們兄弟倆都是偷懶鬼啊。",
  str_homestory_818301001_33_dialog_content = "我、我才不是呢！",
  str_homestory_818201001_0_dialog_content = "妳在幹嘛？",
  str_homestory_818201001_1_dialog_content = "我在感受水的呼吸。",
  str_homestory_818201001_2_dialog_content = "雖然聽不懂，但是感覺很厲害的樣子。",
  str_homestory_818201001_3_dialog_content = "你是否感應過水之呼吸？",
  str_homestory_818201001_4_option_content = "有過",
  str_homestory_818201001_5_dialog_content = "當真？是什麼樣的？",
  str_homestory_818201001_6_dialog_content = "冰涼涼，很清新，挺解渴的。",
  str_homestory_818201001_7_dialog_content = "那是水的味道，不是水之呼吸。",
  str_homestory_818201001_8_option_content = "沒有",
  str_homestory_818201001_9_dialog_content = "如果想學，我可以教你。",
  str_homestory_818201001_10_dialog_content = "好啊。",
  str_homestory_818201001_11_dialog_content = "那就開始。",
  str_homestory_818201001_12_dialog_content = "現在嗎？我沒帶泳褲……",
  str_homestory_818201001_13_dialog_content = "今日在岸邊練習基礎動作即可。",
  str_homestory_818201001_14_dialog_content = "站立，挺胸抬頭，深呼吸，感受水流。",
  str_homestory_818201001_15_dialog_content = "聽起來也不難，我這就試試。",
  str_homestory_818201001_16_dialog_content = "吸——",
  str_homestory_818201001_17_dialog_content = "呼——",
  str_homestory_818201001_18_dialog_content = "話說我要這樣站多久？",
  str_homestory_818201001_19_dialog_content = "一萬個小時。",
  str_homestory_818201001_20_dialog_content = "一萬個小時？！",
  str_homestory_818201001_21_dialog_content = "一萬個小時的錘煉是任何人從平凡變成超凡的必要條件。",
  str_homestory_818201001_22_dialog_content = "話是這麼說，但是這也太枯燥乏味了<sprite=emo_xinsui size=60 />……",
  str_homestory_818201001_23_dialog_content = "如果想放棄，現在就可以。",
  str_homestory_818201001_24_dialog_content = "有趣的事情有很多，但通往成功的道路通常不那麼快樂。",
  str_homestory_818201001_25_dialog_content = "對不起，我會繼續努力！",
  str_homestory_818201001_26_dialog_content = "妳也是經歷了這麼多艱苦的訓練，才練就一身好水性嗎？",
  str_homestory_818201001_27_dialog_content = "沒練過，天生的。",
  str_homestory_818201001_28_dialog_content = "？？？",
  str_homestory_818201001_29_dialog_content = "那妳讓我站一萬個小時，是在逗我？！",
  str_homestory_818201001_30_dialog_content = "不是，是我最初學游泳時，林家長老教的。",
  str_homestory_818201001_31_dialog_content = "只是我天生就能與水共鳴，所以無需練習。",
  str_homestory_818201001_32_dialog_content = "哦，既然是林家長老教的，應該還是有道理的。",
  str_homestory_818201001_33_dialog_content = "繼續站立……",
  str_homestory_818201001_34_dialog_content = "休息一下……腿真的好酸……<sprite=emo_tanqi size=60 />",
  str_homestory_818201001_35_dialog_content = "那就不練了。",
  str_homestory_818201001_36_dialog_content = "欸？可是林家長老說……",
  str_homestory_818201001_37_dialog_content = "林家長老不會游泳，大概只是隨口一說。",
  str_homestory_818201001_38_dialog_content = "！！！",
  str_homestory_818201001_39_dialog_content = "我想了想，就算你在水邊站一萬個小時，應該也無法與水共鳴。",
  str_homestory_818201001_40_dialog_content = "有些事要講天賦，沒有就別勉強了。",
  str_homestory_818201001_41_dialog_content = "妳怎麼不早說！",
  str_homestory_818201001_42_dialog_content = "看你練得很起勁，不忍心打斷。",
  str_homestory_818201001_43_dialog_content = "妳！",
  str_homestory_818201001_44_dialog_content = "啊……我的腿抽筋了……",
  str_homestory_818201001_45_dialog_content = "我背你。",
  str_homestory_818201001_46_dialog_content = "不要，身為男子漢……",
  str_homestory_818201001_47_dialog_content = "那我走了。",
  str_homestory_818201001_48_dialog_content = "等等……唔……妳蹲下來一點……",
  str_homestory_816001001_0_dialog_content = "米迦勒？",
  str_homestory_816001001_1_dialog_content = "妳在看什麼？",
  str_homestory_816001001_2_dialog_content = "（啊，是PlayerName來了。）",
  str_homestory_816001001_3_dialog_content = "（我正在欣賞這個燭台。）",
  str_homestory_816001001_4_dialog_content = "看來妳很喜歡這個燭台，要不要送給妳？",
  str_homestory_816001001_5_dialog_content = "（不，還是請讓我買下吧，多少錢？）",
  str_homestory_816001001_6_dialog_content = "（這裡有一千個白夜幣<sprite=emo_baiyebi size=60 />，夠嗎？）",
  str_homestory_816001001_7_dialog_content = "不不不，不需要這麼多錢。",
  str_homestory_816001001_8_dialog_content = "假如妳要付錢的話，我就不賣給妳了。",
  str_homestory_816001001_9_dialog_content = "（怎麼會？！）",
  str_homestory_816001001_10_dialog_content = "妳怎麼看起來很失落？",
  str_homestory_816001001_11_dialog_content = "我知道了，是因為米迦勒一直以來喜歡收集一些小東西吧？",
  str_homestory_816001001_12_dialog_content = "我記得米迦勒的房間裡，好像堆積著各種各樣奇特的物品呢。",
  str_homestory_816001001_13_dialog_content = "（這個愛好，很奇怪嗎？）",
  str_homestory_816001001_14_option_content = "（承認）",
  str_homestory_816001001_15_dialog_content = "有些物品看起來都已經徹底報廢了，不過妳還是留了下來。",
  str_homestory_816001001_16_dialog_content = "大概是這個愛好有些與眾不同吧？",
  str_homestory_816001001_17_option_content = "（否認）",
  str_homestory_816001001_18_dialog_content = "每個人都會有自己不一樣的愛好，我不覺得奇怪。",
  str_homestory_816001001_19_dialog_content = "我想只是米迦勒喜歡收集物品的類型比較廣泛而已。",
  str_homestory_816001001_20_dialog_content = "（我只是覺得它們很有趣，所以想要收集。）",
  str_homestory_816001001_21_dialog_content = "（不過，其實我想要買下這個燭台，也有別的原因。）",
  str_homestory_816001001_22_dialog_content = "什麼原因？",
  str_homestory_816001001_23_dialog_content = "（燭台裡的蠟燭是易燃品，我怕它會引起火災<sprite=emo_nuhuo size=60 />。）",
  str_homestory_816001001_24_dialog_content = "（許多災難的源頭都是一些小小的隱患。）",
  str_homestory_816001001_25_dialog_content = "（這個……會不會很難以理解？）",
  str_homestory_816001001_26_dialog_content = "嗯，倒是可以理解……",
  str_homestory_816001001_27_dialog_content = "所以米迦勒是為了我的安全著想？",
  str_homestory_816001001_28_dialog_content = "（守護白夜城，是我的職責所在。）",
  str_homestory_816001001_29_dialog_content = "（你幫過我很多，守護PlayerName，也是我內心的想法。）",
  str_homestory_816001001_30_dialog_content = "米迦勒其實也幫了我很多。",
  str_homestory_816001001_31_dialog_content = "不過，這應該不是米迦勒想要買下燭台的一種藉口吧？",
  str_homestory_816001001_32_dialog_content = "（當然不是！）",
  str_homestory_816001001_33_dialog_content = "（守護之人，應該慎重對待。）",
  str_homestory_816001001_34_dialog_content = "欸，米迦勒怎麼好像臉紅了？",
  str_homestory_816001001_35_dialog_content = "（是因為……被燭光照射導致的。）",
  str_homestory_816001001_36_dialog_content = "（說起來，剛才我在河裡也看到了亮亮的東西。）",
  str_homestory_816001001_37_dialog_content = "（和這燭光一樣。）",
  str_homestory_816001001_38_dialog_content = "總感覺米迦勒在轉移話題……",
  str_homestory_818401001_0_dialog_content = "喂，耶利亞～",
  str_homestory_818401001_1_dialog_content = "……",
  str_homestory_818401001_2_dialog_content = "耶利亞？喂～",
  str_homestory_818401001_3_dialog_content = "嗯？這不是空裔小哥嘛。",
  str_homestory_818401001_4_dialog_content = "耶利亞妳在幹什麼，這麼專注？",
  str_homestory_818401001_5_dialog_content = "嗯……我只是在發呆罷了。",
  str_homestory_818401001_6_dialog_content = "發呆？",
  str_homestory_818401001_7_dialog_content = "我跟你說過嗎？我以前去過這附近的空谷遺址。",
  str_homestory_818401001_8_dialog_content = "那時候，你還沒回到這裡。",
  str_homestory_818401001_9_dialog_content = "這裡只有廢墟，和暗鬼<sprite=emo_kulou size=60 />。",
  str_homestory_818401001_10_dialog_content = "哎，別提了，為了打掃這裡，我可廢了好大勁呢！",
  str_homestory_818401001_11_dialog_content = "嗯，真不容易。",
  str_homestory_818401001_12_dialog_content = "說到這個，我想問你。",
  str_homestory_818401001_13_dialog_content = "你覺得，修建空庭是件有意義的事情嗎？",
  str_homestory_818401001_14_dialog_content = "現在的空庭的確很美，但如果遭到襲擊，或是百年後你也離去。",
  str_homestory_818401001_15_dialog_content = "這裡的一切可能還會變回廢墟。",
  str_homestory_818401001_16_option_content = "有意義",
  str_homestory_818401001_17_dialog_content = "有啊！至少現在大家來這裡都玩得很開心。",
  str_homestory_818401001_18_dialog_content = "如果敵人來了，我就趕走他們。",
  str_homestory_818401001_19_dialog_content = "如果我不能照顧這裡了，就託付給信得過的人。",
  str_homestory_818401001_20_dialog_content = "總會有辦法的！",
  str_homestory_818401001_21_dialog_content = "小空裔真是積極啊。",
  str_homestory_818401001_22_option_content = "可能沒有",
  str_homestory_818401001_23_dialog_content = "如果目的是讓空庭永遠存在的話，那可能沒什麼意義吧。",
  str_homestory_818401001_24_dialog_content = "我對自己的能力還是有自知之明的……",
  str_homestory_818401001_25_dialog_content = "但至少現在，我和大家都很開心。",
  str_homestory_818401001_26_dialog_content = "這就夠了！",
  str_homestory_818401001_27_dialog_content = "「活在當下」，這想法也不錯。",
  str_homestory_818401001_28_dialog_content = "我第一次來空之山谷的時候，覺得這裡是個十分悲傷的地方。",
  str_homestory_818401001_29_dialog_content = "打翻的餐具、半開的家門、淩亂的衣物。",
  str_homestory_818401001_30_dialog_content = "能令人輕易地從中聯想到，人們過去平淡而幸福的日子。",
  str_homestory_818401001_31_dialog_content = "而那樣的日子，呼——，就像蒲公英<sprite=emo_pugongying size=60 />一樣，一吹就散了。",
  str_homestory_818401001_32_dialog_content = "嗯……",
  str_homestory_818401001_33_dialog_content = "但是蒲公英也會把希望的種子帶去更遠的地方。",
  str_homestory_818401001_34_dialog_content = "這一切並不是毫無意義的！",
  str_homestory_818401001_35_dialog_content = "也是，如今你這顆小小的種子，就回到這裡重新發芽了呢。",
  str_homestory_818401001_36_dialog_content = "和你聊天，總能給我帶來一些不一樣的感受。",
  str_homestory_818401001_37_dialog_content = "嘿嘿，過獎過獎。",
  str_homestory_818401001_38_dialog_content = "嗯……作為回禮，告訴你一件有意思的事情吧。",
  str_homestory_818401001_39_dialog_content = "剛剛我在河邊，看到河裡有什麼東西在發光。",
  str_homestory_818401001_40_dialog_content = "你或許可以去看看，就當做是一次「探險」。",
  str_homestory_818401001_41_dialog_content = "好像有點意思……謝謝妳，耶利亞！",
  str_homestory_818501001_0_dialog_content = "妳怎麼了？",
  str_homestory_818501001_1_dialog_content = "剛坐了旋轉咖啡杯，頭有點暈暈<sprite=emo_xuanyun size=60 />……",
  str_homestory_818501001_2_dialog_content = "怎麼會頭暈呢？難道設備沒調試好？",
  str_homestory_818501001_3_dialog_content = "我記得轉數已經調到最低了，等一下我上去體驗一下吧。",
  str_homestory_818501001_4_dialog_content = "這是種很危險的遊樂設備，請你務必小心！",
  str_homestory_818501001_5_dialog_content = "危險？",
  str_homestory_818501001_6_dialog_content = "我怎麼記得旋轉咖啡杯適合四歲以上兒童？",
  str_homestory_818501001_7_dialog_content = "也許不適合二十歲的超齡兒童呢……",
  str_homestory_818501001_8_dialog_content = "有些人無法適應旋轉，也是正常的。",
  str_homestory_818501001_9_dialog_content = "休息一下應該就能有所緩解。",
  str_homestory_818501001_10_dialog_content = "好吧，我先回去休息了，等一下還要去北邊送信呢……",
  str_homestory_818501001_11_dialog_content = "嗯？南……北……",
  str_homestory_818501001_12_dialog_content = "糟了！我分不清方向了！",
  str_homestory_818501001_13_dialog_content = "我引以為傲的方向感！沒有了？！",
  str_homestory_818501001_14_dialog_content = "嗚嗚<sprite=emo_daku size=60 />，沒法送信了，我的職業生涯要就此斷送了嗎？",
  str_homestory_818501001_15_dialog_content = "啊？這麼嚴重嗎？",
  str_homestory_818501001_16_dialog_content = "PlayerName，你能告訴我哪邊是北嗎？",
  str_homestory_818501001_17_option_content = "左邊是北",
  str_homestory_818501001_18_dialog_content = "是嗎？完全無法判斷啊……",
  str_homestory_818501001_19_option_content = "我也分不清",
  str_homestory_818501001_20_dialog_content = "果然，連你也……",
  str_homestory_818501001_21_dialog_content = "我們會被困死在這裡嗎？",
  str_homestory_818501001_22_dialog_content = "？？？",
  str_homestory_818501001_23_dialog_content = "一般人在自己家裡，是不會被困死的吧？",
  str_homestory_818501001_24_dialog_content = "被妳說得我都不確定自己在哪裡了……",
  str_homestory_818501001_25_dialog_content = "信使公會守則說，無論何時都要保持方向感。",
  str_homestory_818501001_26_dialog_content = "很多信使都是因為迷失了方向，而陷入險境，無法逃脫。",
  str_homestory_818501001_27_dialog_content = "那種情況應該是指在野外或者密林吧？",
  str_homestory_818501001_28_dialog_content = "我們在空庭裡，妳看見門了嗎？",
  str_homestory_818501001_29_dialog_content = "就在那邊，走幾步就能出去。",
  str_homestory_818501001_30_dialog_content = "可是如果我在野外的時候，也像現在這樣暈乎乎了呢？",
  str_homestory_818501001_31_dialog_content = "野外也有旋轉咖啡杯嗎？",
  str_homestory_818501001_32_dialog_content = "咦咦，對喔……",
  str_homestory_818501001_33_dialog_content = "而且就算真的有，只要不上去坐就可以啦～",
  str_homestory_818501001_34_dialog_content = "對喔！你好聰明啊！",
  str_homestory_818501001_35_dialog_content = "哈哈哈～那是當然～",
  str_homestory_818501001_36_dialog_content = "我這就回去加在信使公會的守則裡——",
  str_homestory_818501001_37_dialog_content = "「如果在野外遇見旋轉咖啡杯，千萬不要坐上去！」",
  str_homestory_818501001_38_dialog_content = "遇見的機率應該很低吧……",
  str_homestory_818501001_39_dialog_content = "「——來自空裔的忠告。」",
  str_homestory_818501001_40_dialog_content = "！！！",
  str_homestory_818501001_41_dialog_content = "我出錢！出多少錢妳才會不寫上去？！",
  str_homestory_818501001_42_dialog_content = "什麼呀？這可是很有用的忠告，我先走啦。",
  str_homestory_818501001_43_dialog_content = "救命……這下一定會成為信使公會的笑柄吧……<sprite=emo_tanqi size=60 />",
  str_homestory_802901001_0_dialog_content = "加百列？",
  str_homestory_802901001_1_dialog_content = "你在幹什麼？",
  str_homestory_802901001_2_dialog_content = "我正在樹下小憩<sprite=emo_kun size=60 />，順道感受樹的呼吸。",
  str_homestory_802901001_3_dialog_content = "樹的呼吸？",
  str_homestory_802901001_4_dialog_content = "正是……樹也是有生命的存在。",
  str_homestory_802901001_5_dialog_content = "我能感受到它呼吸的頻率，PlayerName能察覺到嗎？",
  str_homestory_802901001_6_option_content = "（承認）",
  str_homestory_802901001_7_dialog_content = "枝葉搖晃的時候，感覺就像樹猛地呼了一口氣呢～",
  str_homestory_802901001_8_dialog_content = "不，或許還是單純因為風的吹拂吧……",
  str_homestory_802901001_9_option_content = "（否認）",
  str_homestory_802901001_10_dialog_content = "啊，我感受不到……",
  str_homestory_802901001_11_dialog_content = "看來還是加百列才有感受植物的特殊能力吧？",
  str_homestory_802901001_12_dialog_content = "每棵樹都不同，就像每個人都不同。",
  str_homestory_802901001_13_dialog_content = "只要用心去感受……就能察覺它們的狀態。",
  str_homestory_802901001_14_dialog_content = "舉個例子，這棵樹的呼吸就不太順暢。唔，好像有輕微的病徵……",
  str_homestory_802901001_15_dialog_content = "經你這麼一說，這棵樹的葉子相較於別的樹似乎略為泛黃。",
  str_homestory_802901001_16_dialog_content = "看起來的確有無精打采的感覺。",
  str_homestory_802901001_17_dialog_content = "周圍的樹都長得很茂盛，阻礙了它吸收陽光<sprite=emo_taiyang size=60 />。",
  str_homestory_802901001_18_dialog_content = "看來這孩子沒能好好進行光合作用啊～",
  str_homestory_802901001_19_dialog_content = "咦？那是不是應該移植這棵樹？",
  str_homestory_802901001_20_dialog_content = "那倒是不必～植物也有植物的生存法則。",
  str_homestory_802901001_21_dialog_content = "這棵樹不夠努力生長，才會讓別的樹奪走了它應有的陽光……",
  str_homestory_802901001_22_dialog_content = "得靠自己真正成長起來……太過寵愛它也不行哦～",
  str_homestory_802901001_23_dialog_content = "原來如此，加百列的話聽起來很有道理！",
  str_homestory_802901001_24_dialog_content = "嗯～我本來還擔心PlayerName可能很難理解呢……",
  str_homestory_802901001_25_dialog_content = "沒那回事！比較讓我驚訝的反而是——",
  str_homestory_802901001_26_dialog_content = "平時表現得有點迷糊的加百列竟會說出這麼正經的話。",
  str_homestory_802901001_27_dialog_content = "哎呀，其實我一直都是這麼「隨緣」的哦……",
  str_homestory_802901001_28_dialog_content = "植物也有自己的「命運」……",
  str_homestory_802901001_29_dialog_content = "「命運」是嗎……",
  str_homestory_802901001_30_dialog_content = "沒錯，我會在樹下與你相遇正是「命運」使然呢～",
  str_homestory_802901001_31_dialog_content = "說到這個，剛才我沿河流走來，途中看見了發光的東西……",
  str_homestory_802901001_32_dialog_content = "加百列有沒有去查看那是什麼？",
  str_homestory_802901001_33_dialog_content = "沒有，我的目標就是來樹林小憩一會兒～",
  str_homestory_802901001_34_dialog_content = "我沒查看河中的東西，也是「命運」的安排哦～",
  str_homestory_802901001_35_dialog_content = "我大概能理解加百列所謂的「命運」了……",
  str_homestory_818901001_0_dialog_content = "零恩在做什麼？",
  str_homestory_818901001_1_dialog_content = "喂——零恩——",
  str_homestory_818901001_2_dialog_content = "酒心巧克力、果味夾心巧克力<sprite=emo_sikao size=60 />……嗯？",
  str_homestory_818901001_3_dialog_content = "啊，您好。",
  str_homestory_818901001_4_dialog_content = "零恩在看什麼這麼專注？",
  str_homestory_818901001_5_dialog_content = "沒什麼，就是在端詳這盒巧克力。",
  str_homestory_818901001_6_dialog_content = "這盒巧克力是冠月節的商品。",
  str_homestory_818901001_7_dialog_content = "零恩想吃的話可以隨意吃！",
  str_homestory_818901001_8_dialog_content = "不，我並不是想吃，只是有點在意巧克力的工藝。",
  str_homestory_818901001_9_dialog_content = "我平常在家也會手做巧克力點心。",
  str_homestory_818901001_10_dialog_content = "但不外乎是融化巧克力，用做裝飾的簡單步驟。",
  str_homestory_818901001_11_dialog_content = "沒想到市面上的甜點工藝已經進化到這個地步……",
  str_homestory_818901001_12_dialog_content = "話說回來，您喜歡吃巧克力嗎？",
  str_homestory_818901001_13_option_content = "喜歡！",
  str_homestory_818901001_14_dialog_content = "這樣的話，等我學會新工藝，就做來給您嚐嚐吧。",
  str_homestory_818901001_15_dialog_content = "酒心巧克力對您來說可能為時尚早……",
  str_homestory_818901001_16_dialog_content = "到時候就幫您準備水果夾心口味吧。",
  str_homestory_818901001_17_option_content = "不喜歡......",
  str_homestory_818901001_18_dialog_content = "這樣啊……真可惜。",
  str_homestory_818901001_19_dialog_content = "那下次，我就帶些別種類的點心給您吧。",
  str_homestory_818901001_20_dialog_content = "有任何想吃的，請您隨時告訴我。",
  str_homestory_818901001_21_dialog_content = "好耶！謝謝零恩！",
  str_homestory_818901001_22_dialog_content = "嗯……",
  str_homestory_818901001_23_dialog_content = "怎麼了？零恩為什麼還盯著巧克力看？",
  str_homestory_818901001_24_dialog_content = "難道……其實你還是想吃巧克力？",
  str_homestory_818901001_25_dialog_content = "只、只是有點好奇味道罷了！<sprite=emo_hanshui size=60 />",
  str_homestory_818901001_26_dialog_content = "我會自己買一盒來研究！",
  str_homestory_818901001_27_dialog_content = "哎呀，你怎麼又跟我客氣。",
  str_homestory_818901001_28_dialog_content = "想吃就吃吧！",
  str_homestory_818901001_29_dialog_content = "人都有饞嘴的時候嘛。",
  str_homestory_818901001_30_dialog_content = "我，這……",
  str_homestory_818901001_31_dialog_content = "謝謝您的好意，那我就不客氣了……",
  str_homestory_818601001_0_dialog_content = "蒂娜？",
  str_homestory_818601001_1_dialog_content = "你怎麼在這裡？",
  str_homestory_818601001_2_dialog_content = "PlayerName，你好啊～",
  str_homestory_818601001_3_dialog_content = "這個椅子，讓我感到十分好奇。",
  str_homestory_818601001_4_dialog_content = "妳是說這個沙灘椅嗎？",
  str_homestory_818601001_5_dialog_content = "對～原來這是沙灘椅啊……",
  str_homestory_818601001_6_dialog_content = "說實話，我不熟悉海邊。我大半的時光都在白夜城的審判庭中度過。",
  str_homestory_818601001_7_dialog_content = "PlayerName常去海邊嗎？",
  str_homestory_818601001_8_option_content = "常去",
  str_homestory_818601001_9_dialog_content = "我還滿常去海邊呢。",
  str_homestory_818601001_10_dialog_content = "海邊真的很好玩！",
  str_homestory_818601001_11_option_content = "很少去",
  str_homestory_818601001_12_dialog_content = "其實我也不常去啦。",
  str_homestory_818601001_13_dialog_content = "不過海邊很好玩哦，讓我印象深刻。",
  str_homestory_818601001_14_dialog_content = "這樣啊～",
  str_homestory_818601001_15_dialog_content = "要是有機會能和PlayerName一起去海邊該多好～",
  str_homestory_818601001_16_dialog_content = "不過審判庭還有許多案件等著我處理，實在分不開身啊～",
  str_homestory_818601001_17_dialog_content = "或許未來有機會。",
  str_homestory_818601001_18_dialog_content = "不過海邊比較流行穿泳裝……蒂娜不介意嗎？",
  str_homestory_818601001_19_dialog_content = "泳裝……我在書裡讀到過，是十分輕薄的衣服<sprite=emo_qunzi size=60 />嗎？",
  str_homestory_818601001_20_dialog_content = "是的。白夜城的貴族服飾在海邊恐怕過於厚重……",
  str_homestory_818601001_21_dialog_content = "我很能理解不同場合應該穿著不同服飾的習慣，我沒關係的～",
  str_homestory_818601001_22_dialog_content = "只不過家族元老可能會責怪我「不守禮儀」，讓人有點怯懦呢～",
  str_homestory_818601001_23_dialog_content = "咳咳，我是覺得蒂娜不必杞人憂天……",
  str_homestory_818601001_24_dialog_content = "畢竟也還不曉得何時可以去海邊……",
  str_homestory_818601001_25_dialog_content = "說得也是呢～",
  str_homestory_818601001_26_dialog_content = "或許蒂娜會想試躺沙灘椅？",
  str_homestory_818601001_27_dialog_content = "嗯！我想體驗看看～",
  str_homestory_818601001_28_dialog_content = "雖然沒有我的特製躺椅柔軟，也很舒適呢～",
  str_homestory_818601001_29_dialog_content = "畢竟這種材質在海邊更為實用。",
  str_homestory_818601001_30_dialog_content = "欸，蒂娜，妳有在聽嗎？",
  str_homestory_818601001_31_dialog_content = "就這樣睡著啦……",
  str_homestory_819001001_0_dialog_content = "馬太？",
  str_homestory_819001001_1_dialog_content = "你來得正好。",
  str_homestory_819001001_2_dialog_content = "我看這座復古亭子挺有氣氛，恰恰適合我品茶看書。",
  str_homestory_819001001_3_dialog_content = "不過距離真正堪用還缺少幾樣東西——",
  str_homestory_819001001_4_dialog_content = "什麼東西？",
  str_homestory_819001001_5_dialog_content = "目前的樣子有點單調，你不覺得嗎？",
  str_homestory_819001001_6_option_content = "不覺得啊",
  str_homestory_819001001_7_option_content = "少了點裝飾",
  str_homestory_819001001_8_dialog_content = "晚點我拿兩個靠枕過來吧，這樣就沒問題了。",
  str_homestory_819001001_9_dialog_content = "我打算布置珍稀花草、金銀茶具，方能配得上我等貴族使用。",
  str_homestory_819001001_10_dialog_content = "珍稀花草、金銀茶具……這樣會不會過於奢靡了？",
  str_homestory_819001001_11_dialog_content = "你在擔憂錢<sprite=emo_baiyebi size=60 />的問題嗎？真是個精打細算的空裔啊。",
  str_homestory_819001001_12_dialog_content = "錢的方面你就不用顧慮了，我會解決。",
  str_homestory_819001001_13_dialog_content = "問題不在於錢。當然，這要花很多錢也確實是個難題。",
  str_homestory_819001001_14_dialog_content = "不過既然你會解決，就不算是難題了。只不過……",
  str_homestory_819001001_15_dialog_content = "妳到底想說什麼？",
  str_homestory_819001001_16_dialog_content = "這裡是空庭，是我們所有人共同生活的地方。",
  str_homestory_819001001_17_dialog_content = "不是所有人都喜歡茂盛鮮花、金銀器皿這類玩意兒。",
  str_homestory_819001001_18_dialog_content = "我不想弄得太奢華，反讓部分光靈感到不自在。",
  str_homestory_819001001_19_dialog_content = "你是在考量沒享受過正常生活的那票人嗎？",
  str_homestory_819001001_20_dialog_content = "正常生活也不一定就是被鮮花和金銀包圍吧……",
  str_homestory_819001001_21_dialog_content = "總之我馬上派人來布置。",
  str_homestory_819001001_22_dialog_content = "等等，這裡是我的地盤，一切我說了算。",
  str_homestory_819001001_23_dialog_content = "如果你還想繼續和我們一起生活，就必須學會與不同的人共處。",
  str_homestory_819001001_24_dialog_content = "什麼嘛，怎麼突然說出這麼正經的話？",
  str_homestory_819001001_25_dialog_content = "還是說……你在<size=45>模仿史瓦</size>？！",
  str_homestory_819001001_26_dialog_content = "啥？你在說什麼啊？",
  str_homestory_819001001_27_dialog_content = "據說史瓦也喜歡在滿是鮮花的涼亭中讀書，藉此引來大批少女的傾慕。",
  str_homestory_819001001_28_dialog_content = "所以你是想透過同樣的方式引起女孩們的注意？",
  str_homestory_819001001_29_dialog_content = "想像史瓦一樣受歡迎，所以模仿他的行為舉止。",
  str_homestory_819001001_30_dialog_content = "原來如此……",
  str_homestory_819001001_31_dialog_content = "幹嘛啦！別一副「破案了」的表情！<sprite=emo_shengqi size=60 />",
  str_homestory_819001001_32_dialog_content = "根本不是那麼一回事！我怎麼可能模仿那種笨蛋？",
  str_homestory_819001001_33_dialog_content = "「笨蛋」這個詞語乍聽起來像是罵人的話。",
  str_homestory_819001001_34_dialog_content = "但據說近日也常被用在有好感的人身上哦。",
  str_homestory_819001001_35_dialog_content = "有點噁心……",
  str_homestory_819001001_36_dialog_content = "我可是黎明學院有史以來難得的天才！",
  str_homestory_819001001_37_dialog_content = "怎麼可能會模仿那種只顧著在女人面前維持形象的笨蛋！",
  str_homestory_819001001_38_dialog_content = "不然你為何非要在復古亭子裡布置鮮花和茶具？",
  str_homestory_819001001_39_dialog_content = "這不過是貴族的共通喜好！",
  str_homestory_819001001_40_dialog_content = "算了，你愛怎樣裝修就怎樣裝修吧。",
  str_homestory_819001001_41_dialog_content = "我不管了。",
  str_homestory_819001001_42_dialog_content = "（看他氣急敗壞的樣子，難道他的目的真的只有看書？）",
  str_homestory_819101001_0_dialog_content = "哈提？",
  str_homestory_819101001_1_dialog_content = "妳在做什麼？",
  str_homestory_819101001_2_dialog_content = "剛才在和書架上的書對話。",
  str_homestory_819101001_3_dialog_content = "啊？和書怎麼對話？<sprite=emo_yihuo size=60 />",
  str_homestory_819101001_4_dialog_content = "你只要問問題，答案就會顯示在書頁上，而且都真實得恐怖。",
  str_homestory_819101001_5_dialog_content = "妳問了什麼問題？",
  str_homestory_819101001_6_dialog_content = "我想聽故事，就請答案書講故事給我聽。",
  str_homestory_819101001_7_dialog_content = "是恐怖故事嗎？什麼樣的故事？",
  str_homestory_819101001_8_dialog_content = "你不害怕？",
  str_homestory_819101001_9_option_content = "有點害怕",
  str_homestory_819101001_10_dialog_content = "但是又有點好奇。",
  str_homestory_819101001_11_option_content = "不害怕呀",
  str_homestory_819101001_12_dialog_content = "堂堂男子漢怎麼可能怕一本書？",
  str_homestory_819101001_13_dialog_content = "它剛才說的故事是這樣的——",
  str_homestory_819101001_14_dialog_content = "「在一個寒冬的夜晚，你獨自在書架前看書。」",
  str_homestory_819101001_15_dialog_content = "「突然你感覺到背後有動靜，這時你面前的答案書緩緩顯示出一行字——」",
  str_homestory_819101001_16_dialog_content = "「別回頭，你背後<size=45>有人</size>。」",
  str_homestory_819101001_17_dialog_content = "「你心裡很害怕，但還是忍不住回頭看了一眼。」",
  str_homestory_819101001_18_dialog_content = "剛看到這裡，我回頭就看見你正往這邊走來。",
  str_homestory_819101001_19_dialog_content = "哈哈，老套的懸疑小說開頭，不過居然還會結合真實場景，然後呢？",
  str_homestory_819101001_20_dialog_content = "「背後不是別人，而是你的房東。」",
  str_homestory_819101001_21_dialog_content = "「你放下心來，因為房東很弱，你一拳就可以把他打倒。」",
  str_homestory_819101001_22_dialog_content = "什麼啊！這個答案書根本就是亂掰的！",
  str_homestory_819101001_23_dialog_content = "不得不說非常符合真實情況，所以我完全沉迷其中了——",
  str_homestory_819101001_24_dialog_content = "「你責怪房東在背後嚇你，輕輕打了他一拳。」",
  str_homestory_819101001_25_dialog_content = "「房東被你打倒在地，而你被掃地出門，流落街頭，感染風寒而死。」",
  str_homestory_819101001_26_dialog_content = "你看，這個故事果然真實得恐怖。房東先生，我不會打你的。",
  str_homestory_819101001_27_dialog_content = "我也不會趕妳出去呀。不對，我才不可能被妳一拳打倒！",
  str_homestory_819101001_28_dialog_content = "要試試看嗎？",
  str_homestory_819101001_29_dialog_content = "當然！<sprite=emo_dianzan size=60 />",
  str_homestory_819101001_30_dialog_content = "等一下，我活動一下手臂。",
  str_homestory_819101001_31_dialog_content = "我、我是說我要試試這本答案書。",
  str_homestory_819101001_32_dialog_content = "你要問什麼？",
  str_homestory_819101001_33_dialog_content = "真的能回答任何問題嗎？",
  str_homestory_819101001_34_dialog_content = "最近的確有點苦惱，薇絲逼我統計巨像這個月的收支……",
  str_homestory_819101001_35_dialog_content = "剛才在餐廳聽到你們說這件事了。",
  str_homestory_819101001_36_dialog_content = "所以我一開始就問了答案書這個問題，它的回答是——",
  str_homestory_819101001_37_dialog_content = "「我只是本書，沒有資產，所以也不能幫你整理資產表。」",
  str_homestory_819101001_38_dialog_content = "呿，我還以為這本書真的這麼厲害呢。",
  str_homestory_819101001_39_dialog_content = "這個問題用不著答案書，我就可以給你答案。",
  str_homestory_819101001_40_dialog_content = "什麼答案？",
  str_homestory_819101001_41_dialog_content = "巨像收支嚴重失衡，你快要破產了，最終流落街頭，感染風寒而死。",
  str_homestory_819101001_42_dialog_content = "別照抄答案書的回答啊！",
  str_homestory_819101001_43_dialog_content = "因為很符合真實情況。",
  str_homestory_819101001_44_dialog_content = "一點也不符合……吧？嗚嗚嗚……",
  str_homestory_817702001_0_dialog_content = "歌爾蒂在唱歌耶！",
  str_homestory_817702001_1_dialog_content = "啦啦啦～♪",
  str_homestory_817702001_2_dialog_content = "……咦？這不是PlayerName嗎？你好呀～",
  str_homestory_817702001_3_dialog_content = "妳好，歌爾蒂！",
  str_homestory_817702001_4_dialog_content = "抱歉，我是不是打擾到妳了？",
  str_homestory_817702001_5_dialog_content = "沒這回事喔！",
  str_homestory_817702001_6_dialog_content = "我只是看到這把小提琴，就不由自主地唱起來啦。",
  str_homestory_817702001_7_dialog_content = "話說，PlayerName你居然會有小提琴。",
  str_homestory_817702001_8_dialog_content = "難道說……你其實對樂器有興趣嗎？",
  str_homestory_817702001_9_option_content = "有興趣",
  str_homestory_817702001_10_dialog_content = "嗯，我很喜歡樂器！",
  str_homestory_817702001_11_dialog_content = "不過只是有興趣，我根本不會任何樂器，嘿嘿……",
  str_homestory_817702001_12_dialog_content = "那可真是太好了～",
  str_homestory_817702001_13_dialog_content = "我和PlayerName的共同話題又增加了呢！",
  str_homestory_817702001_14_option_content = "還好",
  str_homestory_817702001_15_dialog_content = "嗯～還行吧，說不上喜歡……",
  str_homestory_817702001_16_dialog_content = "不過如果能學會樂器的話……我會演奏給歌爾蒂聽的！",
  str_homestory_817702001_17_dialog_content = "真的嗎？嘿嘿，謝謝你！",
  str_homestory_817702001_18_dialog_content = "不過其實……",
  str_homestory_817702001_19_dialog_content = "這把小提琴並不是一把普通的樂器。",
  str_homestory_817702001_20_dialog_content = "而是某個知名偵探的同款珍品！",
  str_homestory_817702001_21_dialog_content = "偵探？",
  str_homestory_817702001_22_dialog_content = "嗯，據說那個大偵探，在辦案之餘非常喜歡演奏小提琴。",
  str_homestory_817702001_23_dialog_content = "詳細情況我也不是很瞭解……",
  str_homestory_817702001_24_dialog_content = "不過這種多才多藝的偵探，總覺得很浪漫<sprite=emo_aixin size=60 />啊！",
  str_homestory_817702001_25_dialog_content = "原來如此～",
  str_homestory_817702001_26_dialog_content = "看似理性冷酷的偵探，卻也會在夜深人靜時獨自演奏小提琴……",
  str_homestory_817702001_27_dialog_content = "這個畫面……嗯，我有靈感了！",
  str_homestory_817702001_28_dialog_content = "什麼靈感？",
  str_homestory_817702001_29_dialog_content = "新曲子<sprite=emo_yinfu size=60 />的靈感！",
  str_homestory_817702001_30_dialog_content = "到時候還可以製作新的演出服，再配上特殊的編舞。",
  str_homestory_817702001_31_dialog_content = "想想就令人興奮！",
  str_homestory_817702001_32_dialog_content = "偵探主題的偶像演唱會……",
  str_homestory_817702001_33_dialog_content = "感覺會很棒耶！",
  str_homestory_817702001_34_dialog_content = "真不愧是歌爾蒂！",
  str_homestory_817702001_35_dialog_content = "嘿嘿～到時候，你也一定要來捧場哦！",
  str_homestory_811602001_0_dialog_content = "弗勞爾在幹什麼呢？",
  str_homestory_811602001_1_dialog_content = "嗨，弗勞爾！你在做什麼呢？",
  str_homestory_811602001_2_dialog_content = "嗨，導航員！",
  str_homestory_811602001_3_dialog_content = "我在調整這個擺飾。",
  str_homestory_811602001_4_dialog_content = "剛剛我隨手拿起來玩了一下……",
  str_homestory_811602001_5_dialog_content = "結果發現它的聲音不太對勁。",
  str_homestory_811602001_6_dialog_content = "聲音？",
  str_homestory_811602001_7_dialog_content = "對，或許是哪個螺絲太緊了，也可能是潤滑不夠了……",
  str_homestory_811602001_8_dialog_content = "輪子總是會「咯吱咯吱」地響。",
  str_homestory_811602001_9_option_content = "原來如此",
  str_homestory_811602001_10_dialog_content = "看來這個擺飾的確有點問題……",
  str_homestory_811602001_11_dialog_content = "會發出這種聲音，是不是代表零件的狀態不太對？",
  str_homestory_811602001_12_dialog_content = "對！",
  str_homestory_811602001_13_dialog_content = "這種問題一般人很難理解，看來你也有修理機械的天賦啊。",
  str_homestory_811602001_14_dialog_content = "是這樣嗎？嘿嘿嘿～",
  str_homestory_811602001_15_option_content = "我不懂",
  str_homestory_811602001_16_dialog_content = "這樣啊……",
  str_homestory_811602001_17_dialog_content = "弗勞爾這樣的專家就是厲害，我這種外行人就完全不懂。",
  str_homestory_811602001_18_dialog_content = "好吧……本來以為能和你聊聊機械的問題呢。",
  str_homestory_811602001_19_dialog_content = "沒事，我自己也能把它修好的。",
  str_homestory_811602001_20_dialog_content = "嗯……看來的確是這裡的螺絲有點緊……",
  str_homestory_811602001_21_dialog_content = "可惜我手頭沒有適合的工具。",
  str_homestory_811602001_22_dialog_content = "等我找到了，再回來修理它吧。",
  str_homestory_811602001_23_dialog_content = "那就麻煩你了！",
  str_homestory_811602001_24_dialog_content = "沒事，畢竟也不是什麼大問題。",
  str_homestory_811602001_25_dialog_content = "不過對於機械來說，疏忽這種細節有時才是最致命的。",
  str_homestory_811602001_26_dialog_content = "幸好這只是個小擺飾，如果是一輛真的手推車……",
  str_homestory_811602001_27_dialog_content = "可能現在輪子已經壞了吧，哈哈哈。",
  str_homestory_811602001_28_dialog_content = "是啊，我們這種普通人，都是等東西真的壞了才知道要修。",
  str_homestory_811602001_29_dialog_content = "如果機械都能像臨空者號一樣，能自己把問題說出來就好了。",
  str_homestory_811602001_30_dialog_content = "是嗎……？",
  str_homestory_811602001_31_dialog_content = "我倒是覺得，人們說的話更難懂<sprite=emo_sikao size=60 />。",
  str_homestory_811602001_32_dialog_content = "能將「人格」賦予機械，的確是個偉大之舉……",
  str_homestory_811602001_33_dialog_content = "但我真的不希望機械也染上那種說話拐彎抹角的壞習慣啊！",
  str_homestory_811602001_34_dialog_content = "哈哈哈……說得也是。",
  str_homestory_811602001_35_dialog_content = "如果哪天機械也都有了個性，弗勞爾一定會很頭痛吧！",
  str_homestory_808401001_0_dialog_content = "伊斯塔萬也喜歡解謎嗎？",
  str_homestory_808401001_1_dialog_content = "你來了，來得正好。",
  str_homestory_808401001_2_dialog_content = "你怎麼看待這幅線索圖？",
  str_homestory_808401001_3_dialog_content = "我怎麼看？我……",
  str_homestory_808401001_4_option_content = "有點頭緒",
  str_homestory_808401001_5_dialog_content = "我覺得其中幾道線索有點可疑<sprite=emo_sikao size=60 />。",
  str_homestory_808401001_6_dialog_content = "再給我點時間，說不定我能想出答案！",
  str_homestory_808401001_7_option_content = "看不懂",
  str_homestory_808401001_8_dialog_content = "嗯……我不太擅長解謎<sprite=emo_tanqi size=60 />。",
  str_homestory_808401001_9_dialog_content = "完全看不懂……",
  str_homestory_808401001_10_dialog_content = "原來如此。",
  str_homestory_808401001_11_dialog_content = "抱歉，明明是你先問我的，我卻回了你一個新問題。",
  str_homestory_808401001_12_dialog_content = "現在我來解答你的疑惑吧……",
  str_homestory_808401001_13_dialog_content = "答案是，我不喜歡解謎。",
  str_homestory_808401001_14_dialog_content = "嗯？那為什麼伊斯塔萬還要盯著推理黑板看呢？",
  str_homestory_808401001_15_dialog_content = "別急，年輕人，讓我慢慢解答你的疑惑。",
  str_homestory_808401001_16_dialog_content = "從剛剛的談話來看，你是把這幅線索圖當做一道「謎題」。",
  str_homestory_808401001_17_dialog_content = "也就是說，你不自覺地將自己代入了「偵探」的視角。",
  str_homestory_808401001_18_dialog_content = "對，沒錯。",
  str_homestory_808401001_19_dialog_content = "但實際上，在這盤「棋局」中，有許許多多不同的角色。",
  str_homestory_808401001_20_dialog_content = "「偵探」、「罪犯」、「受害者」……",
  str_homestory_808401001_21_dialog_content = "還有「推手」。",
  str_homestory_808401001_22_dialog_content = "「推手」？",
  str_homestory_808401001_23_dialog_content = "推手，如同牧人，是一切的締造者，也應是一切的得利者。",
  str_homestory_808401001_24_dialog_content = "驅犬牧羊、收攏羊群、逐狼護羊……",
  str_homestory_808401001_25_dialog_content = "好的牧人，從不會將牧場放手交於天命。",
  str_homestory_808401001_26_dialog_content = "所以推手也從不解謎，他會主動選擇對自己有利的謎底。",
  str_homestory_808401001_27_dialog_content = "嗯、嗯～好複雜啊！",
  str_homestory_808401001_28_dialog_content = "伊斯塔萬的意思是不是……",
  str_homestory_808401001_29_dialog_content = "像伊斯塔萬這樣的領導者，比起真相，更注重結果？",
  str_homestory_808401001_30_dialog_content = "沒錯，你理解得很正確。",
  str_homestory_808401001_31_dialog_content = "雖然你還年輕，有很多種可能性。",
  str_homestory_808401001_32_dialog_content = "但我更希望，你這樣的領航者能學會驅動棋子，為自己所用。",
  str_homestory_808401001_33_dialog_content = "而不是像羔羊一般，沉溺於小聰明帶來的快意。",
  str_homestory_808401001_34_dialog_content = "哈哈、哈哈哈……我覺得這種事，對我來說還有點早……",
  str_homestory_808401001_35_dialog_content = "……說得也是，沒必要急著挫傷你的衝勁。",
  str_homestory_808401001_36_dialog_content = "那麼，還是來一場具有少年氣息的冒險吧。",
  str_homestory_808401001_37_dialog_content = "剛才我在河邊，看到河裡有一枚閃閃發光的錢幣<sprite=emo_baiyebi size=60 />。",
  str_homestory_808401001_38_dialog_content = "雖然看不清楚，但以我的眼光判斷，那會是個稀有玩意。",
  str_homestory_808401001_39_dialog_content = "去找找看吧。",
  str_homestory_808401001_40_dialog_content = "謝謝你，伊斯塔萬！",
  str_homestory_819301001_0_dialog_content = "克莉絲汀？",
  str_homestory_819301001_1_dialog_content = "克莉絲汀，在幹什麼？",
  str_homestory_819301001_2_dialog_content = "哼～哼哼～<sprite=emo_yinfu size=60 />",
  str_homestory_819301001_3_dialog_content = "我在聽音樂呀～",
  str_homestory_819301001_4_dialog_content = "您的唱片機很漂亮，於是我試了一下。",
  str_homestory_819301001_5_dialog_content = "感覺怎麼樣？",
  str_homestory_819301001_6_dialog_content = "非常好！音質優美動聽，是台很不錯的唱片機。",
  str_homestory_819301001_7_dialog_content = "PlayerName什麼時候有這個愛好的？",
  str_homestory_819301001_8_dialog_content = "偶爾我會收集一些四處看到的精美物品。",
  str_homestory_819301001_9_dialog_content = "不過克莉絲汀應該見過很多類似的唱片機了吧？",
  str_homestory_819301001_10_dialog_content = "嗯，我家族的莊園裡收藏了許多唱片機，其中有一台很特別。",
  str_homestory_819301001_11_dialog_content = "大概——",
  str_homestory_819301001_12_dialog_content = "有審判庭的門廊那麼高。",
  str_homestory_819301001_13_dialog_content = "什、什麼？",
  str_homestory_819301001_14_dialog_content = "審判庭門廊……豈不是超大的嗎？",
  str_homestory_819301001_15_dialog_content = "根本可以當演出舞臺了吧！",
  str_homestory_819301001_16_dialog_content = "我父親那種貴族的喜好，有時候就是這麼難以捉摸～",
  str_homestory_819301001_17_dialog_content = "明明克莉絲汀也是貴族……",
  str_homestory_819301001_18_dialog_content = "啊，我和我父親可不一樣喔～",
  str_homestory_819301001_19_dialog_content = "PlayerName覺得我和那些老貴族一樣嗎？",
  str_homestory_819301001_20_option_content = "不一樣",
  str_homestory_819301001_21_dialog_content = "克莉絲汀喜歡追逐一些新潮的東西。",
  str_homestory_819301001_22_dialog_content = "比如在音樂方面。",
  str_homestory_819301001_23_option_content = "有時一樣",
  str_homestory_819301001_24_dialog_content = "克莉絲汀十分有教養，就像我見到的那些貴族。",
  str_homestory_819301001_25_dialog_content = "嗯～原來PlayerName是這麼想的啊～",
  str_homestory_819301001_26_dialog_content = "不過我認為你說得沒錯。",
  str_homestory_819301001_27_dialog_content = "雖然我的身體裡流著貴族的血——",
  str_homestory_819301001_28_dialog_content = "但我內心希望能走出不一樣的路。",
  str_homestory_819301001_29_dialog_content = "就從新潮的音樂開始，我有新的靈感了！",
  str_homestory_819301001_30_dialog_content = "等一下！",
  str_homestory_819301001_31_dialog_content = "克莉絲汀要在這裡演唱嗎？",
  str_homestory_819301001_32_dialog_content = "是的，隨著唱片機的音樂，正適合高歌一曲，啦～<sprite=emo_yinfu size=60 />",
  str_homestory_819301001_33_dialog_content = "稍等！",
  str_homestory_819301001_34_dialog_content = "剛看一下時間，我好像有事，先走了。",
  str_homestory_819301001_35_dialog_content = "現在嗎？",
  str_homestory_819301001_36_dialog_content = "嗯……妳隨意！盡情演唱吧！",
  str_homestory_819201001_0_dialog_content = "李奧？",
  str_homestory_819201001_1_dialog_content = "正好想找一個放大鏡，居然在這裡找到了。",
  str_homestory_819201001_2_dialog_content = "你要用來做什麼？",
  str_homestory_819201001_3_dialog_content = "查看地圖。",
  str_homestory_819201001_4_dialog_content = "之前我叫部下探查了邊境地區各個軍事要塞的位置。",
  str_homestory_819201001_5_dialog_content = "今天剛好繪製完成，他們就送來給我了。",
  str_homestory_819201001_6_dialog_content = "但是這上面的手寫字體又小又潦草，看得我頭都痛了<sprite=emo_xuanyun size=60 />。",
  str_homestory_819201001_7_dialog_content = "地圖上面會寫很多字嗎？",
  str_homestory_819201001_8_dialog_content = "你看看。",
  str_homestory_819201001_9_dialog_content = "《關於黃昏鎮方圓80公里的軍事要塞的探查展示分析其……》",
  str_homestory_819201001_10_dialog_content = "第二行還有。",
  str_homestory_819201001_11_dialog_content = "《……空間分布、數量品質特徵及相互關係等資訊的地圖》。",
  str_homestory_819201001_12_dialog_content = "呼……呼……<sprite=emo_kun size=60 />",
  str_homestory_819201001_13_dialog_content = "地……地圖的名稱都……這麼複雜嗎？",
  str_homestory_819201001_14_dialog_content = "一口氣唸完都差點喘不過氣了。",
  str_homestory_819201001_15_dialog_content = "當然不是，只不過這次的製圖員特別嚴謹，以致於寫了很多……",
  str_homestory_819201001_16_dialog_content = "不必要的話。",
  str_homestory_819201001_17_dialog_content = "怪不得很多軍事家都會隨身帶一個放大鏡。",
  str_homestory_819201001_18_dialog_content = "萬一遇上這種「嚴謹」的製圖員就能看清楚字了。",
  str_homestory_819201001_19_dialog_content = "（不過看清楚了大概會更生氣吧。）",
  str_homestory_819201001_20_dialog_content = "的確有很多將領喜歡用放大鏡。",
  str_homestory_819201001_21_dialog_content = "它既可以放大文字和圖片，方便閱讀，還可以在白天用來生火。",
  str_homestory_819201001_22_dialog_content = "可謂是一物多用，行軍必備。",
  str_homestory_819201001_23_dialog_content = "不過我對放大鏡的好處持保留意見。",
  str_homestory_819201001_24_dialog_content = "為什麼？",
  str_homestory_819201001_25_dialog_content = "你也是指揮大家作戰的領袖，不妨猜猜我的理由？",
  str_homestory_819201001_26_option_content = "依賴光線",
  str_homestory_819201001_27_dialog_content = "如果在夜晚或暗面，就很難使用了。",
  str_homestory_819201001_28_dialog_content = "這的確是個問題，不過只要準備好光源就沒有問題。",
  str_homestory_819201001_29_option_content = "會使視野受到侷限",
  str_homestory_819201001_30_dialog_content = "沒錯。",
  str_homestory_819201001_31_dialog_content = "放大鏡會放大局部，讓觀察者可以更加清楚地觀察細節。",
  str_homestory_819201001_32_dialog_content = "但同時觀察者的視野也被限制在放大鏡的範圍內。",
  str_homestory_819201001_33_dialog_content = "無法觀察更廣闊的周圍環境。",
  str_homestory_819201001_34_dialog_content = "但戰爭往往需要從宏觀的角度去部署。",
  str_homestory_819201001_35_dialog_content = "為了不讓自己的視野過於集中，我有時候會刻意不去使用放大鏡。",
  str_homestory_819201001_36_dialog_content = "真不愧是一個合格的戰略家。",
  str_homestory_819201001_37_dialog_content = "這不過是個人習慣罷了，比如現在我也不得不借助放大鏡。",
  str_homestory_819201001_38_dialog_content = "這裡的放大鏡你可以隨便使用。",
  str_homestory_819201001_39_dialog_content = "不過用完之後請務必放到專用盒子中保管。",
  str_homestory_819201001_40_dialog_content = "若是被陽光直射，搞不好會引發火災<sprite=emo_nuhuo size=60 />。",
  str_homestory_819201001_41_dialog_content = "哈哈，防火意識真強。",
  str_homestory_819201001_42_dialog_content = "這畢竟是我辛辛苦苦建立的家園嘛。",
  str_homestory_819201001_43_dialog_content = "要是燒起來了我的錢……呃，心血就白費了。",
  str_homestory_819901001_0_dialog_content = "鶯歌？",
  str_homestory_819901001_1_dialog_content = "是你啊，PlayerName，我正準備品嚐咖啡。",
  str_homestory_819901001_2_dialog_content = "是鶯歌自己泡的咖啡嗎？",
  str_homestory_819901001_3_dialog_content = "沒錯。",
  str_homestory_819901001_4_dialog_content = "剛才看到了這個漂亮的咖啡杯，於是我就自己嘗試泡了一杯。",
  str_homestory_819901001_5_dialog_content = "聞起來好香啊～<sprite=emo_dianzan size=60 />",
  str_homestory_819901001_6_dialog_content = "看到上面的拉花了嗎？這個是拿鐵咖啡。",
  str_homestory_819901001_7_dialog_content = "啊，看到了，上面有漂亮的花紋！",
  str_homestory_819901001_8_dialog_content = "這個形狀好像是……藍波？",
  str_homestory_819901001_9_dialog_content = "能看出來是藍波嗎？嗯，那這次的嘗試倒不算失敗。",
  str_homestory_819901001_10_dialog_content = "當然不算失敗！太厲害了！",
  str_homestory_819901001_11_dialog_content = "鶯歌是怎麼做到的？",
  str_homestory_819901001_12_dialog_content = "拿鐵咖啡的製作並不困難，材料也很簡單。",
  str_homestory_819901001_13_dialog_content = "首先需要在咖啡杯中放入一小杯濃縮咖啡……",
  str_homestory_819901001_14_dialog_content = "然後再加入用鮮牛奶打發的奶泡。",
  str_homestory_819901001_15_dialog_content = "加入奶泡時，透過移動奶泡杯的位置調整造型——",
  str_homestory_819901001_16_dialog_content = "最後就能得到一杯有漂亮拉花的拿鐵咖啡。",
  str_homestory_819901001_17_dialog_content = "鶯歌說起來很容易，但是做起來一定沒那麼簡單吧……",
  str_homestory_819901001_18_dialog_content = "熟能生巧，多練習幾次就好。",
  str_homestory_819901001_19_dialog_content = "當我在工作時感到疲勞，就會為自己泡一杯拿鐵咖啡。",
  str_homestory_819901001_20_dialog_content = "絲滑的牛奶與香醇的咖啡是完美的搭配。",
  str_homestory_819901001_21_dialog_content = "PlayerName想品嚐看看嗎？<sprite=emo_yaosu size=60 />",
  str_homestory_819901001_22_option_content = "想嚐嚐看",
  str_homestory_819901001_23_dialog_content = "畢竟是鶯歌親手做的咖啡。",
  str_homestory_819901001_24_option_content = "不太想",
  str_homestory_819901001_25_dialog_content = "我怕喝了咖啡會失眠。",
  str_homestory_819901001_26_dialog_content = "牛奶的比例在三分之二以上，嚐一下不會失眠的。",
  str_homestory_819901001_27_dialog_content = "這樣嗎？那我也想嚐嚐看。",
  str_homestory_819901001_28_dialog_content = "味道怎麼樣？",
  str_homestory_819901001_29_dialog_content = "十分美味！",
  str_homestory_819901001_30_dialog_content = "要是我也能做出這麼好喝的拿鐵咖啡就好了。",
  str_homestory_819901001_31_dialog_content = "我支持你嘗試製作看看，一定可以的。",
  str_homestory_819901001_32_dialog_content = "不過，牛奶好像被我用光了……",
  str_homestory_819901001_33_dialog_content = "咦，已經沒有了嗎？",
  str_homestory_819901001_34_dialog_content = "我剛才十分口渴，於是都喝掉了。",
  str_homestory_819901001_35_dialog_content = "咳咳，鶯歌，牛奶不能當水喝啊……",
  str_homestory_820001001_0_dialog_content = "阿納托利在盯著戶外燈看？",
  str_homestory_820001001_1_dialog_content = "阿納托利，你在幹什麼？",
  str_homestory_820001001_2_dialog_content = "我在觀察這盞燈。",
  str_homestory_820001001_3_option_content = "觀察燈？",
  str_homestory_820001001_4_dialog_content = "我發現就算在白天，這盞燈也依舊亮著。",
  str_homestory_820001001_5_dialog_content = "雖然它發出的光芒遠不及陽光那樣耀眼，卻還是沒有熄滅。",
  str_homestory_820001001_6_dialog_content = "究竟是誰在不停地為它補充燈油呢？",
  str_homestory_820001001_7_dialog_content = "這我也不知道……",
  str_homestory_820001001_8_option_content = "為什麼？",
  str_homestory_820001001_9_dialog_content = "因為它一直亮著，不分晝夜。",
  str_homestory_820001001_10_dialog_content = "雖然白天的時候毫不起眼，卻會在晚上照亮黑暗<sprite=emo_taiyang size=60 />。",
  str_homestory_820001001_11_dialog_content = "確實！",
  str_homestory_820001001_12_dialog_content = "晚上如果能有一盞燈照亮道路，就會很方便！",
  str_homestory_820001001_13_dialog_content = "不過，這盞燈就算白天也一直亮著，感覺有點浪費。",
  str_homestory_820001001_14_dialog_content = "嗯……的確是如此。",
  str_homestory_820001001_15_dialog_content = "畢竟這裡不是永夜，不需要一直點燈照明。",
  str_homestory_820001001_16_dialog_content = "那我就先熄滅它吧，等晚上再點起來。",
  str_homestory_820001001_17_dialog_content = "還是讓它亮著比較好。",
  str_homestory_820001001_18_dialog_content = "咦？為什麼？",
  str_homestory_820001001_19_dialog_content = "不管是誰一直在為這盞燈補油，那個人應該都有自己的目的。",
  str_homestory_820001001_20_dialog_content = "還是不要打擾那個人了。",
  str_homestory_820001001_21_dialog_content = "你說的有道理。",
  str_homestory_820001001_22_dialog_content = "真好奇這個人是誰啊！",
  str_homestory_820001001_23_dialog_content = "那就多來看看吧，或許總有一天會遇到的。",
  str_homestory_820001001_24_dialog_content = "我記得阿納托利很擅長推理和分析……",
  str_homestory_820001001_25_dialog_content = "對於這個人的身分，你有什麼看法嗎？",
  str_homestory_820001001_26_dialog_content = "我確實有一些推測。",
  str_homestory_820001001_27_dialog_content = "說說看？",
  str_homestory_820001001_28_dialog_content = "這個人應該很有耐心，能夠長期堅持做一件事。",
  str_homestory_820001001_29_dialog_content = "並且這個人的記憶力應該很好，不會遺忘這種小事。",
  str_homestory_820001001_30_dialog_content = "最後，這個人可能很喜歡能夠發出微小光芒的物體。",
  str_homestory_820001001_31_dialog_content = "嗯，有道理……",
  str_homestory_820001001_32_dialog_content = "這確實讓我想到幾個可能的人。",
  str_homestory_820001001_33_dialog_content = "等等，我想到了！",
  str_homestory_820001001_34_dialog_content = "你說的這個人，不就是你自己嗎？！",
  str_homestory_820001001_35_dialog_content = "你的推測是正確的。",
  str_homestory_820001001_36_dialog_content = "為什麼你要讓這盞燈一直亮著啊？",
  str_homestory_820001001_37_dialog_content = "明明現在是大白天，不需要用燈照明。",
  str_homestory_820001001_38_dialog_content = "就算是會被陽光掩蓋的弱小光芒，也有只有它能做到的事。",
  str_homestory_820001001_39_dialog_content = "我是這樣相信的。",
  str_homestory_802801001_0_dialog_content = "這聲音該不會是？",
  str_homestory_802801001_1_dialog_content = "果然是拉斐爾呢！",
  str_homestory_802801001_2_dialog_content = "咻！咻！咻——！",
  str_homestory_802801001_3_dialog_content = "PlayerName，遇到你真是太好啦！",
  str_homestory_802801001_4_dialog_content = "嚐嚐我新發明的「神奇能量片」！",
  str_homestory_802801001_5_dialog_content = "它可以讓你瞬間能量滿滿！或許還能感應到神奇的珍寶喔！",
  str_homestory_802801001_6_dialog_content = "限量版！只此一顆！",
  str_homestory_802801001_7_option_content = "不、不必了吧……",
  str_homestory_802801001_8_dialog_content = "拉斐爾四處逛了好一陣子了，終於找到實驗對象了呢！",
  str_homestory_802801001_9_dialog_content = "你也不想讓我失敗而歸吧！",
  str_homestory_802801001_10_dialog_content = "老實說，我沒想過……",
  str_homestory_802801001_11_option_content = "讓我試試！",
  str_homestory_802801001_12_dialog_content = "嘿嘿！今天的PlayerName答應得意外爽快呢！",
  str_homestory_802801001_13_dialog_content = "那明天再多帶一些給你吧！",
  str_homestory_802801001_14_dialog_content = "不是，妳這麼閒的嗎？",
  str_homestory_802801001_15_dialog_content = "快張開嘴吧，啊——",
  str_homestory_802801001_16_dialog_content = "等、等等！",
  str_homestory_802801001_17_dialog_content = "這個氣味，該不會是用薇絲的料理做的吧？",
  str_homestory_802801001_18_dialog_content = "（呃、煮到焦掉的那種……<sprite=emo_hanshui size=60 />）",
  str_homestory_802801001_19_dialog_content = "咦？！拉斐爾有這麼可靠嗎？",
  str_homestory_802801001_20_dialog_content = "呃、我的意思……其實是……",
  str_homestory_802801001_21_dialog_content = "我明白的、我明白的，PlayerName喜歡可靠的夥伴呢！",
  str_homestory_802801001_22_dialog_content = "拉斐爾！也在努力成為一名——無比、可靠的、夥伴呢！",
  str_homestory_802801001_23_dialog_content = "會做「神奇能量片」的那種——",
  str_homestory_802801001_24_dialog_content = "嘿嘿，稍微有些不好意思了呢。",
  str_homestory_802801001_25_dialog_content = "（意外地樂觀呢……）",
  str_homestory_802801001_26_dialog_content = "這樣吧，拉斐爾，妳先多做一點，改天讓卡蓮也一起試試！",
  str_homestory_802801001_27_dialog_content = "她比較辛苦，或許也很需要「神奇能量片」。",
  str_homestory_802801001_28_dialog_content = "咦？卡蓮姐姐嗎……？",
  str_homestory_802801001_29_dialog_content = "拉斐爾不這麼認為喔～",
  str_homestory_802801001_30_dialog_content = "為什麼這麼說呢？",
  str_homestory_802801001_31_dialog_content = "因為、如果是卡蓮姐姐的話，她一定會說——",
  str_homestory_802801001_32_dialog_content = "「拉斐爾！不要再叫我吃奇怪的糖果了，別問為什麼。」",
  str_homestory_802801001_33_dialog_content = "為什麼？",
  str_homestory_802801001_34_dialog_content = "拉斐爾也想知道呢<sprite=emo_sikao size=60 />～但卡蓮姐姐不准拉斐爾問。",
  str_homestory_802801001_35_dialog_content = "還有喔～還有喔～",
  str_homestory_802801001_36_dialog_content = "這可是專門為有感應能力的PlayerName量身定做的呢！",
  str_homestory_802801001_37_dialog_content = "這樣啊，我明白了，那妳給我吧！",
  str_homestory_802801001_38_dialog_content = "（既然是糖果……）",
  str_homestory_802801001_39_dialog_content = "嘿嘿！我就知道，給PlayerName是最適合的！",
  str_homestory_802801001_40_dialog_content = "怎麼樣？怎麼樣？身體有變化嗎？！",
  str_homestory_802801001_41_dialog_content = "有沒有看到什麼閃亮亮的東西？",
  str_homestory_802801001_42_dialog_content = "視野好像確實清晰了不少，能看到更遠的地方——",
  str_homestory_802801001_43_dialog_content = "河裡！確實有閃亮亮的東西！",
  str_homestory_802801001_44_dialog_content = "是吧！是吧！拉斐爾就知道！",
  str_homestory_802801001_45_dialog_content = "「神奇能量片」實驗成功——！<sprite=emo_aixin size=60 />",
  str_homestory_820201001_0_dialog_content = "您怎麼在這裡？",
  str_homestory_820201001_1_dialog_content = "你來了。",
  str_homestory_820201001_2_dialog_content = "這王座，是特地為我準備的吧？",
  str_homestory_820201001_3_dialog_content = "沒……沒錯。",
  str_homestory_820201001_4_dialog_content = "嗯，我認可你的用心。",
  str_homestory_820201001_5_dialog_content = "雖然無法與高庭的正統王座相提並論……",
  str_homestory_820201001_6_dialog_content = "但也只有此等規格配得上我的身分。",
  str_homestory_820201001_7_dialog_content = "您滿意就好！",
  str_homestory_820201001_8_dialog_content = "請問您還有什麼需要嗎？",
  str_homestory_820201001_9_dialog_content = "在此處重新打造一座白夜城的宮殿如何？<sprite=emo_sikao size=60 />",
  str_homestory_820201001_10_dialog_content = "既然有了王座，應當有與之相稱的宮殿才行。",
  str_homestory_820201001_11_dialog_content = "您想在這裡建造一座宮殿嗎？",
  str_homestory_820201001_12_dialog_content = "我這裡會不會太小了？",
  str_homestory_820201001_13_dialog_content = "嗯……如此說來，這裡除了簡陋，也不夠寬闊。",
  str_homestory_820201001_14_dialog_content = "我為你出資，修繕一番如何？",
  str_homestory_820201001_15_option_content = "不用了",
  str_homestory_820201001_16_dialog_content = "您的心意，我收到了。",
  str_homestory_820201001_17_option_content = "可以嗎？",
  str_homestory_820201001_18_dialog_content = "擴建的話除了物力，還需要不少人力……",
  str_homestory_820201001_19_dialog_content = "您只是來小坐的話，似乎不需要這麼費心。",
  str_homestory_820201001_20_dialog_content = "對我來講，不過是小事一樁。",
  str_homestory_820201001_21_dialog_content = "既然你不需要，那便算了。",
  str_homestory_820201001_22_dialog_content = "且慢，我好像聞到了什麼……<sprite=emo_wuzui size=60 />",
  str_homestory_820201001_23_dialog_content = "什麼？奇怪的味道嗎？",
  str_homestory_820201001_24_dialog_content = "咦，又好像什麼都沒聞到。",
  str_homestory_820201001_25_dialog_content = "沒錯，這正是缺失的地方。",
  str_homestory_820201001_26_dialog_content = "你應當補充一些優美的香氛，讓空氣裡洋溢著整潔乾淨的味道。",
  str_homestory_820201001_27_dialog_content = "我對香氛不太感興趣……",
  str_homestory_820201001_28_dialog_content = "客人走進此處，首先沒有優雅的氣息迎接——",
  str_homestory_820201001_29_dialog_content = "實在是有失體面！",
  str_homestory_820201001_30_dialog_content = "既然如此，我便差人送些過來吧。",
  str_homestory_820201001_31_dialog_content = "待我再臨此處之時，希望有所改善。",
  str_homestory_820201001_32_dialog_content = "好的……",
  str_homestory_820301001_0_dialog_content = "加晴？",
  str_homestory_820301001_1_dialog_content = "原來如此……",
  str_homestory_820301001_2_dialog_content = "妳在做什麼？",
  str_homestory_820301001_3_dialog_content = "哎呀，你什麼時候過來的呀？",
  str_homestory_820301001_4_dialog_content = "剛才的占卜結果你都知道了？",
  str_homestory_820301001_5_dialog_content = "我剛過來而已，什麼都不知道。",
  str_homestory_820301001_6_dialog_content = "妳在占卜很祕密的事情嗎？",
  str_homestory_820301001_7_dialog_content = "真抱歉，我這就離開。",
  str_homestory_820301001_8_dialog_content = "是很祕密的事情呢，不過——",
  str_homestory_820301001_9_dialog_content = "跟你有關喔。",
  str_homestory_820301001_10_dialog_content = "啊？跟我有關？",
  str_homestory_820301001_11_dialog_content = "嗯嗯，我剛才聽見你和薇絲聊天喔。",
  str_homestory_820301001_12_dialog_content = "據說你最近的財務狀況不太好。",
  str_homestory_820301001_13_dialog_content = "這個嘛……手頭是有點緊。",
  str_homestory_820301001_14_dialog_content = "唔，我很擔心你呢，所以就替你占卜了。",
  str_homestory_820301001_15_dialog_content = "如果你介意的話，我就永遠保密占卜結果。",
  str_homestory_820301001_16_dialog_content = "沒關係啦，所以占卜結果是……",
  str_homestory_820301001_17_dialog_content = "嗯嗯，有關你將來的財務狀況——",
  str_homestory_820301001_18_dialog_content = "等一下，我還沒做好心理準備，萬一結果不好……",
  str_homestory_820301001_19_dialog_content = "我想告訴你的是，你會變得超級有錢！無憂無慮！天天開心！<sprite=emo_yaosu size=60 />",
  str_homestory_820301001_20_dialog_content = "真的嗎？！真的會這麼好嗎？！",
  str_homestory_820301001_21_dialog_content = "你相信嗎？",
  str_homestory_820301001_22_dialog_content = "哎？所以剛才是在騙我嗎？",
  str_homestory_820301001_23_dialog_content = "只要回答我，你相信這個結果嗎？",
  str_homestory_820301001_24_option_content = "相信",
  str_homestory_820301001_25_dialog_content = "正確！你有這樣的想法就是最棒的！",
  str_homestory_820301001_26_option_content = "不相信",
  str_homestory_820301001_27_dialog_content = "為什麼不相信？我要生氣了！",
  str_homestory_820301001_28_dialog_content = "「相信」的力量非常重要喔！",
  str_homestory_820301001_29_dialog_content = "當你相信一件事，事情就會朝著這個方向發展呢！",
  str_homestory_820301001_30_dialog_content = "可是這跟占卜有什麼關係？",
  str_homestory_820301001_31_dialog_content = "因為占卜的結果就是——",
  str_homestory_820301001_32_dialog_content = "把握當下喔～",
  str_homestory_820301001_33_dialog_content = "呃，聽起來占卜術比較像某種模棱兩可的話術。",
  str_homestory_820301001_34_dialog_content = "因為人生本來就是一條漫長的道路呀。",
  str_homestory_820301001_35_dialog_content = "這條路上面有很多岔路口。",
  str_homestory_820301001_36_dialog_content = "意味著你的決策將會影響你今後的道路呢。",
  str_homestory_820301001_37_dialog_content = "但是無論如何，我在你的路上看到了光明<sprite=emo_taiyang size=60 />喔。",
  str_homestory_820301001_38_dialog_content = "我知道了。",
  str_homestory_820301001_39_dialog_content = "未來充滿變數，而一切取決於現在。",
  str_homestory_820301001_40_dialog_content = "哇喔，說得真好，我要記在我的占卜手冊上。",
  str_homestory_820301001_41_dialog_content = "哈哈，不管怎麼說，跟你聊完我的心情好多啦。",
  str_homestory_809801001_0_dialog_content = "庫絲庫塔？",
  str_homestory_809801001_1_dialog_content = "庫絲庫塔，妳在看什麼？",
  str_homestory_809801001_2_dialog_content = "花<sprite=emo_huaduo size=60 />。",
  str_homestory_809801001_3_dialog_content = "花叢中的花，有的抬頭仰望，有的拒絕欣賞。",
  str_homestory_809801001_4_dialog_content = "我知道一種拒絕欣賞的花，「黑尾花」，你聽過嗎？",
  str_homestory_809801001_5_option_content = "聽過",
  str_homestory_809801001_6_dialog_content = "但是……為什麼是「拒絕欣賞」呢？",
  str_homestory_809801001_7_option_content = "沒聽過",
  str_homestory_809801001_8_dialog_content = "是怎樣的花呢？",
  str_homestory_809801001_9_dialog_content = "「黑尾花」很少見。",
  str_homestory_809801001_10_dialog_content = "它的花瓣嫩，顏色深，容易吸收陽光<sprite=emo_taiyang size=60 />。",
  str_homestory_809801001_11_dialog_content = "所以為了避免被高溫灼傷，通常蔭蔽在葉子下面。",
  str_homestory_809801001_12_dialog_content = "於是，它就成了拒絕欣賞的那一個。",
  str_homestory_809801001_13_dialog_content = "原來是這個意思……",
  str_homestory_809801001_14_dialog_content = "庫絲庫塔很喜歡「黑尾花」吧？",
  str_homestory_809801001_15_dialog_content = "喜歡……要怎麼確定、我是不是喜歡它呢？",
  str_homestory_809801001_16_dialog_content = "嗯……對「黑尾花」有獨特的評價，並對它的生長習性十分瞭解。",
  str_homestory_809801001_17_dialog_content = "我想，應該只有喜歡它的庫絲庫塔才做得到吧。",
  str_homestory_809801001_18_dialog_content = "是嗎……",
  str_homestory_809801001_19_dialog_content = "事實上，「黑尾花」習慣生長於屍體上。",
  str_homestory_809801001_20_dialog_content = "屍體？！",
  str_homestory_809801001_21_dialog_content = "沒錯，我想……",
  str_homestory_809801001_22_dialog_content = "這裡，很快，會有「黑尾花」出現。",
  str_homestory_809801001_23_dialog_content = "你、你的意思是……這裡……埋著屍體？！！",
  str_homestory_809801001_24_dialog_content = "不用擔心，我已經確認過了。",
  str_homestory_809801001_25_dialog_content = "我指的，是我這副——即將枯萎的身體。",
  str_homestory_809801001_26_dialog_content = "呵，我快要沉睡了，這意味著「黑尾花」也會出現。",
  str_homestory_809801001_27_dialog_content = "不、不會的，庫絲庫塔！",
  str_homestory_809801001_28_dialog_content = "丘布告訴過我，空庭的土壤裡含有特殊物質。",
  str_homestory_809801001_29_dialog_content = "就算、就算「黑尾花」出現也不奇怪……",
  str_homestory_809801001_30_dialog_content = "甚至……會長出五顏六色的花也說不定呢！",
  str_homestory_809801001_31_dialog_content = "「五顏六色」……",
  str_homestory_809801001_32_dialog_content = "你說的是、真的嗎？<sprite=emo_yundao size=60 />",
  str_homestory_809801001_33_dialog_content = "嗯！我們一起培育五顏六色的花朵怎麼樣？",
  str_homestory_809801001_34_dialog_content = "「一起培育」……這是、工作？",
  str_homestory_809801001_35_dialog_content = "唔、好像不是……",
  str_homestory_809801001_36_dialog_content = "PlayerName也喜歡花？",
  str_homestory_809801001_37_dialog_content = "算是吧！",
  str_homestory_809801001_38_dialog_content = "我總覺得，空庭的景色還是單調了點。",
  str_homestory_809801001_39_dialog_content = "多虧妳提醒我，可以用花朵來增添色彩呢！",
  str_homestory_809801001_40_dialog_content = "這麼說……增添色彩、會讓人感到高興？",
  str_homestory_809801001_41_dialog_content = "當然！我們四處逛逛，找找其他顏色的花怎麼樣？",
  str_homestory_809801001_42_dialog_content = "嗯……可以試試。",
  str_homestory_809801001_43_dialog_content = "不過，你說的「五顏六色」，也包含金色嗎？",
  str_homestory_809801001_44_dialog_content = "你看湖水中閃著金光的東西，是花嗎？",
  str_homestory_820101001_0_dialog_content = "在看什麼？",
  str_homestory_820101001_1_dialog_content = "如果……",
  str_homestory_820101001_2_dialog_content = "有打擾到妳嗎，蜜雅？",
  str_homestory_820101001_3_dialog_content = "沒、沒有，只是想到一些事情，感到難以抉擇。",
  str_homestory_820101001_4_dialog_content = "有什麼我能幫上忙的嗎？",
  str_homestory_820101001_5_dialog_content = "嗯，我想先問你一個問題，可以嗎？",
  str_homestory_820101001_6_dialog_content = "當然。",
  str_homestory_820101001_7_dialog_content = "假如可以永久保存一天的記憶，你想保存哪一天？",
  str_homestory_820101001_8_dialog_content = "永久保存……還真想不到。",
  str_homestory_820101001_9_dialog_content = "原來是在為這件事苦惱啊。",
  str_homestory_820101001_10_dialog_content = "我是看到這個，所以才……",
  str_homestory_820101001_11_dialog_content = "嗯……讓我想想。",
  str_homestory_820101001_12_option_content = "巨像啟動……",
  str_homestory_820101001_13_dialog_content = "我想保存巨像成功啟動的那一天。",
  str_homestory_820101001_14_dialog_content = "那是我第一次見到艾斯特拉大陸的樣子。",
  str_homestory_820101001_15_dialog_content = "或許可以當作我人生的起點。",
  str_homestory_820101001_16_option_content = "回歸塔升起……",
  str_homestory_820101001_17_dialog_content = "我想保存回歸塔升起的那一天。",
  str_homestory_820101001_18_dialog_content = "我的感知力獲得強化，彷彿可以從每一個角落俯瞰艾斯特拉大陸。",
  str_homestory_820101001_19_dialog_content = "那種感覺無比震撼。",
  str_homestory_820101001_20_dialog_content = "聽起來，確實是很棒的一天呢。",
  str_homestory_820101001_21_dialog_content = "PlayerName很容易就想到了。",
  str_homestory_820101001_22_dialog_content = "其實巨像成功啟動之前，我度過的每一天，都像是前一天的重複。",
  str_homestory_820101001_23_dialog_content = "直到遇見大家之後，我的記憶才逐漸豐富起來。",
  str_homestory_820101001_24_dialog_content = "所以我越珍惜這一切，大家在我的腦海中就越清晰。",
  str_homestory_820101001_25_dialog_content = "我會努力記住這一切，讓每一天都能永存。",
  str_homestory_820101001_26_dialog_content = "唔……<sprite=emo_sikao size=60 />",
  str_homestory_820101001_27_dialog_content = "可以說說妳的想法嗎，蜜雅？",
  str_homestory_820101001_28_dialog_content = "我的想法……",
  str_homestory_820101001_29_dialog_content = "因為我曾經遺忘掉一些重要的事情，直到最近才想起來。",
  str_homestory_820101001_30_dialog_content = "我很擔心未來還會遺忘，所以想要保存……",
  str_homestory_820101001_31_dialog_content = "但想來想去，媽媽、妹妹……那麼多回憶，始終難以割捨。",
  str_homestory_820101001_32_dialog_content = "蜜雅……",
  str_homestory_820101001_33_dialog_content = "啊，對不起，讓你煩惱了……",
  str_homestory_820101001_34_dialog_content = "是我該向妳道歉，不該說那些話……",
  str_homestory_820101001_35_dialog_content = "唔、沒關係的PlayerName。",
  str_homestory_820101001_36_dialog_content = "聽你這麼說，我反而輕鬆了許多。",
  str_homestory_820101001_37_dialog_content = "真的嗎？",
  str_homestory_820101001_38_dialog_content = "嗯！比起擔心記憶會遺忘，珍惜眼前的一切才更重要<sprite=emo_yaosu size=60 />。",
  str_homestory_820401001_0_dialog_content = "約書亞夫人？",
  str_homestory_820401001_1_dialog_content = "您在做什麼？",
  str_homestory_820401001_2_dialog_content = "PlayerName，你看。",
  str_homestory_820401001_3_dialog_content = "這盆栽長得真不錯呢～",
  str_homestory_820401001_4_dialog_content = "我正在研究它是什麼品種。",
  str_homestory_820401001_5_dialog_content = "這樣啊，那您認出來了嗎？",
  str_homestory_820401001_6_dialog_content = "不過，我還是沒認出來這是什麼植物……",
  str_homestory_820401001_7_dialog_content = "你知道這是什麼植物嗎？",
  str_homestory_820401001_8_option_content = "（點頭）",
  str_homestory_820401001_9_dialog_content = "這是不久前我在影鎮買的。",
  str_homestory_820401001_10_dialog_content = "當時隨便挑了幾盆。",
  str_homestory_820401001_11_dialog_content = "老闆好像說這叫……莊園盆栽？",
  str_homestory_820401001_12_dialog_content = "沒錯，就是這個名字。",
  str_homestory_820401001_13_dialog_content = "雖然名字很普通，但你養得很好～",
  str_homestory_820401001_14_dialog_content = "嘿嘿，老闆說這盆栽可以長得很茂盛唷。",
  str_homestory_820401001_15_option_content = "（搖頭）",
  str_homestory_820401001_16_dialog_content = "啊，我也不太清楚。",
  str_homestory_820401001_17_dialog_content = "我只記得老闆說，這是一種四季常青的植物。",
  str_homestory_820401001_18_dialog_content = "在室內也可以培養。",
  str_homestory_820401001_19_dialog_content = "看來是很好養活的品種。",
  str_homestory_820401001_20_dialog_content = "PlayerName這裡有不少植栽呢。",
  str_homestory_820401001_21_dialog_content = "不考慮種些鮮花<sprite=emo_huaduo size=60 />嗎？",
  str_homestory_820401001_22_dialog_content = "這樣周遭環境就不會單調了。",
  str_homestory_820401001_23_dialog_content = "啊，好主意！",
  str_homestory_820401001_24_dialog_content = "不過我不太會種花……",
  str_homestory_820401001_25_dialog_content = "還是這些綠色植栽比較好養活。",
  str_homestory_820401001_26_dialog_content = "在白夜城的時候，我會在花園裡培育各式各樣的花。",
  str_homestory_820401001_27_dialog_content = "閒來無事就幫花澆澆水、修剪一下雜枝——",
  str_homestory_820401001_28_dialog_content = "能讓內心平靜下來。",
  str_homestory_820401001_29_dialog_content = "原來您還有這個愛好！",
  str_homestory_820401001_30_dialog_content = "那約書亞夫人可以教我種花嗎？",
  str_homestory_820401001_31_dialog_content = "當然可以～",
  str_homestory_820401001_32_dialog_content = "種植花卉並不困難，但是需要耐心。",
  str_homestory_820401001_33_dialog_content = "鮮花在培育初期是很敏感的。",
  str_homestory_820401001_34_dialog_content = "這盆植物的花盆，剛好就能用來進行初期培養。",
  str_homestory_820401001_35_dialog_content = "種下種子後，就要按時澆水<sprite=emo_hanshui size=60 />，等待發芽。",
  str_homestory_820401001_36_dialog_content = "要記得，不可以澆太多水唷。",
  str_homestory_820401001_37_dialog_content = "嗯嗯，我記住了。然後呢？",
  str_homestory_820401001_38_dialog_content = "種子發芽後，再培育一個月。",
  str_homestory_820401001_39_dialog_content = "這個時期，就能幫小苗施加更多營養了～",
  str_homestory_820401001_40_dialog_content = "等到長出小樹苗後，就可以移植到寬闊的地方了。",
  str_homestory_820401001_41_dialog_content = "原來還要移植啊……",
  str_homestory_820401001_42_dialog_content = "沒錯呢，PlayerName從小苗長成勇敢的孩子後——",
  str_homestory_820401001_43_dialog_content = "不也到別的地方去歷險了嗎？",
  str_homestory_820401001_44_dialog_content = "這是成長的一環唷。",
  str_homestory_820401001_45_dialog_content = "雖、雖然是這樣沒錯……",
  str_homestory_820401001_46_dialog_content = "但說得我有點不好意思了。",
  str_homestory_820401001_47_dialog_content = "呵呵，PlayerName是乖孩子呢～",
  str_homestory_820501001_0_dialog_content = "白蘭小姐？",
  str_homestory_820501001_1_dialog_content = "我剛才看妳閉著眼睛，是在睡覺<sprite=emo_kun size=60 />嗎？",
  str_homestory_820501001_2_dialog_content = "不，我在冥想。",
  str_homestory_820501001_3_dialog_content = "冥想？",
  str_homestory_820501001_4_dialog_content = "是的，您知道冥想嗎？",
  str_homestory_820501001_5_option_content = "算是知道",
  str_homestory_820501001_6_dialog_content = "聽說冥想可以舒緩身心，療癒創傷。",
  str_homestory_820501001_7_dialog_content = "嗯，不錯，的確有這樣的功效。",
  str_homestory_820501001_8_option_content = "不瞭解",
  str_homestory_820501001_9_dialog_content = "冥想是一種針對精神的練習，可以舒緩身心，療癒創傷。",
  str_homestory_820501001_10_dialog_content = "妳遇到什麼困難了嗎？心情很煩躁？",
  str_homestory_820501001_11_dialog_content = "其實除了獨自冥想，也可以找朋友傾訴啊，比如我。",
  str_homestory_820501001_12_dialog_content = "剛才看妳一個人待在這裡，顯得有點孤單。",
  str_homestory_820501001_13_dialog_content = "謝謝您的關心和好意。",
  str_homestory_820501001_14_dialog_content = "我很樂意經常與您相聚，只不過我冥想的內容無法向您傾訴。",
  str_homestory_820501001_15_dialog_content = "應該說，傾訴了也沒有任何用處。",
  str_homestory_820501001_16_dialog_content = "是很嚴重的事情嗎？我想想辦法……",
  str_homestory_820501001_17_dialog_content = "呵呵，能有您這樣的朋友，大概真的對我所求有幫助。",
  str_homestory_820501001_18_dialog_content = "因為只要看見您，心情就會變得非常愉快。",
  str_homestory_820501001_19_dialog_content = "這也是美容保養的祕訣。",
  str_homestory_820501001_20_dialog_content = "美容保養？",
  str_homestory_820501001_21_dialog_content = "對呀，我剛才冥想的內容就是延緩衰老，養顏美容。",
  str_homestory_820501001_22_dialog_content = "這種事情光靠冥想就能獲得嗎？",
  str_homestory_820501001_23_dialog_content = "思想的力量非常強大。",
  str_homestory_820501001_24_dialog_content = "怎麼樣？要試試看嗎？",
  str_homestory_820501001_25_dialog_content = "可以讓我變得非常強壯，戰鬥力超群嗎？",
  str_homestory_820501001_26_dialog_content = "您想要的竟然是這個？",
  str_homestory_820501001_27_dialog_content = "對啊，這樣就更能守護我愛的人了。",
  str_homestory_820501001_28_dialog_content = "我非常讚許您的想法。一直以來，我也是為了「守護」而戰。",
  str_homestory_820501001_29_dialog_content = "不過我想提醒您，守護的形式有很多種。",
  str_homestory_820501001_30_dialog_content = "以我自己為例，哪怕平常只是當向導，也是在用不同的方式守護白夜城。",
  str_homestory_820501001_31_dialog_content = "為什麼要提醒這個？難道是我冥想的內容無法實現嗎？",
  str_homestory_820501001_32_dialog_content = "我的確不知道冥想能不能真的鍛鍊和增長肌肉。",
  str_homestory_820501001_33_dialog_content = "不過您也可以試試。",
  str_homestory_820501001_34_dialog_content = "唔……果然是不太可能吧……",
  str_homestory_807501001_0_dialog_content = "歐緹？",
  str_homestory_807501001_1_dialog_content = "這裡竟然有這種好東西！",
  str_homestory_807501001_2_dialog_content = "我的扳手呢？我要開始拆東西了！",
  str_homestory_807501001_3_dialog_content = "等一下，妳要拆什麼？",
  str_homestory_807501001_4_dialog_content = "拆這個路燈，不行嗎？",
  str_homestory_807501001_5_option_content = "當然不行呀",
  str_homestory_807501001_6_option_content = "路燈壞了嗎？",
  str_homestory_807501001_7_dialog_content = "沒壞，就是想拆。",
  str_homestory_807501001_8_dialog_content = "那就不行。<sprite=emo_shengqi size=60 />",
  str_homestory_807501001_9_dialog_content = "你這傢伙！幹嘛不行？不就是個破爛路燈嗎？",
  str_homestory_807501001_10_dialog_content = "路燈又沒壞，為什麼要拆它？",
  str_homestory_807501001_11_dialog_content = "當然是要研究一下啊。",
  str_homestory_807501001_12_dialog_content = "你看這盞燈，長得就和別的燈完全不一樣吧？",
  str_homestory_807501001_13_dialog_content = "沒什麼差別吧？",
  str_homestory_807501001_14_dialog_content = "從它的外表，我已經可以看到內部錯綜複雜的齒輪和電路。",
  str_homestory_807501001_15_dialog_content = "白夜城的路燈應該不是這種結構吧……",
  str_homestory_807501001_16_dialog_content = "所以說你不懂嘛。",
  str_homestory_807501001_17_dialog_content = "妳也沒說啊。",
  str_homestory_807501001_18_dialog_content = "喲呵，你小子最近很嗆嘛。",
  str_homestory_807501001_19_dialog_content = "好，你一定要守護這盞路燈是吧？",
  str_homestory_807501001_20_dialog_content = "那我們就現場過兩招。",
  str_homestory_807501001_21_dialog_content = "看我不把你搞到機械故障！",
  str_homestory_807501001_22_dialog_content = "我又不是機械，怎麼會故障呢？",
  str_homestory_807501001_23_dialog_content = "要故障也是妳的改裝電纜吧。",
  str_homestory_807501001_24_dialog_content = "居然敢挑釁我？",
  str_homestory_807501001_25_dialog_content = "我只是實話實說啊……",
  str_homestory_807501001_26_dialog_content = "別小看我們技術人員，就算你是空裔，我也敢……",
  str_homestory_807501001_27_dialog_content = "？？？",
  str_homestory_807501001_28_dialog_content = "唔，一下沒想好後面的狠話該說什麼。<sprite=emo_sikao size=60 />",
  str_homestory_807501001_29_dialog_content = "噗嗤......",
  str_homestory_807501001_30_dialog_content = "喂，你再笑，我開通訊裝置叫人了！",
  str_homestory_807501001_31_dialog_content = "哈哈哈哈。",
  str_homestory_807501001_32_dialog_content = "還笑？我叫醒山過來，你怕不怕？",
  str_homestory_807501001_33_dialog_content = "妳確定醒山會站在妳那邊？",
  str_homestory_807501001_34_dialog_content = "唔……這個倒沒什麼把握……",
  str_homestory_807501001_35_dialog_content = "所以，妳想研究這盞路燈？",
  str_homestory_807501001_36_dialog_content = "是啊，看它結構蠻精巧的，手癢想拆開看一下。",
  str_homestory_807501001_37_dialog_content = "可是這盞燈現在運作得很平順，想必內部結構也很和諧。",
  str_homestory_807501001_38_dialog_content = "還是，等它壞了的時候，我再請妳來拆開維修？",
  str_homestory_807501001_39_dialog_content = "這主意不錯，我最擅長修破爛了！",
  str_homestory_807501001_40_dialog_content = "好吧好吧，今天就先不拆它了。",
  str_homestory_807501001_41_dialog_content = "那我就替這盞路燈謝謝妳了。",
  str_homestory_807501001_42_dialog_content = "說起來，我剛才看見水裡有點反光，說不定也是什麼機械零件！",
  str_homestory_807501001_43_dialog_content = "乾脆撈出來拆拆看！",
  str_homestory_807501001_44_dialog_content = "呃，我還是趕緊去搶救水裡的東西吧。",
  str_homestory_820601001_0_dialog_content = "她在幹什麼呢？",
  str_homestory_820601001_1_dialog_content = "妳在看什麼？<sprite=emo_yihuo size=60 />",
  str_homestory_820601001_2_dialog_content = "上面的風景真不錯！",
  str_homestory_820601001_3_dialog_content = "妳似乎看了好久了，真的只是在看風景？",
  str_homestory_820601001_4_dialog_content = "先別管風景了，有沒有興趣跟我幹一番大事？",
  str_homestory_820601001_5_dialog_content = "空裔敏銳的感官，在未來的商戰中絕對可以助我一臂之力！",
  str_homestory_820601001_6_dialog_content = "商戰？一臂之力？",
  str_homestory_820601001_7_dialog_content = "俗話說「商場如戰場」，我需要的正是你這樣的人才！",
  str_homestory_820601001_8_dialog_content = "給你計畫獎金，還有創業股份，怎麼樣？來不來？",
  str_homestory_820601001_9_dialog_content = "那要看計畫進展情況和有多少股份……",
  str_homestory_820601001_10_dialog_content = "等等！我沒說有興趣參與啊！",
  str_homestory_820601001_11_dialog_content = "是說商戰到底是怎麼回事？這和妳在上面看風景又有什麼關係？",
  str_homestory_820601001_12_dialog_content = "我其實剛剛想到一個絕妙的商業模式……你可不要告訴別人。",
  str_homestory_820601001_13_dialog_content = "好、好的。",
  str_homestory_820601001_14_dialog_content = "那就是——向藍海進軍！",
  str_homestory_820601001_15_option_content = "藍海？",
  str_homestory_820601001_16_dialog_content = "顧名思義，就是大海啦！",
  str_homestory_820601001_17_dialog_content = "那……妳是想要搞海運嗎？",
  str_homestory_820601001_18_option_content = "船舶業？",
  str_homestory_820601001_19_dialog_content = "不對！",
  str_homestory_820601001_20_dialog_content = "藍海是一個比喻！比喻！",
  str_homestory_820601001_21_dialog_content = "……比喻什麼？",
  str_homestory_820601001_22_dialog_content = "在商戰上用來形容尚未開發的領域，充滿了商機！",
  str_homestory_820601001_23_dialog_content = "但是這個與妳在瞭望台看風景有什麼關係？",
  str_homestory_820601001_24_dialog_content = "因為我想到了，那些海洋上的小島確實還沒怎麼開發過！",
  str_homestory_820601001_25_dialog_content = "無論是從實體角度還是商業意義，都是藍海啊！",
  str_homestory_820601001_26_dialog_content = "如果能發現海洋上的小島，再開發成度假村……",
  str_homestory_820601001_27_dialog_content = "避暑、探險、尋寶、運動、泳衣、親子樂園……",
  str_homestory_820601001_28_dialog_content = "光是相關主題的點子我就已經想不完了！",
  str_homestory_820601001_29_dialog_content = "所以萊蕾妳是要去開發島嶼嗎？有具體目標了嗎？",
  str_homestory_820601001_30_dialog_content = "正因為現在還沒有合適的島嶼，所以想弄條船去海上找找。",
  str_homestory_820601001_31_dialog_content = "大海這麼大，總有無人的小島！",
  str_homestory_820601001_32_dialog_content = "只要搶先別人一步，整座島嶼就是我們的了，想怎麼開發就怎麼開發！",
  str_homestory_820601001_33_dialog_content = "我們？我也要去嗎？",
  str_homestory_820601001_34_dialog_content = "沒錯！你那過人的視力和聽覺……絕對能夠派上用場。",
  str_homestory_820601001_35_dialog_content = "在妳的口中，我好像很厲害啊。",
  str_homestory_820601001_36_dialog_content = "所以第一步是先想辦法找到一座合適的小島嗎？",
  str_homestory_820601001_37_dialog_content = "沒錯。我想試試將這座瞭望台搬到船上，看看會不會看得更遠。",
  str_homestory_820601001_38_dialog_content = "正好你來了，順便問問你價格。",
  str_homestory_820601001_39_dialog_content = "我沒有想賣耶……<sprite=emo_tanqi size=60 />",
  str_homestory_820601001_40_dialog_content = "不如以這筆收入當做本錢入股？看來你也挺中意這個計畫的啊。",
  str_homestory_820601001_41_dialog_content = "我不是那個意思。",
  str_homestory_820601001_42_dialog_content = "還要再考慮？行，反正企劃書還沒寫，在簽字之前都能夠商量。",
  str_homestory_820601001_43_dialog_content = "我會盡快確定具體計畫，你也要快點下決定啊！",
  str_homestory_820601001_44_dialog_content = "……再見。",
  str_homestory_820701001_0_dialog_content = "他在玩遊戲？",
  str_homestory_820701001_1_dialog_content = "看來你玩得很開心。",
  str_homestory_820701001_2_dialog_content = "你很趕流行嘛！新遊戲設施這麼快就引進到空庭了！刺激！",
  str_homestory_820701001_3_dialog_content = "但我聽說這遊戲要兩個人玩才好玩。",
  str_homestory_820701001_4_dialog_content = "我聽說兩個人玩可以當做一種測試，尤其對於情侶……<sprite=emo_sikao size=60 />",
  str_homestory_820701001_5_dialog_content = "測試？",
  str_homestory_820701001_6_dialog_content = "如果兩人確定了戀愛關係，然後坐上去轉個幾圈……",
  str_homestory_820701001_7_dialog_content = "走下來後還能馬上詢問或關心彼此的感受的話……",
  str_homestory_820701001_8_dialog_content = "那這段關係就沒問題啦。反之，嘖嘖……",
  str_homestory_820701001_9_dialog_content = "但你一個人玩這個要做什麼？為將來的測試做準備？",
  str_homestory_820701001_10_dialog_content = "想錯了！老弟！",
  str_homestory_820701001_11_dialog_content = "坐上去雖然會感覺天旋地轉，但十分刺激。",
  str_homestory_820701001_12_dialog_content = "刺激到能讓我想起過去的那些日子……",
  str_homestory_820701001_13_dialog_content = "你過去都遭遇了什麼……看來是要講故事了嗎。",
  str_homestory_820701001_14_dialog_content = "我之前可是一名「獵手」，專門負責打擊壞蛋。",
  str_homestory_820701001_15_dialog_content = "治安官那樣的工作嗎？但是我記得你來自紅油沙漠……",
  str_homestory_820701001_16_dialog_content = "那邊只有紅油扳手這個遊手好閒的團夥，沒有治安官這種人吧。",
  str_homestory_820701001_17_dialog_content = "是我個人的行為，所以我說的是「獵手」而非「義務治安官」。",
  str_homestory_820701001_18_dialog_content = "那麼你專門打擊哪些壞蛋？難道和你的遭遇有關？",
  str_homestory_820701001_19_dialog_content = "聽說德諾奧峽谷之前有個村子被毀掉了，與這個有關？",
  str_homestory_820701001_20_dialog_content = "要怎麼說起呢……講個故事好了。",
  str_homestory_820701001_21_dialog_content = "講吧。",
  str_homestory_820701001_22_dialog_content = "很久以前有個厲害的漁夫，補魚技巧十分高超。",
  str_homestory_820701001_23_dialog_content = "重點是他織的網子很結實，網眼也很小，什麼魚都逃不出去。",
  str_homestory_820701001_24_dialog_content = "每次出海補魚都收穫滿滿，也因此成了富裕人家。",
  str_homestory_820701001_25_dialog_content = "可是……漁夫逐漸捕不到魚了。",
  str_homestory_820701001_26_dialog_content = "魚沒了？",
  str_homestory_820701001_27_dialog_content = "沒錯！因為網眼太小，連魚苗都不放過。",
  str_homestory_820701001_28_dialog_content = "漸漸地就沒有魚了，漁夫家裡因而斷炊，直到有一天……",
  str_homestory_820701001_29_dialog_content = "看來故事要轉折了。<sprite=emo_yaosu size=60 />",
  str_homestory_820701001_30_dialog_content = "漁夫的兒子在一片隱祕礁石群中，找到一條美麗的海魚！",
  str_homestory_820701001_31_dialog_content = "從體型上看來似乎是條幼魚，不過真的很美。",
  str_homestory_820701001_32_dialog_content = "回家之後忍不住告訴了漁夫，也就是他的父親。",
  str_homestory_820701001_33_dialog_content = "我猜漁夫立刻就去捕捉了。",
  str_homestory_820701001_34_dialog_content = "這次漁夫帶上了最結實、網眼最細密的漁網，下定決心要補到那條魚。",
  str_homestory_820701001_35_dialog_content = "因為他知道那是條價值連城的觀賞魚，能在市面上賣個好價錢。",
  str_homestory_820701001_36_dialog_content = "於是他讓兒子做嚮導，一路前往那片隱祕的礁石……",
  str_homestory_820701001_37_dialog_content = "我猜他們要倒楣了。",
  str_homestory_820701001_38_dialog_content = "對！隨後他們果然找到了一條魚，只不過更大、更美麗！",
  str_homestory_820701001_39_dialog_content = "那條魚是漁夫兒子看到的魚的雙親吧？",
  str_homestory_820701001_40_dialog_content = "應該是吧。",
  str_homestory_820701001_41_dialog_content = "那美麗的大魚見到船，立刻在礁石裡竄來竄去躲避捕捉。",
  str_homestory_820701001_42_dialog_content = "漁夫也駕船追了上去，雙方你追我趕……",
  str_homestory_820701001_43_dialog_content = "結果船撞上了礁石。",
  str_homestory_820701001_44_dialog_content = "船沉了，漁夫和兒子都死了。",
  str_homestory_820701001_45_dialog_content = "哦……",
  str_homestory_820701001_46_dialog_content = "那你剛才說的壞蛋又是誰？這故事裡的漁夫和兒子都死了啊。",
  str_homestory_820701001_47_dialog_content = "所以說這只是一個故事，請勿混為一談。",
  str_homestory_820801001_0_dialog_content = "她呆了好久……",
  str_homestory_820801001_1_dialog_content = "妳在幹什麼？",
  str_homestory_820801001_2_dialog_content = "啊？是你！竟然注意到我了！<sprite=emo_wuzui size=60 />",
  str_homestory_820801001_3_dialog_content = "因為妳在這裡看這座碑很久了，眼睛不累嗎？",
  str_homestory_820801001_4_dialog_content = "你這麼一說確實有點疼……",
  str_homestory_820801001_5_dialog_content = "不對！重點是你竟然注意到我了！",
  str_homestory_820801001_6_dialog_content = "難道這就是它的力量？能讓沒什麼存在感的人也能被人注意到？",
  str_homestory_820801001_7_dialog_content = "不是啦，真的是因為妳站在這裡太久了。",
  str_homestory_820801001_8_dialog_content = "看看碑上的那些圖案！你知道它們的含義嗎，PlayerName？",
  str_homestory_820801001_9_dialog_content = "不太清楚……好像是古時候留下的。",
  str_homestory_820801001_10_dialog_content = "因為年代久遠，可能已經沒辦法弄清具體含義了吧。",
  str_homestory_820801001_11_dialog_content = "是嗎……哎……",
  str_homestory_820801001_12_dialog_content = "怎麼突然擺出這種表情？看起來有點落寞。",
  str_homestory_820801001_13_dialog_content = "因為我在思考紅油扳手的未來……",
  str_homestory_820801001_14_option_content = "什麼未來？",
  str_homestory_820801001_15_dialog_content = "我暫時還沒想好，反正一定要有個長遠目標……不能像現在這樣整天遊手好閒。",
  str_homestory_820801001_16_dialog_content = "這是紅油扳手的風格啊，很多人也是因為這樣才加入你們的。",
  str_homestory_820801001_17_dialog_content = "確實……不過有規劃總是比較好！我現在雖然想不到，但一定要有個規劃！",
  str_homestory_820801001_18_option_content = "幹嘛想這麼多？",
  str_homestory_820801001_19_dialog_content = "……",
  str_homestory_820801001_20_dialog_content = "叭噗？",
  str_homestory_820801001_21_dialog_content = "我也不明白為什麼，但總感覺一定要有人多思考一下才行！",
  str_homestory_820801001_22_dialog_content = "天天吊兒郎當、四處遊蕩、東一榔頭西一扳手的……也太不實在了。",
  str_homestory_820801001_23_dialog_content = "看來妳確實在認真思考，真是辛苦妳了……",
  str_homestory_820801001_24_dialog_content = "我覺得醒山都不一定想過這件事。",
  str_homestory_820801001_25_dialog_content = "我知道，他是老大，保持原本灑脫的領導作風就夠了。",
  str_homestory_820801001_26_dialog_content = "這種事情應該由我這位軍師來思考謀劃。",
  str_homestory_820801001_27_dialog_content = "不過這種事和紀念碑有什麼關係呢？",
  str_homestory_820801001_28_dialog_content = "因為我突然聯想到一些事啦！",
  str_homestory_820801001_29_dialog_content = "我聽別人說白夜城、啟光聯邦，甚至北境，都有這種紀念碑。",
  str_homestory_820801001_30_dialog_content = "為的就是紀念他們當中的著名人物，或是大功績、大事件什麼的！",
  str_homestory_820801001_31_dialog_content = "我們紅油扳手可沒有這種東西……",
  str_homestory_820801001_32_dialog_content = "加上又不像他們那樣，有自己的地盤之類的……",
  str_homestory_820801001_33_dialog_content = "將來一旦發展不佳，或是大家吵了起來，一氣之下散夥了怎麼辦！",
  str_homestory_820801001_34_dialog_content = "妳說的確實有點道理。",
  str_homestory_820801001_35_dialog_content = "沒錯吧！",
  str_homestory_820801001_36_dialog_content = "不過，妳有沒有想過紀念碑的形式？",
  str_homestory_820801001_37_dialog_content = "形式？",
  str_homestory_820801001_38_dialog_content = "不一定要是紀念碑的外形，只要是能代表紅油扳手的東西就行了吧。",
  str_homestory_820801001_39_dialog_content = "你的意思是……",
  str_homestory_820801001_40_dialog_content = "比如在車上塗鴉？",
  str_homestory_820801001_41_dialog_content = "這樣做就是你們的風格，走到天涯海角也一眼就能認出是紅油扳手。",
  str_homestory_820801001_42_dialog_content = "比如說如果擊退過大沙蟲，就畫個沙蟲塗鴉再打個叉什麼的。",
  str_homestory_820801001_43_dialog_content = "沒錯！這是個好主意！",
  str_homestory_820801001_44_dialog_content = "而且紅油扳手裡塗鴉高手很多，俯拾即是！",
  str_homestory_820801001_45_dialog_content = "我這就去想辦法舉辦一場「紅油扳手車輛塗鴉大獎賽」！<sprite=emo_yaosu size=60 />",
  str_homestory_820901001_0_dialog_content = "她在看什麼？",
  str_homestory_820901001_1_dialog_content = "雷霆長官，您在這裡做什麼？",
  str_homestory_820901001_2_dialog_content = "沒什麼，只是看到一個很有意思的東西。",
  str_homestory_820901001_3_dialog_content = "原來啟光是用這種方式招兵買馬的。",
  str_homestory_820901001_4_dialog_content = "您不是大元帥嗎？為什麼一副恍然大悟的樣子……",
  str_homestory_820901001_5_dialog_content = "對外徵兵這種事，不是大元帥的職責。",
  str_homestory_820901001_6_dialog_content = "大概吧？",
  str_homestory_820901001_7_option_content = "確實",
  str_homestory_820901001_8_dialog_content = "大元帥應該沒時間處理這些事。",
  str_homestory_820901001_9_option_content = "疑問句？！",
  str_homestory_820901001_10_dialog_content = "為什麼對自己的職責是問句？！",
  str_homestory_820901001_11_dialog_content = "我當上大元帥後的第一件事就是率兵出征。",
  str_homestory_820901001_12_dialog_content = "不過現在確實應該過問一下其他事務。",
  str_homestory_820901001_13_dialog_content = "這個東西，你們是哪裡找到的？",
  str_homestory_820901001_14_dialog_content = "在影鎮……我記得是拍電影的時候。",
  str_homestory_820901001_15_dialog_content = "電影嗎？我想到了。<sprite=emo_sikao size=60 />",
  str_homestory_820901001_16_dialog_content = "想到什麼了？",
  str_homestory_820901001_17_dialog_content = "徵兵廣告啊，只用這麼一塊板子要怎麼吸引人。",
  str_homestory_820901001_18_dialog_content = "我在職期間，啟光應該更加強大。",
  str_homestory_820901001_19_dialog_content = "所以？",
  str_homestory_820901001_20_dialog_content = "我們拍一部以啟光軍人為主題的電影來打廣告如何？",
  str_homestory_820901001_21_option_content = "您認真的嗎？",
  str_homestory_820901001_22_dialog_content = "就算您這麼說……啟光感覺不像是能拍電影的樣子。",
  str_homestory_820901001_23_dialog_content = "的確，啟光教育傾向理工應用和戰場知識，對藝術研究不深。",
  str_homestory_820901001_24_dialog_content = "我就說嘛。",
  str_homestory_820901001_25_dialog_content = "所以我打算請你來拍。",
  str_homestory_820901001_26_option_content = "拍！",
  str_homestory_820901001_27_dialog_content = "的確，雖然宣傳語寫得很有氣勢，但還是不能和電影比。",
  str_homestory_820901001_28_dialog_content = "如果能夠把啟光戰士的英勇放上大銀幕，一定更加震撼。",
  str_homestory_820901001_29_dialog_content = "我很期待！",
  str_homestory_820901001_30_dialog_content = "很好，那這個任務就委託給你了，我會準備好報酬的。",
  str_homestory_820901001_31_dialog_content = "我？我不會啊。",
  str_homestory_820901001_32_dialog_content = "空裔不是挺會創作的嗎？我記得你還寫過詩。",
  str_homestory_820901001_33_dialog_content = "寫詩和拍電影是兩回事！再說我寫詩技巧也普普通通。",
  str_homestory_820901001_34_dialog_content = "藝術總是互通的嘛。",
  str_homestory_820901001_35_dialog_content = "不是那種問題！",
  str_homestory_820901001_36_dialog_content = "而且說回來，啟光根本沒有電影院吧！",
  str_homestory_820901001_37_dialog_content = "放映廳還是有的，不過只會在休息日營業。",
  str_homestory_820901001_38_dialog_content = "所以大家也沒時間去看電影。",
  str_homestory_820901001_39_dialog_content = "啟光全民皆兵，徵兵廣告當然是給別人看的。",
  str_homestory_820901001_40_dialog_content = "不過你這麼一說，給啟光內部看一看似乎也能鼓舞士氣。",
  str_homestory_820901001_41_dialog_content = "既然這樣……機會難得，我也出演一下好了。",
  str_homestory_820901001_42_dialog_content = "不然把萊因哈特也叫來一起，比一比誰在大銀幕上更能振奮人心。",
  str_homestory_820901001_43_dialog_content = "幾位軍團長也上鏡的話，說不定還能激起軍團間的良性競爭。",
  str_homestory_820901001_44_dialog_content = "不用那麼大張旗鼓！",
  str_homestory_820901001_45_dialog_content = "對了，你也可以自導自演。",
  str_homestory_820901001_46_dialog_content = "身為唯一的空裔兼導演，你應該有一個角色。",
  str_homestory_820901001_47_dialog_content = "完全聽不到我說話，我是不是該放棄抵抗了……<sprite=emo_yundao size=60 />",
  str_homestory_820901001_48_dialog_content = "電影的名字我也想好了。",
  str_homestory_820901001_49_dialog_content = "就叫《拯救空裔PlayerName》怎麼樣！",
  str_homestory_821001001_0_dialog_content = "喬瑟琳在旗幟前祈禱……",
  str_homestory_821001001_1_dialog_content = "喬瑟琳？",
  str_homestory_821001001_2_dialog_content = "您不必在旁邊站那麼久，直接叫我就好。",
  str_homestory_821001001_3_dialog_content = "我怕影響到妳。",
  str_homestory_821001001_4_dialog_content = "光之神不會因為祈禱被打斷就質疑子民的信仰。",
  str_homestory_821001001_5_dialog_content = "我更不會為此生氣。您找我是需要幫助嗎？",
  str_homestory_821001001_6_dialog_content = "不是，我只是看妳一直站在這面旗幟前。",
  str_homestory_821001001_7_dialog_content = "妳剛剛是在祈禱嗎？對著旗幟？",
  str_homestory_821001001_8_dialog_content = "祈禱？的確，如果對特定的媒介祈禱，神音會更加清晰。",
  str_homestory_821001001_9_option_content = "像是這面旗幟？",
  str_homestory_821001001_10_dialog_content = "信仰光之神對白夜城來說是傳統吧。",
  str_homestory_821001001_11_dialog_content = "白夜城的旗幟確實很適合當作祈禱的媒介。",
  str_homestory_821001001_12_option_content = "像是聖物？",
  str_homestory_821001001_13_dialog_content = "如果要用來和神溝通的話，用聖物比較常見吧。",
  str_homestory_821001001_14_dialog_content = "就像直接和神面對面一樣，感覺很有效。",
  str_homestory_821001001_15_dialog_content = "其實無論用什麼樣的物件來當媒介都可以。",
  str_homestory_821001001_16_dialog_content = "光<sprite=emo_taiyang size=60 />恩惠遍佈大地，陽光之下的事物都與神光相連。",
  str_homestory_821001001_17_dialog_content = "在菜園耕作的時候，我就常對著番茄花祈禱。",
  str_homestory_821001001_18_dialog_content = "還能這樣呀？",
  str_homestory_821001001_19_dialog_content = "不過進行特定祈禱時，還是需要挑選適合的物件。",
  str_homestory_821001001_20_dialog_content = "那對白夜城旗幟祈禱的內容是什麼？",
  str_homestory_821001001_21_dialog_content = "……",
  str_homestory_821001001_22_dialog_content = "抱歉，我只是很好奇。",
  str_homestory_821001001_23_dialog_content = "如果我問了什麼不該問的，妳可以直接無視就好。",
  str_homestory_821001001_24_dialog_content = "那倒沒有。將光之神的恩惠傳播給每個人也是我的使命。",
  str_homestory_821001001_25_dialog_content = "關於信仰，我會知無不言。",
  str_homestory_821001001_26_dialog_content = "不過，我剛剛只是……",
  str_homestory_821001001_27_dialog_content = "只是？",
  str_homestory_821001001_28_dialog_content = "我只是想近距離看一下這面旗幟的縫紉工藝。",
  str_homestory_821001001_29_dialog_content = "白夜城的宗教物品，製作都十分精巧。",
  str_homestory_821001001_30_dialog_content = "尤其是旗幟，身為引導眾人的信標，必須足夠堅韌。",
  str_homestory_821001001_31_dialog_content = "如果我的縫紉技術也能有所長進，就更能幫助大家。",
  str_homestory_821001001_32_dialog_content = "我好像能想像喬瑟琳舉起旗幟的英姿了。",
  str_homestory_821001001_33_dialog_content = "我不行啦，掌旗並不是件容易的事。",
  str_homestory_821001001_34_dialog_content = "雖然被居民們冠以「聖女」之名，但我還沒辦法引領好大家。",
  str_homestory_821001001_35_dialog_content = "現在的我，還是要先從幫鐵棘騎士團縫好軍旗做起。",
  str_homestory_821001001_36_dialog_content = "嗯，做好一面旗幟和把它揮舞起來同樣重要，我也會幫妳的。",
  str_homestory_821001001_37_dialog_content = "你也懂針線活嗎？",
  str_homestory_821001001_38_dialog_content = "小時候從臨空者號那裡學過一點點……",
  str_homestory_821001001_39_dialog_content = "我會把我所知的都教給你，教學相長嘛。",
  str_homestory_821001001_40_dialog_content = "首先，把你的衣服全部拿過來。",
  str_homestory_821001001_41_dialog_content = "全……全部嗎？",
  str_homestory_821001001_42_dialog_content = "只有大量的練習才能掌握必要的基本功。",
  str_homestory_821001001_43_dialog_content = "如果只是口頭說說不付諸實踐，即使是光之神也無能為力。",
  str_homestory_821001001_44_dialog_content = "我相信你不是如此。",
  str_homestory_821001001_45_dialog_content = "我知道了，我馬上去拿！",
  str_homestory_821201001_0_dialog_content = "安頓？",
  str_homestory_821201001_1_dialog_content = "安頓，你已經站在「嶙峋巨廊」旁半個小時了。",
  str_homestory_821201001_2_dialog_content = "你對這東西很感興趣？",
  str_homestory_821201001_3_dialog_content = "PlayerName啊，你好。",
  str_homestory_821201001_4_dialog_content = "不瞞你說，我確實很感興趣。",
  str_homestory_821201001_5_dialog_content = "在看到它第一眼時我就確信：",
  str_homestory_821201001_6_dialog_content = "它絕對具有研究價值！",
  str_homestory_821201001_7_dialog_content = "請問一下，這是什麼東西的骨頭？",
  str_homestory_821201001_8_dialog_content = "這還真是難倒我了……",
  str_homestory_821201001_9_dialog_content = "目前還沒統一的說法，什麼說法都有。",
  str_homestory_821201001_10_dialog_content = "如果從你的角度去判斷呢？",
  str_homestory_821201001_11_dialog_content = "我相信你的判斷。",
  str_homestory_821201001_12_dialog_content = "讓我想想<sprite=emo_sikao size=60 />……這或許是……",
  str_homestory_821201001_13_option_content = "某種動物的骨頭",
  str_homestory_821201001_14_dialog_content = "動物的骨頭嗎？",
  str_homestory_821201001_15_dialog_content = "我走了那麼多地方，還沒見過這樣的骨頭。",
  str_homestory_821201001_16_dialog_content = "那這麼說，這可能是某種已經滅絕的生物遺骸！",
  str_homestory_821201001_17_dialog_content = "真的嗎……",
  str_homestory_821201001_18_option_content = "巨像的龍骨",
  str_homestory_821201001_19_dialog_content = "什麼？！",
  str_homestory_821201001_20_dialog_content = "PlayerName，你可別騙我啊！",
  str_homestory_821201001_21_dialog_content = "這這這、這真的是製造巨像用的龍骨嗎？！",
  str_homestory_821201001_22_dialog_content = "我也只是隨便說說的而已。",
  str_homestory_821201001_23_dialog_content = "不不，你可是空裔啊！你的話絕對不會錯！",
  str_homestory_821201001_24_dialog_content = "不管怎麼說，我都要好好去研究一下「嶙峋巨廊」！",
  str_homestory_821201001_25_dialog_content = "我能把它的一部分搬到房間裡研究嗎？！",
  str_homestory_821201001_26_dialog_content = "喂喂，別什麼東西都往房間裡搬啊！",
  str_homestory_821201001_27_dialog_content = "不管怎麼說，這都是公共財產……",
  str_homestory_821201001_28_dialog_content = "不過，我也有點好奇它究竟是什麼。",
  str_homestory_821201001_29_dialog_content = "這樣吧，你可以在這裡進行研究，人手不足的話也可以找幫手。",
  str_homestory_821201001_30_dialog_content = "放心吧！",
  str_homestory_821201001_31_dialog_content = "我一定會查明它的真實身分的！<sprite=emo_dianzan size=60 />",
  str_homestory_821101001_0_dialog_content = "札莉雅？妳在幹什麼？",
  str_homestory_821101001_1_dialog_content = "咦？PlayerName，你說這是什麼？",
  str_homestory_821101001_2_dialog_content = "上面寫的名字是「夏洛克式轎車」。",
  str_homestory_821101001_3_dialog_content = "「轎車」……是什麼？",
  str_homestory_821101001_4_dialog_content = "簡單來說，是一種很便利的交通工具。",
  str_homestory_821101001_5_dialog_content = "這個東西是交通工具？",
  str_homestory_821101001_6_dialog_content = "原來大家已經不用馬車了嗎……",
  str_homestory_821101001_7_dialog_content = "有些地方依舊保留著使用馬車的習慣啦，但大部分地區的有錢人都是開轎車了。",
  str_homestory_821101001_8_dialog_content = "這樣啊……",
  str_homestory_821101001_9_dialog_content = "札莉雅對轎車很感興趣？",
  str_homestory_821101001_10_dialog_content = "畢竟是沒見過的東西，當然有興趣囉。",
  str_homestory_821101001_11_dialog_content = "你晚點能帶我去看看「真傢伙」嗎？",
  str_homestory_821101001_12_option_content = "可以",
  str_homestory_821101001_13_dialog_content = "但前提是，妳只能坐在後排。",
  str_homestory_821101001_14_dialog_content = "絕對不能駕駛。",
  str_homestory_821101001_15_option_content = "不可以",
  str_homestory_821101001_16_dialog_content = "欸？為什麼……<sprite=emo_yihuo size=60 />",
  str_homestory_821101001_17_dialog_content = "總覺得妳會做出很危險的行為。",
  str_homestory_821101001_18_dialog_content = "比如，想要駕駛轎車之類的。",
  str_homestory_821101001_19_dialog_content = "PlayerName先生真厲害。",
  str_homestory_821101001_20_dialog_content = "你怎麼知道我想要「騎」這個「機械馬車」？",
  str_homestory_821101001_21_dialog_content = "騎？",
  str_homestory_821101001_22_dialog_content = "你不是說這和馬車一樣都是交通工具嗎？",
  str_homestory_821101001_23_dialog_content = "那原理應該是一樣的吧？",
  str_homestory_821101001_24_dialog_content = "只要對某個地方抽鞭子，就會跑起來了。",
  str_homestory_821101001_25_dialog_content = "或是下達什麼指令？",
  str_homestory_821101001_26_dialog_content = "我雖然光能術控制得不太好，但對騎術可是很有心得喔～",
  str_homestory_821101001_27_dialog_content = "……",
  str_homestory_821101001_28_dialog_content = "欸？你怎麼不說話了？",
  str_homestory_821101001_29_dialog_content = "看起來，妳真的需要惡補一下現代知識了……",
  str_homestory_821101001_30_dialog_content = "咦？",
  str_homestory_821301001_0_dialog_content = "三十三號？",
  str_homestory_821301001_1_dialog_content = "妳是想要去野餐嗎？",
  str_homestory_821301001_2_dialog_content = "如您所見，是的。",
  str_homestory_821301001_3_dialog_content = "為此，我正在做準備。",
  str_homestory_821301001_4_dialog_content = "妳該不會是打算一個人去吧？",
  str_homestory_821301001_5_dialog_content = "看來，您對我有一些誤會。",
  str_homestory_821301001_6_dialog_content = "我自然有邀請其他光靈友人一同前去。",
  str_homestory_821301001_7_dialog_content = "當然，這其中也包括您。",
  str_homestory_821301001_8_dialog_content = "那我很榮幸。",
  str_homestory_821301001_9_dialog_content = "……",
  str_homestory_821301001_10_dialog_content = "說起來，妳怎麼還不去邀請薇絲他們？",
  str_homestory_821301001_11_dialog_content = "我在進行重要的分析工作。",
  str_homestory_821301001_12_dialog_content = "藉由詢問他人，我得知你們以前野餐時的餐飲標準。",
  str_homestory_821301001_13_dialog_content = "再結合目前友人送來的野餐食物，我得出了一個危險的結論：",
  str_homestory_821301001_14_dialog_content = "熱量過高，非常有害身體健康。",
  str_homestory_821301001_15_dialog_content = "啊？",
  str_homestory_821301001_16_dialog_content = "PlayerName先生，您覺得呢？",
  str_homestory_821301001_17_option_content = "妳說得對",
  str_homestory_821301001_18_dialog_content = "從營養學方面來看，這些食物的熱量確實太高了。",
  str_homestory_821301001_19_dialog_content = "難得您能夠完全認同我的觀點。",
  str_homestory_821301001_20_dialog_content = "不過……",
  str_homestory_821301001_21_option_content = "這不對吧",
  str_homestory_821301001_22_dialog_content = "關於「這不對吧」的結論，您是如何分析出來的？",
  str_homestory_821301001_23_dialog_content = "我認為，我剛才的判斷很合理。",
  str_homestory_821301001_24_dialog_content = "我們是去野餐的，當然是以放鬆為主。",
  str_homestory_821301001_25_dialog_content = "太計較熱量的話，就沒辦法達到放鬆的目的了。",
  str_homestory_821301001_26_dialog_content = "計較？放鬆？",
  str_homestory_821301001_27_dialog_content = "三十三號的本意是為我們好，但有時其實不用那麼嚴格。",
  str_homestory_821301001_28_dialog_content = "該嚴格時嚴格，該放鬆時放鬆，這樣才能讓更多人喜歡妳。",
  str_homestory_821301001_29_dialog_content = "接受資訊。資訊分析。",
  str_homestory_821301001_30_dialog_content = "我明白了。",
  str_homestory_821301001_31_dialog_content = "那麼我會再對食譜執行調整。",
  str_homestory_821301001_32_dialog_content = "請靜候我的邀約。",
  str_homestory_821401001_0_dialog_content = "麗蓓卡？",
  str_homestory_821401001_1_dialog_content = "導航員……",
  str_homestory_821401001_2_dialog_content = "你想坐吊椅嗎？",
  str_homestory_821401001_3_dialog_content = "不……只是，有點懷念……",
  str_homestory_821401001_4_dialog_content = "以前……在我家的院子裡，也有一個類似的吊椅。",
  str_homestory_821401001_5_dialog_content = "那時我和姐姐，還有艾洛諾，常常會一起在吊椅上玩。",
  str_homestory_821401001_6_dialog_content = "不過，因為吊椅太小了……能承載的人數有限，只有兩個人。",
  str_homestory_821401001_7_dialog_content = "也就是說，必須要有一個人下去…",
  str_homestory_821401001_8_dialog_content = "哦？那你們是怎麼決定誰下去的？",
  str_homestory_821401001_9_dialog_content = "用猜拳。",
  str_homestory_821401001_10_dialog_content = "現在想來也奇怪，那時的猜拳，我從來沒輸過，一次都沒輸過。",
  str_homestory_821401001_11_dialog_content = "她們早就商量好了吧？",
  str_homestory_821401001_12_dialog_content = "那也說不定呢，姊姊和艾洛諾的關係，其實……一直都不太好……",
  str_homestory_821401001_13_dialog_content = "記得有一次我主動下去搖吊椅……",
  str_homestory_821401001_14_dialog_content = "結果姊姊和艾洛諾居然在吊椅上吵了起來。",
  str_homestory_821401001_15_dialog_content = "那次，她們差點把吊椅弄散架了……",
  str_homestory_821401001_16_dialog_content = "看來你真的很懷念呢<sprite=emo_sikao size=60 />。",
  str_homestory_821401001_17_dialog_content = "要不要上去坐坐？",
  str_homestory_821401001_18_dialog_content = "欸？我嗎？那……",
  str_homestory_821401001_19_dialog_content = "還是算了。",
  str_homestory_821401001_20_option_content = "為什麼？",
  str_homestory_821401001_21_option_content = "試一下吧",
  str_homestory_821401001_22_dialog_content = "其實……最近我體內的毒液，有些不安分……",
  str_homestory_821401001_23_dialog_content = "要是我坐在吊椅上不小心睡著了，溢出的毒液恐怕會破壞這張吊椅吧。",
  str_homestory_821401001_24_dialog_content = "所以，我只要看看就好。",
  str_homestory_821401001_25_dialog_content = "站在這附近，閉上眼睛，就彷彿一切都回到了從前……",
  str_homestory_821401001_26_dialog_content = "不用擔心，有我在這裡。",
  str_homestory_821401001_27_dialog_content = "如果你睡著了，我會及時提醒你的。",
  str_homestory_821401001_28_dialog_content = "會不會太麻煩您了……",
  str_homestory_821401001_29_dialog_content = "沒事的。",
  str_homestory_821401001_30_dialog_content = "那……可以再等我一會嗎？",
  str_homestory_821401001_31_dialog_content = "診所那裡還有些雜事。我處理完就過來。",
  str_homestory_821401001_32_dialog_content = "謝謝你，導航員。",
  str_homestory_821501001_0_dialog_content = "伊莎？",
  str_homestory_821501001_1_dialog_content = "喲，是你啊。",
  str_homestory_821501001_2_dialog_content = "這輛車怎麼了嗎？你一直盯著它看。",
  str_homestory_821501001_3_dialog_content = "嗯！問得好。",
  str_homestory_821501001_4_dialog_content = "你不覺得這輛車……超級帥氣嗎？",
  str_homestory_821501001_5_option_content = "沒覺得。",
  str_homestory_821501001_6_dialog_content = "這應該說是漂亮吧。",
  str_homestory_821501001_7_option_content = "確實是。",
  str_homestory_821501001_8_dialog_content = "從某種意義上來說，也算是帥氣吧。",
  str_homestory_821501001_9_dialog_content = "總之，這輛車和我超級搭啊。",
  str_homestory_821501001_10_dialog_content = "要是我開著這輛車去接麗蓓卡……",
  str_homestory_821501001_11_dialog_content = "那她一定會非常興奮的！",
  str_homestory_821501001_12_dialog_content = "你打算用這輛車去接麗蓓卡？",
  str_homestory_821501001_13_dialog_content = "是啊，麗蓓卡她身體不好。",
  str_homestory_821501001_14_dialog_content = "但她每天都要走路去工作，不覺得有點太勉強了嗎？",
  str_homestory_821501001_15_dialog_content = "確實很辛苦。",
  str_homestory_821501001_16_dialog_content = "是吧是吧。這可是我深思熟慮後想出來的。",
  str_homestory_821501001_17_dialog_content = "麗蓓卡總說我不知道她想要什麼，哼哼，這次這個代步工具她肯定需要。",
  str_homestory_821501001_18_dialog_content = "可是……這輛車太招搖了，麗蓓卡不會喜歡的。",
  str_homestory_821501001_19_dialog_content = "放心啦放心啦，我可是麗蓓卡的姐姐，她喜歡什麼我還不知道嘛。",
  str_homestory_821501001_20_dialog_content = "麗蓓卡那孩子最喜歡花了，這輛車到處都是花，她怎麼會討厭呢。",
  str_homestory_821501001_21_dialog_content = "……呃，那試試吧？",
  str_homestory_821501001_22_dialog_content = "好，我現在就去給麗蓓卡說一下。",
  str_homestory_821501001_23_dialog_content = "她應該會很高興吧。",
  str_homestory_821501001_24_dialog_content = "加油吧。",
  str_homestory_821601001_0_dialog_content = "璇極，這部機器怎麼了嗎？",
  str_homestory_821601001_1_dialog_content = "這是空裔以前使用的東西，感興趣嗎？",
  str_homestory_821601001_2_dialog_content = "唔，是紡織機吧。",
  str_homestory_821601001_3_dialog_content = "是的，臨空者號上有文獻記載。",
  str_homestory_821601001_4_dialog_content = "空谷曾靠這樣的機器來生產紡織品，過自給自足的生活。",
  str_homestory_821601001_5_dialog_content = "但它似乎需要勤加維護的樣子，已經很久沒用了……",
  str_homestory_821601001_6_dialog_content = "璇極想用嗎？",
  str_homestory_821601001_7_dialog_content = "倒是不必。",
  str_homestory_821601001_8_dialog_content = "只是這設計讓我很懷念罷了～",
  str_homestory_821601001_9_dialog_content = "懷念？",
  str_homestory_821601001_10_dialog_content = "嗯，這讓我想起小時候使用過的教學用機關。",
  str_homestory_821601001_11_dialog_content = "宗門的師傅為年幼弟子講解工造，會從原型機開始。",
  str_homestory_821601001_12_dialog_content = "像這樣的紡織機就是常見案例，算我的第二個老師了。",
  str_homestory_821601001_13_dialog_content = "難怪妳會對它感興趣。",
  str_homestory_821601001_14_dialog_content = "而且，原型機通常都很脆弱。",
  str_homestory_821601001_15_dialog_content = "我分到的那台紡織機也是，部分結構甚至和它一模一樣……",
  str_homestory_821601001_16_dialog_content = "師傅常藉此教育我們要愛惜工造。",
  str_homestory_821601001_17_dialog_content = "我也想愛護，但它還是很容易壞……哈哈。",
  str_homestory_821601001_18_option_content = "因為改造？",
  str_homestory_821601001_19_dialog_content = "你猜中囉。",
  str_homestory_821601001_20_option_content = "好脆弱",
  str_homestory_821601001_21_dialog_content = "不，主要是我太常改造它的原因……",
  str_homestory_821601001_22_dialog_content = "所以它沒辦法陪伴我到這門修行結束。",
  str_homestory_821601001_23_dialog_content = "等我成長到能應付它的時候，它已經修不好了。",
  str_homestory_821601001_24_dialog_content = "……原來如此。",
  str_homestory_821601001_25_dialog_content = "怎麼樣，要不要我把這台紡織機修好？",
  str_homestory_821601001_26_dialog_content = "對現在的我來說，讓它恢復正常狀態就很簡單了。",
  str_homestory_821601001_27_dialog_content = "我還能繼續改進它的結構，讓它盡量可以自動工作、自我修復。",
  str_homestory_821601001_28_dialog_content = "……唔<sprite=emo_sikao size=60 />，還是不用了吧。",
  str_homestory_821601001_29_dialog_content = "即使修好，原料也不好找，沒法發揮作用。",
  str_homestory_821601001_30_dialog_content = "更何況，現代人只需要去商店就能買到便宜又精美的布料。",
  str_homestory_821601001_31_dialog_content = "是啊……龍洲的城市也是如此。",
  str_homestory_821601001_32_dialog_content = "對普通人來說，現在是商會比工匠重要的時代了。",
  str_homestory_821601001_33_dialog_content = "這就是進步，不是嗎？",
  str_homestory_821601001_34_dialog_content = "還真無法反駁。它的使命結束了。",
  str_homestory_821601001_35_dialog_content = "讓它好好休息吧。",
  str_homestory_818702001_0_dialog_content = "天閑？李大師？",
  str_homestory_818702001_1_dialog_content = "你怎麼在這裡站著睡著了啊？",
  str_homestory_818702001_2_dialog_content = "醒醒，快回房間休息吧。",
  str_homestory_818702001_3_dialog_content = "哎喲喂！",
  str_homestory_818702001_4_dialog_content = "在下剛才不是身處雲霄寶殿，和天兵天將談笑風生嗎？",
  str_homestory_818702001_5_dialog_content = "這麼快就墮回凡塵了……",
  str_homestory_818702001_6_dialog_content = "看來，我的修爲還不夠呀。",
  str_homestory_818702001_7_dialog_content = "真是服了。你沒發現嗎？",
  str_homestory_818702001_8_dialog_content = "你差點靠著睡著的這個東西……",
  str_homestory_818702001_9_dialog_content = "是一座時鐘啊。",
  str_homestory_818702001_10_dialog_content = "這麼大的時鐘就在旁邊，你居然也能睡得香。",
  str_homestory_818702001_11_dialog_content = "此言差矣，差矣。",
  str_homestory_818702001_12_dialog_content = "據在下所知，這艾斯特拉大陸上，有不少人都在枕邊置一鬧鐘。",
  str_homestory_818702001_13_dialog_content = "在下以天爲蓋地爲廬，靠一日晷而睡。",
  str_homestory_818702001_14_dialog_content = "也是入鄉隨俗啦。",
  str_homestory_818702001_15_dialog_content = "可別人那麼做是爲了及時起床，你只是想打瞌睡<sprite=emo_kun size=60 />吧？",
  str_homestory_818702001_16_dialog_content = "你難道一點都感覺不到時間流逝的緊迫感嗎……",
  str_homestory_818702001_17_dialog_content = "正是時間緊迫，人生苦短，才要及時入睡。",
  str_homestory_818702001_18_dialog_content = "犯困當睡直須睡，莫待不困空欠伸。",
  str_homestory_818702001_19_dialog_content = "您不如也靠這兒睡那麼一睡，就懂得好啦。",
  str_homestory_818702001_20_option_content = "不睡。",
  str_homestory_818702001_21_dialog_content = "到底是年輕人吶。",
  str_homestory_818702001_22_dialog_content = "我這走南闖北久了的，可不想放棄打盹兒的機會。",
  str_homestory_818702001_23_option_content = "試試也行。",
  str_homestory_818702001_24_dialog_content = "您終於開竅啦！",
  str_homestory_818702001_25_dialog_content = "但我就算要在這裡睡，也要做個準備。",
  str_homestory_818702001_26_dialog_content = "把我的睡袋、野餐墊和各種裝備都帶來。",
  str_homestory_818702001_27_dialog_content = "還數您會享受，在下就只有這一幡倆鳥的，不頂用。",
  str_homestory_818702001_28_dialog_content = "唉，想來還是晷老兄你的命好啊。",
  str_homestory_818702001_29_dialog_content = "無論在龍洲還是艾斯特拉，你的作用都一樣。",
  str_homestory_818702001_30_dialog_content = "只要不出太陽就能休息。",
  str_homestory_818702001_31_dialog_content = "你已經進化到羨慕石頭去了嗎？",
  str_homestory_818702001_32_dialog_content = "可千萬別看不起石頭，石頭裡還能變出大英雄呢！",
  str_homestory_818702001_33_dialog_content = "可惜，在下只有在夢裡才能變成石頭。",
  str_homestory_818702001_34_dialog_content = "哎，說著說著，瞌睡又上來了。",
  str_homestory_818702001_35_dialog_content = "還真是一點緊張感都沒有啊……",
  str_homestory_818702001_36_dialog_content = "PlayerName，人生在世，莫要太清醒。",
  str_homestory_818702001_37_dialog_content = "摸魚曬網，浮生偷閒，有何不可？<sprite=emo_qingsong size=60 />",
  str_homestory_818702001_38_dialog_content = "也對……不愧是我熟悉的李天閑。",
  str_homestory_818802001_0_dialog_content = "丹棠呢？",
  str_homestory_818802001_1_dialog_content = "這風箏……做工真是別緻呢。",
  str_homestory_818802001_2_dialog_content = "這有棱有角的花紋，樸素的配色……",
  str_homestory_818802001_3_dialog_content = "很像龍洲大陸最常見的那種風箏。",
  str_homestory_818802001_4_dialog_content = "空裔也偏愛這素雅的風格？真是難得啊……",
  str_homestory_818802001_5_option_content = "龍洲的人喜歡放風箏嗎？",
  str_homestory_818802001_6_dialog_content = "那是當然。",
  str_homestory_818802001_7_option_content = "丹棠也放過風箏嗎？",
  str_homestory_818802001_8_dialog_content = "對。我很喜歡風箏。",
  str_homestory_818802001_9_dialog_content = "在龍洲，放風箏是小朋友很喜歡的活動。",
  str_homestory_818802001_10_dialog_content = "在我小時候，和姐姐妹妹一起放風箏是難得的樂趣。",
  str_homestory_818802001_11_dialog_content = "那時，我們的風箏線常常纏在一起。",
  str_homestory_818802001_12_dialog_content = "有時候甚至會吵起來呢，呵呵。",
  str_homestory_818802001_13_dialog_content = "不過一轉頭，我們又會和好如初。",
  str_homestory_818802001_14_dialog_content = "丹棠放的風箏，長什麼樣子呢？",
  str_homestory_818802001_15_dialog_content = "我的風箏？嗯……我放過的風箏可就多了。",
  str_homestory_818802001_16_dialog_content = "我的姐妹們比較喜歡鳥形的風箏，而我喜歡花形的。",
  str_homestory_818802001_17_dialog_content = "我還沒見過那種樣子的風箏。",
  str_homestory_818802001_18_dialog_content = "是啊，龍洲的風箏風格非常多樣化。",
  str_homestory_818802001_19_dialog_content = "以鄴國為例，鄴國喜歡在風箏上施加各式機巧。",
  str_homestory_818802001_20_dialog_content = "讓風箏的各個部位能各自舞動。",
  str_homestory_818802001_21_dialog_content = "我那時放的風箏，都是宮內的能工巧匠製作的。",
  str_homestory_818802001_22_dialog_content = "描金塗朱，雍容華貴。",
  str_homestory_818802001_23_dialog_content = "還真是懷念呢，真想再放一次風箏。",
  str_homestory_818802001_24_dialog_content = "這隻風箏可比不上妳以前的那一隻喔。",
  str_homestory_818802001_25_dialog_content = "無妨。我懷念的，是過去那種無憂無慮的時光。",
  str_homestory_818802001_26_dialog_content = "放什麼風箏，倒是次要了。",
  str_homestory_818802001_27_dialog_content = "唔，最近身邊的瑣事也已經處理完畢。",
  str_homestory_818802001_28_dialog_content = "我差不多也該休息一下了，正好可以放放風箏。",
  str_homestory_818802001_29_dialog_content = "如何，公子，要不要與我一同放風箏呀？",
  str_homestory_818802001_30_dialog_content = "這風箏，一個人放也沒意思。",
  str_homestory_818802001_31_dialog_content = "可惜這架子上只有一隻……",
  str_homestory_818802001_32_dialog_content = "這不是問題，我們可以一人放一會，或是我親自去做一隻。",
  str_homestory_822001001_0_dialog_content = "維吉爾？",
  str_homestory_822001001_1_dialog_content = "維吉爾，你怎麼一直盯著這個稻草人啊？",
  str_homestory_822001001_2_dialog_content = "這個稻草人……<sprite=emo_sikao size=60 />",
  str_homestory_822001001_3_dialog_content = "怎麼？難道這個稻草人是古董？",
  str_homestory_822001001_4_dialog_content = "第一眼看起來確實很像……",
  str_homestory_822001001_5_dialog_content = "真的嗎？這稻草人有什麼特別之處嗎？",
  str_homestory_822001001_6_dialog_content = "這稻草人身上的配件……說不定是古董。",
  str_homestory_822001001_7_dialog_content = "古董！真的嗎？",
  str_homestory_822001001_8_dialog_content = "嗯，這個背心，應該是影鎮一個名牌的限定產品。",
  str_homestory_822001001_9_dialog_content = "那可是五十年前流行的款式。",
  str_homestory_822001001_10_dialog_content = "這款限定產品最大的特點就是……",
  str_homestory_822001001_11_dialog_content = "這種花紋是在黑布上染白條紋形成的。",
  str_homestory_822001001_12_dialog_content = "而不是像一般的條紋圖案那樣，在白布上印黑條紋。",
  str_homestory_822001001_13_dialog_content = "而且衣領反面有用金線縫的數字。",
  str_homestory_822001001_14_dialog_content = "真的有耶……<sprite=emo_wuzui size=60 />",
  str_homestory_822001001_15_dialog_content = "然後，你仔細看稻草人的眼睛，這是黑曜石的。",
  str_homestory_822001001_16_dialog_content = "這個光澤和純度，都算得上是寶石等級。",
  str_homestory_822001001_17_dialog_content = "白夜城的貴族幾十年前常用這種寶石做鈕扣。",
  str_homestory_822001001_18_dialog_content = "這兩隻也非常相似。",
  str_homestory_822001001_19_dialog_content = "你不說，我還真沒發現。",
  str_homestory_822001001_20_dialog_content = "最後就是支撐這稻草人的木頭了……",
  str_homestory_822001001_21_dialog_content = "這支木頭的木材好像是香木。",
  str_homestory_822001001_22_dialog_content = "雖然木材偏細，但是靠近還是能聞到淡淡的香氣。",
  str_homestory_822001001_23_dialog_content = "這種木材做的手杖很值錢。",
  str_homestory_822001001_24_dialog_content = "哇……那這稻草人難道是價值連城了？",
  str_homestory_822001001_25_dialog_content = "可惜……古董也是得看整體性。",
  str_homestory_822001001_26_dialog_content = "一套的東西湊在一起雖然價值連城，但少一件就會失去價值。",
  str_homestory_822001001_27_dialog_content = "反過來也一樣，這個稻草人把這些毫不相關的東西堆在一起。",
  str_homestory_822001001_28_dialog_content = "即使站在藝術品的角度來看……",
  str_homestory_822001001_29_dialog_content = "這也只能說是當代的三流作品，不值錢了。",
  str_homestory_822001001_30_dialog_content = "遺憾……<sprite=emo_tanqi size=60 />",
  str_homestory_822001001_31_dialog_content = "除非……",
  str_homestory_822001001_32_dialog_content = "除非什麼？",
  str_homestory_822001001_33_dialog_content = "除非你把他拆了。你要這麼做嗎？哥哥。",
  str_homestory_822001001_34_dialog_content = "嗯……算了吧。",
  str_homestory_822001001_35_dialog_content = "我還是喜歡它以這種姿態站在這裡陪伴我們。",
  str_homestory_822001001_36_dialog_content = "嘿嘿，我就知道PlayerName哥哥會這麼說。",
  str_homestory_821901001_0_dialog_content = "怎麼了嗎？",
  str_homestory_821901001_1_dialog_content = "你的樣子……難道說……",
  str_homestory_821901001_2_dialog_content = "您很喜歡這個時鐘嗎？",
  str_homestory_821901001_3_dialog_content = "是我未曾見過的風格。",
  str_homestory_821901001_4_dialog_content = "這就是空裔的時鐘嗎？",
  str_homestory_821901001_5_dialog_content = "我想是吧。",
  str_homestory_821901001_6_dialog_content = "臨空者號上的一切，都是空裔的風格。",
  str_homestory_821901001_7_dialog_content = "它並非機械，而是利用日光的倒影來計時。",
  str_homestory_821901001_8_dialog_content = "這種巧思……",
  str_homestory_821901001_9_dialog_content = "可以稱之為影子的藝術。",
  str_homestory_821901001_10_dialog_content = "看來您真的很喜歡這座時鐘。",
  str_homestory_821901001_11_dialog_content = "流逝的時間，也令我不由得肅然起敬。",
  str_homestory_821901001_12_dialog_content = "因此，我也熱衷收藏各種風格的鐘錶。",
  str_homestory_821901001_13_dialog_content = "啊？外面的世界，連鐘錶也有很多種類嗎？",
  str_homestory_821901001_14_dialog_content = "白夜城的時鐘古典浪漫。",
  str_homestory_821901001_15_dialog_content = "北境的時鐘簡樸又實用。",
  str_homestory_821901001_16_dialog_content = "紅油沙漠的時鐘富有機械藝術。",
  str_homestory_821901001_17_dialog_content = "而影鎮的時鐘低調奢華。",
  str_homestory_821901001_18_dialog_content = "我懂了，您真的很愛收藏呢。",
  str_homestory_821901001_19_dialog_content = "我從來沒想過，日常用品也會這麼講究。",
  str_homestory_821901001_20_dialog_content = "您讓我大開眼界。",
  str_homestory_821901001_21_dialog_content = "那些鐘錶都是當代的產物。",
  str_homestory_821901001_22_dialog_content = "空裔的時鐘卻讓我意識到時光的厚重。",
  str_homestory_821901001_23_dialog_content = "這份感覺非常獨特。",
  str_homestory_821901001_24_dialog_content = "唔，這麼說的話……<sprite=emo_sikao size=60 />",
  str_homestory_821901001_25_dialog_content = "我想把它送給您。",
  str_homestory_821901001_26_dialog_content = "為什麼？",
  str_homestory_821901001_27_option_content = "我們是朋友",
  str_homestory_821901001_28_dialog_content = "出於友誼嗎？",
  str_homestory_821901001_29_dialog_content = "很真摯的說法。",
  str_homestory_821901001_30_option_content = "看您很喜歡",
  str_homestory_821901001_31_dialog_content = "即便如此，我也無意奪人所好。",
  str_homestory_821901001_32_dialog_content = "我很感謝你有這份心意。",
  str_homestory_821901001_33_dialog_content = "但就讓它待在自己的「家」中吧。",
  str_homestory_821901001_34_dialog_content = "我不懂，您不是很喜歡嗎？",
  str_homestory_821901001_35_dialog_content = "我這裡還有別的時鐘，所以……",
  str_homestory_821901001_36_dialog_content = "我很高興，你願意毫無保留跟朋友分享。",
  str_homestory_821901001_37_dialog_content = "不過我想，這個世界上，沒有更配得上它的地方。",
  str_homestory_821901001_38_dialog_content = "過去的時光代表著回憶，而回憶承載歷史。",
  str_homestory_821901001_39_dialog_content = "PlayerName，空裔的一切都在這些點點滴滴裡。",
  str_homestory_821901001_40_dialog_content = "這裡的一切對你都那麼有意義。",
  str_homestory_821901001_41_dialog_content = "我不希望取走任何物品。",
  str_homestory_821901001_42_dialog_content = "伊斯塔萬大人……",
  str_homestory_821901001_43_dialog_content = "再見了——願影子注視著你。",
  str_homestory_821801001_0_dialog_content = "涉女士？",
  str_homestory_821801001_1_dialog_content = "真是奇遇呢。能在這裡遇見您，今天一定會有好事發生。",
  str_homestory_821801001_2_dialog_content = "您說對嗎，PlayerName？",
  str_homestory_821801001_3_dialog_content = "奇遇？涉女士，這裡可是空庭耶……",
  str_homestory_821801001_4_dialog_content = "沒錯，我當然知道。",
  str_homestory_821801001_5_dialog_content = "但總是要有些巧合才好，無論是生意還是生活。",
  str_homestory_821801001_6_dialog_content = "抱歉，我不太明白。",
  str_homestory_821801001_7_dialog_content = "沒關係，讓我解釋給您聽。",
  str_homestory_821801001_8_dialog_content = "例如，客人您的空庭正好需要一些改造，而浮空商會……",
  str_homestory_821801001_9_dialog_content = "正好有個企劃。",
  str_homestory_821801001_10_dialog_content = "您說這是不是巧合？",
  str_homestory_821801001_11_dialog_content = "也就是說？",
  str_homestory_821801001_12_dialog_content = "這空庭十分特別，不過，您不覺得宿舍稍嫌普通了嗎？",
  str_homestory_821801001_13_option_content = "會嗎？",
  str_homestory_821801001_14_dialog_content = "當然，否則我又何必多此一言呢？",
  str_homestory_821801001_15_dialog_content = "您可能已經習慣了，所以不覺得。",
  str_homestory_821801001_16_dialog_content = "但我認為這樣普通的宿舍，跟空庭不太搭呢。",
  str_homestory_821801001_17_option_content = "我也覺得",
  str_homestory_821801001_18_dialog_content = "不愧是客人！",
  str_homestory_821801001_19_dialog_content = "既然如此，您就不想做點什麼嗎？",
  str_homestory_821801001_20_dialog_content = "像是，把宿舍改造一下？",
  str_homestory_821801001_21_dialog_content = "我的意思是，我們可以將宿舍打造得更豪華。",
  str_homestory_821801001_22_dialog_content = "更……豪華？",
  str_homestory_821801001_23_dialog_content = "那倒是不錯，可惜預算<sprite=emo_baiyebi size=60 />有限……",
  str_homestory_821801001_24_dialog_content = "不用擔心！您大可將這個計畫委託給我的浮空商會！",
  str_homestory_821801001_25_dialog_content = "我會免費為您將宿舍打造成足以與空庭相配的程度。",
  str_homestory_821801001_26_dialog_content = "免免免……免費？！",
  str_homestory_821801001_27_dialog_content = "不太好吧？",
  str_homestory_821801001_28_dialog_content = "雖然我們是朋友，但這樣的話涉女士也太吃虧了。",
  str_homestory_821801001_29_dialog_content = "您也知道，我不會做虧本生意。",
  str_homestory_821801001_30_dialog_content = "等到宿舍改造完畢，我們就把整座空庭打造成一個主題度假村。",
  str_homestory_821801001_31_dialog_content = "主題度假村！？",
  str_homestory_821801001_32_dialog_content = "您什麼都不用做，一切交給我就好。",
  str_homestory_821801001_33_dialog_content = "應該說，您要是願意，可以負責數錢，我保證您數到手軟！",
  str_homestory_821801001_34_dialog_content = "數錢數到手軟！！",
  str_homestory_821801001_35_dialog_content = "難道，這就是涉女士剛才說的企劃！！",
  str_homestory_821801001_36_dialog_content = "這……真的很難不心動<sprite=emo_aixin size=60 />！",
  str_homestory_821801001_37_dialog_content = "很好！那我們就這麼說定——",
  str_homestory_821801001_38_dialog_content = "等、等一下！涉女士！",
  str_homestory_821801001_39_dialog_content = "抱歉，只是……我想盡可能讓空庭先維持現狀。",
  str_homestory_821801001_40_dialog_content = "我還不知道空庭的生態環境承不承受得了……",
  str_homestory_821801001_41_dialog_content = "就這樣開主題度假村的話……",
  str_homestory_821801001_42_dialog_content = "原來如此，我明白了。",
  str_homestory_821801001_43_dialog_content = "也就是說，未來我們還是有機會發展旅宿業的，是嗎？",
  str_homestory_821801001_44_dialog_content = "啊？旅、旅宿業？！",
  str_homestory_821801001_45_dialog_content = "那我就靜待您的好消息囉～",
  str_homestory_822101001_0_dialog_content = "很感興趣嗎？",
  str_homestory_822101001_1_dialog_content = "看妳在這裡站了老半天，興致盎然的樣子。",
  str_homestory_822101001_2_dialog_content = "這件家具難道<sprite=emo_sikao size=60 />……",
  str_homestory_822101001_3_dialog_content = "是會自動分類回收的垃圾桶？",
  str_homestory_822101001_4_dialog_content = "咦？！妳怎麼會知道？",
  str_homestory_822101001_5_dialog_content = "這是空裔式樣的垃圾桶，和一般的垃圾桶不一樣。",
  str_homestory_822101001_6_dialog_content = "我以為沒那麼容易認出來呢。",
  str_homestory_822101001_7_dialog_content = "哼哼，小看我了吧？",
  str_homestory_822101001_8_dialog_content = "我來仔細告訴你我的分析過程吧。",
  str_homestory_822101001_9_dialog_content = "首先，我剛才駭入這件家具的控制程式看了一眼……",
  str_homestory_822101001_10_dialog_content = "妳對別人的家具做什麼啊？！",
  str_homestory_822101001_11_dialog_content = "使用的是另一種程式語言，簡潔又高明，不愧是空裔的高科技！",
  str_homestory_822101001_12_dialog_content = "但在功能上，能看出與啟光食堂自動分菜系統有相似性。",
  str_homestory_822101001_13_dialog_content = "可見這件家具同樣搭載「分類」功能。",
  str_homestory_822101001_14_dialog_content = "順帶一提，啟光食堂的程式是我寫的。",
  str_homestory_822101001_15_dialog_content = "能根據不同營養成分自動分類食物喔！",
  str_homestory_822101001_16_dialog_content = "真不錯。",
  str_homestory_822101001_17_dialog_content = "不知道有沒有一種營養成分能降低人對朋友家具的破壞慾。",
  str_homestory_822101001_18_dialog_content = "……總之，能從「分類」就聯想到垃圾桶，妳還挺厲害的。",
  str_homestory_822101001_19_dialog_content = "還有一個更具決定性的理由。",
  str_homestory_822101001_20_dialog_content = "哦？",
  str_homestory_822101001_21_dialog_content = "這件家具上，畫著一個很大的垃圾桶標誌。",
  str_homestory_822101001_22_dialog_content = "…………",
  str_homestory_822101001_23_dialog_content = "真的很神奇！",
  str_homestory_822101001_24_dialog_content = "「自動分類」雖然不是什麼了不起的技術。",
  str_homestory_822101001_25_dialog_content = "但要把自動分類系統做進這麼小巧的體積內——",
  str_homestory_822101001_26_dialog_content = "分類還做得這麼細緻……以啟光目前的技術根本做不到。",
  str_homestory_822101001_27_dialog_content = "空裔，真是個了不起的種族啊！",
  str_homestory_822101001_28_dialog_content = "……唔。",
  str_homestory_822101001_29_option_content = "真有這麼厲害嗎？",
  str_homestory_822101001_30_dialog_content = "只是個垃圾桶嘛。",
  str_homestory_822101001_31_dialog_content = "「只是個垃圾桶」，最了不起的就是這部分。",
  str_homestory_822101001_32_option_content = "沒想到妳這麼喜歡「自碼回收箱」",
  str_homestory_822101001_33_dialog_content = "弄得我都自豪起來了，嘿嘿。",
  str_homestory_822101001_34_dialog_content = "自豪就對了！",
  str_homestory_822101001_35_dialog_content = "高精尖科技誕生之初，都是應用在軍事領域。",
  str_homestory_822101001_36_dialog_content = "只有非常非常普及，普及到不值一提後，才能惠及普通人民。",
  str_homestory_822101001_37_dialog_content = "這個……「自碼回收箱」？正因為只是個垃圾桶……",
  str_homestory_822101001_38_dialog_content = "才充分體現空裔文明的偉大啊！",
  str_homestory_822101001_39_dialog_content = "喔喔……！仔細一想，確實是這個道理！",
  str_homestory_822101001_40_dialog_content = "雖然我對妳駭入底層程式的行為還是抱有疑慮……",
  str_homestory_822101001_41_dialog_content = "但是，每次跟妳聊天真的很有收穫。",
  str_homestory_822101001_42_dialog_content = "謝謝妳，阿爾戈爾。",
  str_homestory_822101001_43_dialog_content = "客氣了！與其道謝，不如授權我拆開自碼回收箱徹底研究——",
  str_homestory_822101001_44_dialog_content = "這妳就別想了！",
  str_homestory_822301001_0_dialog_content = "這石像……",
  str_homestory_822301001_1_dialog_content = "很少在小PlayerName的洞府裡看到塑像呢。",
  str_homestory_822301001_2_dialog_content = "這座塑像，對小PlayerName有什麼特別的意義嗎？",
  str_homestory_822301001_3_dialog_content = "被妳看穿了……這是一位空裔女性的塑像。",
  str_homestory_822301001_4_dialog_content = "空裔……這麼說，是小PlayerName的族人？很久以前的族人。",
  str_homestory_822301001_5_dialog_content = "從這雕刻的痕跡中，阿霓能感受到漫長歲月的氣息。",
  str_homestory_822301001_6_dialog_content = "傳說中，她是一位旅行家，踏遍世界的名山大川。",
  str_homestory_822301001_7_dialog_content = "正如阿霓所說，那是很久很久以前的事了……",
  str_homestory_822301001_8_dialog_content = "在這暗鬼<sprite=emo_kulou size=60 />遍地的世界，空裔再獨自旅遊就很危險了……",
  str_homestory_822301001_9_dialog_content = "有吾在側，汝何須懼怕？",
  str_homestory_822301001_10_dialog_content = "有朝一日，汝亦以雕塑之形傳於後世，亦未可知。",
  str_homestory_822301001_11_dialog_content = "咦？！我、我嗎？應該不會吧，我可能沒有那麼大能耐……",
  str_homestory_822301001_12_dialog_content = "怎麼不可能呀？好比說，適逢天下大旱，阿霓招來雷雨，澤被蒼生。",
  str_homestory_822301001_13_dialog_content = "小PlayerName在一旁引路，帶阿霓買麥芽糖……",
  str_homestory_822301001_14_dialog_content = "那你就成為「龍神童子」，和阿霓一起變成塑像啦！",
  str_homestory_822301001_15_dialog_content = "好具體，總覺得是真實發生過的事……",
  str_homestory_822301001_16_dialog_content = "又比如，阿霓一口氣從冬天的海難中救出三十八個人。",
  str_homestory_822301001_17_dialog_content = "你善良可親，為災民披上毯子、升起火堆，免得他們死於寒凍……",
  str_homestory_822301001_18_dialog_content = "那你的塑像也能立在阿霓旁邊，享受後世的香火。",
  str_homestory_822301001_19_dialog_content = "……",
  str_homestory_822301001_20_dialog_content = "怎麼啦？這些故事，你覺得沒意思嗎？",
  str_homestory_822301001_21_option_content = "有意思",
  str_homestory_822301001_22_dialog_content = "可是，也很悲傷。",
  str_homestory_822301001_23_option_content = "不好說……",
  str_homestory_822301001_24_dialog_content = "感覺無法用「有沒有意思」來衡量。",
  str_homestory_822301001_25_dialog_content = "因為，這些都不只是故事吧？",
  str_homestory_822301001_26_dialog_content = "我在龍洲的那段時間，就已經見過好幾處阿霓的塑像。",
  str_homestory_822301001_27_dialog_content = "可以想像妳在龍洲各地幫助過多少人，留下過多少剛才那樣的傳說。",
  str_homestory_822301001_28_dialog_content = "而那些往事中，帶妳買麥芽糖的人、幫助妳救人的人……",
  str_homestory_822301001_29_dialog_content = "恐怕都不在人世了……只留妳在。",
  str_homestory_822301001_30_dialog_content = "小PlayerName，難道在同情我？",
  str_homestory_822301001_31_dialog_content = "如果我說，我對妳經歷的離別而感到難過……",
  str_homestory_822301001_32_dialog_content = "會不會太自大，又對龍神太冒犯了？",
  str_homestory_822301001_33_dialog_content = "汝乃血肉之軀，心生此想，最是自然不過。",
  str_homestory_822301001_34_dialog_content = "吾感念於汝的，亦是此處。",
  str_homestory_822301001_35_dialog_content = "歲月悠長，終將帶走一切。",
  str_homestory_822301001_36_dialog_content = "哪怕如我長生，與天地相比，也不過小小一蜉蝣。",
  str_homestory_822301001_37_dialog_content = "既然眾生都是蜉蝣，能同行一段，已是緣分，珍惜便是。",
  str_homestory_822301001_38_dialog_content = "我若憐憫凡人之短壽，反倒失於傲慢了。",
  str_homestory_822301001_39_dialog_content = "這樣看倒也有理……連我的心情都一下子開闊了。",
  str_homestory_822301001_40_dialog_content = "「有情何怕隔年期」……龍洲的諺語，是這樣說的嗎？",
  str_homestory_822301001_41_dialog_content = "一字不差！小PlayerName，最近成長很大。",
  str_homestory_822301001_42_dialog_content = "時光殘酷，時光也有好的一面。",
  str_homestory_822301001_43_dialog_content = "嘿嘿<sprite=emo_qingsong size=60 />……那我畢竟不能虛擲光陰，原地踏步嘛。",
  str_homestory_822301001_44_dialog_content = "而且，若非時光流逝，你我又怎能相遇……",
  str_homestory_822301001_45_dialog_content = "又怎能在此地閒話往昔呢？",
  str_homestory_822401001_0_dialog_content = "羅松？",
  str_homestory_822401001_1_dialog_content = "羅松想使用這個嗎？",
  str_homestory_822401001_2_dialog_content = "當然想！這東西做得還真是精緻啊。",
  str_homestory_822401001_3_dialog_content = "精……精緻？",
  str_homestory_822401001_4_dialog_content = "當然了，你看，這勾起人對壘之慾的神色。",
  str_homestory_822401001_5_dialog_content = "這軟硬剛好的觸感。",
  str_homestory_822401001_6_dialog_content = "不管怎麼打都會自己回到原位的神奇功效……",
  str_homestory_822401001_7_dialog_content = "這種鍛煉拳頭的工具，簡直太完美了！",
  str_homestory_822401001_8_option_content = "可以理解",
  str_homestory_822401001_9_dialog_content = "果然<sprite=emo_guilian size=60 />，我就知道PlayerName你會懂。",
  str_homestory_822401001_10_option_content = "不太懂……",
  str_homestory_822401001_11_dialog_content = "我也解釋不清<sprite=emo_sikao size=60 />，大概是習武之人的直覺？",
  str_homestory_822401001_12_dialog_content = "我當初在龍州遊歷的時候，每天都在為訓練而苦惱。",
  str_homestory_822401001_13_dialog_content = "鍛煉、修行、舞拳這種事啊。",
  str_homestory_822401001_14_dialog_content = "只一日不練，說不定就手法生疏了。",
  str_homestory_822401001_15_dialog_content = "不過嘛，鍛煉畢竟是鍛煉，目的是強身健體。",
  str_homestory_822401001_16_dialog_content = "很多人鍛煉的時候，喜歡把吃苦掛在嘴邊，然後故意折磨自己。",
  str_homestory_822401001_17_dialog_content = "這就本末倒置了吧。",
  str_homestory_822401001_18_dialog_content = "對呀！",
  str_homestory_822401001_19_dialog_content = "像有的人練習「鐵山靠」這門功夫，就以大樹為陪，不斷撞之。",
  str_homestory_822401001_20_dialog_content = "實際上那樣很容易留下傷病，非常不明智。",
  str_homestory_822401001_21_dialog_content = "原來如此，又長知識了……",
  str_homestory_822401001_22_dialog_content = "在遊歷的時候，我因為找不到適合的器材，也用樹來練過。",
  str_homestory_822401001_23_dialog_content = "可能是因為年輕吧，所以我沒什麼感覺。",
  str_homestory_822401001_24_dialog_content = "直到後來，我開始教導阿丁牠們。",
  str_homestory_822401001_25_dialog_content = "我發現阿丁牠們用我的方式來訓練，非常容易受傷。",
  str_homestory_822401001_26_dialog_content = "這時我才意識到，我過去使用的器材和方式還是太粗暴了。",
  str_homestory_822401001_27_dialog_content = "為此，我開始更留意護具之類的保護措施，講究安全性。",
  str_homestory_822401001_28_dialog_content = "甚至為阿丁牠們做了專用的訓練工具……",
  str_homestory_822401001_29_dialog_content = "對那些傢伙，不能用我們的邏輯來設計工具，著實費了我一番功夫。",
  str_homestory_822401001_30_dialog_content = "尤其是梅花樁，試了好幾次才找到適合牠們那小短腿的間距。",
  str_homestory_822401001_31_dialog_content = "羅松，在這方面很用心呢。",
  str_homestory_822401001_32_dialog_content = "那當然，我這人沒什麼別的愛好，就是喜歡強身健體。",
  str_homestory_822401001_33_dialog_content = "替朋友選的道具，當然要用心。",
  str_homestory_822401001_34_dialog_content = "下次有機會的話，我也設計一些適合PlayerName的器材吧。",
  str_homestory_822501001_0_dialog_content = "那盞燈……",
  str_homestory_822501001_1_dialog_content = "提亞拉，妳喜歡那盞庭燈嗎？",
  str_homestory_822501001_2_dialog_content = "可以再靠近一點看呀。",
  str_homestory_822501001_3_dialog_content = "……現在的距離，剛剛好。",
  str_homestory_822501001_4_dialog_content = "從這裡眺望，那盞燈讓我想起北境的「燈塔」。",
  str_homestory_822501001_5_dialog_content = "這麼一看，還真有點像。",
  str_homestory_822501001_6_dialog_content = "可惜那只是一盞普通的燈，不像「燈塔」庇護著北境的生靈。",
  str_homestory_822501001_7_dialog_content = "……",
  str_homestory_822501001_8_dialog_content = "我小時候，常坐在雪松林頂上眺望「燈塔」。",
  str_homestory_822501001_9_dialog_content = "「燈塔」是那麼明亮……",
  str_homestory_822501001_10_dialog_content = "無論夜多深、霧多濃，「燈塔」的光芒都能照遍四方。",
  str_homestory_822501001_11_dialog_content = "在那種光芒的籠罩下，雪松林裡很安靜。",
  str_homestory_822501001_12_dialog_content = "沒有暗鬼的咆哮，沒有光靈的慘叫……那種安靜非常可貴。",
  str_homestory_822501001_13_dialog_content = "那是我們北境人才擁有，最特別的「燈塔」。",
  str_homestory_822501001_14_dialog_content = "看得出來，北境人對「燈塔」都充滿了感激和崇敬。",
  str_homestory_822501001_15_dialog_content = "其實我知道，令大家感激、崇敬的並不是那座「燈塔」……",
  str_homestory_822501001_16_dialog_content = "有一次，我追著一隻狡猾的獵物，不知不覺追了好遠……",
  str_homestory_822501001_17_dialog_content = "直到陰影中暗鬼的吼聲驚醒我！我才發現自己離家太遠了……",
  str_homestory_822501001_18_dialog_content = "就在那時，我看見燈塔的光。",
  str_homestory_822501001_19_dialog_content = "離家太遠……是還在能看到「燈塔」的地方嗎？",
  str_homestory_822501001_20_dialog_content = "……不，我看到的不是庇護我們的「燈塔」。",
  str_homestory_822501001_21_dialog_content = "那只是一座普通的燈塔，立在海岬上……",
  str_homestory_822501001_22_dialog_content = "每到夜晚，那裡就變成暗鬼的巢穴。",
  str_homestory_822501001_23_dialog_content = "天啊……",
  str_homestory_822501001_24_dialog_content = "我藏在樹林裡，動也不敢動。",
  str_homestory_822501001_25_dialog_content = "那燈塔的光不時掃過我……",
  str_homestory_822501001_26_dialog_content = "我望著燈塔，暗鬼就在那底下走來走去。",
  str_homestory_822501001_27_dialog_content = "你知道我忽然發現什麼嗎？",
  str_homestory_822501001_28_dialog_content = "什麼？",
  str_homestory_822501001_29_dialog_content = "那座燈塔，與我感激、崇敬的「燈塔」其實一模一樣。",
  str_homestory_822501001_30_dialog_content = "……",
  str_homestory_822501001_31_dialog_content = "一樣明亮的光芒，一樣能照徹最黑的夜，穿透最濃的霧……",
  str_homestory_822501001_32_dialog_content = "但它保護不了我。那一整個晚上，只要我敢動彈一下……",
  str_homestory_822501001_33_dialog_content = "暗鬼群就會將我撕成碎片。",
  str_homestory_822501001_34_dialog_content = "提亞拉……",
  str_homestory_822501001_35_dialog_content = "就是在那個晚上，我明白了。",
  str_homestory_822501001_36_dialog_content = "只是「燈塔」本身，其實沒有什麼特別的。",
  str_homestory_822501001_37_dialog_content = "就像我們眼前這盞燈，只是一盞普通的燈，那也只是一座普通的塔。",
  str_homestory_822501001_38_dialog_content = "若沒有人點亮它，維持它，用信念成就它的光，它什麼也不是。",
  str_homestory_822501001_39_dialog_content = "庇護我們北境人的，從來不是北境的「燈塔」……",
  str_homestory_822501001_40_dialog_content = "而是伯利恆女王。",
  str_homestory_822501001_41_dialog_content = "……",
  str_homestory_822501001_42_option_content = "陛下的信念令人敬畏",
  str_homestory_822501001_43_dialog_content = "即使沒有「燈塔」，她也會竭盡全力，守護北境的百姓。",
  str_homestory_822501001_44_option_content = "那一定是妳人生中很重要的一夜",
  str_homestory_822501001_45_dialog_content = "在那一夜，妳鑄就了屬於妳的信念。",
  str_homestory_822501001_46_dialog_content = "沒錯。",
  str_homestory_822501001_47_dialog_content = "即使不及女王陛下萬一，我也還是會追隨陛下的腳步。",
  str_homestory_822501001_48_dialog_content = "為守護而生，為守護而戰。",
  str_homestory_822501001_49_dialog_content = "真巧，我也是這樣想。",
  str_homestory_822501001_50_dialog_content = "尤其是「不及女王陛下萬一」這部分。",
  str_homestory_822501001_51_dialog_content = "哈哈，女王陛下又有誰追得上呢？",
  str_homestory_822501001_52_dialog_content = "但是，只要遙望她的背影，我就永遠不會迷失方向。",
  str_homestory_822601001_0_dialog_content = "我說……",
  str_homestory_822601001_1_dialog_content = "蕾切爾，妳對這匹木馬有興趣嗎？",
  str_homestory_822601001_2_dialog_content = "雖然有點幼稚，但坐上去搖啊搖，意外地很有趣呢。",
  str_homestory_822601001_3_dialog_content = "妳要不要試試看？",
  str_homestory_822601001_4_dialog_content = "不……",
  str_homestory_822601001_5_dialog_content = "再怎麼說我都過了那個年紀了。",
  str_homestory_822601001_6_dialog_content = "倒是你，原來很常玩搖搖木馬嗎？",
  str_homestory_822601001_7_dialog_content = "也、也沒有到「很常」的地步……",
  str_homestory_822601001_8_dialog_content = "（以為蕾切爾不好意思玩木馬，反而暴了我自己的底！）",
  str_homestory_822601001_9_dialog_content = "不過，這確實是很精緻的玩具。",
  str_homestory_822601001_10_dialog_content = "乍看簡單，但設計到位，做工也很精良。",
  str_homestory_822601001_11_dialog_content = "不管從結構力學還是人體工學方面看，都堪稱範本。",
  str_homestory_822601001_12_dialog_content = "不自覺就會看出神。",
  str_homestory_822601001_13_dialog_content = "哇……我從來沒注意過妳說的這些。",
  str_homestory_822601001_14_dialog_content = "妳隨便就能看出這麼多門道？",
  str_homestory_822601001_15_dialog_content = "這是工程專業的基本功。",
  str_homestory_822601001_16_dialog_content = "任何物體看一眼就要能畫出三視圖。",
  str_homestory_822601001_17_dialog_content = "我差不多知道這匹木馬該怎麼製作了。",
  str_homestory_822601001_18_dialog_content = "這已經算是超能力了吧……",
  str_homestory_822601001_19_dialog_content = "好，木馬就送給妳吧！",
  str_homestory_822601001_20_dialog_content = "咦？",
  str_homestory_822601001_21_option_content = "帶回家比較方便研究。",
  str_homestory_822601001_22_dialog_content = "知道了，是不希望我再待在這裡煩你吧？",
  str_homestory_822601001_23_dialog_content = "怎麼會！",
  str_homestory_822601001_24_option_content = "難得妳這麼喜歡。",
  str_homestory_822601001_25_dialog_content = "我最喜歡的是你的巨像。",
  str_homestory_822601001_26_dialog_content = "放過臨空者號！",
  str_homestory_822601001_27_dialog_content = "呵……開玩笑的。",
  str_homestory_822601001_28_dialog_content = "謝謝你的心意，不過……",
  str_homestory_822601001_29_dialog_content = "送給妹妹的禮物，我希望能親手製作。",
  str_homestory_822601001_30_dialog_content = "……妹妹？",
  str_homestory_822601001_31_dialog_content = "嗯。一看到這匹木馬，我就想做一個一模一樣的送給妹妹。",
  str_homestory_822601001_32_dialog_content = "我小時候沒有機會接觸這些玩具，那麼至少讓妹妹……",
  str_homestory_822601001_33_dialog_content = "也許只是我的自我滿足吧。",
  str_homestory_822601001_34_dialog_content = "蕾切爾……",
  str_homestory_822601001_35_dialog_content = "我剛才是說認真的。",
  str_homestory_822601001_36_dialog_content = "木馬……真的很有趣，妳絕對會想試試看！",
  str_homestory_822601001_37_dialog_content = "欸……欸？",
  str_homestory_822601001_38_dialog_content = "試試看嘛！親自坐過才能做出最好的禮物給妹妹，不是嗎？",
  str_homestory_822601001_39_dialog_content = "請，不用客氣！",
  str_homestory_822601001_40_dialog_content = "那……那我就……試一下。",
  str_homestory_822601001_41_dialog_content = "我敢說妳一定會上癮。",
  str_homestory_822701001_0_dialog_content = "澤塔？",
  str_homestory_822701001_1_dialog_content = "到底是什麼東西呢……",
  str_homestory_822701001_2_dialog_content = "這可愛到爆的翅膀，這精湛的做工……",
  str_homestory_822701001_3_dialog_content = "根據勇者澤塔的鑑定，這一定是某種遠古的祕寶吧？",
  str_homestory_822701001_4_dialog_content = "這是彩偶。",
  str_homestory_822701001_5_dialog_content = "喔！空之末裔！真是巧遇啊。",
  str_homestory_822701001_6_dialog_content = "既然你能說出它的名字，就證明你對這個東西一定很有研究。",
  str_homestory_822701001_7_dialog_content = "這是溫德嵐節的慶典裝飾。",
  str_homestory_822701001_8_dialog_content = "「溫德嵐節」？",
  str_homestory_822701001_9_dialog_content = "有人跟我說過，這對光靈相當於懷念聖者、紀念光明的節日。",
  str_homestory_822701001_10_dialog_content = "懷念聖者、紀念光明？聽起來超酷的！",
  str_homestory_822701001_11_dialog_content = "我以前竟然都不知道，世界上還有這麼酷的節日？",
  str_homestory_822701001_12_dialog_content = "我的朋友好像也是從書中得知這個節日的。",
  str_homestory_822701001_13_dialog_content = "對我們空裔來說，這是非常重要的節日。",
  str_homestory_822701001_14_dialog_content = "這一天，我們會紀念大自然，舉行盛大的宴會。",
  str_homestory_822701001_15_dialog_content = "唔……過節的方法聽起來好普通喔。",
  str_homestory_822701001_16_dialog_content = "咳咳……總之這個就是我們在溫德嵐節做的裝飾品啦。",
  str_homestory_822701001_17_dialog_content = "我們會在彩偶的肚子裡放祝福和糖果。",
  str_homestory_822701001_18_dialog_content = "祝福……還有……糖果！",
  str_homestory_822701001_19_dialog_content = "過節吧！我們現在就來過溫德嵐節！",
  str_homestory_822701001_20_dialog_content = "妳幹嘛突然這麼興奮？",
  str_homestory_822701001_21_dialog_content = "我也想做彩偶！",
  str_homestory_822701001_22_option_content = "即使不過節也能做彩偶呀。",
  str_homestory_822701001_23_dialog_content = "也對吼，那你教我怎麼做彩偶吧。",
  str_homestory_822701001_24_option_content = "好，我來教妳怎麼做。",
  str_homestory_822701001_25_dialog_content = "真的嗎！空之末裔，你人真是太好了！",
  str_homestory_822701001_26_dialog_content = "嘿嘿，做好後我就在裡面放我的傑作……",
  str_homestory_822701001_27_dialog_content = "然後在大家好奇這裡面是什麼的時候……",
  str_homestory_822701001_28_dialog_content = "噗啪！嘩啦！呼嚕！把煙霧和糖果帶給大家！",
  str_homestory_822701001_29_dialog_content = "呃？妳該不會想在裡面放炸彈吧？",
  str_homestory_822701001_30_dialog_content = "不會全部放啦，要的是糖果四處飛濺的衝擊感！",
  str_homestory_822801001_0_dialog_content = "巴緹牙！",
  str_homestory_822801001_1_dialog_content = "妳終於出來了！",
  str_homestory_822801001_2_dialog_content = "嗚……是你呀……",
  str_homestory_822801001_3_dialog_content = "有事情找我？",
  str_homestory_822801001_4_dialog_content = "不，只是發現妳一直待在帳篷裡打遊戲。",
  str_homestory_822801001_5_dialog_content = "想找妳出來透透氣。",
  str_homestory_822801001_6_dialog_content = "哈——呼——",
  str_homestory_822801001_7_dialog_content = "透完了。那，我回去了。",
  str_homestory_822801001_8_dialog_content = "等等！至少在外面散個步再回去吧？！",
  str_homestory_822801001_9_dialog_content = "呃，外面啊……",
  str_homestory_822801001_10_dialog_content = "巴緹牙，就這麼討厭室外嗎？",
  str_homestory_822801001_11_dialog_content = "這裡的環境……也不行嗎？",
  str_homestory_822801001_12_dialog_content = "沒有！絕對不是討厭這裡的意思……",
  str_homestory_822801001_13_dialog_content = "這、這裡還是比影鎮大街好很多啦！",
  str_homestory_822801001_14_dialog_content = "啊……比較對象是影鎮大街呀……",
  str_homestory_822801001_15_dialog_content = "嗚哇——對不起，好像說錯話了！",
  str_homestory_822801001_16_dialog_content = "但我只熟悉影鎮大街……",
  str_homestory_822801001_17_dialog_content = "那就更應該多去其他地方逛逛了。",
  str_homestory_822801001_18_option_content = "PlayerName……想去哪裡？",
  str_homestory_822801001_19_dialog_content = "河邊",
  str_homestory_822801001_20_dialog_content = "我們可以找一條河，下河捉魚。",
  str_homestory_822801001_21_dialog_content = "喔喔，實戰版「捕魚大師」嗎？",
  str_homestory_822801001_22_dialog_content = "不過，不知道我能不能捉到真的魚……",
  str_homestory_822801001_23_dialog_content = "哈哈，和遊戲的規則確實不一樣呢。",
  str_homestory_822801001_24_option_content = "樹林",
  str_homestory_822801001_25_dialog_content = "去樹林裡露營吧！生火、野炊、採野果！",
  str_homestory_822801001_26_dialog_content = "喔，似乎是需要認真經營的玩法。",
  str_homestory_822801001_27_dialog_content = "提前規劃地點和流程，提高效率……",
  str_homestory_822801001_28_dialog_content = "這種事沒有成就和積分要完成啦！",
  str_homestory_822801001_29_dialog_content = "我，知道了，我會試試看……",
  str_homestory_822801001_30_dialog_content = "要出去玩的話，可以把這個帳篷也帶上嗎？",
  str_homestory_822801001_31_dialog_content = "累的時候，我們就可以縮進去打遊戲了……",
  str_homestory_822801001_32_dialog_content = "嗯，這樣應該也可以吧……",
  str_homestory_822901001_0_dialog_content = "維多利亞小姐，怎麼一直盯著這張吊椅看呢？",
  str_homestory_822901001_1_dialog_content = "這吊椅有哪裡不對勁嗎？",
  str_homestory_822901001_2_dialog_content = "我只是想起真理結社也有一把類似的吊椅。",
  str_homestory_822901001_3_dialog_content = "是他們最喜歡的椅子。",
  str_homestory_822901001_4_dialog_content = "他們？",
  str_homestory_822901001_5_dialog_content = "每每路過那把吊椅，十次有八次會看到拜里厄蜷在裡面讀書。",
  str_homestory_822901001_6_dialog_content = "剩下兩次是她枕著書睡著了。",
  str_homestory_822901001_7_dialog_content = "那不就是被她霸佔了嗎！",
  str_homestory_822901001_8_dialog_content = "偶爾，我會看到艾希圍著那張吊椅打轉。",
  str_homestory_822901001_9_dialog_content = "咕噥著一些常人難以理解的話語，像是……",
  str_homestory_822901001_10_dialog_content = "「在坐墊和靠背裝上鐵刺，就能成為完美的刑具了！」",
  str_homestory_822901001_11_dialog_content = "趁她還沒下手，妳要保護好那把吊椅……還有拜里厄啊！",
  str_homestory_822901001_12_dialog_content = "不能怪艾希有這樣的想法。",
  str_homestory_822901001_13_dialog_content = "吊椅濺上聖釘的血時，看上去確實與刑具……頗為神似。",
  str_homestory_822901001_14_dialog_content = "連聖釘也？！",
  str_homestory_822901001_15_dialog_content = "也不能怪聖釘。那確實是一把舒服的椅子。",
  str_homestory_822901001_16_dialog_content = "我們虔誠的苦修者偶爾也會想要坐上去吧。",
  str_homestory_822901001_17_dialog_content = "……",
  str_homestory_822901001_18_dialog_content = "結果……就只有妳從來沒坐過嗎？",
  str_homestory_822901001_19_dialog_content = "回想起來，的確如此。",
  str_homestory_822901001_20_dialog_content = "我或許是在有意地躲避它。",
  str_homestory_822901001_21_dialog_content = "躲避……一把椅子？",
  str_homestory_822901001_22_dialog_content = "那是瓦拉吉古宅中的吊椅，曾屬於我的父親。",
  str_homestory_822901001_23_dialog_content = "浮士德不知出於什麼心態，特地將它搬回來還給我。",
  str_homestory_822901001_24_dialog_content = "看到它，我就想到父母、童年，還有瓦拉吉別無選擇的命運。",
  str_homestory_822901001_25_dialog_content = "我……並不想常常憶起那一切。",
  str_homestory_822901001_26_dialog_content = "浮士德也太多事了",
  str_homestory_822901001_27_dialog_content = "他或許是想提醒我，面對宿命也是真理的一環。",
  str_homestory_822901001_28_dialog_content = "吊椅畢竟紀念了妳的童年",
  str_homestory_822901001_29_dialog_content = "回憶中有痛苦，但也有快樂吧？",
  str_homestory_822901001_30_dialog_content = "呵，的確。父親曾抱著我在吊椅上讀書，那是一段美好的記憶。",
  str_homestory_822901001_31_dialog_content = "不過，經歷了最近種種，我明白了。",
  str_homestory_822901001_32_dialog_content = "過往的痛苦只存在於我心中。",
  str_homestory_822901001_33_dialog_content = "只要我能超越它，吊椅就只是一把吊椅而已。",
  str_homestory_822901001_34_dialog_content = "正如同您與生俱來的智慧所說——",
  str_homestory_822901001_35_dialog_content = "我不該盯著它看，而是應該舒服地坐上去。",
  str_homestory_822901001_36_dialog_content = "沒、沒錯，這就是我想表達的！",
  str_homestory_822901001_37_dialog_content = "請坐，請坐，我的吊椅隨時歡迎妳。",
  str_homestory_822901001_38_dialog_content = "那就讓我先道一聲謝了，PlayerName。",
  str_homestory_823001001_0_dialog_content = "這棟房子外形很奇怪吧？",
  str_homestory_823001001_1_dialog_content = "不過，別看它這樣，裡面意外地舒適唷！",
  str_homestory_823001001_2_dialog_content = "「奇怪」？怎麼會呢？",
  str_homestory_823001001_3_dialog_content = "那塔樓一般的結構，以及窗戶的排列，就像一座小小的城堡。",
  str_homestory_823001001_4_dialog_content = "如果您允許，我想偶爾來這裡修行。",
  str_homestory_823001001_5_dialog_content = "沒問題！",
  str_homestory_823001001_6_dialog_content = "你隨時可以來。",
  str_homestory_823001001_7_dialog_content = "沒問題……",
  str_homestory_823001001_8_dialog_content = "只要你保證房子裡不會上演流血事件……",
  str_homestory_823001001_9_dialog_content = "我永遠感激您的慷慨。",
  str_homestory_823001001_10_dialog_content = "說起來，威廉先生就是在一座城堡裡隱修的吧？",
  str_homestory_823001001_11_dialog_content = "正、正是！您為何忽然提起導師？",
  str_homestory_823001001_12_dialog_content = "我是想，你希望在「像城堡一樣」的房子裡修行……",
  str_homestory_823001001_13_dialog_content = "會不會是受到威廉先生的影響呢？",
  str_homestory_823001001_14_dialog_content = "……",
  str_homestory_823001001_15_dialog_content = "說謊是罪孽。既然被您看穿，我也只能承認了。",
  str_homestory_823001001_16_dialog_content = "我確實有一點點想要……模仿導師。",
  str_homestory_823001001_17_dialog_content = "儘管我已經答應導師不會再這麼做。",
  str_homestory_823001001_18_dialog_content = "渺小如我，竟想變得像導師一樣，這是莫大的罪行！我——",
  str_homestory_823001001_19_dialog_content = "不會啊！想要模仿崇拜的人，這不是很正常嗎？",
  str_homestory_823001001_20_dialog_content = "你都模仿了些什麼？",
  str_homestory_823001001_21_dialog_content = "我......",
  str_homestory_823001001_22_dialog_content = "我試著……把頭髮留長。",
  str_homestory_823001001_23_dialog_content = "……",
  str_homestory_823001001_24_dialog_content = "但我的髮質似乎不適合長髮。一對麻雀以為那是牠們的巢……",
  str_homestory_823001001_25_dialog_content = "等我結束懺悔時，雛鳥都從我頭上孵出來了。",
  str_homestory_823001001_26_dialog_content = "這懺悔真夠久的啊……",
  str_homestory_823001001_27_dialog_content = "剪掉頭髮後，我又試著像導師一樣晚上不睡，徹夜讀書。",
  str_homestory_823001001_28_dialog_content = "結果走路時睡著，從樓梯上滾了下去。",
  str_homestory_823001001_29_dialog_content = "喂喂！",
  str_homestory_823001001_30_dialog_content = "導師那把劍，「赤流」，我覺得非常帥氣。",
  str_homestory_823001001_31_dialog_content = "當我有一天試著用我的血模仿「赤流」時，導師終於制止了我。",
  str_homestory_823001001_32_dialog_content = "噢！他一定是對你說「你只要做自己就很好」吧？",
  str_homestory_823001001_33_dialog_content = "導師親切地說：「聖釘，抬起頭來。你看到了什麼？」",
  str_homestory_823001001_34_dialog_content = "我說：「導師，我看見了天空。真理之主就在那裡注視著我們。」",
  str_homestory_823001001_35_dialog_content = "導師又問：「你知道為什麼我們能看到天空嗎？」",
  str_homestory_823001001_36_dialog_content = "我說：「因為主創造了它。」",
  str_homestory_823001001_37_dialog_content = "導師說：「是因為你的『赤流』剛剛削掉了我們的屋頂。」",
  str_homestory_823001001_38_dialog_content = "…………",
  str_homestory_823001001_39_dialog_content = "我深刻懺悔了自己的罪行。",
  str_homestory_823001001_40_dialog_content = "然後我醒悟了，我沒有學到導師身上最值得學習的東西。",
  str_homestory_823001001_41_dialog_content = "導師一直堅持著自己的信念，從不歪曲。",
  str_homestory_823001001_42_dialog_content = "我也應該如他一般，以我最原本的面貌，活在世上。",
  str_homestory_823001001_43_dialog_content = "能從剛才那一連串災難，不是，事件中得出這個結論……",
  str_homestory_823001001_44_dialog_content = "你說不定非常有悟性。",
  str_homestory_823001001_45_dialog_content = "感謝您溫暖的言語，PlayerName。",
  str_homestory_823001001_46_dialog_content = "作為回報，我隨時願意在這座小小的城堡裡聆聽您的懺悔。",
  str_homestory_823001001_47_dialog_content = "咳咳，等我想到有什麼事要懺悔再說吧！",
  str_homestory_823101001_0_dialog_content = "威廉先生，您怎麼一直盯著這座涼亭？裡面什麼也沒有呀。",
  str_homestory_823101001_1_dialog_content = "我正在思考，你這座亭子底下是否也埋藏著謎題？",
  str_homestory_823101001_2_dialog_content = "謎題？不、不會吧，您怎麼會這麼想？",
  str_homestory_823101001_3_dialog_content = "荒郊野外，兀然孤佇的涼亭，似乎與冒險、謎團有著天然的緣分。",
  str_homestory_823101001_4_dialog_content = "許多傳奇故事中都有類似的情節。",
  str_homestory_823101001_5_dialog_content = "我受此啟發，當年曾為維多利亞出過一道題。",
  str_homestory_823101001_6_dialog_content = "在、在涼亭裡？",
  str_homestory_823101001_7_dialog_content = "首先，我微微地惹火她——",
  str_homestory_823101001_8_dialog_content = "為什麼要這麼做啊！",
  str_homestory_823101001_9_dialog_content = "這一步很簡單，她原本就對我心存敵意。",
  str_homestory_823101001_10_dialog_content = "不過，從她大叫著「魔鬼，下地獄去吧！」然後眼睛紅通通跑掉的結果看來……",
  str_homestory_823101001_11_dialog_content = "我似乎做得太過頭了。",
  str_homestory_823101001_12_dialog_content = "維多利亞小姐當年也很……活潑嘛。",
  str_homestory_823101001_13_dialog_content = "然後，我故意留下種種線索，讓她以為瓦拉吉家有一件祖傳寶物。",
  str_homestory_823101001_14_dialog_content = "只要找到那件寶物，就能將我扳倒，奪回家主之位。",
  str_homestory_823101001_15_dialog_content = "你倆的相處何止彆扭……",
  str_homestory_823101001_16_dialog_content = "她不負我所望，成功解讀線索，得出了正確的結論。",
  str_homestory_823101001_17_dialog_content = "「祖傳寶物」的位置，就刻印在花園深處的涼亭中。",
  str_homestory_823101001_18_dialog_content = "然後呢？",
  str_homestory_823101001_19_dialog_content = "當然，找到了涼亭還不算結束。",
  str_homestory_823101001_20_dialog_content = "她還需要解開刻在涼亭石板上的一道道謎語，找出最終的藏寶地。",
  str_homestory_823101001_21_dialog_content = "順帶一提，我對那些石板的舊化效果非常滿意。",
  str_homestory_823101001_22_dialog_content = "……",
  str_homestory_823101001_23_dialog_content = "那上面的謎語是您出的嗎？都是些什麼謎語？",
  str_homestory_823101001_24_dialog_content = "不值一提。不過是些歷史常識、神話寓言，再加上幾道數學題。",
  str_homestory_823101001_25_dialog_content = "她只要回去讀上一星期的書，輕輕鬆鬆就能解開。",
  str_homestory_823101001_26_dialog_content = "我有種預感，這事絕不會有好結果……",
  str_homestory_823101001_27_dialog_content = "取決於你怎麼看。她成功了，我就知道難不倒她。",
  str_homestory_823101001_28_dialog_content = "但我確實不明白她找到「寶藏」後，為什麼那麼生氣。",
  str_homestory_823101001_29_dialog_content = "我還是先問一句吧，您究竟埋了什麼「寶藏」？",
  str_homestory_823101001_30_dialog_content = "維多利亞最喜歡的蜂蜜。當年新鮮採集的，整整一罐。",
  str_homestory_823101001_31_dialog_content = "就這樣？！",
  str_homestory_823101001_32_dialog_content = "這還不夠嗎？《如何與叛逆期少女相處》裡白紙黑字地寫了——",
  str_homestory_823101001_33_dialog_content = "「準備她喜歡的東西，甜食永遠不會出錯。」",
  str_homestory_823101001_34_dialog_content = "我真不明白問題出在哪裡。",
  str_homestory_823101001_35_dialog_content = "那您為什麼不直接把蜂蜜給她啊！！",
  str_homestory_823101001_36_dialog_content = "還記得她對我心存敵意嗎？",
  str_homestory_823101001_37_dialog_content = "與她互相挑釁雖不至於無趣，但也著實累人。",
  str_homestory_823101001_38_dialog_content = "我不介意用其他事物分散她的注意力。",
  str_homestory_823101001_39_dialog_content = "她研讀了整整一週的歷史、神話、數學，苦思冥想，滿心期待……",
  str_homestory_823101001_40_dialog_content = "最後卻只找到一罐蜂蜜，簡直就是您在嘲笑她上當啊。",
  str_homestory_823101001_41_dialog_content = "您還不明白她為什麼生氣？",
  str_homestory_823101001_42_dialog_content = "你說的也有一些道理。",
  str_homestory_823101001_43_dialog_content = "但也不用在家主集會前偷偷把蜂蜜倒在我的椅子上……",
  str_homestory_823101001_44_dialog_content = "害我只能坐在一坨蜂蜜上面，若無其事地開一上午會吧！",
  str_homestory_823101001_45_dialog_content = "你怎麼看？",
  str_homestory_823101001_46_dialog_content = "您活該。",
  str_homestory_823101001_47_dialog_content = "您罪有應得。",
  str_homestory_823101001_48_dialog_content = "呿……"
}
return config
